464 CONSTANT _EXT4-JWR.CP-TARGET-ENTRIES
472 CONSTANT _EXT4-JWR.CP-INODE-BITMAP-HOME
480 CONSTANT _EXT4-JWR.CP-INODE-BITMAP-CRC
488 CONSTANT _EXT4-JWR.CP-INODE-GDT-HOME
496 CONSTANT _EXT4-JWR.CP-INODE-GDT-OFF
504 CONSTANT _EXT4-JWR.CP-INODE-GDT-CRC
512 CONSTANT _EXT4-JWR.CP-INODE-SUPER-CRC
520 CONSTANT _EXT4-JWR.CP-DELETE-RANGE-COUNT
528 CONSTANT _EXT4-JWR.CP-DELETE-BLOCKS
536 CONSTANT _EXT4-JWR.CP-EA-HOME
544 CONSTANT _EXT4-JWR.CP-DATA-MAP-KIND
552 CONSTANT _EXT4-JWR.CP-PRE-ACTIVE
560 CONSTANT _EXT4-JWR.CP-PRE-MODERN
568 CONSTANT _EXT4-JWR.CP-PRE-LEGACY
576 CONSTANT _EXT4-JWR.CP-EA-ACTION
584 CONSTANT _EXT4-JWR.CP-EA-REFCOUNT
592 CONSTANT _EXT4-JWR.CP-EA-CRC
600 CONSTANT _EXT4-JWR.CP-ADD-PARENT-INO
608 CONSTANT _EXT4-JWR.CP-ADD-PARENT-GEN
616 CONSTANT _EXT4-JWR.CP-ADD-PARENT-HOME
624 CONSTANT _EXT4-JWR.CP-ADD-PARENT-OFF
632 CONSTANT _EXT4-JWR.CP-ADD-DIR-HOME
640 CONSTANT _EXT4-JWR.CP-ADD-DIR-TARGET-OFF
648 CONSTANT _EXT4-JWR.CP-ADD-DIR-TARGET-REC
656 CONSTANT _EXT4-JWR.CP-ADD-DIR-PREV-OFF
664 CONSTANT _EXT4-JWR.CP-ADD-DIR-PREV-REC
672 CONSTANT _EXT4-JWR.CP-ADD-SOURCE-INO
680 CONSTANT _EXT4-JWR.CP-ADD-SOURCE-GEN
688 CONSTANT _EXT4-JWR.CP-ADD-SOURCE-HOME
696 CONSTANT _EXT4-JWR.CP-ADD-SOURCE-OFF
704 CONSTANT _EXT4-JWR.CP-ADD-OLD-PARENT-INO
712 CONSTANT _EXT4-JWR.CP-ADD-OLD-PARENT-GEN
720 CONSTANT _EXT4-JWR.CP-ADD-OLD-PARENT-HOME
728 CONSTANT _EXT4-JWR.CP-ADD-OLD-PARENT-OFF
736 CONSTANT _EXT4-JWR.CP-ADD-OLD-DIR-HOME
744 CONSTANT _EXT4-JWR.CP-ADD-OLD-DIR-SOURCE-OFF
752 CONSTANT _EXT4-JWR.CP-ADD-OLD-DIR-SOURCE-REC
760 CONSTANT _EXT4-JWR.CP-ADD-OLD-DIR-PREV-OFF
768 CONSTANT _EXT4-JWR.CP-ADD-OLD-DIR-PREV-REC
776 CONSTANT _EXT4-JWR.CP-ADD-CHILD-HOME
784 CONSTANT _EXT4-JWR.CP-ADD-TARGET-SIZE-LO
792 CONSTANT _EXT4-JWR.CP-ADD-TARGET-SIZE-HI
800 CONSTANT _EXT4-JWR-SIZE

\ CP fields after TARGET-ENTRIES are a mode-discriminated payload.  Deletion
\ uses their inode-release meanings above; modern orphan insertion instead
\ seals the requested timestamps and the primary-super after-image checksum
\ here.  A linked record's release and final cleanup seal the block whose
\ bytes past EOF the final cleanup zeroes, and the checksum of the target's
\ inode record before the transaction.
_EXT4-JWR.CP-INODE-BITMAP-HOME CONSTANT _EXT4-JWR.CP-ADD-SECONDS
_EXT4-JWR.CP-INODE-BITMAP-CRC  CONSTANT _EXT4-JWR.CP-ADD-NSEC
_EXT4-JWR.CP-INODE-GDT-HOME   CONSTANT _EXT4-JWR.CP-ADD-SUPER-CRC
_EXT4-JWR.CP-INODE-BITMAP-HOME CONSTANT _EXT4-JWR.CP-TAIL-HOME
_EXT4-JWR.CP-INODE-BITMAP-CRC  CONSTANT _EXT4-JWR.CP-TARGET-PRE-CRC

: _EXT4-JWR-CP-DELETE-RANGES  ( writer -- ranges )
    _EXT4-JWR.CP-DELETE-RANGES + @ ;

: _EXT4-JWR-CP-DELETE-RANGE  ( index writer -- pair-address )
    _EXT4-JWR-CP-DELETE-RANGES SWAP 2* CELLS + ;

3 CONSTANT _EXT4-JWR-IMAGE-ENTRY-CELLS  \ home, state, image CRC32C
2 CONSTANT _EXT4-JWR-REVOKE-ENTRY-CELLS \ home, state

\ One full sparse-double child plus all direct and single-indirect data fixes a
\ useful bounded authority budget: twelve direct data blocks, two full pointer
\ blocks of data, three map homes, and one optional xattr, or 2P+16 ranges for
\ P=block-size/4.  The same budget admits additional sparse children whenever
\ their exact data-plus-map vector fits.  It also bounds resident depth-one
\ extent fanout.  This is caller-workspace geometry, not a child-count limit.
: _EXT4-DELETE-RANGE-CAPACITY  ( block-size -- capacity ior )
    DUP
    DUP 1024 = OVER 2048 = OR SWAP 4096 = OR 0= IF
        DROP 0 VFS-E-INVALID EXIT
    THEN
    4 / 2 _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP
    16 _EXT4-UADD? ;

: _EXT4-JWR-CP-DELETE-RANGE-CAPACITY
  ( block-size -- capacity ior )
    _EXT4-DELETE-RANGE-CAPACITY ;

VARIABLE _EXT4-HG-CAP
VARIABLE _EXT4-HG-SLOTS

: _EXT4-HASH-SLOTS  ( capacity -- slots ior )
    DUP 0< IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP _EXT4-HG-CAP ! 0= IF 0 0 EXIT THEN
    2 _EXT4-HG-SLOTS !
    BEGIN
        _EXT4-HG-SLOTS @ 2 / _EXT4-HG-CAP @ U<
    WHILE
        _EXT4-HG-SLOTS @ _EXT4-NONNEG-MAX 2 / U> IF
            0 VFS-E-OVERFLOW EXIT
        THEN
        _EXT4-HG-SLOTS @ 2* _EXT4-HG-SLOTS !
    REPEAT
    _EXT4-HG-SLOTS @ 0 ;

VARIABLE _EXT4-ROE-CTX VARIABLE _EXT4-ROE-V
VARIABLE _EXT4-ROE-CAP VARIABLE _EXT4-ROE-SLOTS
VARIABLE _EXT4-ROE-BYTES VARIABLE _EXT4-ROE-ARENA
VARIABLE _EXT4-ROE-MARK VARIABLE _EXT4-ROE-TABLE
VARIABLE _EXT4-ROE-SIZE VARIABLE _EXT4-ROE-BASE
VARIABLE _EXT4-ROE-END VARIABLE _EXT4-ROE-RUNTIME-END

: _EXT4-LOAD-MOUNT-ARENA  ( ctx -- ior )
    DUP _EXT4-ROE-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-C.ARENA + @ DUP _EXT4-ROE-ARENA !
    0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-ARENA @ A.BASE @ DUP _EXT4-ROE-BASE !
    0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-BASE @ 7 AND IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-ARENA @ A.SIZE @ DUP _EXT4-ROE-SIZE !
    DUP 0< SWAP 0= OR IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-BASE @ _EXT4-ROE-SIZE @
    MSPAN-NONWRAPPING? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-ARENA @ A.PTR @ DUP _EXT4-ROE-END !
    DUP 7 AND IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-ROE-BASE @ U< IF DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-BASE @ _EXT4-ROE-SIZE @ + U> IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ Bound mounted orphan publication by all three authenticated resources: the
\ physical orphan-file slots, filesystem inode geometry, and descriptors plus
\ one synchronous closed final-unlink candidate.
: _EXT4-RUNTIME-ORPHAN-CAPACITY  ( ctx vfs -- capacity ior )
    _EXT4-ROE-V ! _EXT4-ROE-CTX !
    _EXT4-ROE-CTX @ 0= _EXT4-ROE-V @ 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-ROE-V @ V.BCTX @ _EXT4-ROE-CTX @ <>
    _EXT4-ROE-V @ V.ARENA @
    _EXT4-ROE-CTX @ _EXT4-C.ARENA + @ <> OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-ROE-V @ _EXT4-ATTACHED? 0= IF 0 VFS-E-STALE EXIT THEN
    _EXT4-ROE-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-ROE-V @ _EXT4-IO-VFS !
    _EXT4-ROE-CTX @ _EXT4-PREPARE-ORPHAN-FILE
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-C.BSIZE + @ DUP 8 U< IF
        DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    8 - DUP 4 MOD IF
        DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    4 / DUP 0= IF
        DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-BLOCKS @ SWAP _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP
    _EXT4-ROE-V @ V.FDMAX @ 1 _EXT4-UADD?
    DUP IF >R 2DROP 0 R> EXIT THEN DROP
    _EXT4-ROE-CTX @ _EXT4-C.INODES + @ DUP
    0< OVER 0= OR IF
        2DROP DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    MIN MIN 0 ;

\ Validate the exact retained runtime allocation against current authenticated
\ geometry and the used portion of the owning mount arena.  Once the mount is
\ published, later VFS objects may legitimately follow this retained allocation
\ in the same arena; only a live transient mount tail must begin exactly at its
\ end.
: _EXT4-VALIDATE-RUNTIME-ORPHAN-WORKSPACE  ( ctx vfs -- ior )
    _EXT4-ROE-V ! _EXT4-ROE-CTX !
    _EXT4-ROE-CTX @ _EXT4-ROE-V @ _EXT4-RUNTIME-ORPHAN-CAPACITY
    DUP IF NIP EXIT THEN DROP _EXT4-ROE-CAP !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-TABLE + @ _EXT4-ROE-TABLE !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-SLOTS + @ _EXT4-ROE-SLOTS !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-END + @
    _EXT4-ROE-RUNTIME-END !
    _EXT4-ROE-TABLE @ 0= _EXT4-ROE-SLOTS @ 0= OR
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ 0= OR
    _EXT4-ROE-RUNTIME-END @ 0= OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @
    _EXT4-ROE-CAP @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROE-CAP @ _EXT4-HASH-SLOTS
    DUP IF 2DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    DROP _EXT4-ROE-SLOTS @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROE-SLOTS @ _EXT4-ORPHAN-RECORD-SIZE _EXT4-UMUL?
    DUP IF 2DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    DROP _EXT4-ROE-BYTES !
    _EXT4-ROE-TABLE @ 7 AND IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BYTES @
    MSPAN-NONWRAPPING? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BYTES @ +
    _EXT4-ROE-RUNTIME-END @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-LOAD-MOUNT-ARENA ?DUP IF EXIT THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BASE @ U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-RUNTIME-END @ _EXT4-ROE-END @ U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.MOUNT-TAIL-MARK + @ DUP
    _EXT4-ROE-MARK ! IF
        _EXT4-ROE-MARK @ _EXT4-ROE-BASE @ U<
        _EXT4-ROE-MARK @ _EXT4-ROE-END @ U> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-ROE-RUNTIME-END @ _EXT4-ROE-MARK @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Allocate the runtime table once below any mount-transient tail.  Retried
\ mounts may only validate, reuse, and clear that exact retained allocation.
: _EXT4-ENSURE-RUNTIME-ORPHAN-WORKSPACE  ( ctx vfs -- ior )
    _EXT4-ROE-V ! _EXT4-ROE-CTX !
    _EXT4-ROE-CTX @ 0= _EXT4-ROE-V @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ROE-V @ VFS-CAPS@ VFS-CAP-WRITE AND 0= IF
        VFS-E-UNSUPPORTED EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.MOUNT-TAIL-MARK + @ IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.TABLE + @
    _EXT4-ROE-CTX @ _EXT4-C.O.SLOTS + @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-ROE-V @ _EXT4-RUNTIME-ORPHAN-CAPACITY
    DUP IF NIP EXIT THEN DROP DUP _EXT4-ROE-CAP !
    _EXT4-HASH-SLOTS DUP IF NIP EXIT THEN
    DROP DUP _EXT4-ROE-SLOTS !
    _EXT4-ORPHAN-RECORD-SIZE _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-ROE-BYTES !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-TABLE + @ IF
        _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-SLOTS + @ 0=
        _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ 0= OR
        _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-END + @ 0= OR IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-ROE-CTX @ _EXT4-ROE-V @
        _EXT4-VALIDATE-RUNTIME-ORPHAN-WORKSPACE ?DUP IF EXIT THEN
        _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-TABLE + @
        _EXT4-ROE-BYTES @ 0 FILL 0 EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-SLOTS + @
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ OR
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-END + @ OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-LOAD-MOUNT-ARENA ?DUP IF EXIT THEN
    _EXT4-ROE-ARENA @ ARENA-SNAP DUP _EXT4-ROE-MARK !
    _EXT4-ROE-END @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-MARK @ _EXT4-ROE-BYTES @
    MSPAN-NONWRAPPING? 0= IF VFS-E-NOMEM EXIT THEN
    _EXT4-ROE-BASE @ _EXT4-ROE-SIZE @ +
    _EXT4-ROE-MARK @ _EXT4-ROE-BYTES @ + U< IF VFS-E-NOMEM EXIT THEN
    _EXT4-ROE-ARENA @ _EXT4-ROE-BYTES @ ARENA-ALLOT? IF
        DROP VFS-E-NOMEM EXIT
    THEN
    DUP _EXT4-ROE-TABLE ! _EXT4-ROE-MARK @ <> IF
        _EXT4-ROE-ARENA @ _EXT4-ROE-MARK @ ARENA-ROLLBACK
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-ROE-ARENA @ A.PTR @
    _EXT4-ROE-TABLE @ _EXT4-ROE-BYTES @ + <> IF
        _EXT4-ROE-ARENA @ _EXT4-ROE-MARK @ ARENA-ROLLBACK
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BYTES @ 0 FILL
    _EXT4-ROE-ARENA @ A.PTR @ _EXT4-ROE-CTX @
    _EXT4-C.O.RUNTIME-END + !
    _EXT4-ROE-CAP @ _EXT4-ROE-CTX @
    _EXT4-C.O.RUNTIME-CAPACITY + !
    _EXT4-ROE-SLOTS @ _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-SLOTS + !
    _EXT4-ROE-TABLE @ _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-TABLE + !
    0 ;

: _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING  ( ctx vfs -- ior )
    2DUP _EXT4-VALIDATE-RUNTIME-ORPHAN-WORKSPACE ?DUP IF
        >R 2DROP R> EXIT
    THEN
    DROP
    DUP _EXT4-C.O.MOUNT-TAIL-MARK + @ IF DROP VFS-E-BUSY EXIT THEN
    DUP _EXT4-C.O.TABLE + @ OVER _EXT4-C.O.RUNTIME-TABLE + @ <>
    OVER _EXT4-C.O.SLOTS + @
    ROT _EXT4-C.O.RUNTIME-SLOTS + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-BIND-RUNTIME-ORPHAN-WORKSPACE  ( ctx vfs -- ior )
    2DUP _EXT4-VALIDATE-RUNTIME-ORPHAN-WORKSPACE ?DUP IF
        >R 2DROP R> EXIT
    THEN
    DROP
    DUP _EXT4-C.O.MOUNT-TAIL-MARK + @ IF DROP VFS-E-BUSY EXIT THEN
    DUP _EXT4-C.O.TABLE + @ OVER _EXT4-C.O.SLOTS + @ OR IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DUP _EXT4-C.O.RUNTIME-SLOTS + @ OVER _EXT4-C.O.SLOTS + !
    DUP _EXT4-C.O.RUNTIME-TABLE + @ SWAP _EXT4-C.O.TABLE + !
    0 ;

: _EXT4-UNBIND-RUNTIME-ORPHAN-WORKSPACE  ( ctx -- ior )
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-C.O.TABLE + @ OVER _EXT4-C.O.SLOTS + @ OR 0= IF
        DROP 0 EXIT
    THEN
    DUP _EXT4-C.O.TABLE + @ OVER _EXT4-C.O.RUNTIME-TABLE + @ =
    OVER _EXT4-C.O.SLOTS + @
    2 PICK _EXT4-C.O.RUNTIME-SLOTS + @ = AND IF
        0 OVER _EXT4-C.O.TABLE + !
        0 SWAP _EXT4-C.O.SLOTS + ! 0 EXIT
    THEN
    _EXT4-C.O.MOUNT-TAIL-MARK + @ IF 0 ELSE VFS-E-CORRUPT THEN ;

VARIABLE _EXT4-JWM-META
VARIABLE _EXT4-JWM-DATA
VARIABLE _EXT4-JWM-REVOKE
VARIABLE _EXT4-JWM-BSIZE
VARIABLE _EXT4-JWM-META-SLOTS
VARIABLE _EXT4-JWM-DATA-SLOTS
VARIABLE _EXT4-JWM-REVOKE-SLOTS
VARIABLE _EXT4-JWM-CP-RANGE-CAP
VARIABLE _EXT4-JWM-BYTES
VARIABLE _EXT4-JWM-COMPONENT

: _EXT4-JWR-ADD-BYTES  ( bytes -- ior )
    _EXT4-JWM-COMPONENT !
    _EXT4-JWM-BYTES @ _EXT4-JWM-COMPONENT @ _EXT4-UADD?
    DUP IF NIP EXIT THEN
    DROP _EXT4-JWM-BYTES ! 0 ;

: _EXT4-JWR-MEASURE  ( meta-cap data-cap revoke-cap block-size -- bytes ior )
    _EXT4-JWM-BSIZE ! _EXT4-JWM-REVOKE !
    _EXT4-JWM-DATA ! _EXT4-JWM-META !
    _EXT4-JWM-META @ 0< _EXT4-JWM-DATA @ 0< OR
    _EXT4-JWM-REVOKE @ 0< OR IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JWM-BSIZE @ 1024 =
    _EXT4-JWM-BSIZE @ 2048 = OR
    _EXT4-JWM-BSIZE @ 4096 = OR 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JWM-META @ _EXT4-HASH-SLOTS
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWM-META-SLOTS !
    _EXT4-JWM-DATA @ _EXT4-HASH-SLOTS
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWM-DATA-SLOTS !
    _EXT4-JWM-REVOKE @ _EXT4-HASH-SLOTS
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWM-REVOKE-SLOTS !
    _EXT4-JWM-BSIZE @ _EXT4-JWR-CP-DELETE-RANGE-CAPACITY
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWM-CP-RANGE-CAP !
    _EXT4-JWR-SIZE _EXT4-JWM-BYTES !
    _EXT4-JWM-META @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-DATA @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-REVOKE @ _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-META-SLOTS @ CELLS _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-DATA-SLOTS @ CELLS _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-REVOKE-SLOTS @ CELLS _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-META @ _EXT4-JWM-BSIZE @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-DATA @ _EXT4-JWM-BSIZE @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    2 _EXT4-JWM-BSIZE @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-CP-RANGE-CAP @ 2 CELLS _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP _EXT4-JWR-ADD-BYTES
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWM-BYTES @ 0 ;

: _EXT4-JWR-GEOMETRY?  ( ctx -- flag )
    DUP 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-C.ARENA + @ 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-C.BSIZE + @ DUP 1024 = OVER 2048 = OR SWAP 4096 = OR 0= IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-C.BLOCKS + @ DUP 0< SWAP 0= OR IF DROP FALSE EXIT THEN
    DUP _EXT4-C.J.FIRST + @ DUP 0= IF 2DROP FALSE EXIT THEN
    OVER _EXT4-C.J.MAXLEN + @ U< 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-C.J.MAP + @ 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-C.J.MAP-HASH + @ 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-C.J.MAP-CAPACITY + @
    OVER _EXT4-C.J.MAXLEN + @ <> IF DROP FALSE EXIT THEN
    DUP _EXT4-C.J.MAP-HASH-SLOTS + @ DUP 0< IF 2DROP FALSE EXIT THEN
    DUP 2 U< IF 2DROP FALSE EXIT THEN
    DUP 1- AND IF DROP FALSE EXIT THEN
    DUP _EXT4-C.J.MAP-HASH-SLOTS + @ 2 /
    OVER _EXT4-C.J.MAP-CAPACITY + @ U< IF DROP FALSE EXIT THEN
    DROP TRUE ;

: _EXT4-JWR-CONTEXT?  ( ctx -- flag )
    DUP _EXT4-JWR-GEOMETRY? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-C.RECOVERY + @ IF
        _EXT4-C.J.WRITE-ACTIVE + @ 0<> EXIT
    THEN DROP TRUE ;

VARIABLE _EXT4-JWV-WRITER
VARIABLE _EXT4-JWV-CTX
VARIABLE _EXT4-JWV-CURSOR
VARIABLE _EXT4-JWV-BYTES
VARIABLE _EXT4-JWV-IOR
VARIABLE _EXT4-JWV-OK
VARIABLE _EXT4-JWV-RING-CAP
VARIABLE _EXT4-JWV-STATE
VARIABLE _EXT4-JWV-PHASE
VARIABLE _EXT4-JWV-TX-ACTIVE
VARIABLE _EXT4-JWV-COMMITTED-SHAPE
VARIABLE _EXT4-JWV-CAP
VARIABLE _EXT4-JWV-CREDIT
VARIABLE _EXT4-JWV-USED
VARIABLE _EXT4-JWV-ACTIVE

VARIABLE _EXT4-JWS-WRITER
VARIABLE _EXT4-JWS-CTX
VARIABLE _EXT4-JWS-ARENA
VARIABLE _EXT4-JWS-BASE
VARIABLE _EXT4-JWS-SIZE
VARIABLE _EXT4-JWS-END
VARIABLE _EXT4-JWS-BYTES
VARIABLE _EXT4-JWS-MOUNT-ARENA
VARIABLE _EXT4-JWS-MOUNT-BASE
VARIABLE _EXT4-JWS-MOUNT-SIZE

1 CONSTANT _EXT4-JWR-STORE-MOUNT
2 CONSTANT _EXT4-JWR-STORE-DEDICATED

\ A production writer profile owns the first and only allocation in a
\ dedicated caller arena.  Internal mount-time recovery writers instead own
\ the current tail of the ordinary mount arena.  STORE-KIND prevents a
\ damaged arena handle from silently downgrading either ownership contract.
\ Revalidate the live arena descriptor, exact allocation endpoint, and
\ dedicated-backing separation whenever writer shape is used.
: _EXT4-JWR-PROFILE-STORAGE?  ( writer -- flag )
    DUP _EXT4-JWS-WRITER ! _EXT4-JWR.CTX + @ DUP
    _EXT4-JWS-CTX ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-CTX @ _EXT4-C.J.WRITER-ARENA + @ DUP
    _EXT4-JWS-ARENA ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ 4 CELLS MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.SOURCE @ DUP 0< SWAP 2 > OR IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.BASE @ DUP _EXT4-JWS-BASE ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.SIZE @ DUP _EXT4-JWS-SIZE !
    DUP 0< SWAP 0= OR IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ A.PTR @ DUP _EXT4-JWS-END ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-BASE @ 7 AND _EXT4-JWS-END @ 7 AND OR IF FALSE EXIT THEN
    _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @ MSPAN-NONWRAPPING? 0= IF
        FALSE EXIT
    THEN
    _EXT4-JWS-ARENA @ 4 CELLS _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @
    MSPAN-OVERLAP? IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWS-BASE @ U< IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWR.TOTAL + @ DUP _EXT4-JWS-BYTES !
    _EXT4-JWS-WRITER @ SWAP MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWS-BYTES @ + DUP
    _EXT4-JWS-END @ <> IF DROP FALSE EXIT THEN
    _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @ + U> IF FALSE EXIT THEN
    _EXT4-JWS-CTX @ _EXT4-C.ARENA + @ DUP
    _EXT4-JWS-MOUNT-ARENA ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ DUP
    _EXT4-JWR-STORE-MOUNT = IF
        DROP _EXT4-JWS-ARENA @ _EXT4-JWS-MOUNT-ARENA @ = EXIT
    THEN
    _EXT4-JWR-STORE-DEDICATED <> IF FALSE EXIT THEN
    _EXT4-JWS-ARENA @ _EXT4-JWS-MOUNT-ARENA @ = IF FALSE EXIT THEN
    _EXT4-JWS-WRITER @ _EXT4-JWS-BASE @ <> IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-ARENA @ A.BASE @ DUP
    _EXT4-JWS-MOUNT-BASE ! 0= IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-ARENA @ A.SIZE @ DUP
    _EXT4-JWS-MOUNT-SIZE ! DUP 0< SWAP 0= OR IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-BASE @ 7 AND IF FALSE EXIT THEN
    _EXT4-JWS-MOUNT-BASE @ _EXT4-JWS-MOUNT-SIZE @
    MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-JWS-BASE @ _EXT4-JWS-SIZE @
    _EXT4-JWS-MOUNT-BASE @ _EXT4-JWS-MOUNT-SIZE @
    MSPAN-OVERLAP? 0= ;

: _EXT4-JWV-EXPECT  ( address -- )
    _EXT4-JWV-CURSOR @ <> IF 0 _EXT4-JWV-OK ! THEN ;

: _EXT4-JWV-ADVANCE  ( count bytes-per-item -- )
    * _EXT4-JWV-CURSOR +! ;

: _EXT4-JWR-SHAPE?  ( writer -- flag )
    _EXT4-JWV-WRITER !
    _EXT4-JWV-WRITER @ 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAGIC + @
    _EXT4-JWR-MAGIC <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.SELF + @
    _EXT4-JWV-WRITER @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWR-SIZE U< IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ DUP
    _EXT4-JWV-CTX ! 0= IF FALSE EXIT THEN
    _EXT4-JWV-CTX @ _EXT4-JWR-CONTEXT? 0= IF FALSE EXIT THEN
    _EXT4-JWV-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-JWV-WRITER @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR-PROFILE-STORAGE? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ DUP 1024 =
    OVER 2048 = OR SWAP 4096 = OR 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JWV-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ DUP 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @ U< 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @
    _EXT4-JWV-CTX @ _EXT4-C.J.FIRST + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JWV-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @ 0<
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @ 0< OR
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @ 0< OR IF
        FALSE EXIT
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JWR-MEASURE _EXT4-JWV-IOR ! _EXT4-JWV-BYTES !
    _EXT4-JWV-IOR @ IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWV-BYTES @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JWM-META-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JWM-DATA-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JWM-REVOKE-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + @
    _EXT4-JWM-CP-RANGE-CAP @ <> IF FALSE EXIT THEN
    -1 _EXT4-JWV-OK !
    _EXT4-JWV-WRITER @ _EXT4-JWR-SIZE + _EXT4-JWV-CURSOR !
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-IMAGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-IMAGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JWV-EXPECT
    1 _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.SCRATCH-B + @ _EXT4-JWV-EXPECT
    1 _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.CP-DELETE-RANGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + @
    2 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-CURSOR @
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWV-WRITER @ + <> IF 0 _EXT4-JWV-OK ! THEN
    _EXT4-JWV-OK @ ;

: _EXT4-JWR-COUNTS?  ( capacity credit used active -- flag )
    _EXT4-JWV-ACTIVE ! _EXT4-JWV-USED !
    _EXT4-JWV-CREDIT ! _EXT4-JWV-CAP !
    _EXT4-JWV-CAP @ 0< _EXT4-JWV-CREDIT @ 0< OR
    _EXT4-JWV-USED @ 0< OR _EXT4-JWV-ACTIVE @ 0< OR IF FALSE EXIT THEN
    _EXT4-JWV-CREDIT @ _EXT4-JWV-CAP @ U>
    _EXT4-JWV-USED @ _EXT4-JWV-CREDIT @ U> OR
    _EXT4-JWV-ACTIVE @ _EXT4-JWV-USED @ U> OR 0= ;

: _EXT4-JWV-RING-POS?  ( logical -- flag )
    DUP _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ U< IF DROP FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @ U< ;

: _EXT4-JWR-ZERO-CP-DELETE-RANGES  ( writer -- )
    DUP _EXT4-JWR.CP-DELETE-RANGES + @
    SWAP _EXT4-JWR.CP-DELETE-RANGE-CAP + @ 2* CELLS 0 FILL ;

: _EXT4-JWR-CP-DELETE-RANGES-ZERO?  ( writer -- flag )
    DUP _EXT4-JWR.CP-DELETE-RANGES + @
    SWAP _EXT4-JWR.CP-DELETE-RANGE-CAP + @ 2* CELLS
    _EXT4-BYTES-ZERO? ;

: _EXT4-JWR-CLEAR-CP-AUTHORITY  ( writer -- )
    DUP _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JWR.CP-MODE +
    _EXT4-JWR-SIZE _EXT4-JWR.CP-MODE - 0 FILL ;

: _EXT4-JWR-TRANSACTION-CLEAN?  ( writer -- flag )
    DUP _EXT4-JWR.META-CREDIT + @
    OVER _EXT4-JWR.DATA-CREDIT + @ OR
    OVER _EXT4-JWR.REVOKE-CREDIT + @ OR
    OVER _EXT4-JWR.META-USED + @ OR
    OVER _EXT4-JWR.DATA-USED + @ OR
    OVER _EXT4-JWR.REVOKE-USED + @ OR
    OVER _EXT4-JWR.META-ACTIVE + @ OR
    OVER _EXT4-JWR.DATA-ACTIVE + @ OR
    OVER _EXT4-JWR.REVOKE-ACTIVE + @ OR
    OVER _EXT4-JWR.LOG-RESERVED + @ OR
    OVER _EXT4-JWR.TX-START + @ OR
    OVER _EXT4-JWR.TX-CURSOR + @ OR
    OVER _EXT4-JWR.TX-TID + @ OR
    OVER _EXT4-JWR.CP-MODE + @ OR
    OVER _EXT4-JWR.CP-EPOCH + @ OR
    OVER _EXT4-JWR.CP-O-INO + @ OR
    OVER _EXT4-JWR.CP-O-LOGICAL + @ OR
    OVER _EXT4-JWR.CP-O-SLOT + @ OR
    OVER _EXT4-JWR.CP-O-HOME + @ OR
    OVER _EXT4-JWR.CP-O-GEN + @ OR
    OVER _EXT4-JWR.CP-TARGET-GEN + @ OR
    OVER _EXT4-JWR.CP-TARGET-HOME + @ OR
    OVER _EXT4-JWR.CP-TARGET-OFF + @ OR
    OVER _EXT4-JWR.CP-TARGET-CRC + @ OR
    OVER _EXT4-JWR.CP-ORPHAN-CRC + @ OR
    OVER _EXT4-JWR.CP-TARGET-ENTRIES + @ OR
    OVER _EXT4-JWR.CP-INODE-BITMAP-HOME + @ OR
    OVER _EXT4-JWR.CP-INODE-BITMAP-CRC + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-HOME + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-OFF + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-CRC + @ OR
    OVER _EXT4-JWR.CP-INODE-SUPER-CRC + @ OR
    OVER _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ OR
    OVER _EXT4-JWR.CP-DELETE-BLOCKS + @ OR
    OVER _EXT4-JWR-CP-DELETE-RANGES
    2 PICK _EXT4-JWR.CP-DELETE-RANGE-CAP + @ 2* CELLS
    _EXT4-BYTES-ZERO? 0= OR
    OVER _EXT4-JWR.CP-EA-HOME + @ OR
    OVER _EXT4-JWR.CP-DATA-MAP-KIND + @ OR
    OVER _EXT4-JWR.CP-PRE-ACTIVE + @ OR
    OVER _EXT4-JWR.CP-PRE-MODERN + @ OR
    OVER _EXT4-JWR.CP-PRE-LEGACY + @ OR
    OVER _EXT4-JWR.CP-EA-ACTION + @ OR
    OVER _EXT4-JWR.CP-EA-REFCOUNT + @ OR
    SWAP _EXT4-JWR.CP-EA-CRC + @ OR 0= ;

: _EXT4-JWR-IDLE-CLEAN?  ( writer -- flag )
    DUP _EXT4-JWR-TRANSACTION-CLEAN?
    SWAP _EXT4-JWR.PHASE + @ 0= AND ;

VARIABLE _EXT4-JWV-LOG-EXPECTED
VARIABLE _EXT4-JWV-LOG-IOR
VARIABLE _EXT4-JWV-RES-META
VARIABLE _EXT4-JWV-RES-REVOKE
VARIABLE _EXT4-JWV-RES-WRITER

: _EXT4-JWV-CEIL/  ( nonnegative-n positive-d -- quotient )
    /MOD SWAP 0<> IF 1+ THEN ;

: _EXT4-JWV-LOG-ADD?  ( nonnegative-u -- flag )
    _EXT4-JWV-LOG-EXPECTED @ SWAP _EXT4-UADD?
    _EXT4-JWV-LOG-IOR ! _EXT4-JWV-LOG-EXPECTED !
    _EXT4-JWV-LOG-IOR @ 0= ;

: _EXT4-JWR-RESERVATION-COUNTS?
  ( meta-count revoke-count writer -- flag )
    _EXT4-JWV-RES-WRITER ! _EXT4-JWV-RES-REVOKE !
    _EXT4-JWV-RES-META !
    _EXT4-JWV-RES-META @ _EXT4-JWV-LOG-EXPECTED !
    _EXT4-JWV-RES-META @
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.BSIZE + @
    32 - _EXT4-JBD2-TAG3-SIZE /
    _EXT4-JWV-CEIL/ _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    _EXT4-JWV-RES-REVOKE @
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.BSIZE + @ 20 - 8 /
    _EXT4-JWV-CEIL/ _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    2 _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    _EXT4-JWV-LOG-EXPECTED @ = ;

: _EXT4-JWR-RESERVATION?  ( writer -- flag )
    DUP _EXT4-JWR.META-CREDIT + @
    OVER _EXT4-JWR.REVOKE-CREDIT + @
    ROT _EXT4-JWR-RESERVATION-COUNTS? ;

: _EXT4-JWR-ACTUAL-RESERVATION?  ( writer -- flag )
    DUP _EXT4-JWR.META-ACTIVE + @
    OVER _EXT4-JWR.REVOKE-ACTIVE + @
    ROT _EXT4-JWR-RESERVATION-COUNTS? ;

: _EXT4-JWP-ACTIVATION?  ( phase -- flag )
    DUP _EXT4-JWP-GUARD-PRESEED >=
    SWAP _EXT4-JWP-GUARD-RETIRE <= AND ;

: _EXT4-JWP-EMISSION?  ( phase -- flag )
    DUP _EXT4-JWP-ORDERED-DATA >=
    SWAP _EXT4-JWP-COMMIT-FLUSH <= AND ;

: _EXT4-JWP-CHECKPOINT?  ( phase -- flag )
    DUP _EXT4-JWP-CHECKPOINT-PREFLIGHT >=
    SWAP _EXT4-JWP-CHECKPOINT-FINAL-PROOF <= AND ;

: _EXT4-JWP-DEACTIVATION?  ( phase -- flag )
    DUP _EXT4-JWP-DEACTIVATE-PREFLIGHT >=
    SWAP _EXT4-JWP-DEACTIVATE-FINAL-PROOF <= AND ;

VARIABLE _EXT4-JCA-WRITER
VARIABLE _EXT4-JCA-MODE
VARIABLE _EXT4-JCA-TARGET-HOME
VARIABLE _EXT4-JCA-BITMAP-HOME
VARIABLE _EXT4-JCA-GDT-HOME
VARIABLE _EXT4-JCA-TARGET-ENTRIES
VARIABLE _EXT4-JCA-RANGE-COUNT
VARIABLE _EXT4-JCA-RANGE-CAP
VARIABLE _EXT4-JCA-RANGE-INDEX
VARIABLE _EXT4-JCA-OTHER-INDEX
VARIABLE _EXT4-JCA-DATA-FIRST
VARIABLE _EXT4-JCA-DATA-COUNT
VARIABLE _EXT4-JCA-DATA-BLOCKS
VARIABLE _EXT4-JCA-DATA-SUM
VARIABLE _EXT4-JCA-EA-HOME
VARIABLE _EXT4-JCA-EA-ACTION
VARIABLE _EXT4-JCA-EA-REFCOUNT
VARIABLE _EXT4-JCA-EA-CRC
VARIABLE _EXT4-JCA-DATA-MAP-KIND
VARIABLE _EXT4-JCA-REVOKE-INDEX
VARIABLE _EXT4-JCA-REVOKE-HOME
VARIABLE _EXT4-JCA-PRE-ACTIVE
VARIABLE _EXT4-JCA-PRE-MODERN
VARIABLE _EXT4-JCA-PRE-LEGACY
VARIABLE _EXT4-JCA-QUERY-HOME

: _EXT4-JCA-DATA-RANGES?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + @ DUP
    _EXT4-JCA-RANGE-CAP ! DUP 0= SWAP 0< OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ DUP
    _EXT4-JCA-RANGE-COUNT !
    DUP 0< SWAP _EXT4-JCA-RANGE-CAP @ U> OR IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-BLOCKS + @ DUP
    _EXT4-JCA-DATA-BLOCKS !
    DUP 0< IF DROP FALSE EXIT THEN
    _EXT4-JCA-RANGE-COUNT @ 0= IF
        IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES
        _EXT4-JCA-RANGE-CAP @ 2* CELLS
        _EXT4-BYTES-ZERO?
        EXIT
    THEN
    0= IF FALSE EXIT THEN
    0 _EXT4-JCA-DATA-SUM !
    0 _EXT4-JCA-RANGE-INDEX !
    BEGIN
        _EXT4-JCA-RANGE-INDEX @ _EXT4-JCA-RANGE-COUNT @ U<
    WHILE
        _EXT4-JCA-RANGE-INDEX @ _EXT4-JCA-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE DUP @ _EXT4-JCA-DATA-FIRST !
        CELL+ @ DUP _EXT4-JCA-DATA-COUNT !
        DUP 0= SWAP 32768 U> OR IF FALSE EXIT THEN
        _EXT4-JCA-DATA-FIRST @ DUP 0= IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.FIRST + @ U< IF
            FALSE EXIT
        THEN
        _EXT4-JCA-DATA-FIRST @ _EXT4-JCA-DATA-COUNT @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @
        BLOCK-RANGE? 0= IF FALSE EXIT THEN
        _EXT4-JCA-DATA-SUM @ _EXT4-JCA-DATA-COUNT @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP _EXT4-JCA-DATA-SUM !
        0 _EXT4-JCA-OTHER-INDEX !
        BEGIN
            _EXT4-JCA-OTHER-INDEX @ _EXT4-JCA-RANGE-INDEX @ U<
        WHILE
            _EXT4-JCA-DATA-FIRST @ _EXT4-JCA-DATA-COUNT @
            _EXT4-JCA-OTHER-INDEX @ _EXT4-JCA-WRITER @
            _EXT4-JWR-CP-DELETE-RANGE DUP @ SWAP CELL+ @
            _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF FALSE EXIT THEN
            1 _EXT4-JCA-OTHER-INDEX +!
        REPEAT
        1 _EXT4-JCA-RANGE-INDEX +!
    REPEAT
    _EXT4-JCA-DATA-SUM @ _EXT4-JCA-DATA-BLOCKS @ <> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES
    _EXT4-JCA-RANGE-COUNT @ 2* CELLS +
    _EXT4-JCA-RANGE-CAP @ _EXT4-JCA-RANGE-COUNT @ -
    2* CELLS _EXT4-BYTES-ZERO? ;

: _EXT4-JCA-RANGES-ALIAS-HOME?  ( home -- flag )
    _EXT4-JCA-QUERY-HOME !
    _EXT4-JCA-RANGE-COUNT @ 0 ?DO
        _EXT4-JCA-QUERY-HOME @ 1
        I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE
        DUP @ SWAP CELL+ @ _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            TRUE UNLOOP EXIT
        THEN
    LOOP
    FALSE ;

\ Validate the independent external-xattr authority without consuming a data
\ range slot.  RELEASE has no retained header state.  REFDEC binds the durable
\ post-decrement refcount and exact retained-image CRC while keeping the home
\ allocated.  Every present home remains disjoint from the data vector.
: _EXT4-JCA-EA-HOME?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-HOME + @ DUP
    _EXT4-JCA-EA-HOME ! DUP 0< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-ACTION + @ DUP
    _EXT4-JCA-EA-ACTION ! DUP 0< IF 2DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @ DUP
    _EXT4-JCA-EA-REFCOUNT ! DUP 0< IF 2DROP DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-CRC + @ DUP
    _EXT4-JCA-EA-CRC ! DUP 0< OVER 0xFFFFFFFF U> OR IF
        2DROP 2DROP FALSE EXIT
    THEN
    2DROP 2DROP
    _EXT4-JCA-EA-HOME @ 0= IF
        _EXT4-JCA-EA-ACTION @ _EXT4-JEA-NONE =
        _EXT4-JCA-EA-REFCOUNT @ 0= AND
        _EXT4-JCA-EA-CRC @ 0= AND EXIT
    THEN
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = IF
        _EXT4-JCA-EA-REFCOUNT @
        _EXT4-JCA-EA-CRC @ OR IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-EA-ACTION @ _EXT4-JEA-REFDEC <> IF FALSE EXIT THEN
        _EXT4-JCA-EA-REFCOUNT @ DUP 0= IF DROP FALSE EXIT THEN
        _EXT4-XATTR-REFCOUNT-MAX U< 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-EA-HOME @
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.FIRST + @ U< IF DROP FALSE EXIT THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF DROP FALSE EXIT THEN
    DROP
    _EXT4-JCA-RANGE-COUNT @ 0 ?DO
        _EXT4-JCA-EA-HOME @ 1
        I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE
        DUP @ SWAP CELL+ @ _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

\ A deletion's data vector is the runs a release pass freed with it, or
\ nothing at all once release passes have emptied the map.  The target's
\ entry count is the vector's run count.
: _EXT4-JCA-DELETE-DATA-MAP?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @ DUP
    _EXT4-JCA-DATA-MAP-KIND !
    _EXT4-JCA-TARGET-ENTRIES @ _EXT4-JCA-RANGE-COUNT @ <> IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JDM-RELEASED = IF DROP TRUE EXIT THEN
    _EXT4-JDM-NONE = _EXT4-JCA-RANGE-COUNT @ 0= AND ;

: _EXT4-JCA-REVOKE-ENTRY?  ( index home -- flag )
    _EXT4-JCA-REVOKE-HOME ! _EXT4-JCA-REVOKE-INDEX !
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JCA-REVOKE-INDEX @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * +
    DUP @ _EXT4-JCA-REVOKE-HOME @ =
    SWAP CELL+ @ _EXT4-JE-ACTIVE = AND ;

\ True when BLOCK lies inside one of the certificate's delete ranges.
: _EXT4-JCA-IN-RANGES?  ( block -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ 0 ?DO
        DUP I _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGE
        DUP @ ROT SWAP - SWAP CELL+ @ U< IF
            DROP TRUE UNLOOP EXIT
        THEN
    LOOP
    DROP FALSE ;

\ A released vector's revokes are the tree nodes the release freed, each
\ inside one of its runs, then a released xattr block.  The staging proof
\ bound every freed run to the target's map.
: _EXT4-JCA-RELEASED-REVOKES?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U>
    OVER _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> OR IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = IF
        DUP 0= IF DROP FALSE EXIT THEN
        1- DUP _EXT4-JCA-EA-HOME @ _EXT4-JCA-REVOKE-ENTRY? 0= IF
            DROP FALSE EXIT
        THEN
    THEN
    0 ?DO
        _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
        I _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * +
        DUP CELL+ @ _EXT4-JE-ACTIVE <> IF DROP FALSE UNLOOP EXIT THEN
        @ _EXT4-JCA-IN-RANGES? 0= IF FALSE UNLOOP EXIT THEN
    LOOP
    TRUE ;

\ Bind generic revoke storage back to the deletion authority retained in
\ the checkpoint certificate: a released xattr block alone, or after it the
\ revokes of the release pass a deletion folded into.
: _EXT4-JCA-DELETE-REVOKES?  ( -- flag )
    _EXT4-JCA-DATA-MAP-KIND @ _EXT4-JDM-RELEASED = IF
        _EXT4-JCA-RELEASED-REVOKES? EXIT
    THEN
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = 1 AND
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <>
    OVER _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @ <> OR
    SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
        FALSE EXIT
    THEN
    _EXT4-JCA-EA-ACTION @ _EXT4-JEA-RELEASE = IF
        0 _EXT4-JCA-EA-HOME @ _EXT4-JCA-REVOKE-ENTRY? 0= IF
            FALSE EXIT
        THEN
    THEN
    TRUE ;

: _EXT4-JCPM-ORPHAN-MODERN?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-FINAL =
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-MODERN-RELEASE = OR ;

: _EXT4-JCPM-ORPHAN-LEGACY?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-LEGACY-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-RELEASE = OR ;

: _EXT4-JCPM-ORPHAN-DELETE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN-DATA-DELETE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

: _EXT4-JCPM-ORPHAN-FINAL?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR ;

: _EXT4-JCPM-ORPHAN-MORE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-MORE =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE = OR ;

\ A release pass frees part of a linked record's storage and keeps the
\ record, so the union it leaves is the union it found.
: _EXT4-JCPM-ORPHAN-RELEASE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-RELEASE =
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-RELEASE = OR ;

: _EXT4-JCPM-ORPHAN?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-FINAL?
    OVER _EXT4-JCPM-ORPHAN-MORE? OR
    SWAP _EXT4-JCPM-ORPHAN-RELEASE? OR ;

: _EXT4-JCPM-ORPHAN-ADD-FIRST?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-ADD-FIRST =
    SWAP _EXT4-JCPM-ORPHAN-MODERN-UNLINK-ADD-FIRST = OR ;

: _EXT4-JCPM-ORPHAN-ADD?  ( mode -- flag )  _EXT4-JCPM-ORPHAN-ADD-FIRST? ;

: _EXT4-JCPM-ORPHAN-UNLINK-ADD?  ( mode -- flag )
    _EXT4-JCPM-ORPHAN-MODERN-UNLINK-ADD-FIRST = ;

\ The namespace payload only a final-link unlink ADD seals.
: _EXT4-JWR-CP-UNLINK-ADD-PAYLOAD-ZERO?  ( writer -- flag )
    _EXT4-JWR.CP-ADD-PARENT-INO +
    _EXT4-JWR.CP-ADD-TARGET-SIZE-LO _EXT4-JWR.CP-ADD-PARENT-INO -
    _EXT4-BYTES-ZERO? ;

\ The size every ADD seals for its target, zero in every other mode.
: _EXT4-JWR-CP-ADD-SIZE-ZERO?  ( writer -- flag )
    _EXT4-JWR.CP-ADD-TARGET-SIZE-LO +
    _EXT4-JWR-SIZE _EXT4-JWR.CP-ADD-TARGET-SIZE-LO -
    _EXT4-BYTES-ZERO? ;

\ A sealed size is a valid nonnegative 64-bit ext4 size.
: _EXT4-JWR-CP-ADD-SIZE?  ( writer -- flag )
    DUP _EXT4-JWR.CP-ADD-TARGET-SIZE-LO + @ 0xFFFFFFFF U> IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWR.CP-ADD-TARGET-SIZE-HI + @
    DUP 0xFFFFFFFF U> SWAP 0x80000000 AND 0<> OR 0= ;

VARIABLE _EXT4-JUA-PARENT-INO
VARIABLE _EXT4-JUA-PARENT-GEN
VARIABLE _EXT4-JUA-PARENT-HOME
VARIABLE _EXT4-JUA-PARENT-OFF
VARIABLE _EXT4-JUA-DIR-HOME
VARIABLE _EXT4-JUA-TARGET-OFF
VARIABLE _EXT4-JUA-TARGET-REC
VARIABLE _EXT4-JUA-PREV-OFF
VARIABLE _EXT4-JUA-PREV-REC
VARIABLE _EXT4-JUA-SIZE-LO
VARIABLE _EXT4-JUA-SIZE-HI
VARIABLE _EXT4-JUA-META
VARIABLE _EXT4-JUA-SOURCE-INO
VARIABLE _EXT4-JUA-SOURCE-GEN
VARIABLE _EXT4-JUA-SOURCE-HOME
VARIABLE _EXT4-JUA-SOURCE-OFF
VARIABLE _EXT4-JUA-OLD-PARENT-INO
VARIABLE _EXT4-JUA-OLD-PARENT-GEN
VARIABLE _EXT4-JUA-OLD-PARENT-HOME
VARIABLE _EXT4-JUA-OLD-PARENT-OFF
VARIABLE _EXT4-JUA-OLD-DIR-HOME
VARIABLE _EXT4-JUA-OLD-SOURCE-OFF
VARIABLE _EXT4-JUA-OLD-SOURCE-REC
VARIABLE _EXT4-JUA-OLD-PREV-OFF
VARIABLE _EXT4-JUA-OLD-PREV-REC
VARIABLE _EXT4-JUA-CHILD-HOME

\ An unlink seals the payload's rename form as zeros.
: _EXT4-JUA-CLEAR-RENAME  ( -- )
    0 _EXT4-JUA-SOURCE-INO ! 0 _EXT4-JUA-SOURCE-GEN !
    0 _EXT4-JUA-SOURCE-HOME ! 0 _EXT4-JUA-SOURCE-OFF !
    0 _EXT4-JUA-OLD-PARENT-INO ! 0 _EXT4-JUA-OLD-PARENT-GEN !
    0 _EXT4-JUA-OLD-PARENT-HOME ! 0 _EXT4-JUA-OLD-PARENT-OFF !
    0 _EXT4-JUA-OLD-DIR-HOME !
    0 _EXT4-JUA-OLD-SOURCE-OFF ! 0 _EXT4-JUA-OLD-SOURCE-REC !
    0 _EXT4-JUA-OLD-PREV-OFF ! 0 _EXT4-JUA-OLD-PREV-REC !
    0 _EXT4-JUA-CHILD-HOME ! ;

\ An inode a namespace payload names: the root or an ordinary inode, and
\ never the orphan's target.
: _EXT4-JCA-NAMESPACE-INODE?  ( inode-number -- flag )
    DUP 2 <>
    OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< AND IF DROP FALSE EXIT THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.INODES + @ U>
    SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-INO + @ = OR 0= ;

\ An inode record's table block lies in the volume and the record in it.
: _EXT4-JCA-INODE-HOME?  ( home offset -- flag )
    DUP 0< IF 2DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.ISIZE + @ -
    U> IF DROP FALSE EXIT THEN
    DUP 0< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< ;

\ A directory block lies past the volume's first data block.
: _EXT4-JCA-DIR-HOME?  ( home -- flag )
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.FIRST + @ U< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< ;

\ A record length covers a header, keeps four-byte alignment and fits its
\ sixteen-bit field.
: _EXT4-JCA-REC?  ( rec -- flag )
    DUP 12 U< OVER 0xFFFF U> OR SWAP 3 AND 0<> OR 0= ;

\ A record ends at or before the block's dirent tail.
: _EXT4-JCA-RECORD-IN-BLOCK?  ( offset rec -- flag )
    _EXT4-UADD? IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 12 - U> 0= ;

\ A removed record and the predecessor that absorbs it: both records are
\ well formed, adjacent, and inside the block.
: _EXT4-JCA-SPLICE?  ( prev-offset prev-rec offset rec -- flag )
    DUP _EXT4-JCA-REC? 0= IF 2DROP 2DROP FALSE EXIT THEN
    2 PICK _EXT4-JCA-REC? 0= IF 2DROP 2DROP FALSE EXIT THEN
    OVER 0< 4 PICK 0< OR IF 2DROP 2DROP FALSE EXIT THEN
    OVER SWAP _EXT4-JCA-RECORD-IN-BLOCK? 0= IF
        2DROP DROP FALSE EXIT
    THEN
    >R _EXT4-UADD? IF R> 2DROP FALSE EXIT THEN
    R> = ;

\ A removed record, joined to its predecessor or, as the first record of
\ its block, left unused.  The first record's form names a predecessor of
\ no length at offset zero, which no splice can, since a record covers at
\ least a header.
: _EXT4-JCA-REMOVAL?  ( prev-offset prev-rec offset rec -- flag )
    2 PICK IF _EXT4-JCA-SPLICE? EXIT THEN
    DUP _EXT4-JCA-REC? 0= IF 2DROP 2DROP FALSE EXIT THEN
    0 SWAP _EXT4-JCA-RECORD-IN-BLOCK? 0= IF 2DROP DROP FALSE EXIT THEN
    OR OR 0= ;

\ The rename form of the payload: a rename over the target hands its record
\ to the source, whose own record leaves its block as a removal's does,
\ joined to its predecessor or, as the block's first record, left unused, in
\ the target's directory or, across directories, in the old parent's.  A
\ directory that changes parent also names the new parent in its block 0,
\ the child home.  Every inode home may share a table block with the others;
\ every directory home is distinct from them, from the orphan block and from
\ the primary super, so the exact deduplicated credit is between five and
\ nine metadata images.
: _EXT4-JWR-CP-RENAME-PAYLOAD?  ( -- flag )
    _EXT4-JUA-PREV-OFF @ _EXT4-JUA-PREV-REC @ OR IF FALSE EXIT THEN
    _EXT4-JUA-TARGET-OFF @ _EXT4-JUA-TARGET-REC @
    _EXT4-JCA-RECORD-IN-BLOCK? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SOURCE-INO + @
    DUP _EXT4-JUA-SOURCE-INO !
    DUP _EXT4-JCA-NAMESPACE-INODE? 0= IF DROP FALSE EXIT THEN
    DUP 2 = OVER _EXT4-JUA-PARENT-INO @ = OR IF DROP FALSE EXIT THEN
    DROP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SOURCE-GEN + @ DUP
    _EXT4-JUA-SOURCE-GEN ! 0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SOURCE-HOME + @
    DUP _EXT4-JUA-SOURCE-HOME !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SOURCE-OFF + @
    DUP _EXT4-JUA-SOURCE-OFF !
    _EXT4-JCA-INODE-HOME? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-PARENT-INO + @
    DUP _EXT4-JUA-OLD-PARENT-INO !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-PARENT-GEN + @
    _EXT4-JUA-OLD-PARENT-GEN !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-PARENT-HOME + @
    _EXT4-JUA-OLD-PARENT-HOME !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-PARENT-OFF + @
    _EXT4-JUA-OLD-PARENT-OFF !
    IF
        _EXT4-JUA-OLD-PARENT-INO @ DUP _EXT4-JCA-NAMESPACE-INODE? 0=
        OVER _EXT4-JUA-PARENT-INO @ = OR
        SWAP _EXT4-JUA-SOURCE-INO @ = OR IF FALSE EXIT THEN
        _EXT4-JUA-OLD-PARENT-GEN @ 0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-OLD-PARENT-OFF @
        _EXT4-JCA-INODE-HOME? 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JUA-OLD-PARENT-GEN @ _EXT4-JUA-OLD-PARENT-HOME @ OR
        _EXT4-JUA-OLD-PARENT-OFF @ OR IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-DIR-HOME + @
    DUP _EXT4-JUA-OLD-DIR-HOME !
    _EXT4-JCA-DIR-HOME? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-DIR-SOURCE-OFF + @
    _EXT4-JUA-OLD-SOURCE-OFF !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-DIR-SOURCE-REC + @
    _EXT4-JUA-OLD-SOURCE-REC !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-DIR-PREV-OFF + @
    _EXT4-JUA-OLD-PREV-OFF !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-OLD-DIR-PREV-REC + @
    _EXT4-JUA-OLD-PREV-REC !
    _EXT4-JUA-OLD-PREV-OFF @ _EXT4-JUA-OLD-PREV-REC @
    _EXT4-JUA-OLD-SOURCE-OFF @ _EXT4-JUA-OLD-SOURCE-REC @
    _EXT4-JCA-REMOVAL? 0= IF FALSE EXIT THEN
    \ One block holds both records only inside one parent, and the source's
    \ record never overlaps the target's.
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JUA-DIR-HOME @ = IF
        _EXT4-JUA-OLD-PARENT-INO @ IF FALSE EXIT THEN
        _EXT4-JUA-OLD-SOURCE-OFF @ _EXT4-JUA-OLD-SOURCE-REC @ +
        _EXT4-JUA-TARGET-OFF @ U> 0=
        _EXT4-JUA-TARGET-OFF @ _EXT4-JUA-TARGET-REC @ +
        _EXT4-JUA-OLD-SOURCE-OFF @ U> 0= OR 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JUA-PARENT-HOME @ =
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JUA-SOURCE-HOME @ = OR
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JUA-OLD-PARENT-HOME @ = OR
    _EXT4-JUA-OLD-DIR-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ = OR
    _EXT4-JUA-OLD-DIR-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
    _EXT4-JUA-OLD-DIR-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = OR
    _EXT4-JUA-DIR-HOME @ _EXT4-JUA-SOURCE-HOME @ = OR
    _EXT4-JUA-DIR-HOME @ _EXT4-JUA-OLD-PARENT-HOME @ = OR
    _EXT4-JUA-SOURCE-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
    _EXT4-JUA-SOURCE-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
    _EXT4-JUA-OLD-PARENT-INO @ IF
        _EXT4-JUA-OLD-PARENT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ =
        _EXT4-JUA-OLD-PARENT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
    THEN
    _EXT4-JUA-SOURCE-HOME @ _EXT4-JCA-RANGES-ALIAS-HOME?
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JCA-RANGES-ALIAS-HOME? OR
    _EXT4-JUA-OLD-PARENT-INO @ IF
        _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JCA-RANGES-ALIAS-HOME? OR
    THEN IF FALSE EXIT THEN
    _EXT4-JCA-EA-HOME @ ?DUP IF
        DUP _EXT4-JUA-SOURCE-HOME @ =
        OVER _EXT4-JUA-OLD-DIR-HOME @ = OR
        SWAP _EXT4-JUA-OLD-PARENT-HOME @ = OR IF FALSE EXIT THEN
    THEN
    \ Only a move across parents names a child home, which is no other home.
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-CHILD-HOME + @
    DUP _EXT4-JUA-CHILD-HOME ! ?DUP IF
        _EXT4-JUA-OLD-PARENT-INO @ 0= IF DROP FALSE EXIT THEN
        DUP _EXT4-JCA-DIR-HOME? 0= IF DROP FALSE EXIT THEN
        DUP _EXT4-JUA-PARENT-HOME @ =
        OVER _EXT4-JUA-SOURCE-HOME @ = OR
        OVER _EXT4-JUA-OLD-PARENT-HOME @ = OR
        OVER _EXT4-JUA-DIR-HOME @ = OR
        OVER _EXT4-JUA-OLD-DIR-HOME @ = OR
        OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ = OR
        OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
        OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK = OR
        OVER _EXT4-JCA-RANGES-ALIAS-HOME? OR
        SWAP _EXT4-JCA-EA-HOME @ = OR IF FALSE EXIT THEN
    THEN
    \ The orphan block, the primary super, the target's table block and the
    \ target's directory block, then each further distinct home.
    4 _EXT4-JUA-META !
    _EXT4-JUA-CHILD-HOME @ IF 1 _EXT4-JUA-META +! THEN
    _EXT4-JUA-PARENT-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <> IF
        1 _EXT4-JUA-META +!
    THEN
    _EXT4-JUA-SOURCE-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <>
    _EXT4-JUA-SOURCE-HOME @ _EXT4-JUA-PARENT-HOME @ <> AND IF
        1 _EXT4-JUA-META +!
    THEN
    _EXT4-JUA-OLD-PARENT-INO @ IF
        _EXT4-JUA-OLD-PARENT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <>
        _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-PARENT-HOME @ <> AND
        _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-SOURCE-HOME @ <> AND IF
            1 _EXT4-JUA-META +!
        THEN
    THEN
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JUA-DIR-HOME @ <> IF
        1 _EXT4-JUA-META +!
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JUA-META @ =
    _EXT4-JCA-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JUA-META @ = AND
    _EXT4-JCA-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JUA-META @ = AND ;

\ Validate the mode-discriminated namespace payload retained by a final-link
\ orphan ADD.  A removal's form takes the target's record out of its block:
\ the record joins its predecessor, or as a block's first record becomes
\ unused.  The target's inode type distinguishes RMDIR's form from
\ UNLINK's when the checkpoint rebuilds the after-images.  Target and
\ parent inode records may share one inode-table block; every other home
\ is distinct, and the exact deduplicated credit is therefore four or five
\ metadata images.  A rename over the target seals the rename form instead.
: _EXT4-JWR-CP-UNLINK-ADD-PAYLOAD?  ( -- flag )
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-UNLINK-ADD? 0= IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-PARENT-INO + @
    DUP _EXT4-JUA-PARENT-INO !
    _EXT4-JCA-NAMESPACE-INODE? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-PARENT-GEN + @ DUP
    _EXT4-JUA-PARENT-GEN ! 0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-PARENT-HOME + @
    DUP _EXT4-JUA-PARENT-HOME !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-PARENT-OFF + @
    DUP _EXT4-JUA-PARENT-OFF !
    _EXT4-JCA-INODE-HOME? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-DIR-HOME + @
    DUP _EXT4-JUA-DIR-HOME !
    _EXT4-JCA-DIR-HOME? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-DIR-TARGET-OFF + @
    DUP _EXT4-JUA-TARGET-OFF ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-DIR-TARGET-REC + @
    DUP _EXT4-JUA-TARGET-REC !
    _EXT4-JCA-REC? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-DIR-PREV-OFF + @
    _EXT4-JUA-PREV-OFF !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-DIR-PREV-REC + @
    _EXT4-JUA-PREV-REC !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-LO + @
    DUP _EXT4-JUA-SIZE-LO ! 0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-HI + @
    DUP _EXT4-JUA-SIZE-HI !
    DUP 0xFFFFFFFF U> SWAP 0x80000000 AND 0<> OR IF FALSE EXIT THEN
    _EXT4-JUA-PARENT-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ =
    _EXT4-JUA-PARENT-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = OR
    _EXT4-JUA-PARENT-HOME @ _EXT4-JUA-DIR-HOME @ = OR
    _EXT4-JUA-DIR-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ = OR
    _EXT4-JUA-DIR-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
    _EXT4-JUA-DIR-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
    _EXT4-JUA-PARENT-HOME @ _EXT4-JCA-RANGES-ALIAS-HOME?
    _EXT4-JUA-DIR-HOME @ _EXT4-JCA-RANGES-ALIAS-HOME? OR IF
        FALSE EXIT
    THEN
    _EXT4-JCA-EA-HOME @ ?DUP IF
        DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ =
        OVER _EXT4-JUA-PARENT-HOME @ = OR
        OVER _EXT4-JUA-DIR-HOME @ = OR
        OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
        SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SOURCE-INO + @ IF
        _EXT4-JWR-CP-RENAME-PAYLOAD? EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SOURCE-INO +
    _EXT4-JWR.CP-ADD-TARGET-SIZE-LO _EXT4-JWR.CP-ADD-SOURCE-INO -
    _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
    _EXT4-JUA-PREV-OFF @ _EXT4-JUA-PREV-REC @
    _EXT4-JUA-TARGET-OFF @ _EXT4-JUA-TARGET-REC @
    _EXT4-JCA-REMOVAL? 0= IF FALSE EXIT THEN
    4 _EXT4-JUA-META !
    _EXT4-JUA-PARENT-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <> IF
        1 _EXT4-JUA-META +!
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JUA-META @ =
    _EXT4-JCA-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JUA-META @ = AND
    _EXT4-JCA-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JUA-META @ = AND ;

\ Add certificates describe exact transitions from the empty union to one
\ record.  Keep them separate from cleanup's union-minus-one modes: before
\ checkpoint the chosen raw slot is zero, while after checkpoint the exact
\ inode is recoverable, and the primary super publishes ORPHAN_PRESENT.  A
\ truncate's insertion seals its target's new size; a final-link unlink's
\ seals its namespace payload.
: _EXT4-JWR-CP-ADD-AUTHORITY?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.EPOCH + @ <> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-INO + @ DUP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.INODES + @ U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0< IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 8 - 4 / U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ DUP 0< IF
        2DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF 2DROP FALSE EXIT THEN
    2DUP = IF
        2DROP FALSE EXIT
    THEN
    DUP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = IF 2DROP FALSE EXIT THEN
    OVER
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = IF 2DROP FALSE EXIT THEN
    2DROP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U> IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.ISIZE + @ U< IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-GEN + @ 0xFFFFFFFF U>
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ 0xFFFFFFFF U> OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ 0xFFFFFFFF U> OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ 0xFFFFFFFF U> OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SUPER-CRC + @
    0xFFFFFFFF U> OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ DUP
    0< IF DROP FALSE EXIT THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-UNLINK-ADD? 0= IF
        DUP _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> IF
            DROP FALSE EXIT
        THEN
    THEN
    _EXT4-JCA-TARGET-ENTRIES !
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-UNLINK-ADD? IF
        _EXT4-JCA-DATA-RANGES? 0= IF FALSE EXIT THEN
        _EXT4-JCA-EA-HOME? 0= IF FALSE EXIT THEN
        \ An unlink binds no release vector, as a truncate's insertion
        \ binds none: release passes free the file's blocks, and its
        \ deletion then frees an empty map.
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @ _EXT4-JDM-NONE <>
        _EXT4-JCA-RANGE-COUNT @ OR _EXT4-JCA-TARGET-ENTRIES @ OR IF
            FALSE EXIT
        THEN
    ELSE
        \ A truncate ADD binds no release vector: each later release pass
        \ proves the runs it frees.
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES-ZERO? 0= IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT +
        _EXT4-JWR.CP-PRE-ACTIVE _EXT4-JWR.CP-DELETE-RANGE-COUNT -
        _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-ACTION +
        _EXT4-JWR.CP-ADD-PARENT-INO _EXT4-JWR.CP-EA-ACTION -
        _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
        0 _EXT4-JCA-RANGE-COUNT ! 0 _EXT4-JCA-EA-HOME !
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCA-RANGES-ALIAS-HOME? IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @
    _EXT4-JCA-RANGES-ALIAS-HOME? IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCA-RANGES-ALIAS-HOME? IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-SECONDS + @ DUP
    0< SWAP 15032385535 U> OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ADD-NSEC + @ DUP
    0< SWAP 1000000000 U< 0= OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ OR IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ DUP
    _EXT4-JCA-PRE-ACTIVE ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ DUP
    _EXT4-JCA-PRE-MODERN ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ DUP
    _EXT4-JCA-PRE-LEGACY ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-PRE-MODERN @ _EXT4-JCA-PRE-LEGACY @ _EXT4-UADD?
    DUP IF 2DROP FALSE EXIT THEN DROP
    _EXT4-JCA-PRE-ACTIVE @ <> IF FALSE EXIT THEN
    _EXT4-JCA-PRE-LEGACY @ IF FALSE EXIT THEN
    _EXT4-JCA-PRE-MODERN @ _EXT4-JCA-PRE-ACTIVE @ <> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.O.RUNTIME-CAPACITY + @ DUP 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-PRE-ACTIVE @ SWAP U< 0= IF FALSE EXIT THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-ADD-FIRST? 0= IF FALSE EXIT THEN
    _EXT4-JCA-PRE-ACTIVE @ IF FALSE EXIT THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-UNLINK-ADD? IF
        _EXT4-JWR-CP-UNLINK-ADD-PAYLOAD? 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-WRITER @
        _EXT4-JWR-CP-UNLINK-ADD-PAYLOAD-ZERO? 0= IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-ADD-SIZE? 0= IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.META-CREDIT + @ 3 <>
        _EXT4-JCA-WRITER @ _EXT4-JWR.META-USED + @ 3 <> OR
        _EXT4-JCA-WRITER @ _EXT4-JWR.META-ACTIVE + @ 3 <> OR IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.DATA-CREDIT + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.PHASE + @ DUP
        _EXT4-JWP-EMISSION? SWAP _EXT4-JWP-CHECKPOINT? OR EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = OVER _EXT4-JWR-EMITTING = OR
    OVER _EXT4-JWR-COMMITTED = OR
    SWAP _EXT4-JWR-CHECKPOINTING = OR ;

: _EXT4-JCA-REVOKES?  ( -- flag )
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCA-DELETE-REVOKES? EXIT
    THEN
    \ A linked record's release revokes each tree node it frees; its
    \ staging proof binds those nodes to the target's tree.
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN?
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? 0= AND IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @
        _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ =
        _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
        _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U> 0= AND EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JCA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR 0= ;

\ A release pass stages its target's inode and zeroes no tail.  A linked
\ final cleanup stages the target at least to clear a legacy record's
\ successor link, and may zero the bytes past EOF in one data block that is
\ none of the transaction's other homes.
: _EXT4-JCA-LINKED-HOMES?  ( -- flag )
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-PRE-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TAIL-HOME + @
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-RELEASE? IF 0= EXIT THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-LEGACY?
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0<> AND IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ 0= IF
            DROP FALSE EXIT
        THEN
    THEN
    ?DUP 0= IF TRUE EXIT THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.FIRST + @ U< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ =
    OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ = OR
    SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-PRIMARY-SUPER-BLOCK = OR 0= ;

\ An orphan-cleanup certificate is arena-owned transaction state, not a global
\ permission bit.  Its typed ranges and revoke vector are exact transaction
\ authority; raw locators and staged images are authenticated again at
\ checkpoint.
: _EXT4-JWR-CP-AUTHORITY?  ( writer -- flag )
    DUP _EXT4-JCA-WRITER !
    _EXT4-JDM-NONE _EXT4-JCA-DATA-MAP-KIND !
    _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCA-MODE ! _EXT4-JCPM-NONE = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH +
        _EXT4-JWR-SIZE _EXT4-JWR.CP-EPOCH - _EXT4-BYTES-ZERO?
        _EXT4-JCA-WRITER @ _EXT4-JWR-CP-DELETE-RANGES-ZERO? AND EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-ADD? IF
        _EXT4-JWR-CP-ADD-AUTHORITY? EXIT
    THEN
    _EXT4-JCA-WRITER @
    _EXT4-JWR-CP-UNLINK-ADD-PAYLOAD-ZERO? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR-CP-ADD-SIZE-ZERO? 0= IF FALSE EXIT THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.EPOCH + @ <> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-INO + @ DUP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.INODES + @ U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0< IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ DUP 0< IF
            DROP FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 8 - 4 / U< 0= IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ ?DUP IF
            DUP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
            _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
                DROP FALSE EXIT
            THEN
            _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
            _EXT4-C.INODES + @ U> IF FALSE EXIT THEN
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK <> IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-TARGET-HOME !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
    _EXT4-JCA-TARGET-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-GEN + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @
    DUP 0< OVER _EXT4-JCA-WRITER @
    _EXT4-JWR.CP-DELETE-RANGE-CAP + @ U> OR IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-TARGET-ENTRIES !
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE? IF
        _EXT4-JCA-DATA-RANGES? 0= IF FALSE EXIT THEN
        _EXT4-JCA-RANGE-COUNT @ 0= IF FALSE EXIT THEN
        _EXT4-JCA-EA-HOME? 0= IF FALSE EXIT THEN
        _EXT4-JCA-DELETE-DATA-MAP? 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
            _EXT4-JCA-TARGET-ENTRIES @ IF FALSE EXIT THEN
            _EXT4-JCA-DATA-RANGES? 0= IF FALSE EXIT THEN
            _EXT4-JCA-RANGE-COUNT @ IF FALSE EXIT THEN
            _EXT4-JCA-EA-HOME? 0= IF FALSE EXIT THEN
            _EXT4-JCA-DELETE-DATA-MAP? 0= IF FALSE EXIT THEN
        ELSE
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @
            _EXT4-JDM-NONE <> IF FALSE EXIT THEN
            _EXT4-JCA-TARGET-ENTRIES @
            _EXT4-RESIDENT-EXTENT-ENTRY-MAX U> IF FALSE EXIT THEN
            _EXT4-JCA-LINKED-HOMES? 0= IF FALSE EXIT THEN
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-HOME + @
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-ACTION + @ OR
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @ OR
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EA-CRC + @ OR IF
                FALSE EXIT
            THEN
        THEN
    THEN
    _EXT4-JCA-REVOKES? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U< 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.ISIZE + @ U< IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ DUP
        _EXT4-JCA-BITMAP-HOME ! DUP 0< IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JCA-BITMAP-HOME @ _EXT4-JCA-TARGET-HOME @ =
        _EXT4-JCA-BITMAP-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ DUP
        _EXT4-JCA-GDT-HOME ! DUP 0< IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JCA-GDT-HOME @ _EXT4-JCA-BITMAP-HOME @ =
        _EXT4-JCA-GDT-HOME @ _EXT4-JCA-TARGET-HOME @ = OR
        _EXT4-JCA-GDT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-BITMAP-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK =
        _EXT4-JCA-GDT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
        _EXT4-JCA-EA-HOME @ ?DUP IF
            DUP _EXT4-JCA-TARGET-HOME @ =
            OVER _EXT4-JCA-BITMAP-HOME @ = OR
            OVER _EXT4-JCA-GDT-HOME @ = OR
            OVER _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR
            SWAP _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
            _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ DUP 0< IF
            DROP FALSE EXIT
        THEN
        DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U< 0= IF
            DROP FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
        _EXT4-DESC-SIZE U< IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE? 0= IF
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT +
            _EXT4-JWR.CP-EA-HOME _EXT4-JWR.CP-DELETE-RANGE-COUNT -
            _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
        THEN
    ELSE
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME +
        _EXT4-JWR.CP-PRE-ACTIVE _EXT4-JWR.CP-INODE-GDT-HOME -
        _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ DUP
    _EXT4-JCA-PRE-ACTIVE ! DUP 0< SWAP 0= OR IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ DUP
    _EXT4-JCA-PRE-MODERN ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ DUP
    _EXT4-JCA-PRE-LEGACY ! 0< IF FALSE EXIT THEN
    _EXT4-JCA-PRE-MODERN @ _EXT4-JCA-PRE-ACTIVE @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-PRE-LEGACY @ _EXT4-JCA-PRE-ACTIVE @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-PRE-MODERN @ _EXT4-JCA-PRE-LEGACY @ _EXT4-UADD?
    DUP IF 2DROP FALSE EXIT THEN DROP
    _EXT4-JCA-PRE-ACTIVE @ <> IF FALSE EXIT THEN
    _EXT4-JCA-PRE-ACTIVE @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.INODES + @ U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCA-PRE-MODERN @ 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-PRE-LEGACY @ 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-FINAL? IF
        _EXT4-JCA-PRE-ACTIVE @ 1 <> IF FALSE EXIT THEN
    ELSE _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MORE? IF
        _EXT4-JCA-PRE-ACTIVE @ 1 U> 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-RELEASE? 0= IF FALSE EXIT THEN
    THEN THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.PHASE + @ DUP
        _EXT4-JWP-EMISSION? SWAP _EXT4-JWP-CHECKPOINT? OR EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = OVER _EXT4-JWR-EMITTING = OR
    OVER _EXT4-JWR-COMMITTED = OR
    SWAP _EXT4-JWR-CHECKPOINTING = OR ;

: _EXT4-JWR-RUNTIME?  ( writer -- flag )
    DUP _EXT4-JWV-WRITER !
    _EXT4-JWR.STATE + @ DUP _EXT4-JWV-STATE !
    DUP 0< SWAP _EXT4-JWR-DEACTIVATING U> OR IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.PHASE + @ _EXT4-JWV-PHASE !
    _EXT4-JWV-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF FALSE EXIT THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED = IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.FAULT + @ 0= IF FALSE EXIT THEN
        _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
        _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? OR
        _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? OR
        _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR 0= IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JWV-WRITER @ _EXT4-JWR.FAULT + @ IF FALSE EXIT THEN
        _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION? 0= IF FALSE EXIT THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-EMITTING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? 0= IF FALSE EXIT THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-CHECKPOINTING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? 0= IF
                FALSE EXIT
            THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? 0= IF
                FALSE EXIT
            THEN
        ELSE
            _EXT4-JWV-PHASE @ IF FALSE EXIT THEN
        THEN THEN THEN THEN
    THEN
    0 _EXT4-JWV-COMMITTED-SHAPE !
    _EXT4-JWV-STATE @ _EXT4-JWR-COMMITTED =
    _EXT4-JWV-STATE @ _EXT4-JWR-CHECKPOINTING = OR
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? AND OR IF
        -1 _EXT4-JWV-COMMITTED-SHAPE !
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING =
    _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = OR IF
        _EXT4-JWV-WRITER @ _EXT4-JWR-TRANSACTION-CLEAN? 0= IF
            FALSE EXIT
        THEN
    ELSE _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
        _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
        _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR AND IF
            _EXT4-JWV-WRITER @ _EXT4-JWR-TRANSACTION-CLEAN? 0= IF
                FALSE EXIT
            THEN
        THEN
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ - 1-
    _EXT4-JWV-RING-CAP !
    _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @
    _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TAIL + @
    _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @
    0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @
    0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
    _EXT4-JWV-COMMITTED-SHAPE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-NEXT
        <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.SEQUENCE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.HEAD + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.ANCHOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.CURSOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.COMMITTED + @
        1 <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.NEXT-SEQUENCE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
        0xFFFFFFFF AND <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.WITNESS + @ DUP IF
            _EXT4-JW-RECOVERY <> IF FALSE EXIT THEN
            _EXT4-JWV-PHASE @
            _EXT4-JWP-CHECKPOINT-WITNESS-CLEAR < IF FALSE EXIT THEN
        ELSE
            DROP
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.PRIMARY-TORN + @ IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.SUPER-TORN + @ IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.START + @ IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-IDLE = IF
        _EXT4-JWV-WRITER @ _EXT4-JWR-IDLE-CLEAN? EXIT
    THEN
    0 _EXT4-JWV-TX-ACTIVE !
    _EXT4-JWV-STATE @ _EXT4-JWR-STAGING =
    _EXT4-JWV-STATE @ _EXT4-JWR-EMITTING = OR IF
        -1 _EXT4-JWV-TX-ACTIVE !
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? AND IF
        -1 _EXT4-JWV-TX-ACTIVE !
    THEN
    _EXT4-JWV-TX-ACTIVE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR-RESERVATION? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
        TRUE EXIT
    THEN
    _EXT4-JWV-COMMITTED-SHAPE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR-ACTUAL-RESERVATION? 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TAIL + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-ADVANCE
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ 1+
        0xFFFFFFFF AND
        _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
        TRUE EXIT
    THEN
    \ The only remaining states are activation/deactivation, or a fault in one
    \ of those clean-transaction protocols, whose invariant was proved above.
    _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING =
    _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = OR
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
    _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR AND OR ;

: _EXT4-JWR-VALID?  ( writer -- flag )
    DUP _EXT4-JWR-SHAPE? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWR-RUNTIME? ;

VARIABLE _EXT4-JWN-META
VARIABLE _EXT4-JWN-DATA
VARIABLE _EXT4-JWN-REVOKE
VARIABLE _EXT4-JWN-CTX
VARIABLE _EXT4-JWN-BSIZE
VARIABLE _EXT4-JWN-MAXLEN
VARIABLE _EXT4-JWN-FIRST
VARIABLE _EXT4-JWN-HEAD
VARIABLE _EXT4-JWN-FREE
VARIABLE _EXT4-JWN-BYTES
VARIABLE _EXT4-JWN-IOR
VARIABLE _EXT4-JWN-WRITER
VARIABLE _EXT4-JWN-CURSOR

: _EXT4-JWR-MATCH?  ( writer -- flag )
    DUP _EXT4-JWR-VALID? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-JWN-CTX @ =
    OVER _EXT4-JWR.BSIZE + @ _EXT4-JWN-BSIZE @ = AND
    OVER _EXT4-JWR.MAXLEN + @ _EXT4-JWN-MAXLEN @ = AND
    OVER _EXT4-JWR.FIRST + @ _EXT4-JWN-FIRST @ = AND
    OVER _EXT4-JWR.META-CAP + @ _EXT4-JWN-META @ U< 0= AND
    OVER _EXT4-JWR.DATA-CAP + @ _EXT4-JWN-DATA @ U< 0= AND
    SWAP _EXT4-JWR.REVOKE-CAP + @ _EXT4-JWN-REVOKE @ U< 0= AND ;

: _EXT4-JWR-ZERO-OWNED  ( writer -- )
    DUP _EXT4-JWR.META-ENTRIES + @
    OVER _EXT4-JWR.META-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.DATA-ENTRIES + @
    OVER _EXT4-JWR.DATA-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.REVOKE-ENTRIES + @
    OVER _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.META-HASH + @
    OVER _EXT4-JWR.META-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.DATA-HASH + @
    OVER _EXT4-JWR.DATA-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.REVOKE-HASH + @
    OVER _EXT4-JWR.REVOKE-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.META-IMAGES + @
    OVER _EXT4-JWR.META-CAP + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.DATA-IMAGES + @
    OVER _EXT4-JWR.DATA-CAP + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.SCRATCH-A + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JWR-ZERO-CP-DELETE-RANGES ;

: _EXT4-JWR-REBASE-IDLE  ( writer -- writer )
    DUP _EXT4-JWR-ZERO-OWNED
    DUP _EXT4-JWR-CLEAR-CP-AUTHORITY
    0 OVER _EXT4-JWR.META-CREDIT + !
    0 OVER _EXT4-JWR.DATA-CREDIT + !
    0 OVER _EXT4-JWR.REVOKE-CREDIT + !
    0 OVER _EXT4-JWR.META-USED + !
    0 OVER _EXT4-JWR.DATA-USED + !
    0 OVER _EXT4-JWR.REVOKE-USED + !
    0 OVER _EXT4-JWR.META-ACTIVE + !
    0 OVER _EXT4-JWR.DATA-ACTIVE + !
    0 OVER _EXT4-JWR.REVOKE-ACTIVE + !
    0 OVER _EXT4-JWR.LOG-RESERVED + !
    0 OVER _EXT4-JWR.TX-START + !
    0 OVER _EXT4-JWR.TX-CURSOR + !
    0 OVER _EXT4-JWR.TX-TID + !
    0 OVER _EXT4-JWR.PHASE + !
    _EXT4-JWN-HEAD @ DUP 2 PICK _EXT4-JWR.HEAD + !
    OVER _EXT4-JWR.TAIL + !
    _EXT4-JWN-FREE @ OVER _EXT4-JWR.FREE + !
    _EXT4-JWN-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    OVER _EXT4-JWR.NEXT-TID + ! ;

\ Validate and retain one requested capacity tuple in the shared constructor
\ state.  Allocation policy is deliberately separate: production profiles use
\ a fresh dedicated arena, while pre-publication recovery uses a scoped tail
\ allocation from the ordinary mount arena.
: _EXT4-JWR-PREPARE  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JWN-CTX ! _EXT4-JWN-REVOKE !
    _EXT4-JWN-DATA ! _EXT4-JWN-META !
    _EXT4-JWN-CTX @ _EXT4-JWR-CONTEXT? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JWN-CTX @ _EXT4-C.BSIZE + @ _EXT4-JWN-BSIZE !
    _EXT4-JWN-META @ _EXT4-JWN-DATA @ _EXT4-JWN-REVOKE @
    _EXT4-JWN-BSIZE @
    _EXT4-JWR-MEASURE _EXT4-JWN-IOR ! _EXT4-JWN-BYTES !
    _EXT4-JWN-IOR @ ?DUP IF EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.MAXLEN + @ _EXT4-JWN-MAXLEN !
    _EXT4-JWN-CTX @ _EXT4-C.J.FIRST + @ _EXT4-JWN-FIRST !
    _EXT4-JWN-MAXLEN @ _EXT4-JWN-FIRST @ - DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN
    1- _EXT4-JWN-FREE !
    _EXT4-JWN-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JWN-FIRST @
    ELSE
        DUP _EXT4-JWN-FIRST @ U<
        OVER _EXT4-JWN-MAXLEN @ U< 0= OR IF
            DROP VFS-E-INVALID EXIT
        THEN
    THEN _EXT4-JWN-HEAD ! 0 ;

\ Construct one complete writer layout at an already-owned exact span.  This
\ word neither allocates nor publishes the context pointer.
: _EXT4-JWR-BUILD-AT  ( address -- writer ior )
    DUP _EXT4-JWN-WRITER ! _EXT4-JWN-BYTES @ 0 FILL
    _EXT4-JWR-MAGIC _EXT4-JWN-WRITER @ _EXT4-JWR.MAGIC + !
    _EXT4-JWN-WRITER @ DUP _EXT4-JWR.SELF + !
    _EXT4-JWN-CTX @ _EXT4-JWN-WRITER @ _EXT4-JWR.CTX + !
    _EXT4-JWN-BYTES @ _EXT4-JWN-WRITER @ _EXT4-JWR.TOTAL + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-WRITER @ _EXT4-JWR.BSIZE + !
    _EXT4-JWN-MAXLEN @ _EXT4-JWN-WRITER @ _EXT4-JWR.MAXLEN + !
    _EXT4-JWN-FIRST @ _EXT4-JWN-WRITER @ _EXT4-JWR.FIRST + !
    _EXT4-JWN-META @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-CAP + !
    _EXT4-JWM-META-SLOTS @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-SLOTS + !
    _EXT4-JWN-DATA @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-CAP + !
    _EXT4-JWM-DATA-SLOTS @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-SLOTS + !
    _EXT4-JWN-REVOKE @ _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-CAP + !
    _EXT4-JWM-REVOKE-SLOTS @
    _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-SLOTS + !
    _EXT4-JWN-WRITER @ _EXT4-JWR-SIZE + _EXT4-JWN-CURSOR !
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.META-ENTRIES + !
    _EXT4-JWN-META @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-ENTRIES + !
    _EXT4-JWN-DATA @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + !
    _EXT4-JWN-REVOKE @ _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-HASH + !
    _EXT4-JWM-META-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-HASH + !
    _EXT4-JWM-DATA-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-HASH + !
    _EXT4-JWM-REVOKE-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-IMAGES + !
    _EXT4-JWN-META @ _EXT4-JWN-BSIZE @ * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-IMAGES + !
    _EXT4-JWN-DATA @ _EXT4-JWN-BSIZE @ * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.SCRATCH-A + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.SCRATCH-B + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.CP-DELETE-RANGES + !
    _EXT4-JWM-CP-RANGE-CAP @
    _EXT4-JWN-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-CAP + !
    _EXT4-JWM-CP-RANGE-CAP @ 2 CELLS * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWN-BYTES @ + <> IF
        0 _EXT4-JWN-WRITER @ _EXT4-JWR.MAGIC + !
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWN-HEAD @ DUP _EXT4-JWN-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JWN-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JWN-FREE @ _EXT4-JWN-WRITER @ _EXT4-JWR.FREE + !
    \ Linux advances past a clean superblock's persisted tail sequence when
    \ it initializes the next running transaction, including 32-bit wrap.
    _EXT4-JWN-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JWN-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JWN-WRITER @ 0 ;

VARIABLE _EXT4-JAL-META
VARIABLE _EXT4-JAL-DATA
VARIABLE _EXT4-JAL-REVOKE
VARIABLE _EXT4-JAL-KIND
VARIABLE _EXT4-JAL-ARENA
VARIABLE _EXT4-JAL-CTX
VARIABLE _EXT4-JAL-MARK
VARIABLE _EXT4-JAL-ALLOCATION
VARIABLE _EXT4-JAL-WRITER
VARIABLE _EXT4-JAL-IOR

: _EXT4-JWR-ALLOCATE-ROLLBACK  ( -- )
    0 _EXT4-JAL-CTX @ _EXT4-C.J.WRITER + !
    0 _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-STORE-KIND + !
    0 _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-JAL-ALLOCATION @ ?DUP IF _EXT4-JWN-BYTES @ 0 FILL THEN
    _EXT4-JAL-ARENA @ _EXT4-JAL-MARK @ ARENA-ROLLBACK ;

\ Allocate exactly once in an explicitly selected store.  The caller has
\ already applied any dedicated-arena admission policy; this shared boundary
\ still proves live bounds and publishes storage kind/arena before publishing
\ the writer pointer last.
: _EXT4-JWR-ALLOCATE-IN
  ( meta-cap data-cap revoke-cap store-kind arena ctx -- writer ior )
    _EXT4-JAL-CTX ! _EXT4-JAL-ARENA ! _EXT4-JAL-KIND !
    _EXT4-JAL-REVOKE ! _EXT4-JAL-DATA ! _EXT4-JAL-META !
    0 _EXT4-JAL-ALLOCATION ! 0 _EXT4-JAL-WRITER !
    _EXT4-JAL-META @ _EXT4-JAL-DATA @ _EXT4-JAL-REVOKE @
    _EXT4-JAL-CTX @ _EXT4-JWR-PREPARE ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JAL-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ OR
    _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-ARENA + @ OR IF
        0 VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JAL-KIND @ _EXT4-JWR-STORE-MOUNT = IF
        _EXT4-JAL-ARENA @ _EXT4-JAL-CTX @ _EXT4-C.ARENA + @ <> IF
            0 VFS-E-INVALID EXIT
        THEN
    ELSE
        _EXT4-JAL-KIND @ _EXT4-JWR-STORE-DEDICATED <> IF
            0 VFS-E-INVALID EXIT
        THEN
        _EXT4-JAL-ARENA @ _EXT4-JAL-CTX @ _EXT4-C.ARENA + @ = IF
            0 VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-JAL-ARENA @ DUP 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP A.BASE @ DUP 0= IF 2DROP 0 VFS-E-INVALID EXIT THEN
    DUP 7 AND IF 2DROP 0 VFS-E-INVALID EXIT THEN DROP
    DUP A.SIZE @ DUP 0< SWAP 0= OR IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP A.BASE @ OVER A.SIZE @ MSPAN-NONWRAPPING? 0= IF
        DROP 0 VFS-E-INVALID EXIT
    THEN
    DUP A.PTR @ DUP _EXT4-JAL-MARK ! DUP 7 AND IF
        2DROP 0 VFS-E-INVALID EXIT
    THEN
    OVER A.BASE @ U< IF DROP 0 VFS-E-INVALID EXIT THEN
    DUP A.BASE @ OVER A.SIZE @ + _EXT4-JAL-MARK @ U< IF
        DROP 0 VFS-E-INVALID EXIT
    THEN DROP
    _EXT4-JWN-BYTES @ 7 AND IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JAL-MARK @ _EXT4-JWN-BYTES @ MSPAN-NONWRAPPING? 0= IF
        0 VFS-E-NOMEM EXIT
    THEN
    _EXT4-JAL-ARENA @ A.BASE @ _EXT4-JAL-ARENA @ A.SIZE @ +
    _EXT4-JAL-MARK @ _EXT4-JWN-BYTES @ + U< IF
        0 VFS-E-NOMEM EXIT
    THEN
    _EXT4-JAL-ARENA @ _EXT4-JWN-BYTES @ ARENA-ALLOT?
    IF DROP 0 VFS-E-NOMEM EXIT THEN
    DUP _EXT4-JAL-ALLOCATION ! DUP _EXT4-JAL-WRITER !
    _EXT4-JAL-MARK @ <> IF
        _EXT4-JWR-ALLOCATE-ROLLBACK 0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAL-WRITER @ _EXT4-JWR-BUILD-AT
    _EXT4-JAL-IOR ! _EXT4-JAL-WRITER !
    _EXT4-JAL-IOR @ IF
        _EXT4-JWR-ALLOCATE-ROLLBACK 0 _EXT4-JAL-IOR @ EXIT
    THEN
    _EXT4-JAL-KIND @ _EXT4-JAL-CTX @
    _EXT4-C.J.WRITER-STORE-KIND + !
    _EXT4-JAL-ARENA @ _EXT4-JAL-CTX @ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-JAL-WRITER @ _EXT4-JAL-CTX @ _EXT4-C.J.WRITER + !
    _EXT4-JAL-WRITER @ _EXT4-JWR-VALID? 0= IF
        _EXT4-JWR-ALLOCATE-ROLLBACK 0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAL-WRITER @ 0 ;

VARIABLE _EXT4-JAM-META
VARIABLE _EXT4-JAM-DATA
VARIABLE _EXT4-JAM-REVOKE
VARIABLE _EXT4-JAM-CTX

: _EXT4-JWR-ALLOCATE-MOUNT
  ( meta-cap data-cap revoke-cap ctx -- writer ior )
    _EXT4-JAM-CTX ! _EXT4-JAM-REVOKE !
    _EXT4-JAM-DATA ! _EXT4-JAM-META !
    _EXT4-JAM-META @ _EXT4-JAM-DATA @ _EXT4-JAM-REVOKE @
    _EXT4-JWR-STORE-MOUNT _EXT4-JAM-CTX @ _EXT4-C.ARENA + @
    _EXT4-JAM-CTX @ _EXT4-JWR-ALLOCATE-IN ;

\ Consume an already configured writer profile.  A larger profile serves any
\ componentwise-contained request; an insufficient profile is a bounded-space
\ refusal and never selects new geometry or consumes another arena span.
: _EXT4-JWR-ENSURE  ( meta-cap data-cap revoke-cap ctx -- writer ior )
    _EXT4-JWR-PREPARE ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF
        DROP 0 VFS-E-NOSPC EXIT
    THEN
    DUP _EXT4-JWR-VALID? 0= IF DROP 0 VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JWR-MATCH? 0= IF DROP 0 VFS-E-NOSPC EXIT THEN
    DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        DROP 0 VFS-E-BUSY EXIT
    THEN
    DUP _EXT4-JWR.FAULT + @ IF DROP 0 VFS-E-BUSY EXIT THEN
    _EXT4-JWR-REBASE-IDLE 0 ;

VARIABLE _EXT4-JMR-CTX
VARIABLE _EXT4-JMR-WRITER
VARIABLE _EXT4-JMR-HEAD
VARIABLE _EXT4-JMR-FREE
VARIABLE _EXT4-JMR-WRITE-ACTIVE

\ Rebase only after publication has been withdrawn and strict validation has
\ authenticated an empty standard journal.  Mount recovery supplies a clean
\ endpoint; a live checkpoint supplies the equally standard RECOVER-set,
\ write-active endpoint so later transactions do not repeat AKW1 activation.
: _EXT4-JWR-REBASE-ENDPOINT  ( ctx write-active? -- ior )
    _EXT4-JMR-WRITE-ACTIVE ! _EXT4-JMR-CTX !
    _EXT4-JMR-WRITE-ACTIVE @ IF
        _EXT4-JMR-CTX @ _EXT4-C.RECOVERY + @ 0=
        _EXT4-JMR-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JMR-CTX @ _EXT4-C.SB + DUP
        _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JMR-CTX @ _EXT4-C.RECOVERY + @
        _EXT4-JMR-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.START + @
    _EXT4-JMR-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.SUPER-TORN + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.WRITER-CURRENT + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF DROP 0 EXIT THEN
    DUP _EXT4-JMR-WRITER ! _EXT4-JWR-SHAPE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @ - 1- DUP 0< IF
        DROP VFS-E-CORRUPT EXIT
    THEN _EXT4-JMR-FREE !
    _EXT4-JMR-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @
    ELSE
        DUP _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @ U<
        OVER _EXT4-JMR-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN _EXT4-JMR-HEAD !
    _EXT4-JMR-WRITER @ _EXT4-JWR-ZERO-OWNED
    _EXT4-JMR-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.FAULT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-START + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-CURSOR + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-TID + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JMR-HEAD @ DUP _EXT4-JMR-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JMR-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JMR-FREE @ _EXT4-JMR-WRITER @ _EXT4-JWR.FREE + !
    _EXT4-JMR-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JMR-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JWR-IDLE _EXT4-JMR-WRITER @ _EXT4-JWR.STATE + !
    0 ;

\ A failed mount preserves the one arena allocation and all of its bytes for
\ diagnosis or retry, but never republishes it as a usable transaction.  Only
\ the final authenticated clean endpoint may scrub those retained bytes.
: _EXT4-JWR-REBASE-MOUNTED  ( ctx -- ior )
    0 _EXT4-JWR-REBASE-ENDPOINT ;

: _EXT4-JWR-REBASE-WRITE-ACTIVE  ( ctx -- ior )
    -1 _EXT4-JWR-REBASE-ENDPOINT ;

VARIABLE _EXT4-JHL-HOME
VARIABLE _EXT4-JHL-ENTRIES
VARIABLE _EXT4-JHL-STRIDE
VARIABLE _EXT4-JHL-HASH
VARIABLE _EXT4-JHL-SLOTS
VARIABLE _EXT4-JHL-USED
VARIABLE _EXT4-JHL-SLOT
VARIABLE _EXT4-JHL-INDEX
VARIABLE _EXT4-JHL-IOR

: _EXT4-JTX-HASH-FIND
  ( home entries entry-cells hash slots used -- index found? ior )
    _EXT4-JHL-USED ! _EXT4-JHL-SLOTS ! _EXT4-JHL-HASH !
    _EXT4-JHL-STRIDE !
    _EXT4-JHL-ENTRIES ! _EXT4-JHL-HOME !
    _EXT4-JHL-SLOTS @ 0= IF 0 FALSE 0 EXIT THEN
    _EXT4-JHL-HOME @ _EXT4-JHL-SLOTS @ 1- AND _EXT4-JHL-SLOT !
    _EXT4-JHL-SLOTS @ 0 ?DO
        _EXT4-JHL-HASH @ _EXT4-JHL-SLOT @ CELLS + @ DUP 0= IF
            DROP 0 FALSE 0 UNLOOP EXIT
        THEN
        1- DUP _EXT4-JHL-INDEX !
        _EXT4-JHL-USED @ U< 0= IF
            0 FALSE VFS-E-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JHL-INDEX @ _EXT4-JHL-STRIDE @ *
        CELLS _EXT4-JHL-ENTRIES @ + @
        _EXT4-JHL-HOME @ = IF
            _EXT4-JHL-INDEX @ TRUE 0 UNLOOP EXIT
        THEN
        _EXT4-JHL-SLOT @ 1+ _EXT4-JHL-SLOTS @ 1- AND
        _EXT4-JHL-SLOT !
    LOOP
    0 FALSE 0 ;

VARIABLE _EXT4-JHI-HOME
VARIABLE _EXT4-JHI-INDEX
VARIABLE _EXT4-JHI-HASH
VARIABLE _EXT4-JHI-SLOTS
VARIABLE _EXT4-JHI-SLOT

: _EXT4-JTX-HASH-INSERT  ( home index hash slots -- ior )
    _EXT4-JHI-SLOTS ! _EXT4-JHI-HASH !
    _EXT4-JHI-INDEX ! _EXT4-JHI-HOME !
    _EXT4-JHI-SLOTS @ 0= IF VFS-E-NOSPC EXIT THEN
    _EXT4-JHI-HOME @ _EXT4-JHI-SLOTS @ 1- AND _EXT4-JHI-SLOT !
    _EXT4-JHI-SLOTS @ 0 ?DO
        _EXT4-JHI-HASH @ _EXT4-JHI-SLOT @ CELLS + DUP @ 0= IF
            _EXT4-JHI-INDEX @ 1+ SWAP ! 0 UNLOOP EXIT
        THEN
        DROP
        _EXT4-JHI-SLOT @ 1+ _EXT4-JHI-SLOTS @ 1- AND
        _EXT4-JHI-SLOT !
    LOOP
    VFS-E-NOSPC ;

: _EXT4-JTX-ENTRY  ( index entries entry-cells -- entry )
    ROT * CELLS + ;

VARIABLE _EXT4-JIC-BUFFER
VARIABLE _EXT4-JIC-WRITER

: _EXT4-JTX-IMAGE-CRC  ( buffer writer -- crc ior )
    _EXT4-JIC-WRITER ! _EXT4-JIC-BUFFER !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JIC-BUFFER @
    _EXT4-JIC-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

: _EXT4-JTX-CEIL/  ( nonnegative-n positive-d -- quotient )
    /MOD SWAP 0<> IF 1+ THEN ;

: _EXT4-JTX-TAGS/BLOCK-SIZE  ( block-size -- tags )
    32 - _EXT4-JBD2-TAG3-SIZE / ;

: _EXT4-JTX-REVOKES/BLOCK-SIZE  ( block-size -- revokes )
    20 - 8 / ;

: _EXT4-JTX-TAGS/BLOCK  ( writer -- tags )
    _EXT4-JWR.BSIZE + @ _EXT4-JTX-TAGS/BLOCK-SIZE ;

: _EXT4-JTX-REVOKES/BLOCK  ( writer -- revokes )
    _EXT4-JWR.BSIZE + @ _EXT4-JTX-REVOKES/BLOCK-SIZE ;

VARIABLE _EXT4-JLG-META
VARIABLE _EXT4-JLG-REVOKE
VARIABLE _EXT4-JLG-WRITER
VARIABLE _EXT4-JLG-BSIZE
VARIABLE _EXT4-JLG-TOTAL
VARIABLE _EXT4-JLG-ADD

: _EXT4-JTX-LOG-ADD  ( u -- ior )
    _EXT4-JLG-ADD !
    _EXT4-JLG-TOTAL @ _EXT4-JLG-ADD @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JLG-TOTAL ! 0 ;

: _EXT4-JTX-LOG-BLOCKS-FOR
  ( meta-credit revoke-credit block-size -- blocks ior )
    _EXT4-JLG-BSIZE ! _EXT4-JLG-REVOKE ! _EXT4-JLG-META !
    _EXT4-JLG-META @ 0< _EXT4-JLG-REVOKE @ 0< OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JLG-BSIZE @ 1024 =
    _EXT4-JLG-BSIZE @ 2048 = OR
    _EXT4-JLG-BSIZE @ 4096 = OR 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JLG-META @ _EXT4-JLG-TOTAL !
    _EXT4-JLG-META @
    _EXT4-JLG-BSIZE @ _EXT4-JTX-TAGS/BLOCK-SIZE
    _EXT4-JTX-CEIL/ _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JLG-REVOKE @
    _EXT4-JLG-BSIZE @ _EXT4-JTX-REVOKES/BLOCK-SIZE
    _EXT4-JTX-CEIL/ _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    \ One block holds the standard active-super guard outside the JBD2
    \ record stream, and one holds the transaction commit.  The ring's
    \ separately excluded spare remains available as an exact terminator.
    2 _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JLG-TOTAL @ 0 ;

: _EXT4-JTX-LOG-BLOCKS  ( meta-credit revoke-credit writer -- blocks ior )
    DUP _EXT4-JLG-WRITER ! _EXT4-JWR-VALID? 0= IF
        2DROP 0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JLG-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JTX-LOG-BLOCKS-FOR ;

VARIABLE _EXT4-JPC-META
VARIABLE _EXT4-JPC-DATA
VARIABLE _EXT4-JPC-REVOKE
VARIABLE _EXT4-JPC-CTX
VARIABLE _EXT4-JPC-BSIZE
VARIABLE _EXT4-JPC-BYTES
VARIABLE _EXT4-JPC-LOG
VARIABLE _EXT4-JPC-FREE
VARIABLE _EXT4-JPC-IOR

\ Prove that one requested profile and transaction can fit the authenticated
\ journal.  Storage admission is separate so a dedicated production arena is
\ never constrained by unrelated free space in the mount/VFS arena.
: _EXT4-JTX-PREFLIGHT-JOURNAL
  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JPC-CTX ! _EXT4-JPC-REVOKE !
    _EXT4-JPC-DATA ! _EXT4-JPC-META !
    _EXT4-JPC-CTX @ _EXT4-JWR-GEOMETRY? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.BSIZE + @ _EXT4-JPC-BSIZE !
    _EXT4-JPC-META @ _EXT4-JPC-DATA @ _EXT4-JPC-REVOKE @
    _EXT4-JPC-BSIZE @
    _EXT4-JWR-MEASURE _EXT4-JPC-IOR ! _EXT4-JPC-BYTES !
    _EXT4-JPC-IOR @ ?DUP IF EXIT THEN
    _EXT4-JPC-META @ _EXT4-JPC-REVOKE @ _EXT4-JPC-BSIZE @
    _EXT4-JTX-LOG-BLOCKS-FOR _EXT4-JPC-IOR ! _EXT4-JPC-LOG !
    _EXT4-JPC-IOR @ ?DUP IF EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JPC-CTX @ _EXT4-C.J.FIRST + @ - DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN
    1- DUP _EXT4-JPC-FREE ! 0< IF VFS-E-INVALID EXIT THEN
    _EXT4-JPC-LOG @ _EXT4-JPC-FREE @ U> IF VFS-E-NOSPC EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAX-TRANSACTION + @ ?DUP IF
        _EXT4-JPC-LOG @ 1- SWAP U> IF VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAX-TRANS-DATA + @ ?DUP IF
        _EXT4-JPC-DATA @ SWAP U> IF VFS-E-NOSPC EXIT THEN
    THEN
    0 ;

\ Internal preflight additionally proves that an existing profile contains
\ the request, or that the ordinary mount arena can hold a not-yet-allocated
\ temporary recovery writer.  This word still performs no allocation.
: _EXT4-JTX-PREFLIGHT-CAPACITY
  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JTX-PREFLIGHT-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.WRITER + @ ?DUP IF
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.META-CAP + @ _EXT4-JPC-META @ U<
        OVER _EXT4-JWR.DATA-CAP + @ _EXT4-JPC-DATA @ U< OR
        SWAP _EXT4-JWR.REVOKE-CAP + @ _EXT4-JPC-REVOKE @ U< OR IF
            VFS-E-NOSPC EXIT
        THEN
        0 EXIT
    THEN
    _EXT4-JPC-BYTES @ _EXT4-JPC-CTX @ _EXT4-C.ARENA + @ ARENA-FREE
    U> IF VFS-E-NOMEM EXIT THEN
    0 ;

VARIABLE _EXT4-EWB-META
VARIABLE _EXT4-EWB-DATA
VARIABLE _EXT4-EWB-REVOKE
VARIABLE _EXT4-EWB-V
VARIABLE _EXT4-EWB-CTX

\ Return the exact storage required by one caller-selected capacity tuple,
\ but only when that complete tuple also fits the authenticated journal's
\ ring and advertised transaction limits.
: EXT4-WRITER-WORKSPACE-BYTES?
  ( meta-cap data-cap revoke-cap vfs -- bytes ior )
    _EXT4-EWB-V ! _EXT4-EWB-REVOKE !
    _EXT4-EWB-DATA ! _EXT4-EWB-META !
    _EXT4-EWB-V @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-EWB-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-EWB-V @ V.BCTX @ DUP _EXT4-EWB-CTX ! 0= IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-EWB-V @ _EXT4-ATTACHED? 0= IF 0 VFS-E-STALE EXIT THEN
    _EXT4-EWB-V @ _EXT4-READY? 0= IF 0 VFS-E-STALE EXIT THEN
    _EXT4-EWB-META @ _EXT4-EWB-DATA @ _EXT4-EWB-REVOKE @
    _EXT4-EWB-CTX @ _EXT4-JTX-PREFLIGHT-JOURNAL
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JPC-BYTES @ 0 ;

VARIABLE _EXT4-BWA-ARENA
VARIABLE _EXT4-BWA-META
VARIABLE _EXT4-BWA-DATA
VARIABLE _EXT4-BWA-REVOKE
VARIABLE _EXT4-BWA-V
VARIABLE _EXT4-BWA-CTX
VARIABLE _EXT4-BWA-BYTES
VARIABLE _EXT4-BWA-IOR
VARIABLE _EXT4-BWA-BASE
VARIABLE _EXT4-BWA-SIZE
VARIABLE _EXT4-BWA-MOUNT-ARENA
VARIABLE _EXT4-BWA-MOUNT-BASE
VARIABLE _EXT4-BWA-MOUNT-SIZE
VARIABLE _EXT4-BWA-MOUNT-PTR

\ Bind one fresh, caller-owned arena as the persistent production profile.
\ The backing region is exclusive through clean unmount; the driver owns its
\ bump pointer and rejects overlap with the complete VFS/mount arena.
: EXT4-BIND-WRITER-ARENA?
  ( arena meta-cap data-cap revoke-cap vfs -- ior )
    _EXT4-BWA-V ! _EXT4-BWA-REVOKE ! _EXT4-BWA-DATA !
    _EXT4-BWA-META ! _EXT4-BWA-ARENA !
    _EXT4-BWA-ARENA @ 0= _EXT4-BWA-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-META @ _EXT4-BWA-DATA @ _EXT4-BWA-REVOKE @ _EXT4-BWA-V @
    EXT4-WRITER-WORKSPACE-BYTES? _EXT4-BWA-IOR ! _EXT4-BWA-BYTES !
    _EXT4-BWA-IOR @ ?DUP IF EXIT THEN
    _EXT4-BWA-V @ V.BCTX @ DUP _EXT4-BWA-CTX ! 0= IF VFS-E-STALE EXIT THEN
    _EXT4-BWA-V @ V.FLAGS @ VFS-F-DIRTY AND IF VFS-E-BUSY EXIT THEN
    _EXT4-BWA-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.SUPER-TORN + @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ OR
    _EXT4-BWA-CTX @ _EXT4-C.J.WRITER-ARENA + @ OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-BWA-ARENA @ _EXT4-BWA-V @ V.ARENA @ = IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ 4 CELLS MSPAN-NONWRAPPING? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ A.SOURCE @ DUP 0< SWAP 2 > OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ A.BASE @ DUP _EXT4-BWA-BASE ! 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-BASE @ 7 AND IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-ARENA @ A.SIZE @ DUP _EXT4-BWA-SIZE !
    DUP 0< SWAP 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-BASE @ _EXT4-BWA-SIZE @ MSPAN-NONWRAPPING? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWA-ARENA @ A.PTR @ _EXT4-BWA-BASE @ <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-BWA-ARENA @ 4 CELLS _EXT4-BWA-BASE @ _EXT4-BWA-SIZE @
    MSPAN-OVERLAP? IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-BYTES @ _EXT4-BWA-SIZE @ U> IF VFS-E-NOMEM EXIT THEN
    _EXT4-BWA-V @ V.ARENA @ DUP _EXT4-BWA-MOUNT-ARENA ! 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-BWA-MOUNT-ARENA @ A.BASE @ DUP
    _EXT4-BWA-MOUNT-BASE ! 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-BASE @ 7 AND IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-ARENA @ A.SIZE @ DUP
    _EXT4-BWA-MOUNT-SIZE ! DUP 0< SWAP 0= OR IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-ARENA @ A.PTR @ DUP _EXT4-BWA-MOUNT-PTR !
    _EXT4-BWA-MOUNT-BASE @ U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @
    MSPAN-NONWRAPPING? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @ +
    _EXT4-BWA-MOUNT-PTR @ U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-BWA-BASE @ _EXT4-BWA-SIZE @
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @
    MSPAN-OVERLAP? IF VFS-E-INVALID EXIT THEN
    _EXT4-BWA-ARENA @ 4 CELLS
    _EXT4-BWA-MOUNT-BASE @ _EXT4-BWA-MOUNT-SIZE @
    MSPAN-OVERLAP? IF
        _EXT4-BWA-ARENA @ _EXT4-BWA-MOUNT-BASE @ U< IF
            VFS-E-INVALID EXIT
        THEN
        _EXT4-BWA-ARENA @ 4 CELLS + _EXT4-BWA-MOUNT-PTR @ U> IF
            VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-BWA-V @ VFS-CAPS@ VFS-CAP-WRITE AND IF
        _EXT4-BWA-CTX @ _EXT4-BWA-V @
        _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING ?DUP IF EXIT THEN
    THEN
    _EXT4-BWA-META @ _EXT4-BWA-DATA @ _EXT4-BWA-REVOKE @
    _EXT4-JWR-STORE-DEDICATED _EXT4-BWA-ARENA @ _EXT4-BWA-CTX @
    _EXT4-JWR-ALLOCATE-IN _EXT4-BWA-IOR ! DROP
    _EXT4-BWA-IOR @ ;

VARIABLE _EXT4-JRD-CTX
VARIABLE _EXT4-JRD-WRITER
VARIABLE _EXT4-JRD-ARENA
VARIABLE _EXT4-JRD-BYTES

\ Retire only a clean dedicated profile.  Unpublish authority before
\ scrubbing, then return the exclusive arena to its original fresh mark.
: _EXT4-JWR-RELEASE-DEDICATED  ( ctx -- ior )
    DUP _EXT4-JRD-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @ DUP 0= IF
        DROP _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-ARENA + @
        _EXT4-JRD-CTX @ _EXT4-C.J.WRITER + @ OR IF VFS-E-CORRUPT EXIT THEN
        0 EXIT
    THEN
    _EXT4-JWR-STORE-MOUNT = IF 0 EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER + @ DUP
    _EXT4-JRD-WRITER ! 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-ARENA + @ DUP
    _EXT4-JRD-ARENA ! 0= IF VFS-E-CORRUPT EXIT THEN
    \ A no-write profile still has current authority here; successful dirty
    \ deactivation has deliberately withdrawn it before rebasing the writer
    \ to the clean mounted endpoint.  Validate the complete shape and runtime
    \ directly so both authenticated release paths are accepted.
    _EXT4-JRD-WRITER @ _EXT4-JWR-SHAPE? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR-RUNTIME? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRD-WRITER @ _EXT4-JWR.TOTAL + @ _EXT4-JRD-BYTES !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER + !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-STORE-KIND + !
    0 _EXT4-JRD-CTX @ _EXT4-C.J.WRITER-ARENA + !
    _EXT4-JRD-WRITER @ _EXT4-JRD-BYTES @ 0 FILL
    _EXT4-JRD-ARENA @ _EXT4-JRD-WRITER @ ARENA-ROLLBACK
    0 ;

: _EXT4-JTX-CLEAR-HASHES  ( writer -- )
    DUP _EXT4-JWR.META-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.META-HASH + @ SWAP CELLS 0 FILL
    THEN
    DUP _EXT4-JWR.DATA-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.DATA-HASH + @ SWAP CELLS 0 FILL
    THEN
    DUP _EXT4-JWR.REVOKE-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.REVOKE-HASH + @ SWAP CELLS 0 FILL
    THEN
    DROP ;

VARIABLE _EXT4-JB-META
VARIABLE _EXT4-JB-DATA
VARIABLE _EXT4-JB-REVOKE
VARIABLE _EXT4-JB-WRITER
VARIABLE _EXT4-JB-LOG
VARIABLE _EXT4-JB-IOR

: _EXT4-JTX-BEGIN
  ( meta-credit data-credit revoke-credit writer -- transaction ior )
    _EXT4-JB-WRITER ! _EXT4-JB-REVOKE !
    _EXT4-JB-DATA ! _EXT4-JB-META !
    _EXT4-JB-WRITER @ _EXT4-JWR-VALID? 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        0 VFS-E-BUSY EXIT
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.FAULT + @ IF 0 VFS-E-BUSY EXIT THEN
    _EXT4-JB-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
    _EXT4-JB-META @ 0< _EXT4-JB-DATA @ 0< OR
    _EXT4-JB-REVOKE @ 0< OR IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JB-META @ _EXT4-JB-WRITER @ _EXT4-JWR.META-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-DATA @ _EXT4-JB-WRITER @ _EXT4-JWR.DATA-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-REVOKE @
    _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-META @ _EXT4-JB-REVOKE @ _EXT4-JB-WRITER @
    _EXT4-JTX-LOG-BLOCKS _EXT4-JB-IOR ! _EXT4-JB-LOG !
    _EXT4-JB-IOR @ IF 0 _EXT4-JB-IOR @ EXIT THEN
    _EXT4-JB-LOG @ _EXT4-JB-WRITER @ _EXT4-JWR.FREE + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.J.MAX-TRANSACTION + @ ?DUP IF
        \ s_max_transaction bounds JBD2 records; the private guard is not a
        \ record and therefore does not consume that advertised limit.
        _EXT4-JB-LOG @ 1- SWAP U> IF 0 VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.J.MAX-TRANS-DATA + @ ?DUP IF
        _EXT4-JB-DATA @ SWAP U> IF 0 VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JB-WRITER @ _EXT4-JTX-CLEAR-HASHES
    0 _EXT4-JB-WRITER @ _EXT4-JWR.META-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.DATA-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.META-ACTIVE + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.DATA-ACTIVE + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + !
    _EXT4-JB-META @ _EXT4-JB-WRITER @ _EXT4-JWR.META-CREDIT + !
    _EXT4-JB-DATA @ _EXT4-JB-WRITER @ _EXT4-JWR.DATA-CREDIT + !
    _EXT4-JB-REVOKE @ _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-CREDIT + !
    _EXT4-JB-LOG @ _EXT4-JB-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    _EXT4-JB-LOG @ NEGATE _EXT4-JB-WRITER @ _EXT4-JWR.FREE + +!
    _EXT4-JB-WRITER @ _EXT4-JWR.HEAD + @ DUP
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-START + !
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-CURSOR + !
    _EXT4-JB-WRITER @ _EXT4-JWR.NEXT-TID + @
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-TID + !
    1 _EXT4-JB-WRITER @ _EXT4-JWR.EPOCH + +!
    _EXT4-JWR-STAGING _EXT4-JB-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JB-WRITER @ 0 ;

VARIABLE _EXT4-JHV-HOME
VARIABLE _EXT4-JHV-WRITER

: _EXT4-JTX-HOME?  ( home writer -- flag )
    _EXT4-JHV-WRITER ! _EXT4-JHV-HOME !
    _EXT4-JHV-HOME @
    _EXT4-JHV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JHV-HOME @ _EXT4-JHV-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JOURNAL-DATA? 0= ;

: _EXT4-JWR-META-ENTRY  ( index writer -- entry )
    _EXT4-JWR.META-ENTRIES + @ _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-DATA-ENTRY  ( index writer -- entry )
    _EXT4-JWR.DATA-ENTRIES + @ _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-REVOKE-ENTRY  ( index writer -- entry )
    _EXT4-JWR.REVOKE-ENTRIES + @ _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-META-IMAGE  ( index writer -- image )
    DUP _EXT4-JWR.BSIZE + @ ROT *
    SWAP _EXT4-JWR.META-IMAGES + @ + ;

: _EXT4-JWR-DATA-IMAGE  ( index writer -- image )
    DUP _EXT4-JWR.BSIZE + @ ROT *
    SWAP _EXT4-JWR.DATA-IMAGES + @ + ;

VARIABLE _EXT4-JTV-WRITER
VARIABLE _EXT4-JTV-ENTRIES
VARIABLE _EXT4-JTV-STRIDE
VARIABLE _EXT4-JTV-HASH
VARIABLE _EXT4-JTV-SLOTS
VARIABLE _EXT4-JTV-USED
VARIABLE _EXT4-JTV-ACTIVE
VARIABLE _EXT4-JTV-ALLOW-CANCELLED
VARIABLE _EXT4-JTV-COUNT
VARIABLE _EXT4-JTV-INDEX
VARIABLE _EXT4-JTV-ENTRY
VARIABLE _EXT4-JTV-IOR

: _EXT4-JTX-TABLE-VALID?
  ( entries entry-cells hash slots used active allow-cancelled? writer -- flag )
    _EXT4-JTV-WRITER ! _EXT4-JTV-ALLOW-CANCELLED !
    _EXT4-JTV-ACTIVE ! _EXT4-JTV-USED ! _EXT4-JTV-SLOTS !
    _EXT4-JTV-HASH ! _EXT4-JTV-STRIDE ! _EXT4-JTV-ENTRIES !
    0 _EXT4-JTV-COUNT !
    _EXT4-JTV-USED @ 0 ?DO
        I _EXT4-JTV-INDEX !
        I _EXT4-JTV-STRIDE @ * CELLS _EXT4-JTV-ENTRIES @ +
        DUP _EXT4-JTV-ENTRY !
        DUP @ _EXT4-JTV-WRITER @ _EXT4-JTX-HOME? 0= IF
            DROP FALSE UNLOOP EXIT
        THEN
        CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP 1 _EXT4-JTV-COUNT +!
        ELSE
            _EXT4-JE-CANCELLED <>
            _EXT4-JTV-ALLOW-CANCELLED @ 0= OR IF
                FALSE UNLOOP EXIT
            THEN
        THEN
        _EXT4-JTV-ENTRY @ @
        _EXT4-JTV-ENTRIES @ _EXT4-JTV-STRIDE @
        _EXT4-JTV-HASH @ _EXT4-JTV-SLOTS @ _EXT4-JTV-USED @
        _EXT4-JTX-HASH-FIND _EXT4-JTV-IOR !
        _EXT4-JTV-IOR @ IF 2DROP FALSE UNLOOP EXIT THEN
        0= IF DROP FALSE UNLOOP EXIT THEN
        _EXT4-JTV-INDEX @ <> IF FALSE UNLOOP EXIT THEN
    LOOP
    _EXT4-JTV-COUNT @ _EXT4-JTV-ACTIVE @ = ;

: _EXT4-JTX-TABLES-VALID?  ( writer -- flag )
    _EXT4-JTV-WRITER !
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-ACTIVE + @
    -1 _EXT4-JTV-WRITER @
    _EXT4-JTX-TABLE-VALID? 0= IF FALSE EXIT THEN
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
    0 _EXT4-JTV-WRITER @
    _EXT4-JTX-TABLE-VALID? 0= IF FALSE EXIT THEN
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    -1 _EXT4-JTV-WRITER @ _EXT4-JTX-TABLE-VALID? ;

: _EXT4-JTX-ACTIVE?  ( writer -- ior )
    DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-BUSY EXIT THEN
    DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING <> IF
        DROP VFS-E-BUSY EXIT
    THEN
    DUP _EXT4-JTX-TABLES-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DROP 0 ;

\ Publishing checkpoint authority freezes the complete retained transaction.
\ It remains abortable and emittable, but no generic or typed mutation may
\ change an image after the certificate CRCs and plan identity are sealed.
: _EXT4-JTX-MUTABLE?  ( writer -- ior )
    DUP _EXT4-JTX-ACTIVE? ?DUP IF NIP EXIT THEN
    _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    0 ;

VARIABLE _EXT4-JTM-BUFFER
VARIABLE _EXT4-JTM-HOME
VARIABLE _EXT4-JTM-WRITER
VARIABLE _EXT4-JTM-INDEX
VARIABLE _EXT4-JTM-ENTRY
VARIABLE _EXT4-JTM-IMAGE
VARIABLE _EXT4-JTM-NEW
VARIABLE _EXT4-JTM-CRC
VARIABLE _EXT4-JTM-REVOKE-INDEX
VARIABLE _EXT4-JTM-REVOKE-FOUND

: _EXT4-JTX-META-PUT  ( buffer home transaction -- ior )
    _EXT4-JTM-WRITER ! _EXT4-JTM-HOME ! _EXT4-JTM-BUFFER !
    _EXT4-JTM-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTM-BUFFER @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTM-HOME @ _EXT4-JTM-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTM-WRITER @ _EXT4-JWR-DATA-ENTRY CELL+ @
        _EXT4-JE-ACTIVE = IF VFS-E-CONFLICT ELSE VFS-E-CORRUPT THEN EXIT
    ELSE DROP THEN
    0 _EXT4-JTM-REVOKE-FOUND !
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JTM-REVOKE-INDEX !
        _EXT4-JTM-WRITER @ _EXT4-JWR-REVOKE-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        ELSE
            _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
        THEN
        -1 _EXT4-JTM-REVOKE-FOUND !
    ELSE DROP THEN
    0 _EXT4-JTM-NEW !
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTM-INDEX !
    ELSE
        DROP
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JTM-INDEX !
        -1 _EXT4-JTM-NEW !
    THEN
    _EXT4-JTM-NEW @ 0= IF
        _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JTM-ENTRY !
        CELL+ @ DUP _EXT4-JE-ACTIVE <
        OVER _EXT4-JE-CANCELLED > OR IF DROP VFS-E-CORRUPT EXIT THEN DROP
    THEN
    \ Authenticate the caller-owned image before publishing a new hash slot
    \ or replacing an existing retained after-image.  A hardware error must
    \ leave the transaction byte-for-byte unchanged.
    _EXT4-JTM-BUFFER @ _EXT4-JTM-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JTM-CRC !
    _EXT4-JTM-NEW @ IF
        _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JTM-ENTRY !
        _EXT4-JTM-HOME @ OVER !
        0 OVER CELL+ ! 0 SWAP 2 CELLS + !
        _EXT4-JTM-HOME @ _EXT4-JTM-INDEX @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-HASH + @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTM-ENTRY @ ! EXIT
        THEN
    THEN
    _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
    DUP _EXT4-JTM-ENTRY !
    DROP
    _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JTM-IMAGE !
    _EXT4-JTM-BUFFER @ SWAP
    _EXT4-JTM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JTM-CRC @ _EXT4-JTM-ENTRY @ 2 CELLS + !
    _EXT4-JTM-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE <> IF
        1 _EXT4-JTM-WRITER @ _EXT4-JWR.META-ACTIVE + +!
    THEN
    _EXT4-JE-ACTIVE _EXT4-JTM-ENTRY @ CELL+ !
    _EXT4-JTM-NEW @ IF 1 _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + +! THEN
    _EXT4-JTM-REVOKE-FOUND @ IF
        _EXT4-JTM-REVOKE-INDEX @
        _EXT4-JTM-WRITER @ _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @
        _EXT4-JE-ACTIVE = IF
            _EXT4-JE-CANCELLED SWAP CELL+ !
            -1 _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + +!
        ELSE DROP THEN
    THEN
    0 ;

VARIABLE _EXT4-JMA-SOURCE
VARIABLE _EXT4-JMA-HOME
VARIABLE _EXT4-JMA-WRITER
VARIABLE _EXT4-JMA-INDEX
VARIABLE _EXT4-JMA-ENTRY
VARIABLE _EXT4-JMA-IMAGE
VARIABLE _EXT4-JMA-SCRATCH

\ Acquire a private editing copy of one authenticated metadata block.  A
\ second typed edit of the same home must start from the retained transaction
\ after-image, not from stale media, or the later full-block PUT would silently
\ discard the earlier edit.  The writer-owned image remains immutable while
\ the caller edits SCRATCH-A, so its stored CRC continues to authenticate both
\ transaction preflight and abort until META-REPLACE atomically installs the
\ new complete after-image.
: _EXT4-JTX-META-ACQUIRE
  ( authenticated-source home transaction -- afterimage ior )
    _EXT4-JMA-WRITER ! _EXT4-JMA-HOME ! _EXT4-JMA-SOURCE !
    _EXT4-JMA-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JMA-SOURCE @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JMA-HOME @ _EXT4-JMA-WRITER @ _EXT4-JTX-HOME? 0= IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JMA-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JMA-SCRATCH !
    _EXT4-JMA-HOME @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP 0 _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JMA-INDEX !
        _EXT4-JMA-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JMA-ENTRY ! CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JMA-INDEX @ _EXT4-JMA-WRITER @ _EXT4-JWR-META-IMAGE
            DUP _EXT4-JMA-IMAGE !
            _EXT4-JMA-WRITER @ _EXT4-JTX-IMAGE-CRC
            ?DUP IF NIP 0 SWAP EXIT THEN
            _EXT4-JMA-ENTRY @ 2 CELLS + @ <> IF
                0 VFS-E-CORRUPT EXIT
            THEN
            _EXT4-JMA-IMAGE @
        ELSE
            _EXT4-JE-CANCELLED <> IF 0 VFS-E-CORRUPT EXIT THEN
            _EXT4-JMA-SOURCE @
        THEN
    ELSE
        DROP _EXT4-JMA-SOURCE @
    THEN
    _EXT4-JMA-SCRATCH @
    _EXT4-JMA-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JMA-SCRATCH @ 0 ;

\ Publish one complete scratch after-image through the ordinary conflict,
\ credit, revoke-cancellation, and image-CRC authority of META-PUT.
: _EXT4-JTX-META-REPLACE  ( afterimage home transaction -- ior )
    _EXT4-JTX-META-PUT ;

VARIABLE _EXT4-JMI-HOME
VARIABLE _EXT4-JMI-WRITER
VARIABLE _EXT4-JMI-INDEX

\ The active after-image this transaction holds for HOME, or zero when it
\ holds none.  Its retained CRC is checked before the caller may read it.
: _EXT4-JTX-META-IMAGE  ( home transaction -- image ior )
    _EXT4-JMI-WRITER ! _EXT4-JMI-HOME !
    _EXT4-JMI-WRITER @ _EXT4-JTX-ACTIVE? ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JMI-HOME @
    _EXT4-JMI-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JMI-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JMI-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JMI-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND ?DUP IF NIP NIP 0 SWAP EXIT THEN
    0= IF DROP 0 0 EXIT THEN
    DUP _EXT4-JMI-INDEX !
    _EXT4-JMI-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @
    DUP _EXT4-JE-ACTIVE <> IF
        _EXT4-JE-CANCELLED = IF 0 0 ELSE 0 VFS-E-CORRUPT THEN EXIT
    THEN
    DROP
    _EXT4-JMI-INDEX @ _EXT4-JMI-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JMI-WRITER @ _EXT4-JTX-IMAGE-CRC ?DUP IF NIP NIP 0 SWAP EXIT THEN
    _EXT4-JMI-INDEX @ _EXT4-JMI-WRITER @ _EXT4-JWR-META-ENTRY 2 CELLS + @
    <> IF DROP 0 VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JTD-BUFFER
VARIABLE _EXT4-JTD-HOME
VARIABLE _EXT4-JTD-WRITER
VARIABLE _EXT4-JTD-INDEX
VARIABLE _EXT4-JTD-ENTRY
VARIABLE _EXT4-JTD-IMAGE
VARIABLE _EXT4-JTD-NEW
VARIABLE _EXT4-JTD-CRC

: _EXT4-JTX-DATA-PUT  ( buffer home transaction -- ior )
    _EXT4-JTD-WRITER ! _EXT4-JTD-HOME ! _EXT4-JTD-BUFFER !
    _EXT4-JTD-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTD-BUFFER @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTD-HOME @ _EXT4-JTD-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF DROP VFS-E-CONFLICT EXIT THEN
        _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
    ELSE DROP THEN
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-WRITER @ _EXT4-JWR-REVOKE-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF DROP VFS-E-CONFLICT EXIT THEN
        _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
    ELSE DROP THEN
    0 _EXT4-JTD-NEW !
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-INDEX !
    ELSE
        DROP
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
        _EXT4-JTD-INDEX !
        -1 _EXT4-JTD-NEW !
    THEN
    _EXT4-JTD-NEW @ 0= IF
        _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JTD-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE <> IF VFS-E-CORRUPT EXIT THEN
    THEN
    \ As with metadata, compute the checked CRC while every writer-owned
    \ entry, hash slot, counter, and retained image still names the old state.
    _EXT4-JTD-BUFFER @ _EXT4-JTD-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JTD-CRC !
    _EXT4-JTD-NEW @ IF
        _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JTD-ENTRY !
        _EXT4-JTD-HOME @ OVER !
        0 OVER CELL+ ! 0 SWAP 2 CELLS + !
        _EXT4-JTD-HOME @ _EXT4-JTD-INDEX @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-HASH + @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTD-ENTRY @ ! EXIT
        THEN
    THEN
    _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
    DUP _EXT4-JTD-ENTRY !
    DROP
    _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-IMAGE
    DUP _EXT4-JTD-IMAGE !
    _EXT4-JTD-BUFFER @ SWAP
    _EXT4-JTD-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JTD-CRC @ _EXT4-JTD-ENTRY @ 2 CELLS + !
    _EXT4-JTD-NEW @ IF
        1 _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + +!
        1 _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-ACTIVE + +!
        _EXT4-JE-ACTIVE _EXT4-JTD-ENTRY @ CELL+ !
    THEN
    0 ;

VARIABLE _EXT4-JTR-HOME
VARIABLE _EXT4-JTR-WRITER
VARIABLE _EXT4-JTR-INDEX
VARIABLE _EXT4-JTR-ENTRY
VARIABLE _EXT4-JTR-NEW
VARIABLE _EXT4-JTR-META-INDEX
VARIABLE _EXT4-JTR-META-FOUND

: _EXT4-JTX-REVOKE  ( home transaction -- ior )
    _EXT4-JTR-WRITER ! _EXT4-JTR-HOME !
    _EXT4-JTR-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTR-HOME @ _EXT4-JTR-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTR-WRITER @ _EXT4-JWR-DATA-ENTRY CELL+ @
        _EXT4-JE-ACTIVE = IF VFS-E-CONFLICT ELSE VFS-E-CORRUPT THEN EXIT
    ELSE DROP THEN
    0 _EXT4-JTR-META-FOUND !
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JTR-META-INDEX !
        _EXT4-JTR-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JTR-WRITER @ _EXT4-JWR.META-ACTIVE + @ 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        ELSE
            _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
        THEN
        -1 _EXT4-JTR-META-FOUND !
    ELSE DROP THEN
    0 _EXT4-JTR-NEW !
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTR-INDEX !
    ELSE
        DROP
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @ DUP
        _EXT4-JTR-INDEX ! _EXT4-JTR-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        DUP _EXT4-JTR-ENTRY !
        _EXT4-JTR-HOME @ OVER ! 0 SWAP CELL+ !
        _EXT4-JTR-HOME @ _EXT4-JTR-INDEX @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-HASH + @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTR-ENTRY @ ! EXIT
        THEN
        -1 _EXT4-JTR-NEW !
    THEN
    _EXT4-JTR-INDEX @ _EXT4-JTR-WRITER @ _EXT4-JWR-REVOKE-ENTRY
    DUP _EXT4-JTR-ENTRY !
    _EXT4-JTR-NEW @ 0= IF
        CELL+ @ DUP _EXT4-JE-ACTIVE <
        OVER _EXT4-JE-CANCELLED > OR IF DROP VFS-E-CORRUPT EXIT THEN DROP
    ELSE
        DROP
    THEN
    _EXT4-JTR-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE <> IF
        1 _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + +!
    THEN
    _EXT4-JE-ACTIVE _EXT4-JTR-ENTRY @ CELL+ !
    _EXT4-JTR-NEW @ IF
        1 _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + +!
    THEN
    _EXT4-JTR-META-FOUND @ IF
        _EXT4-JTR-META-INDEX @
        _EXT4-JTR-WRITER @ _EXT4-JWR-META-ENTRY DUP CELL+ @
        _EXT4-JE-ACTIVE = IF
            _EXT4-JE-CANCELLED SWAP CELL+ !
            -1 _EXT4-JTR-WRITER @ _EXT4-JWR.META-ACTIVE + +!
        ELSE DROP THEN
    THEN
    0 ;

: _EXT4-JTX-DATA-ZERO  ( home transaction -- ior )
    DUP _EXT4-JTX-MUTABLE? ?DUP IF NIP NIP EXIT THEN
    DUP _EXT4-JWR.SCRATCH-B + @
    OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ ROT ROT _EXT4-JTX-DATA-PUT ;

: _EXT4-JTX-CLEAR-STAGED  ( writer -- )
    DUP _EXT4-JWR-CLEAR-CP-AUTHORITY
    DUP _EXT4-JWR.META-ENTRIES + @
    OVER _EXT4-JWR.META-USED + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.DATA-ENTRIES + @
    OVER _EXT4-JWR.DATA-USED + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.REVOKE-ENTRIES + @
    OVER _EXT4-JWR.REVOKE-USED + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.META-IMAGES + @
    OVER _EXT4-JWR.META-USED + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.DATA-IMAGES + @
    OVER _EXT4-JWR.DATA-USED + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.SCRATCH-A + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JTX-CLEAR-HASHES
    0 OVER _EXT4-JWR.META-CREDIT + !
    0 OVER _EXT4-JWR.DATA-CREDIT + !
    0 OVER _EXT4-JWR.REVOKE-CREDIT + !
    0 OVER _EXT4-JWR.META-USED + !
    0 OVER _EXT4-JWR.DATA-USED + !
    0 OVER _EXT4-JWR.REVOKE-USED + !
    0 OVER _EXT4-JWR.META-ACTIVE + !
    0 OVER _EXT4-JWR.DATA-ACTIVE + !
    0 OVER _EXT4-JWR.REVOKE-ACTIVE + !
    0 OVER _EXT4-JWR.LOG-RESERVED + !
    0 OVER _EXT4-JWR.TX-START + !
    0 OVER _EXT4-JWR.TX-CURSOR + !
    0 OVER _EXT4-JWR.TX-TID + !
    0 SWAP _EXT4-JWR.PHASE + ! ;

VARIABLE _EXT4-JAB-WRITER
VARIABLE _EXT4-JAB-FREE
VARIABLE _EXT4-JAB-IOR

: _EXT4-JTX-ABORT  ( transaction -- ior )
    DUP _EXT4-JAB-WRITER ! _EXT4-JTX-ACTIVE? ?DUP IF EXIT THEN
    _EXT4-JAB-WRITER @ _EXT4-JWR.FREE + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    _EXT4-UADD? _EXT4-JAB-IOR ! _EXT4-JAB-FREE !
    _EXT4-JAB-IOR @ IF _EXT4-JAB-IOR @ EXIT THEN
    _EXT4-JAB-FREE @
    _EXT4-JAB-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.FIRST + @ - 1- U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAB-FREE @ _EXT4-JAB-WRITER @ _EXT4-JWR.FREE + !
    _EXT4-JAB-WRITER @ _EXT4-JTX-CLEAR-STAGED
    _EXT4-JWR-IDLE _EXT4-JAB-WRITER @ _EXT4-JWR.STATE + !
    0 ;

VARIABLE _EXT4-JS-CTX
VARIABLE _EXT4-JS-POS
VARIABLE _EXT4-JS-SEQUENCE
VARIABLE _EXT4-JS-LEFT
VARIABLE _EXT4-JS-PASS
VARIABLE _EXT4-JS-DONE
VARIABLE _EXT4-JS-TYPE
VARIABLE _EXT4-JS-DESC
VARIABLE _EXT4-JS-OFF
VARIABLE _EXT4-JS-LIMIT
VARIABLE _EXT4-JS-TAG
VARIABLE _EXT4-JS-FLAGS
VARIABLE _EXT4-JS-HOME
VARIABLE _EXT4-JS-TAG-CHECKSUM
VARIABLE _EXT4-JS-LAST
VARIABLE _EXT4-JS-COMMIT-CURSOR
VARIABLE _EXT4-JS-CURRENT
VARIABLE _EXT4-JS-FIRST
VARIABLE _EXT4-JS-TX-REVOKES
VARIABLE _EXT4-JS-REVOKE-COUNT
VARIABLE _EXT4-JS-REVOKE-OFF
VARIABLE _EXT4-JS-REVOKE-HIGH
VARIABLE _EXT4-JS-REVOKE-BLOCK

VARIABLE _EXT4-JSB-WRITER
VARIABLE _EXT4-JSB-META-INDEX
VARIABLE _EXT4-JSB-META-BOUND
VARIABLE _EXT4-JSB-REVOKE-INDEX
VARIABLE _EXT4-JSB-REVOKE-BOUND
VARIABLE _EXT4-JSB-PAYLOAD
VARIABLE _EXT4-JSB-HOME
VARIABLE _EXT4-JSB-ENTRY
VARIABLE _EXT4-JSB-IOR

: _EXT4-JSCAN-FULL?  ( pass -- flag )
    DUP _EXT4-JSCAN-PREFLIGHT =
    SWAP _EXT4-JSCAN-BINDING = OR ;

: _EXT4-JSCAN-BIND-BEGIN  ( writer -- )
    _EXT4-JSB-WRITER !
    0 _EXT4-JSB-META-INDEX !
    0 _EXT4-JSB-META-BOUND !
    0 _EXT4-JSB-REVOKE-INDEX !
    0 _EXT4-JSB-REVOKE-BOUND ! ;

\ Compare the logical, unescaped descriptor stream in the same deterministic
\ order used by emission.  Cancelled retained entries never entered the log.
: _EXT4-JSCAN-BIND-METADATA  ( payload home -- ior )
    _EXT4-JSB-HOME ! _EXT4-JSB-PAYLOAD !
    _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
    BEGIN
        _EXT4-JSB-META-INDEX @
        _EXT4-JSB-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JSB-META-INDEX @ _EXT4-JSB-WRITER @
        _EXT4-JWR-META-ENTRY DUP _EXT4-JSB-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JSB-ENTRY @ @ _EXT4-JSB-HOME @ <> IF
                VFS-E-CORRUPT EXIT
            THEN
            _EXT4-JSB-PAYLOAD @
            _EXT4-JSB-META-INDEX @ _EXT4-JSB-WRITER @
            _EXT4-JWR-META-IMAGE
            _EXT4-JSB-WRITER @ _EXT4-JWR.BSIZE + @
            _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
            1 _EXT4-JSB-META-INDEX +!
            1 _EXT4-JSB-META-BOUND +!
            0 EXIT
        THEN
        1 _EXT4-JSB-META-INDEX +!
    REPEAT
    VFS-E-CORRUPT ;

\ Revoke records are emitted in retained insertion order as well.  Equality
\ with the next admissible retained home rejects duplicates, omissions, and
\ any reordered or substituted revoke identity without allocating a seen set.
: _EXT4-JSCAN-BIND-REVOKE  ( home -- ior )
    _EXT4-JSB-HOME !
    _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
    _EXT4-JSB-HOME @ _EXT4-JSB-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    BEGIN
        _EXT4-JSB-REVOKE-INDEX @
        _EXT4-JSB-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JSB-REVOKE-INDEX @ _EXT4-JSB-WRITER @
        _EXT4-JWR-REVOKE-ENTRY DUP _EXT4-JSB-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JSB-ENTRY @ @ _EXT4-JSB-HOME @ <> IF
                VFS-E-CORRUPT EXIT
            THEN
            1 _EXT4-JSB-REVOKE-INDEX +!
            1 _EXT4-JSB-REVOKE-BOUND +!
            0 EXIT
        THEN
        1 _EXT4-JSB-REVOKE-INDEX +!
    REPEAT
    VFS-E-CORRUPT ;

\ Always withdraw the transient binding publication, including after a scan
\ error.  On success every active retained identity must have appeared once.
: _EXT4-JSCAN-BIND-FINISH  ( scan-ior -- ior )
    _EXT4-JSB-IOR !
    _EXT4-JSB-IOR @ 0= _EXT4-JSB-WRITER @ 0<> AND IF
        _EXT4-JSB-META-BOUND @
        _EXT4-JSB-WRITER @ _EXT4-JWR.META-ACTIVE + @ <>
        _EXT4-JSB-REVOKE-BOUND @
        _EXT4-JSB-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
            VFS-E-CORRUPT _EXT4-JSB-IOR !
        THEN
    THEN
    0 _EXT4-JSB-WRITER !
    _EXT4-JSB-IOR @ ;

: _EXT4-JSCAN-READ-NEXT  ( -- ior )
    _EXT4-JS-LEFT @ 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-JS-POS @ DUP _EXT4-JS-CURRENT !
    _EXT4-JS-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JS-POS @ _EXT4-JS-CTX @ _EXT4-JOURNAL-NEXT _EXT4-JS-POS !
    -1 _EXT4-JS-LEFT +!
    0 ;

VARIABLE _EXT4-JIP-BUF
VARIABLE _EXT4-JIP-HOME
VARIABLE _EXT4-JIP-CTX
VARIABLE _EXT4-RPC-SB
VARIABLE _EXT4-RPC-CTX
VARIABLE _EXT4-RGD-CTX
VARIABLE _EXT4-RAP-BUF
VARIABLE _EXT4-RAP-HOME
VARIABLE _EXT4-RAP-CTX

: _EXT4-PRIMARY-SUPER-CANDIDATE?  ( sb ctx -- flag ior )
    _EXT4-RPC-CTX ! _EXT4-RPC-SB !
    _EXT4-RPC-SB @ _EXT4-SUPER-CHECKSUM? ?DUP IF
        NIP 0 SWAP EXIT
    THEN 0= IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ _EXT4-SUPER-SEED? ?DUP IF
        NIP 0 SWAP EXIT
    THEN 0= IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ _EXT4-SB.INCOMPAT + L@
    _EXT4-INCOMPAT-RECOVER AND 0= IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ -1 _EXT4-VALIDATE-SUPER-RETRY-EARLY IF
        FALSE 0 EXIT
    THEN
    _EXT4-RPC-SB @ _EXT4-VALIDATE-SUPER-RETRY-LATE IF
        FALSE 0 EXIT
    THEN
    _EXT4-RPC-SB @ _EXT4-RPC-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS IF FALSE 0 EXIT THEN
    _EXT4-RPC-SB @ 0
    _EXT4-RPC-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SUPER-INVARIANTS? 0 ;

: _EXT4-PRIMARY-GDT-CANDIDATE?  ( block ctx -- flag ior )
    _EXT4-RGD-CTX !
    DUP _EXT4-GD.BLOCK-BITMAP-HI + L@
    OVER _EXT4-GD.INODE-BITMAP-HI + L@ OR
    OVER _EXT4-GD.INODE-TABLE-HI + L@ OR IF DROP FALSE 0 EXIT THEN
    DUP _EXT4-GD.BLOCK-BITMAP-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.BLOCK-BITMAP-BLOCK + @ <>
    OVER _EXT4-GD.INODE-BITMAP-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ <> OR
    OVER _EXT4-GD.INODE-TABLE-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.INODE-TABLE-BASE + @ <> OR IF
        DROP FALSE 0 EXIT
    THEN
    0 _EXT4-RGD-CTX @ _EXT4-GROUP-DESC-CHECKSUM? ;

: _EXT4-JOURNAL-INODE-PRESERVED?  ( payload home ctx -- flag )
    _EXT4-JIP-CTX ! _EXT4-JIP-HOME ! _EXT4-JIP-BUF !
    _EXT4-JIP-HOME @
    _EXT4-JIP-CTX @ _EXT4-C.J.INODE-TABLE-BLOCK + @ <> IF TRUE EXIT THEN
    _EXT4-JIP-BUF @
    _EXT4-JIP-CTX @ _EXT4-C.J.INODE-TABLE-OFF + @ +
    _EXT4-JIP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JIP-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? ;

\ A valid JBD2 checksum authenticates bytes but does not authorize changing
\ the bootstrap chain.  Hard-frozen sparse copies are never home targets;
\ mutable primary metadata may change only while retaining the exact fields,
\ allocation bit, or inode slice needed by the next retry.
: _EXT4-RECOVERY-AUTHORITY-PRESERVED?  ( payload home ctx -- flag ior )
    _EXT4-RAP-CTX ! _EXT4-RAP-HOME ! _EXT4-RAP-BUF !
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @
    _EXT4-RECOVERY-FROZEN-BLOCK? IF FALSE 0 EXIT THEN
    _EXT4-RAP-BUF @ _EXT4-RAP-HOME @ _EXT4-RAP-CTX @
    _EXT4-JOURNAL-INODE-PRESERVED? 0= IF FALSE 0 EXIT THEN
    _EXT4-RAP-HOME @
    _EXT4-RAP-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ = IF
        0 _EXT4-RAP-CTX @ _EXT4-GROUP-INODE-COUNT
        DUP IF NIP FALSE SWAP EXIT THEN DROP
        _EXT4-RAP-BUF @ SWAP
        _EXT4-JOURNAL-INODE 1- BITSET-TEST? 0= IF
            DROP FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        0= IF FALSE 0 EXIT THEN
    THEN
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = IF
        _EXT4-RAP-BUF @ _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-CANDIDATE? ?DUP IF
            NIP 0 SWAP EXIT
        THEN 0= IF
            FALSE 0 EXIT
        THEN
    THEN
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @ _EXT4-GDT-BASE = IF
        _EXT4-RAP-BUF @ _EXT4-RAP-CTX @
        _EXT4-PRIMARY-GDT-CANDIDATE? ?DUP IF NIP 0 SWAP EXIT THEN
        0= IF FALSE 0 EXIT THEN
    THEN
    TRUE 0 ;

\ A checksum-v3/64-bit revoke block carries a byte count followed by exact
\ big-endian 64-bit home-block numbers and a checksum tail.  Preflight counts
\ records provisionally until the transaction commit is authenticated; the
\ revoke pass records the latest committed sequence for each block.
: _EXT4-JSCAN-REVOKE  ( -- ior )
    _EXT4-JS-CTX @ _EXT4-C.J.FEATURES + @
    _EXT4-JBD2-I-REVOKE AND 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JS-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JS-CTX @ _EXT4-JBD2-BLOCK-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    12 + _EXT4-BE32@ DUP _EXT4-JS-REVOKE-COUNT !
    DUP 16 U< IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-JBD2-TAIL-SIZE -
    U> IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    16 - DUP 8 MOD IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    8 / _EXT4-JS-REVOKE-COUNT !
    _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? IF
        _EXT4-JS-TX-REVOKES @ _EXT4-JS-REVOKE-COUNT @ + DUP
        _EXT4-JS-TX-REVOKES @ U< IF
            DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JS-TX-REVOKES !
        _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
        16 _EXT4-JS-REVOKE-OFF !
        _EXT4-JS-REVOKE-COUNT @ 0 ?DO
            _EXT4-JS-CTX @ _EXT4-C.BLOCK +
            _EXT4-JS-REVOKE-OFF @ + DUP
            _EXT4-BE32@ _EXT4-JS-REVOKE-HIGH !
            4 + _EXT4-BE32@ _EXT4-JS-REVOKE-BLOCK !
            _EXT4-JS-REVOKE-HIGH @ IF
                EXT4-D-JOURNAL _EXT4-UNSUPPORTED UNLOOP EXIT
            THEN
            _EXT4-JS-REVOKE-BLOCK @ _EXT4-JSCAN-BIND-REVOKE
            ?DUP IF UNLOOP EXIT THEN
            8 _EXT4-JS-REVOKE-OFF +!
        LOOP
        0 EXIT
    THEN
    _EXT4-JS-PASS @ _EXT4-JSCAN-REVOKES <> IF 0 EXIT THEN
    16 _EXT4-JS-REVOKE-OFF !
    _EXT4-JS-REVOKE-COUNT @ 0 ?DO
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-REVOKE-OFF @ + DUP
        _EXT4-BE32@ _EXT4-JS-REVOKE-HIGH !
        4 + _EXT4-BE32@ _EXT4-JS-REVOKE-BLOCK !
        _EXT4-JS-REVOKE-HIGH @ IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED UNLOOP EXIT
        THEN
        _EXT4-JS-REVOKE-BLOCK @ _EXT4-JS-CTX @
        _EXT4-JOURNAL-DATA? IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JS-REVOKE-BLOCK @ _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
        _EXT4-REVOKE-PUT ?DUP IF UNLOOP EXIT THEN
        8 _EXT4-JS-REVOKE-OFF +!
    LOOP
    0 ;

: _EXT4-JSCAN-DESCRIPTOR  ( -- ior )
    _EXT4-JS-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JS-CTX @ _EXT4-C.DIR-BLOCK + DUP _EXT4-JS-DESC !
    _EXT4-JS-CTX @ _EXT4-JBD2-BLOCK-CHECKSUM?
    ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-JBD2-TAIL-SIZE -
    _EXT4-JS-LIMIT !
    12 _EXT4-JS-OFF ! 0 _EXT4-JS-LAST !
    BEGIN _EXT4-JS-LAST @ 0= WHILE
        _EXT4-JS-OFF @ _EXT4-JBD2-TAG3-SIZE +
        _EXT4-JS-LIMIT @ U> IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
        _EXT4-JS-DESC @ _EXT4-JS-OFF @ + DUP _EXT4-JS-TAG !
        _EXT4-BE32@ DUP _EXT4-JS-HOME !
        _EXT4-JS-CTX @ _EXT4-C.BLOCKS + @ >= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-HOME @ _EXT4-JS-CTX @ _EXT4-JOURNAL-DATA? IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-TAG @ 4 + _EXT4-BE32@ DUP _EXT4-JS-FLAGS !
        _EXT4-JBD2-F-ALL INVERT AND IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-TAG @ 8 + _EXT4-BE32@ IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JS-TAG @ 12 + _EXT4-BE32@ _EXT4-JS-TAG-CHECKSUM !
        _EXT4-JS-OFF @ _EXT4-JBD2-TAG3-SIZE + _EXT4-JS-OFF !
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-SAME-UUID AND 0= IF
            _EXT4-JS-OFF @ 16 + _EXT4-JS-LIMIT @ U> IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            \ The tag UUID is an opaque per-client identity field, not the
            \ journal superblock UUID.  Recovery uses its flag for tag
            \ layout; the descriptor checksum authenticates its bytes.
            16 _EXT4-JS-OFF +!
        THEN
        _EXT4-JSCAN-READ-NEXT ?DUP IF EXIT THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-TAG-CHECKSUM @
        _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
        _EXT4-JBD2-TAG-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        \ Tag checksums cover the escaped on-disk form.  Reconstruct the
        \ logical home image before comparing or writing it.
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-ESCAPE AND IF
            _EXT4-JBD2-MAGIC
            _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-BE32!
        THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @ _EXT4-JS-CTX @
        _EXT4-RECOVERY-AUTHORITY-PRESERVED? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @
        _EXT4-JSCAN-BIND-METADATA ?DUP IF EXIT THEN
        \ A checksum-torn primary super is admitted provisionally so this
        \ authenticated payload can be inspected.  Do not grant replay
        \ authority until the enclosing transaction's commit is verified.
        _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT =
        _EXT4-JS-HOME @ _EXT4-JS-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = AND IF
            _EXT4-JS-SEQUENCE @ 1+
            _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
        THEN
        _EXT4-JS-PASS @ _EXT4-JSCAN-REPLAY = IF
            _EXT4-JS-HOME @ _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
            _EXT4-JOURNAL-REVOKED? IF
                1 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-HITS + +!
            ELSE
                _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @
                _EXT4-JS-CTX @ _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
                1 _EXT4-JS-CTX @ _EXT4-C.J.HOME-WRITES + +!
            THEN
        THEN
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-LAST AND IF
            -1 _EXT4-JS-LAST !
        THEN
    REPEAT
    0 ;

: _EXT4-JSCAN-FINISH  ( -- ior )
    \ A descriptor without its authenticated commit is only an incomplete
    \ tail.  Never let its provisional repair claim survive this scan.
    0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
    _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND
    _EXT4-JS-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JS-COMMIT-CURSOR @ _EXT4-JS-CTX @ _EXT4-C.J.CURSOR + !
    0 ;

: _EXT4-JSCAN  ( pass ctx -- ior )
    _EXT4-JS-CTX ! _EXT4-JS-PASS !
    _EXT4-JS-PASS @ _EXT4-JSCAN-REPLAY = IF
        _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-READY + @ 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-CTX @ _EXT4-REVOKE-GEOMETRY? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JS-CTX @ _EXT4-C.J.START + @ _EXT4-JS-POS !
    _EXT4-JS-CTX @ _EXT4-C.J.SEQUENCE + @ _EXT4-JS-SEQUENCE !
    _EXT4-JS-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @ - _EXT4-JS-LEFT !
    0 _EXT4-JS-DONE !
    0 _EXT4-JS-TX-REVOKES !
    _EXT4-JS-POS @ _EXT4-JS-COMMIT-CURSOR !
    0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
    _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT = IF
        0 _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-HITS + !
    THEN
    BEGIN
        _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
            _EXT4-JS-DONE @
            _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + @ >= IF 0 EXIT THEN
        THEN
        _EXT4-JS-LEFT @ 0= IF
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JS-DONE @ IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
            _EXT4-JSCAN-FINISH EXIT
        THEN
        _EXT4-JSCAN-READ-NEXT ?DUP IF EXIT THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + DUP
        _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
        OVER 8 + _EXT4-BE32@ _EXT4-JS-SEQUENCE @ <> OR IF
            DROP
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JSCAN-FINISH EXIT
        THEN
        4 + _EXT4-BE32@ _EXT4-JS-TYPE !
        _EXT4-JS-TYPE @ _EXT4-JBD2-DESCRIPTOR = IF
            _EXT4-JSCAN-DESCRIPTOR ?DUP IF EXIT THEN
        ELSE _EXT4-JS-TYPE @ _EXT4-JBD2-COMMIT = IF
            _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-CTX @
            _EXT4-JBD2-COMMIT-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            1 _EXT4-JS-DONE +!
            _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT = IF
                _EXT4-JS-DONE @
                _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + !
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + @
                _EXT4-JS-TX-REVOKES @ + DUP
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + @ U< IF
                    DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
                THEN
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + !
                _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + @ IF
                    _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + @
                    _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + !
                THEN
                0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
                0 _EXT4-JS-TX-REVOKES !
            THEN
            _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND _EXT4-JS-SEQUENCE !
            _EXT4-JS-POS @ _EXT4-JS-COMMIT-CURSOR !
        ELSE _EXT4-JS-TYPE @ _EXT4-JBD2-REVOKE = IF
            _EXT4-JSCAN-REVOKE ?DUP IF EXIT THEN
        ELSE
            _EXT4-JS-TYPE @ _EXT4-JBD2-SUPER-V2 =
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? AND IF
                _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @ _EXT4-JS-FIRST !
                _EXT4-JS-CURRENT @ _EXT4-JS-CTX @
                _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN IF
                    _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @
                    _EXT4-JS-FIRST @ =
                    _EXT4-JA-FEATURES @
                    _EXT4-JS-CTX @ _EXT4-C.J.FEATURES + @ = AND
                    _EXT4-JS-CTX @ _EXT4-C.BLOCK +
                    _EXT4-JS.SEQUENCE + _EXT4-BE32@
                    _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND = AND IF
                        _EXT4-JSCAN-FINISH EXIT
                    THEN
                THEN
            THEN
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN THEN THEN
    AGAIN ;

VARIABLE _EXT4-RM-CTX

: _EXT4-RECOVERY-MEDIA  ( ctx -- ior )
    _EXT4-RM-CTX !
    _EXT4-RM-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-READONLY AND IF EXT4-D-RECOVERY _EXT4-READONLY EXIT THEN
    _EXT4-IO-VOL @ VOL.FLAGS VOL-F-READONLY AND IF
        VOL-E-READONLY VFS-IOR-F-READONLY
        VFS-IOR-D-VOLUME VFS-R-READONLY VFS-IOR-MAKE EXIT
    THEN
    _EXT4-IO-VOL @ VOL.BD BD.CAPS 0x06 AND 0x06 <> IF
        0 0 VFS-IOR-D-VOLUME VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    0 ;

VARIABLE _EXT4-RJ-CTX
VARIABLE _EXT4-RJ-V
VARIABLE _EXT4-RJ-ANCHOR
VARIABLE _EXT4-RJ-OLD-SEQUENCE
VARIABLE _EXT4-RJ-OLD-HEAD
VARIABLE _EXT4-RJ-OLD-CRC
VARIABLE _EXT4-RJ-EMPTY-PREDECESSOR
VARIABLE _EXT4-RJ-PREDECESSOR-MAGIC
VARIABLE _EXT4-RJ-PREDECESSOR-VALUE

: _EXT4-PREPARE-CLEAR  ( ctx -- ior )
    DUP _EXT4-RJ-CTX !
    _EXT4-C.SB + _EXT4-PREPARE-RECOVERED-SUPER ;

: _EXT4-STAMP-JOURNAL-RESET  ( ctx -- ior )
    _EXT4-RJ-CTX !
    0 _EXT4-RJ-EMPTY-PREDECESSOR !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.SEQUENCE + _EXT4-BE32@ _EXT4-RJ-OLD-SEQUENCE !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.HEAD + _EXT4-BE32@ _EXT4-RJ-OLD-HEAD !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-CTX @
    _EXT4-JOURNAL-IMAGE-CRC ?DUP IF NIP EXIT THEN
    _EXT4-RJ-OLD-CRC !
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-ANCHOR !
    ELSE
        _EXT4-RJ-CTX @ _EXT4-C.J.CURSOR + @ _EXT4-RJ-ANCHOR !
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.START + _EXT4-BE32@ 0= IF
            _EXT4-RJ-OLD-SEQUENCE @ 1+ 0xFFFFFFFF AND
            _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @ = IF
                _EXT4-RJ-OLD-HEAD @ DUP 0= IF
                    DROP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @
                ELSE
                    DUP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @ U<
                    OVER _EXT4-RJ-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
                        DROP 0
                    THEN
                THEN
                _EXT4-RJ-ANCHOR @ = IF
                    -1 _EXT4-RJ-EMPTY-PREDECESSOR !
                THEN
            THEN
        THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.SEQUENCE + _EXT4-BE32!
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.START + _EXT4-BE32!
    _EXT4-RJ-ANCHOR @
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-RECOVERY-MAGIC
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    \ AKR1 authenticates the clean super image deterministically derived from
    \ the durable current super.  This is unchanged after PREPARE-CLEAR and
    \ also lets a live checkpoint retire AKG1 while deliberately retaining
    \ the standard RECOVER-set endpoint for the next transaction.
    _EXT4-RJ-CTX @ _EXT4-C.SB +
    _EXT4-INTENDED-RECOVERED-SUPER-CHECKSUM ?DUP IF NIP EXIT THEN
    DUP
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    INVERT 0xFFFFFFFF AND
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-RJ-ANCHOR @ DUP
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    INVERT 0xFFFFFFFF AND
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    0 _EXT4-RJ-PREDECESSOR-MAGIC !
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-JBD2-ACTIVE-RESET-MAGIC _EXT4-RJ-PREDECESSOR-MAGIC !
        _EXT4-RJ-OLD-SEQUENCE @ _EXT4-RJ-PREDECESSOR-VALUE !
    ELSE
        _EXT4-RJ-EMPTY-PREDECESSOR @ IF
            _EXT4-JBD2-EMPTY-RESET-MAGIC _EXT4-RJ-PREDECESSOR-MAGIC !
            _EXT4-RJ-OLD-HEAD @ _EXT4-RJ-PREDECESSOR-VALUE !
        THEN
    THEN
    _EXT4-RJ-PREDECESSOR-MAGIC @ ?DUP IF
        DUP _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
        _EXT4-RJ-PREDECESSOR-VALUE @ DUP
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
        _EXT4-RJ-OLD-CRC @ DUP
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    ELSE
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JBD2-STAMP-SUPER-CHECKSUM ;

VARIABLE _EXT4-AJS-BUF
VARIABLE _EXT4-AJS-GUARD
VARIABLE _EXT4-AJS-CTX
VARIABLE _EXT4-AJS-OLD
VARIABLE _EXT4-AJS-NEW

: _EXT4-STAMP-JOURNAL-ACTIVATION  ( buffer guard ctx -- ior )
    _EXT4-AJS-CTX ! _EXT4-AJS-GUARD ! _EXT4-AJS-BUF !
    _EXT4-AJS-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L!
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    0 _EXT4-AJS-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-AJS-GUARD @ _EXT4-AJS-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-AJS-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    4 _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    0 _EXT4-AJS-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32!
    _EXT4-AJS-CTX @ _EXT4-C.SB + _EXT4-INTENDED-SUPER-CHECKSUM
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-AJS-OLD !
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    _EXT4-AJS-OLD @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-AJS-GUARD @
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    _EXT4-AJS-GUARD @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    _EXT4-AJS-CTX @ _EXT4-C.SB +
    _EXT4-INTENDED-DIRTY-SUPER-CHECKSUM ?DUP IF NIP EXIT THEN
    DUP _EXT4-AJS-NEW !
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
    _EXT4-AJS-NEW @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-JBD2-ACTIVATION-MAGIC
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JBD2-STAMP-SUPER-CHECKSUM ;

: _EXT4-RESET-JOURNAL  ( ctx -- ior )
    _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK + 0 _EXT4-RJ-CTX @
        _EXT4-WRITE-JBLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        0 _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + !
        _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF 0 EXIT THEN
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-CTX @
        _EXT4-JBD2-ACTIVE-GUARD? ?DUP IF NIP EXIT THEN 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-STAMP-JOURNAL-RESET ?DUP IF EXIT THEN
    \ Preseed the whole anchor block with the intended image but invalid byte
    \ zero.  After that flush, the valid write changes only byte zero, so any
    \ applied prefix is either still invalid or already the exact anchor.
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + C!
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-ANCHOR @ _EXT4-RJ-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-ANCHOR @ _EXT4-RJ-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + 0 _EXT4-RJ-CTX @ _EXT4-WRITE-JBLOCK ;

: _EXT4-WRITE-CLEARED-SUPER  ( ctx -- ior )
    _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS ;

\ Return journal block zero to a stock JBD2 superblock only after the witness's
\ authenticated ext4 endpoint is durable, and before retiring its anchor.
: _EXT4-CLEAR-JOURNAL-WITNESS  ( ctx -- ior )
    _EXT4-RJ-CTX !
    0 _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-CTX @
    _EXT4-JBD2-WITNESS? 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-JOURNAL-WITNESS-SUPER?
    ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    \ Freeze the raw primary before the anchor reread.  With the authenticated
    \ ext4 endpoint already durable, witness authority may be withdrawn only if
    \ the named anchor is still exact and the complete primary block equals
    \ it; a checksum-valid 1024-byte prefix is insufficient on larger media.
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK + DUP
    _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF NIP EXIT THEN
    0 _EXT4-RJ-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-JDW-CTX

\ A live checkpoint or mount-time retained-orphan resume may retire AKG1
\ without first clearing ext4 RECOVER.  The on-media reset predecessor tuple,
\ not a same-session cleanup enum, proves that the witness came from an active
\ journal.  This matters after remount, where validation reconstructs the
\ witness but deliberately does not retain the emitter's in-memory enum.
: _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY  ( ctx -- ior )
    DUP _EXT4-JDW-CTX ! _EXT4-C.RECOVERY + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.SUPER-TORN + @ IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JDW-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JDW-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JDW-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-RECOVERY <> IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JBD2-RESET-PREDECESSOR? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-ACTIVE-RESET-MAGIC <> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.START + _EXT4-BE32@ IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @ <> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-JOURNAL-WITNESS-SUPER?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-JDW-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-JDW-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK + DUP
    _EXT4-ZERO-JOURNAL-WITNESS ?DUP IF NIP EXIT THEN
    0 _EXT4-JDW-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-RA-CTX
VARIABLE _EXT4-RA-LOGICAL

\ Zeroing byte zero first makes every applied prefix cease to be a valid JBD2
\ superblock.  Once the standard primary is durable this slot has no authority.
: _EXT4-RETIRE-JOURNAL-ANCHOR  ( ctx -- ior )
    _EXT4-RA-CTX !
    _EXT4-RA-CTX @ _EXT4-C.J.WITNESS + @ IF
        _EXT4-RA-CTX @ _EXT4-C.J.ANCHOR + @
    ELSE
        _EXT4-RA-CTX @ _EXT4-C.J.CURSOR + @
    THEN DUP _EXT4-RA-LOGICAL !
    _EXT4-RA-CTX @ _EXT4-C.J.FIRST + @ U<
    _EXT4-RA-LOGICAL @ _EXT4-RA-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RA-CTX @ _EXT4-C.BLOCK +
    _EXT4-RA-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-RA-CTX @ _EXT4-C.BLOCK +
    _EXT4-RA-LOGICAL @ _EXT4-RA-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-JWF-IOR
VARIABLE _EXT4-JWF-WRITER

: _EXT4-JWR-LATCH-FAULT  ( ior writer -- ior )
    _EXT4-JWF-WRITER ! _EXT4-JWF-IOR !
    _EXT4-JWF-IOR @ 0= IF 0 EXIT THEN
    _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + @ 0= IF
        _EXT4-JWF-IOR @ _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + !
    THEN
    _EXT4-JWR-FAULTED _EXT4-JWF-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-IO-VFS @ ?DUP IF
        DUP V.FLAGS DUP @ VFS-F-RO OR VFS-F-DIRTY OR SWAP ! DROP
    THEN
    _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + @ ;

VARIABLE _EXT4-JAP-BUF
VARIABLE _EXT4-JAP-WRITER
VARIABLE _EXT4-JAP-CTX
VARIABLE _EXT4-JAP-HEAD
VARIABLE _EXT4-JAP-EXPECTED-HEAD
VARIABLE _EXT4-JAP-EXPECTED-NEXT

\ Bind a fresh clean-primary reread to an exact validated journal endpoint.
\ A feature-zero JBD2 superblock has no checksum, so generic usability alone
\ cannot prevent stale geometry or identity from being newly authenticated.
: _EXT4-ACTIVATION-PRIMARY?
  ( buffer ctx expected-head expected-next-tid -- flag ior )
    _EXT4-JAP-EXPECTED-NEXT ! _EXT4-JAP-EXPECTED-HEAD !
    _EXT4-JAP-CTX ! _EXT4-JAP-BUF !
    _EXT4-JAP-BUF @ _EXT4-JS.MAGIC + _EXT4-BE32@
    _EXT4-JBD2-MAGIC <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.TYPE + _EXT4-BE32@
    _EXT4-JBD2-SUPER-V2 <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.HEADER-SEQUENCE + _EXT4-BE32@ IF
        FALSE 0 EXIT
    THEN
    _EXT4-JAP-BUF @ _EXT4-JS.BLOCK-SIZE + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAXLEN + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.FIRST + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.FIRST + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.SEQUENCE + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JAP-EXPECTED-NEXT @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.START + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.START + @ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@ DUP _EXT4-JAP-HEAD !
    _EXT4-JAP-CTX @ _EXT4-C.J.HEAD + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-HEAD @ DUP 0= IF
        DROP _EXT4-JAP-CTX @ _EXT4-C.J.FIRST + @
    THEN
    _EXT4-JAP-EXPECTED-HEAD @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.ERRNO + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.COMPAT + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.RO-COMPAT + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.FEATURES + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.UUID +
    _EXT4-JAP-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
    16 _EXT4-BYTES=? 0= IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.NR-USERS + _EXT4-BE32@ 1 <> IF
        FALSE 0 EXIT
    THEN
    _EXT4-JAP-BUF @ _EXT4-JS.DYNSUPER + _EXT4-BE32@ IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAX-TRANSACTION + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAX-TRANSACTION + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAX-TRANS-DATA + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAX-TRANS-DATA + @ <> IF FALSE 0 EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.FEATURES + @ IF
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@ 4 <> IF
            FALSE 0 EXIT
        THEN
        _EXT4-JAP-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ IF
            FALSE 0 EXIT
        THEN
        _EXT4-JAP-BUF @ _EXT4-JBD2-SUPER-CHECKSUM? ?DUP IF
            NIP 0 SWAP EXIT
        THEN 0= IF FALSE 0 EXIT THEN
    ELSE
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@
        _EXT4-JAP-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ OR
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32@ OR IF
            FALSE 0 EXIT
        THEN
    THEN
    _EXT4-JAP-BUF @ _EXT4-JAP-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        FALSE 0 EXIT
    THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.WITNESS + @ 0= 0 ;

: _EXT4-JWR-ACTIVATION-PRIMARY?  ( buffer writer -- flag ior )
    _EXT4-JAP-WRITER ! _EXT4-JAP-BUF !
    _EXT4-JAP-BUF @
    _EXT4-JAP-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JAP-WRITER @ _EXT4-JWR.HEAD + @
    _EXT4-JAP-WRITER @ _EXT4-JWR.NEXT-TID + @
    _EXT4-ACTIVATION-PRIMARY? ;

VARIABLE _EXT4-JWA-WRITER
VARIABLE _EXT4-JWA-CTX
VARIABLE _EXT4-JWA-GUARD
VARIABLE _EXT4-JAC-CTX
VARIABLE _EXT4-JAC-GUARD
VARIABLE _EXT4-JAC-SUPER
VARIABLE _EXT4-JAC-SCRATCH
VARIABLE _EXT4-JAC-WRITER

: _EXT4-JAC-PHASE  ( phase -- )
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR.PHASE + !
    ELSE
        DROP
    THEN ;

: _EXT4-JAC-FAULT  ( ior -- ior )
    DUP 0= IF EXIT THEN
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR-LATCH-FAULT EXIT
    THEN
    \ Mount owns writer-free activation failures.  Its next attempt must be
    \ able to resolve the durable AKW1 prefix without retaining a synthetic
    \ read-only latch that would poison later private-writer use.
    ;

\ Perform the witnessed clean-journal activation using caller-owned block
\ buffers.  The private writer supplies its retained scratch pair during
\ ordinary mutation; mount-time orphan recovery borrows DIR-BLOCK/TREE-BLOCK,
\ avoiding a one-off arena allocation that would freeze later writer credits.
\ All checks before ACTIVATING are non-mutating.  Every later failure leaves
\ AKW1 or a standard recovery endpoint for the next mount.
: _EXT4-ACTIVATE-CLEAN-JOURNAL
  ( ctx guard super-buffer scratch-buffer writer|0 -- ior )
    _EXT4-JAC-WRITER ! _EXT4-JAC-SCRATCH ! _EXT4-JAC-SUPER !
    _EXT4-JAC-GUARD ! _EXT4-JAC-CTX !
    _EXT4-JAC-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JAC-SUPER @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-STAMP-JOURNAL-ACTIVATION ?DUP IF EXIT THEN
    _EXT4-JAC-SUPER @ _EXT4-JBD2-SUPER-CHECKSUM?
    ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR-ACTIVATING SWAP _EXT4-JWR.STATE + !
    THEN
    _EXT4-JWP-GUARD-PRESEED _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-JAC-SCRATCH @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JAC-SCRATCH @ C!
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-GUARD _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-PRIMARY _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ 0 _EXT4-JAC-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-EXT4-SUPER _EXT4-JAC-PHASE
    _EXT4-JAC-CTX @ _EXT4-C.SB + _EXT4-PREPARE-DIRTY-SUPER
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + _EXT4-SB.CHECKSUM + L@
    _EXT4-AJS-NEW @ <> IF VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-PROOF _EXT4-JAC-PHASE
    0 _EXT4-JAC-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP _EXT4-JAC-FAULT EXIT THEN 0= IF
        DROP VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        DROP VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-SB.CHECKSUM + L@ _EXT4-AJS-NEW @ <> IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JWP-WITNESS-CLEAR _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-ZERO-JOURNAL-WITNESS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-SUPER @ 0 _EXT4-JAC-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-GUARD-RETIRE _EXT4-JAC-PHASE
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-JAC-CTX @ _EXT4-C.J.FEATURES + !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JAC-SUPER @ _EXT4-JS.UUID + 16 _EXT4-CRC-ADD
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-CRC@ _EXT4-JAC-CTX @ _EXT4-C.J.SEED + !
    _EXT4-JAC-SUPER @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JAC-CTX @ _EXT4-C.J.SEQUENCE + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.START + !
    _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JW-NONE _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.ANCHOR + !
    -1 _EXT4-JAC-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-JAC-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-IO-VFS @ ?DUP IF
        VFS-F-DIRTY SWAP V.FLAGS DUP @ ROT OR SWAP !
    THEN
    _EXT4-JAC-SUPER @ _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWP-NONE OVER _EXT4-JWR.PHASE + !
        _EXT4-JWR-IDLE SWAP _EXT4-JWR.STATE + !
    THEN
    0 ;

: _EXT4-JWR-ACTIVATE  ( writer -- ior )
    DUP _EXT4-JWA-WRITER ! _EXT4-JWR-VALID? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JWA-CTX !
    _EXT4-C.RECOVERY + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-CTX _EXT4-JWA-CTX @ <> IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ATTACHED? 0= IF DROP VFS-E-STALE EXIT THEN
    V.VOLUME @ _EXT4-IO-VOL @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.STATE + W@ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    0 _EXT4-JWA-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.BLOCK + _EXT4-JWA-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.HEAD + @ DUP _EXT4-JWA-GUARD !
    DUP _EXT4-JWA-WRITER @ _EXT4-JWR.FIRST + @ U<
    SWAP _EXT4-JWA-WRITER @ _EXT4-JWR.MAXLEN + @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWA-CTX @
    _EXT4-JWA-GUARD @
    _EXT4-JWA-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JWA-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JWA-WRITER @
    _EXT4-ACTIVATE-CLEAN-JOURNAL ;

\ =====================================================================
\  Private one-transaction JBD2 emission
\ =====================================================================
\
\ The public mutation surface remains disabled.  This layer turns one fully
\ staged transaction into an ordered, checksum-v3 JBD2 commit and deliberately
\ stops in COMMITTED state with all after-images retained for checkpointing.

VARIABLE _EXT4-JEE-SOURCE
VARIABLE _EXT4-JEE-DEST
VARIABLE _EXT4-JEE-WRITER

: _EXT4-JTX-ESCAPED-COPY  ( source dest writer -- flags )
    _EXT4-JEE-WRITER ! _EXT4-JEE-DEST ! _EXT4-JEE-SOURCE !
    _EXT4-JEE-SOURCE @ _EXT4-JEE-DEST @
    _EXT4-JEE-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JEE-DEST @ _EXT4-BE32@ _EXT4-JBD2-MAGIC = IF
        0 _EXT4-JEE-DEST @ _EXT4-BE32!
        _EXT4-JBD2-F-ESCAPE EXIT
    THEN
    0 ;

VARIABLE _EXT4-JEH-TYPE
VARIABLE _EXT4-JEH-BUF
VARIABLE _EXT4-JEH-WRITER

: _EXT4-JTX-HEADER!  ( type buffer writer -- )
    _EXT4-JEH-WRITER ! _EXT4-JEH-BUF ! _EXT4-JEH-TYPE !
    _EXT4-JBD2-MAGIC _EXT4-JEH-BUF @ _EXT4-BE32!
    _EXT4-JEH-TYPE @ _EXT4-JEH-BUF @ 4 + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEH-BUF @ 8 + _EXT4-BE32! ;

: _EXT4-JTX-BUILD-COMMIT  ( buffer writer -- ior )
    DUP _EXT4-JEH-WRITER ! SWAP DUP _EXT4-JEH-BUF !
    SWAP _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JBD2-COMMIT _EXT4-JEH-BUF @ _EXT4-JEH-WRITER @
    _EXT4-JTX-HEADER!
    _EXT4-JEH-BUF @ _EXT4-JEH-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JBD2-STAMP-COMMIT-CHECKSUM ;

: _EXT4-JTX-STAMP-ACTIVE-SUPER  ( buffer writer -- ior )
    _EXT4-JEH-WRITER ! _EXT4-JEH-BUF !
    _EXT4-JEH-BUF @ _EXT4-ZERO-JOURNAL-WITNESS
    ?DUP IF EXIT THEN
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEH-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEH-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-NEXT
    _EXT4-JEH-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEH-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-JEH-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    4 _EXT4-JEH-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    0 _EXT4-JEH-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32!
    _EXT4-JEH-BUF @ _EXT4-JBD2-STAMP-SUPER-CHECKSUM ;

VARIABLE _EXT4-JEP-WRITER
VARIABLE _EXT4-JEP-CTX
VARIABLE _EXT4-JEP-INDEX
VARIABLE _EXT4-JEP-INNER
VARIABLE _EXT4-JEP-ENTRY
VARIABLE _EXT4-JEP-IMAGE
VARIABLE _EXT4-JEP-HOME
VARIABLE _EXT4-JEP-ACTUAL
VARIABLE _EXT4-JEP-IOR
VARIABLE _EXT4-JEP-SENTINEL

: _EXT4-JTX-PREFLIGHT-IMAGES  ( writer -- ior )
    DUP _EXT4-JEP-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JEP-CTX !
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JEP-ENTRY ! @ DUP _EXT4-JEP-HOME !
        0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-META-IMAGE
        DUP _EXT4-JEP-IMAGE ! _EXT4-JEP-WRITER @ _EXT4-JTX-IMAGE-CRC
        ?DUP IF NIP EXIT THEN
        _EXT4-JEP-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JEP-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JEP-IMAGE @ _EXT4-JEP-HOME @ _EXT4-JEP-CTX @
            _EXT4-RECOVERY-AUTHORITY-PRESERVED? ?DUP IF NIP EXIT THEN 0= IF
                VFS-E-CORRUPT EXIT
            THEN
            0 _EXT4-JEP-INNER !
            BEGIN
                _EXT4-JEP-INNER @
                _EXT4-JEP-WRITER @ _EXT4-JWR.DATA-USED + @ U<
            WHILE
                _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
                _EXT4-JWR-DATA-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                    @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
                ELSE DROP THEN
                1 _EXT4-JEP-INNER +!
            REPEAT
            0 _EXT4-JEP-INNER !
            BEGIN
                _EXT4-JEP-INNER @
                _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
            WHILE
                _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
                _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                    @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
                ELSE DROP THEN
                1 _EXT4-JEP-INNER +!
            REPEAT
        THEN
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JEP-ENTRY ! @ DUP _EXT4-JEP-HOME !
        0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-DATA-IMAGE
        DUP _EXT4-JEP-IMAGE ! _EXT4-JEP-WRITER @ _EXT4-JTX-IMAGE-CRC
        ?DUP IF NIP EXIT THEN
        _EXT4-JEP-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JEP-HOME @ _EXT4-JEP-CTX @
        _EXT4-RECOVERY-AUTHORITY-BLOCK? IF VFS-E-INVALID EXIT THEN
        0 _EXT4-JEP-INNER !
        BEGIN
            _EXT4-JEP-INNER @
            _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
        WHILE
            _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
            _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
            ELSE DROP THEN
            1 _EXT4-JEP-INNER +!
        REPEAT
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        @ 0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 ;

: _EXT4-JTX-PREFLIGHT  ( writer -- ior )
    DUP _EXT4-JEP-WRITER ! _EXT4-JTX-ACTIVE? ?DUP IF EXIT THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JEP-CTX !
    DUP _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.PRIMARY-TORN + @
    _EXT4-JEP-CTX @ _EXT4-C.J.CLEANUP + @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.SUPER-TORN + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-CTX _EXT4-JEP-CTX @ <> IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ATTACHED? 0= IF DROP VFS-E-STALE EXIT THEN
    V.VOLUME @ _EXT4-IO-VOL @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.STATE + W@ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    8 _EXT4-JEP-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.INODE +
    _EXT4-JEP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JEP-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-JEP-WRITER @ _EXT4-JTX-PREFLIGHT-IMAGES ?DUP IF EXIT THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JEP-WRITER @ _EXT4-JTX-LOG-BLOCKS
    _EXT4-JEP-IOR ! _EXT4-JEP-ACTUAL !
    _EXT4-JEP-IOR @ IF _EXT4-JEP-IOR @ EXIT THEN
    _EXT4-JEP-ACTUAL @ 2 U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-ACTUAL @
    _EXT4-JEP-WRITER @ _EXT4-JWR.LOG-RESERVED + @ U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEP-ACTUAL @ _EXT4-JEP-CTX @ _EXT4-JOURNAL-ADVANCE
    DUP _EXT4-JEP-SENTINEL !
    _EXT4-JEP-WRITER @ _EXT4-JWR.TX-START + @ = IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JEP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.BLOCK + _EXT4-JEP-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JEM-WRITER
VARIABLE _EXT4-JEM-CTX
VARIABLE _EXT4-JEM-CURSOR
VARIABLE _EXT4-JEM-COMMIT
VARIABLE _EXT4-JEM-SENTINEL
VARIABLE _EXT4-JEM-ACTUAL
VARIABLE _EXT4-JEM-INDEX
VARIABLE _EXT4-JEM-SCAN
VARIABLE _EXT4-JEM-BATCH-START
VARIABLE _EXT4-JEM-BATCH-END
VARIABLE _EXT4-JEM-COUNT
VARIABLE _EXT4-JEM-OFF
VARIABLE _EXT4-JEM-LAST-TAG
VARIABLE _EXT4-JEM-ENTRY
VARIABLE _EXT4-JEM-TAG
VARIABLE _EXT4-JEM-FLAGS
VARIABLE _EXT4-JEM-OLD-RESERVED

: _EXT4-JEM-FAULT  ( ior -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR-LATCH-FAULT ;

: _EXT4-JEM-ADVANCE  ( -- )
    _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    _EXT4-JEM-CURSOR ! ;

\ Every block a map validation, a reload or the static-role table reads is
\ one the medium's bitmap marks allocated, or static metadata in a group
\ whose bitmap is uninitialized.  A data home the bitmap marks free, outside
\ every static role and the journal, is therefore none of them, and on a
\ mount whose ownership proof stands, ordered data written only to such homes
\ keeps the map epoch.  The homes are checked before the first data write.
VARIABLE _EXT4-JEM-FRESH
VARIABLE _EXT4-JEM-SCAN

: _EXT4-JEM-FRESH-HOME?  ( home -- fresh? ior )
    DUP _EXT4-JEM-CTX @ _EXT4-JOURNAL-DATA? IF DROP FALSE 0 EXIT THEN
    DUP 1 _EXT4-SR-ALIAS? IF DROP FALSE 0 EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-BLOCK-ALLOCATED? ?DUP IF NIP FALSE SWAP EXIT THEN
    0= 0 ;

: _EXT4-JEM-FRESH-DATA?  ( -- fresh? ior )
    _EXT4-JEM-CTX @ _EXT4-C.OWNERSHIP + @ -1 <> IF FALSE 0 EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-SR-CURRENT ?DUP IF FALSE SWAP EXIT THEN
    0 _EXT4-JEM-SCAN !
    BEGIN
        _EXT4-JEM-SCAN @ _EXT4-JEM-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEM-SCAN @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP CELL+ @ _EXT4-JE-ACTIVE = IF
            @ _EXT4-JEM-FRESH-HOME? ?DUP IF NIP FALSE SWAP EXIT THEN
            0= IF FALSE 0 EXIT THEN
        ELSE
            DROP
        THEN
        1 _EXT4-JEM-SCAN +!
    REPEAT
    TRUE 0 ;

: _EXT4-JTX-EMIT-ORDERED-DATA  ( -- ior )
    FALSE _EXT4-JEM-FRESH !
    _EXT4-JEM-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ IF
        _EXT4-JWP-ORDERED-DATA _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-FRESH-DATA? ?DUP IF NIP _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-FRESH !
    THEN
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JWP-ORDERED-DATA
            _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
            _EXT4-MAP-EPOCH @ >R
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-IMAGE
            _EXT4-JEM-ENTRY @ @ _EXT4-JEM-CTX @ _EXT4-WRITE-BLOCK
            _EXT4-JEM-FRESH @ IF R> _EXT4-MAP-EPOCH ! ELSE R> DROP THEN
            ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT
    0 ;

: _EXT4-JEM-SKIP-CANCELLED-META  ( -- )
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
        CELL+ @ _EXT4-JE-ACTIVE = IF EXIT THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT ;

: _EXT4-JEM-PREPARE-META-PAYLOAD  ( index -- flags )
    _EXT4-JEM-WRITER @ _EXT4-JWR-META-IMAGE
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-ESCAPED-COPY ;

: _EXT4-JTX-EMIT-METADATA  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-SKIP-CANCELLED-META
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
        _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
        _EXT4-JBD2-DESCRIPTOR SWAP _EXT4-JEM-WRITER @
        _EXT4-JTX-HEADER!
        _EXT4-JEM-INDEX @ _EXT4-JEM-BATCH-START !
        0 _EXT4-JEM-COUNT ! 12 _EXT4-JEM-OFF !
        BEGIN
            _EXT4-JEM-INDEX @
            _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
            _EXT4-JEM-COUNT @
            _EXT4-JEM-WRITER @ _EXT4-JTX-TAGS/BLOCK U< AND
        WHILE
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
            DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-INDEX @ _EXT4-JEM-PREPARE-META-PAYLOAD
                _EXT4-JEM-FLAGS !
                _EXT4-JEM-COUNT @ IF
                    _EXT4-JEM-FLAGS @ _EXT4-JBD2-F-SAME-UUID OR
                    _EXT4-JEM-FLAGS !
                THEN
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
                _EXT4-JEM-OFF @ + DUP _EXT4-JEM-TAG !
                _EXT4-JEM-ENTRY @ @ OVER _EXT4-BE32!
                _EXT4-JEM-FLAGS @ OVER 4 + _EXT4-BE32!
                0 OVER 8 + _EXT4-BE32!
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
                _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @
                _EXT4-JEM-CTX @ _EXT4-JBD2-EMIT-TAG-CHECKSUM
                ?DUP IF NIP NIP _EXT4-JEM-FAULT EXIT THEN
                SWAP 12 + _EXT4-BE32!
                _EXT4-JEM-COUNT @ 0= IF
                    _EXT4-JEM-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
                    _EXT4-JEM-TAG @ _EXT4-JBD2-TAG3-SIZE +
                    16 MOVE
                THEN
                _EXT4-JEM-TAG @ _EXT4-JEM-LAST-TAG !
                _EXT4-JBD2-TAG3-SIZE _EXT4-JEM-OFF +!
                _EXT4-JEM-COUNT @ 0= IF 16 _EXT4-JEM-OFF +! THEN
                1 _EXT4-JEM-COUNT +!
            THEN
            1 _EXT4-JEM-INDEX +!
        REPEAT
        _EXT4-JEM-INDEX @ _EXT4-JEM-BATCH-END !
        _EXT4-JEM-COUNT @ 0= IF VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-LAST-TAG @ 4 + DUP _EXT4-BE32@
        _EXT4-JBD2-F-LAST OR SWAP _EXT4-BE32!
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JEM-CTX @
        _EXT4-JBD2-STAMP-BLOCK-CHECKSUM
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JWP-DESCRIPTOR _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
        _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-ADVANCE
        _EXT4-JEM-BATCH-START @ _EXT4-JEM-SCAN !
        BEGIN
            _EXT4-JEM-SCAN @ _EXT4-JEM-BATCH-END @ U<
        WHILE
            _EXT4-JEM-SCAN @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
            CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-SCAN @ _EXT4-JEM-PREPARE-META-PAYLOAD DROP
                _EXT4-JWP-PAYLOAD _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
                _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
                ?DUP IF _EXT4-JEM-FAULT EXIT THEN
                _EXT4-JEM-ADVANCE
            THEN
            1 _EXT4-JEM-SCAN +!
        REPEAT
    REPEAT
    0 ;

: _EXT4-JEM-SKIP-CANCELLED-REVOKE  ( -- )
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        CELL+ @ _EXT4-JE-ACTIVE = IF EXIT THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT ;

: _EXT4-JTX-EMIT-REVOKES  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-SKIP-CANCELLED-REVOKE
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
        _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
        _EXT4-JBD2-REVOKE SWAP _EXT4-JEM-WRITER @ _EXT4-JTX-HEADER!
        0 _EXT4-JEM-COUNT ! 16 _EXT4-JEM-OFF !
        BEGIN
            _EXT4-JEM-INDEX @
            _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
            _EXT4-JEM-COUNT @
            _EXT4-JEM-WRITER @ _EXT4-JTX-REVOKES/BLOCK U< AND
        WHILE
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-REVOKE-ENTRY
            DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
                _EXT4-JEM-OFF @ +
                0 OVER _EXT4-BE32!
                _EXT4-JEM-ENTRY @ @ SWAP 4 + _EXT4-BE32!
                8 _EXT4-JEM-OFF +!
                1 _EXT4-JEM-COUNT +!
            THEN
            1 _EXT4-JEM-INDEX +!
        REPEAT
        _EXT4-JEM-COUNT @ 0= IF VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-COUNT @ 8 * 16 +
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ 12 + _EXT4-BE32!
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JEM-CTX @
        _EXT4-JBD2-STAMP-BLOCK-CHECKSUM
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JWP-REVOKE _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
        _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-ADVANCE
    REPEAT
    0 ;

: _EXT4-JTX-PRESEED-COMMIT-AND-SENTINEL  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-BUILD-COMMIT
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    0 _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @ C!
    _EXT4-JEM-CURSOR @ _EXT4-JEM-COMMIT !
    _EXT4-JWP-COMMIT-PRESEED _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    DUP _EXT4-JEM-CURSOR ! _EXT4-JEM-SENTINEL @ <> IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JWP-SENTINEL _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-SENTINEL @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-BODY-FLUSH _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 ;

: _EXT4-JTX-INSTALL-ACTIVE-SUPER  ( -- ior )
    _EXT4-JWP-ACTIVE-GUARD-PRESEED
    _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    0 _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK + _EXT4-JEM-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? ?DUP IF
        NIP _EXT4-JEM-FAULT EXIT
    THEN 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-STAMP-ACTIVE-SUPER
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    0 _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @ C!
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-ACTIVE-GUARD _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-ACTIVE-PRIMARY _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    0 _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    0 ;

: _EXT4-JTX-WRITE-COMMIT  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-BUILD-COMMIT
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-COMMIT _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-COMMIT-FLUSH _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 ;

: _EXT4-JTX-PUBLISH-COMMITTED  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    DUP _EXT4-JEM-OLD-RESERVED ! _EXT4-JEM-ACTUAL @ U< IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-OLD-RESERVED @ _EXT4-JEM-ACTUAL @ -
    _EXT4-JEM-WRITER @ _EXT4-JWR.FREE + +!
    _EXT4-JEM-ACTUAL @ _EXT4-JEM-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    _EXT4-JEM-SENTINEL @ DUP
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-CURSOR + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @ 1+
    0xFFFFFFFF AND _EXT4-JEM-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    _EXT4-JEM-CTX @ _EXT4-C.J.START + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEM-CTX @ _EXT4-C.J.SEQUENCE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @ DUP
    _EXT4-JEM-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JEM-CTX @ _EXT4-C.J.ANCHOR + !
    _EXT4-JEM-SENTINEL @ _EXT4-JEM-CTX @ _EXT4-C.J.CURSOR + !
    1 _EXT4-JEM-CTX @ _EXT4-C.J.COMMITTED + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
    0xFFFFFFFF AND _EXT4-JEM-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JC-ACTIVE _EXT4-JEM-CTX @ _EXT4-C.J.CLEANUP + !
    _EXT4-JWP-NONE _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-COMMITTED _EXT4-JEM-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR-VALID? 0= IF
        _EXT4-JWP-COMMIT-FLUSH
        _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    0 ;

: _EXT4-JTX-EMIT  ( transaction -- ior )
    DUP _EXT4-JEM-WRITER ! _EXT4-JTX-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JEM-CTX !
    _EXT4-JEP-ACTUAL @ _EXT4-JEM-ACTUAL !
    _EXT4-JEP-SENTINEL @ _EXT4-JEM-SENTINEL !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT _EXT4-JEM-CURSOR !
    _EXT4-JWR-EMITTING _EXT4-JEM-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JTX-EMIT-ORDERED-DATA ?DUP IF EXIT THEN
    _EXT4-JTX-EMIT-METADATA ?DUP IF EXIT THEN
    _EXT4-JTX-EMIT-REVOKES ?DUP IF EXIT THEN
    _EXT4-JTX-PRESEED-COMMIT-AND-SENTINEL ?DUP IF EXIT THEN
    _EXT4-JTX-INSTALL-ACTIVE-SUPER ?DUP IF EXIT THEN
    _EXT4-JTX-WRITE-COMMIT ?DUP IF EXIT THEN
    _EXT4-JTX-PUBLISH-COMMITTED ;

\ =====================================================================
\  Unified legacy/modern orphan recovery preflight
\ =====================================================================
\
\ Orphan state is authoritative only after committed JBD2 after-images have
\ reached home.  Mount therefore calls this through VALIDATE-REST after replay
\ and strict reload.  Two passes first derive the exact union count, then fill
\ one arena-backed open-addressed plan.  Each occupied slot authenticates an
\ inode and retains only protocol locators that can be reauthenticated before
\ later cleanup: legacy { inode, next } or modern { logical block, slot }.
\ Discovery itself never mutates an inode, orphan-file block, or legacy link.
\ Mounted cleanup qualifies the whole union, then drains one deterministic,
\ sealed record per transaction without imposing a record-count policy cap.

VARIABLE _EXT4-OW-CTX
VARIABLE _EXT4-OW-COUNT
VARIABLE _EXT4-OW-REQUIRED
VARIABLE _EXT4-OW-BYTES
VARIABLE _EXT4-MRW-CTX
VARIABLE _EXT4-MRW-REQUIRED
VARIABLE _EXT4-MRW-BYTES

_EXT4-NONNEG-MAX _EXT4-ORPHAN-RECORD-SIZE /
CONSTANT _EXT4-ORPHAN-SLOTS-MAX

\ Retain the shared 2P+16 authority budget: all direct and single-indirect data
\ plus one complete double-indirect child, its three map homes, and one xattr.
\ Additional sparse children are admitted by actual occupancy within the same
\ workspace.  Resident depth-one fanout is smaller at every mounted block size.
: _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY  ( ctx -- capacity ior )
    DUP 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    _EXT4-C.BSIZE + @ _EXT4-DELETE-RANGE-CAPACITY ;

: _EXT4-MUTATION-RANGE-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.MUTATION-RANGES + @
    SWAP _EXT4-C.MUTATION-RANGE-CAP + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 0< IF 2DROP FALSE EXIT THEN
    2 _EXT4-UMUL? DUP IF NIP 2DROP FALSE EXIT THEN DROP
    1 CELLS _EXT4-UMUL? DUP IF NIP 2DROP FALSE EXIT THEN DROP
    MSPAN-NONWRAPPING? ;

: _EXT4-ENSURE-MUTATION-RANGE-WORKSPACE  ( ctx -- ior )
    DUP _EXT4-MRW-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MRW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY
    DUP IF NIP EXIT THEN DROP _EXT4-MRW-REQUIRED !
    _EXT4-MRW-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGES + @ IF
        _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
        _EXT4-MRW-REQUIRED @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGES + @
        _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @
        2 * CELLS 0 FILL
        0 EXIT
    THEN
    _EXT4-MRW-REQUIRED @ 2 _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP
    1 CELLS _EXT4-UMUL? DUP IF NIP EXIT THEN DROP _EXT4-MRW-BYTES !
    _EXT4-MRW-CTX @ _EXT4-C.ARENA + @
    _EXT4-MRW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGES + !
    _EXT4-MRW-BYTES @ 0 FILL
    _EXT4-MRW-REQUIRED @
    _EXT4-MRW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + !
    0 ;

VARIABLE _EXT4-CW-CTX
VARIABLE _EXT4-CW-BYTES

\ The block-claim workspace holds a claim map of the volume's blocks and one
\ block of scratch.  The ownership proof and every transaction's map check
\ use it while a mount cleanup writer may own the arena's end, so it is
\ reserved with the other persistent workspaces and cleared on each reuse.
: _EXT4-CLAIM-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.CLAIM-WORKSPACE + @
    SWAP _EXT4-C.CLAIM-WORKSPACE-BYTES + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 0< IF 2DROP FALSE EXIT THEN
    MSPAN-NONWRAPPING? ;

: _EXT4-ENSURE-CLAIM-WORKSPACE  ( ctx -- ior )
    DUP _EXT4-CW-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-CW-CTX @ _EXT4-CLAIM-WORKSPACE? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-CW-CTX @ _EXT4-OWN-BYTES
    _EXT4-CW-CTX @ _EXT4-C.BSIZE + @ + _EXT4-CW-BYTES !
    _EXT4-CW-CTX @ _EXT4-C.CLAIM-WORKSPACE + @ IF
        _EXT4-CW-CTX @ _EXT4-C.CLAIM-WORKSPACE-BYTES + @
        _EXT4-CW-BYTES @ U< IF VFS-E-NOMEM EXIT THEN
    ELSE
        _EXT4-CW-CTX @ _EXT4-C.ARENA + @
        _EXT4-CW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
        _EXT4-CW-CTX @ _EXT4-C.CLAIM-WORKSPACE + !
        _EXT4-CW-BYTES @
        _EXT4-CW-CTX @ _EXT4-C.CLAIM-WORKSPACE-BYTES + !
    THEN
    _EXT4-CW-CTX @ _EXT4-C.CLAIM-WORKSPACE + @
    _EXT4-CW-CTX @ _EXT4-C.CLAIM-WORKSPACE-BYTES + @ 0 FILL
    0 ;

: _EXT4-ORPHAN-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.O.TABLE + @
    SWAP _EXT4-C.O.SLOTS + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 2 U< IF 2DROP FALSE EXIT THEN
    DUP _EXT4-ORPHAN-SLOTS-MAX U> IF 2DROP FALSE EXIT THEN
    DUP 1- AND 0= NIP ;

\ Reserve the geometry-derived mutation-range, block-claim and static-role
\ workspaces before examining any orphan inode or orphan-file block.  A
\ failed mount's retry reuses the retained allocations, so each is taken
\ from the monotonic arena once.
: _EXT4-ENSURE-ORPHAN-AUTH-WORKSPACE  ( ctx -- ior )
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ENSURE-MUTATION-RANGE-WORKSPACE
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-ENSURE-CLAIM-WORKSPACE ?DUP IF NIP EXIT THEN
    _EXT4-ENSURE-ROLE-WORKSPACE ;

\ Authenticate the retained runtime allocation structurally before using any
\ its fields in rollback geometry.  Current media capacity is authenticated
\ separately when the staged binding validates or binds this workspace.
: _EXT4-MOUNT-RUNTIME-BELOW-MARK?  ( -- flag )
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-TABLE + @ _EXT4-ROE-TABLE !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-SLOTS + @ _EXT4-ROE-SLOTS !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ _EXT4-ROE-CAP !
    _EXT4-ROE-CTX @ _EXT4-C.O.RUNTIME-END + @
    _EXT4-ROE-RUNTIME-END !
    _EXT4-ROE-TABLE @ _EXT4-ROE-SLOTS @ OR
    _EXT4-ROE-CAP @ OR _EXT4-ROE-RUNTIME-END @ OR 0= IF TRUE EXIT THEN
    _EXT4-ROE-TABLE @ 0= _EXT4-ROE-SLOTS @ 0= OR
    _EXT4-ROE-CAP @ 0= OR _EXT4-ROE-RUNTIME-END @ 0= OR IF
        FALSE EXIT
    THEN
    _EXT4-ROE-SLOTS @ 2 U<
    _EXT4-ROE-SLOTS @ _EXT4-ORPHAN-SLOTS-MAX U> OR
    _EXT4-ROE-SLOTS @ 1- _EXT4-ROE-SLOTS @ AND OR IF
        FALSE EXIT
    THEN
    _EXT4-ROE-CAP @ _EXT4-HASH-SLOTS
    DUP IF 2DROP FALSE EXIT THEN
    DROP _EXT4-ROE-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-ROE-SLOTS @ _EXT4-ORPHAN-RECORD-SIZE _EXT4-UMUL?
    DUP IF 2DROP FALSE EXIT THEN
    DROP _EXT4-ROE-BYTES !
    _EXT4-ROE-TABLE @ 7 AND IF FALSE EXIT THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BYTES @
    MSPAN-NONWRAPPING? 0= IF FALSE EXIT THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BASE @ U< IF FALSE EXIT THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-BYTES @ +
    _EXT4-ROE-RUNTIME-END @ <> IF FALSE EXIT THEN
    _EXT4-ROE-RUNTIME-END @ _EXT4-ROE-MARK @ <> IF FALSE EXIT THEN
    TRUE ;

\ Begin the context-owned rollback tail after every persistent mount
\ allocation.  Current plan and replay-revoke publications must be empty.
: _EXT4-MOUNT-TAIL-BEGIN  ( ctx -- ior )
    DUP _EXT4-ROE-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.MOUNT-TAIL-MARK + @ IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.TABLE + @
    _EXT4-ROE-CTX @ _EXT4-C.O.SLOTS + @ OR
    _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-TABLE + @ OR
    _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-SLOTS + @ OR IF
        VFS-E-CONFLICT EXIT
    THEN
    \ A failed or interrupted mount may retain a non-current writer below
    \ this mark (or in its disjoint dedicated arena).  Final mount rebase
    \ validates and scrubs that workspace; only live authority is forbidden.
    _EXT4-ROE-CTX @ _EXT4-C.J.WRITER-CURRENT + @ IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-LOAD-MOUNT-ARENA ?DUP IF EXIT THEN
    _EXT4-ROE-ARENA @ ARENA-SNAP DUP _EXT4-ROE-MARK !
    _EXT4-ROE-END @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-MOUNT-RUNTIME-BELOW-MARK? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-MARK @ _EXT4-ROE-CTX @
    _EXT4-C.O.MOUNT-TAIL-MARK + !
    0 ;

\ Validate and withdraw every transient publication before scrubbing and
\ rolling the complete outer tail back to its retained context mark.
: _EXT4-MOUNT-TAIL-RELEASE  ( ctx -- ior )
    DUP _EXT4-ROE-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-C.O.MOUNT-TAIL-MARK + @ DUP
    _EXT4-ROE-MARK ! 0= IF 0 EXIT THEN
    \ The rollback tail begins after persistent mount allocations.  Preserve
    \ a retained non-current writer for final authenticated rebase while
    \ refusing any publication that could still mutate through it.
    _EXT4-ROE-CTX @ _EXT4-C.J.WRITER-CURRENT + @ IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-LOAD-MOUNT-ARENA ?DUP IF EXIT THEN
    _EXT4-ROE-MARK @ _EXT4-ROE-BASE @ U<
    _EXT4-ROE-END @ _EXT4-ROE-MARK @ U< OR IF VFS-E-CORRUPT EXIT THEN
    _EXT4-ROE-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROE-CTX @ _EXT4-REVOKE-GEOMETRY? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    \ Plan then revoke are the only outer-tail allocations.  Walk their exact
    \ checked extents from MARK to A.PTR so neither gaps nor reordered aliases
    \ can widen the scrubbed region into retained storage.
    _EXT4-ROE-MARK @ _EXT4-ROE-TABLE !
    _EXT4-ROE-CTX @ _EXT4-C.O.TABLE + @ ?DUP IF
        _EXT4-ROE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-ROE-TABLE @ _EXT4-ROE-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-ORPHAN-RECORD-SIZE *
        2DUP MSPAN-NONWRAPPING? 0= IF 2DROP VFS-E-CORRUPT EXIT THEN
        + _EXT4-ROE-TABLE !
    THEN
    _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-TABLE + @ ?DUP IF
        _EXT4-ROE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-ROE-TABLE @ _EXT4-ROE-CTX @
        _EXT4-C.J.REVOKE-SLOTS + @ 2* CELLS
        2DUP MSPAN-NONWRAPPING? 0= IF 2DROP VFS-E-CORRUPT EXIT THEN
        + _EXT4-ROE-TABLE !
    THEN
    _EXT4-ROE-TABLE @ _EXT4-ROE-END @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-MOUNT-RUNTIME-BELOW-MARK? 0= IF VFS-E-CORRUPT EXIT THEN
    0 _EXT4-ROE-CTX @ _EXT4-C.O.TABLE + !
    0 _EXT4-ROE-CTX @ _EXT4-C.O.SLOTS + !
    0 _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-TABLE + !
    0 _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-SLOTS + !
    0 _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-HITS + !
    0 _EXT4-ROE-CTX @ _EXT4-C.J.REVOKE-READY + !
    0 _EXT4-ROE-CTX @ _EXT4-C.O.MOUNT-TAIL-MARK + !
    _EXT4-ROE-MARK @ _EXT4-ROE-END @ _EXT4-ROE-MARK @ - 0 FILL
    _EXT4-ROE-ARENA @ _EXT4-ROE-MARK @ ARENA-ROLLBACK
    0 ;

\ Allocate the half-full power-of-two uniqueness plan only after its exact
\ authenticated union count is known.  A retry that needs a larger table fails
\ without consuming a second monotonic allocation.
: _EXT4-ENSURE-ORPHAN-PLAN-WORKSPACE  ( active-count ctx -- ior )
    _EXT4-OW-CTX ! DUP _EXT4-OW-COUNT ! DROP
    _EXT4-OW-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-OW-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OW-COUNT @ _EXT4-HASH-SLOTS
    DUP IF NIP EXIT THEN DROP _EXT4-OW-REQUIRED !
    _EXT4-OW-CTX @ _EXT4-C.O.TABLE + @ IF
        _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-OW-REQUIRED @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-OW-CTX @ _EXT4-C.O.TABLE + @
        _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-ORPHAN-RECORD-SIZE * 0 FILL
        0 EXIT
    THEN
    _EXT4-OW-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-OW-REQUIRED @ _EXT4-ORPHAN-SLOTS-MAX U> IF
        EXT4-D-ORPHAN-FILE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-OW-REQUIRED @ _EXT4-ORPHAN-RECORD-SIZE * _EXT4-OW-BYTES !
    _EXT4-OW-CTX @ _EXT4-C.ARENA + @
    _EXT4-OW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-OW-CTX @ _EXT4-C.O.TABLE + !
    _EXT4-OW-BYTES @ 0 FILL
    _EXT4-OW-REQUIRED @ _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + !
    0 ;

VARIABLE _EXT4-OH-CTX
VARIABLE _EXT4-OH-INO
VARIABLE _EXT4-OH-KIND
VARIABLE _EXT4-OH-A
VARIABLE _EXT4-OH-B
VARIABLE _EXT4-OH-SLOT

: _EXT4-ORPHAN-TABLE-ENTRY  ( slot ctx -- address )
    _EXT4-C.O.TABLE + @ SWAP _EXT4-ORPHAN-RECORD-SIZE * + ;

: _EXT4-ORPHAN-TABLE-PUT  ( inode kind locator-a locator-b ctx -- ior )
    _EXT4-OH-CTX ! _EXT4-OH-B ! _EXT4-OH-A !
    _EXT4-OH-KIND ! _EXT4-OH-INO !
    _EXT4-OH-INO @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OH-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-OH-B @ IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    ELSE
        _EXT4-OH-KIND @ _EXT4-OK-MODERN <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ DUP 0= IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    1- _EXT4-OH-INO @ SWAP AND _EXT4-OH-SLOT !
    _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        _EXT4-OH-SLOT @ _EXT4-OH-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP @ DUP 0= IF
            DROP
            _EXT4-OH-INO @ OVER _EXT4-OE.INO + !
            _EXT4-OH-KIND @ OVER _EXT4-OE.KIND + !
            _EXT4-OH-A @ OVER _EXT4-OE.LOCATOR-A + !
            _EXT4-OH-B @ SWAP _EXT4-OE.LOCATOR-B + !
            0 UNLOOP EXIT
        THEN
        NIP _EXT4-OH-INO @ = IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-OH-SLOT @ 1+
        _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ 1- AND
        _EXT4-OH-SLOT !
    LOOP
    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT ;

VARIABLE _EXT4-OP-CTX
VARIABLE _EXT4-OP-COUNT
VARIABLE _EXT4-OP-ENTRIES
VARIABLE _EXT4-OL-CTX
VARIABLE _EXT4-OL-CURRENT
VARIABLE _EXT4-OL-NEXT
VARIABLE _EXT4-OL-COUNT
VARIABLE _EXT4-OL-LIMIT
VARIABLE _EXT4-OL-SLOW
VARIABLE _EXT4-OL-FAST
VARIABLE _EXT4-OS-CTX
VARIABLE _EXT4-OS-INO
VARIABLE _EXT4-ON-CTX
VARIABLE _EXT4-ON-INO

: _EXT4-ORPHAN-INODE-NUMBER?  ( inode-number ctx -- flag )
    _EXT4-ON-CTX ! _EXT4-ON-INO !
    _EXT4-ON-INO @
    _EXT4-ON-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0=
    _EXT4-ON-INO @ _EXT4-ON-CTX @ _EXT4-C.INODES + @ U> 0= AND ;

VARIABLE _EXT4-OPF-CTX
VARIABLE _EXT4-OPF-INO
VARIABLE _EXT4-OPF-ACTIVE
VARIABLE _EXT4-OPF-SLOTS
VARIABLE _EXT4-OPF-SLOT
VARIABLE _EXT4-OPF-ENTRY

\ Return the exact retained plan record for one inode.  Absence is not an
\ error: insertion preflight also uses this lookup to prove that a candidate
\ is not already in the authenticated union.  Every probe is bounded by the
\ retained power-of-two table size.
: _EXT4-ORPHAN-PLAN-FIND  ( inode-number ctx -- plan-record|0 ior )
    _EXT4-OPF-CTX ! _EXT4-OPF-INO !
    _EXT4-OPF-CTX @ 0= _EXT4-OPF-INO @ 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-OPF-INO @ _EXT4-OPF-CTX @
    _EXT4-ORPHAN-INODE-NUMBER? 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-OPF-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OPF-CTX @ _EXT4-C.O.ACTIVE + @ DUP 0< IF
        DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-OPF-ACTIVE !
    _EXT4-OPF-CTX @ _EXT4-C.INODES + @ U> IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OPF-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-OPF-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ _EXT4-UADD?
    DUP IF
        2DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP _EXT4-OPF-ACTIVE @ <> IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OPF-CTX @ _EXT4-C.O.SLOTS + @ _EXT4-OPF-SLOTS !
    _EXT4-OPF-ACTIVE @ 0= IF 0 0 EXIT THEN
    _EXT4-OPF-SLOTS @ 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OPF-ACTIVE @ _EXT4-HASH-SLOTS
    DUP IF
        2DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP _EXT4-OPF-SLOTS @ U> IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OPF-CTX @ _EXT4-C.O.TABLE + @
    _EXT4-OPF-SLOTS @ _EXT4-ORPHAN-RECORD-SIZE *
    MSPAN-NONWRAPPING? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OPF-INO @ _EXT4-OPF-SLOTS @ 1- AND _EXT4-OPF-SLOT !
    _EXT4-OPF-SLOTS @ 0 ?DO
        _EXT4-OPF-SLOT @ _EXT4-OPF-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-OPF-ENTRY ! @ DUP 0= IF
            DROP 0 0 UNLOOP EXIT
        THEN
        _EXT4-OPF-INO @ = IF
            _EXT4-OPF-ENTRY @ 0 UNLOOP EXIT
        THEN
        _EXT4-OPF-SLOT @ 1+ _EXT4-OPF-SLOTS @ 1- AND
        _EXT4-OPF-SLOT !
    LOOP
    0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT ;

: _EXT4-LEGACY-ORPHAN-NEXT  ( inode-number ctx -- next ior )
    _EXT4-OS-CTX ! DUP _EXT4-OS-INO !
    _EXT4-OS-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OS-INO @ _EXT4-OS-CTX @
    _EXT4-LOAD-ORPHAN-INODE DUP IF 0 SWAP EXIT THEN DROP
    _EXT4-OS-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@ DUP IF
        DUP _EXT4-OS-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
            DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Floyd's constant-space pass rejects cycles before the exact counting pass.
\ This avoids making a short malformed loop consume the whole inode-count
\ bound while retaining an allocation-free first pass.
: _EXT4-VALIDATE-LEGACY-TERMINATION  ( ctx -- ior )
    DUP _EXT4-OL-CTX ! _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
    DUP _EXT4-OL-SLOW ! _EXT4-OL-FAST !
    BEGIN
        _EXT4-OL-FAST @ 0= IF 0 EXIT THEN
        _EXT4-OL-FAST @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-FAST !
        _EXT4-OL-FAST @ 0= IF 0 EXIT THEN
        _EXT4-OL-FAST @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-FAST !
        _EXT4-OL-SLOW @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-SLOW !
        _EXT4-OL-FAST @ _EXT4-OL-SLOW @ = IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    AGAIN ;

\ Count the legacy singly linked list without allocating cycle state.  No
\ valid chain can visit more distinct inode numbers than FIRST_INO..INODES;
\ crossing that geometry-derived bound proves nontermination.  The second
\ pass inserts into the shared uniqueness plan and therefore identifies the
\ repeated inode directly.
: _EXT4-COUNT-LEGACY-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OL-CTX !
    DUP _EXT4-VALIDATE-LEGACY-TERMINATION ?DUP IF NIP EXIT THEN
    DUP _EXT4-C.INODES + @
    OVER _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ - 1+
    _EXT4-OL-LIMIT !
    _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ _EXT4-OL-CURRENT !
    0 _EXT4-OL-COUNT !
    BEGIN _EXT4-OL-CURRENT @ WHILE
        _EXT4-OL-COUNT @ _EXT4-OL-LIMIT @ U< 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-OL-CURRENT @ _EXT4-OL-CTX @
        _EXT4-LEGACY-ORPHAN-NEXT DUP IF NIP EXIT THEN
        DROP _EXT4-OL-NEXT !
        1 _EXT4-OL-COUNT +!
        _EXT4-OL-NEXT @ _EXT4-OL-CURRENT !
    REPEAT
    _EXT4-OL-COUNT @ _EXT4-OL-CTX @
    _EXT4-C.O.LEGACY-ACTIVE + !
    0 ;

: _EXT4-COUNT-ACTIVE-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.BSIZE + @ 8 - 4 / _EXT4-OP-ENTRIES !
    0 _EXT4-OP-COUNT !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-OP-ENTRIES @ 0 ?DO
            _EXT4-OP-CTX @ _EXT4-C.BLOCK + I 4 * + L@ ?DUP IF
                _EXT4-OP-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                    UNLOOP UNLOOP EXIT
                THEN
                1 _EXT4-OP-COUNT +!
            THEN
        LOOP
    LOOP
    _EXT4-OP-COUNT @ _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 ;

: _EXT4-INDEX-ACTIVE-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.BSIZE + @ 8 - 4 / _EXT4-OP-ENTRIES !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-OP-ENTRIES @ 0 ?DO
            _EXT4-OP-CTX @ _EXT4-C.BLOCK + I 4 * + L@ ?DUP IF
                _EXT4-OK-MODERN J I _EXT4-OP-CTX @
                _EXT4-ORPHAN-TABLE-PUT ?DUP IF
                    UNLOOP UNLOOP EXIT
                THEN
            THEN
        LOOP
    LOOP
    0 ;

: _EXT4-INDEX-LEGACY-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OL-CTX !
    _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ _EXT4-OL-CURRENT !
    _EXT4-OL-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0 ?DO
        _EXT4-OL-CURRENT @ 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-OL-CURRENT @ _EXT4-OL-CTX @
        _EXT4-LEGACY-ORPHAN-NEXT DUP IF NIP UNLOOP EXIT THEN
        DROP _EXT4-OL-NEXT !
        _EXT4-OL-CURRENT @ _EXT4-OK-LEGACY
        _EXT4-OL-NEXT @ 0 _EXT4-OL-CTX @
        _EXT4-ORPHAN-TABLE-PUT ?DUP IF UNLOOP EXIT THEN
        _EXT4-OL-NEXT @ _EXT4-OL-CURRENT !
    LOOP
    _EXT4-OL-CURRENT @ IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-OI-CTX
VARIABLE _EXT4-OI-INO
VARIABLE _EXT4-OI-IN
VARIABLE _EXT4-OI-NLINK
VARIABLE _EXT4-OI-TYPE
VARIABLE _EXT4-OI-IOR

\ ext4_orphan_get() admits allocated, checksum-valid inodes at or above
\ s_first_ino.  Linked entries must be truncatable; unlinked entries may be
\ any valid inode type because cleanup deletes them.  STAGE-CURRENT-INODE
\ already owns the complete type/size/flag/map checks.  For an unlinked inode
\ only, temporarily substitute a nonzero link count in the authenticated cache
\ while running that read-only validator, then restore the original bytes.
: _EXT4-VALIDATE-ACTIVE-ORPHAN  ( inode-number ctx -- ior )
    _EXT4-OI-CTX ! DUP _EXT4-OI-INO !
    DUP _EXT4-OI-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U<
    OVER _EXT4-OI-CTX @ _EXT4-C.INODES + @ U> OR IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-OI-INO @ _EXT4-OI-CTX @ _EXT4-LOAD-ORPHAN-INODE ?DUP IF
        EXIT
    THEN
    _EXT4-OI-CTX @ _EXT4-C.INODE + DUP _EXT4-OI-IN !
    _EXT4-I.LINKS + W@ DUP _EXT4-OI-NLINK ! 0= IF
        1 _EXT4-OI-IN @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-OI-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-OI-IOR ! _EXT4-OI-TYPE !
    _EXT4-OI-NLINK @ 0= IF
        0 _EXT4-OI-IN @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-OI-IOR @ ?DUP IF EXIT THEN
    _EXT4-OI-NLINK @ IF
        _EXT4-OI-TYPE @ VFS-T-FILE =
        _EXT4-OI-TYPE @ VFS-T-DIR = OR
        _EXT4-OI-TYPE @ VFS-T-SYMLINK = OR 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-OI-CTX @ _EXT4-OI-TYPE @ _EXT4-FAST-SYMLINK-STORAGE? IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

VARIABLE _EXT4-OQ-CTX
VARIABLE _EXT4-OQ-RECORD

: _EXT4-ORPHAN-RECORD?  ( record ctx -- flag )
    _EXT4-OQ-CTX ! DUP _EXT4-OQ-RECORD !
    DUP _EXT4-OE.INO + @ _EXT4-OQ-CTX @
    _EXT4-ORPHAN-INODE-NUMBER? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        DUP _EXT4-OE.LOCATOR-B + @ IF DROP FALSE EXIT THEN
        _EXT4-OE.LOCATOR-A + @ ?DUP IF
            _EXT4-OQ-CTX @ _EXT4-ORPHAN-INODE-NUMBER?
        ELSE
            TRUE
        THEN EXIT
    THEN
    DUP _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        DUP _EXT4-OE.LOCATOR-A + @ _EXT4-OV-BLOCKS @ U<
        SWAP _EXT4-OE.LOCATOR-B + @
        _EXT4-OQ-CTX @ _EXT4-C.BSIZE + @ 8 - 4 / U< AND
        EXIT
    THEN
    DROP FALSE ;

VARIABLE _EXT4-OM-RECORD
VARIABLE _EXT4-OM-CTX
VARIABLE _EXT4-OM-BASE
VARIABLE _EXT4-OM-OFF
VARIABLE _EXT4-OM-INO

\ Cleanup authority belongs to the exact retained discovery plan, not to a
\ caller-authored record that merely copies its four cells.
: _EXT4-ORPHAN-PLAN-MEMBER?  ( record ctx -- flag )
    _EXT4-OM-CTX ! _EXT4-OM-RECORD !
    _EXT4-OM-RECORD @ 0= _EXT4-OM-CTX @ 0= OR IF FALSE EXIT THEN
    _EXT4-OM-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF FALSE EXIT THEN
    _EXT4-OM-CTX @ _EXT4-C.O.TABLE + @ DUP _EXT4-OM-BASE !
    _EXT4-OM-BASE @ 0= IF DROP FALSE EXIT THEN
    _EXT4-OM-RECORD @ U> IF FALSE EXIT THEN
    _EXT4-OM-RECORD @ _EXT4-OM-BASE @ - DUP _EXT4-OM-OFF !
    _EXT4-ORPHAN-RECORD-SIZE MOD IF FALSE EXIT THEN
    _EXT4-OM-OFF @
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @
    _EXT4-ORPHAN-RECORD-SIZE * U< 0= IF FALSE EXIT THEN
    _EXT4-OM-RECORD @ @ DUP 0= IF DROP FALSE EXIT THEN
    _EXT4-OM-INO !
    _EXT4-OM-INO @ _EXT4-OM-CTX @ _EXT4-ORPHAN-PLAN-FIND
    DUP IF 2DROP FALSE EXIT THEN
    DROP _EXT4-OM-RECORD @ = ;

VARIABLE _EXT4-ORA-RECORD
VARIABLE _EXT4-ORA-CTX
VARIABLE _EXT4-ORA-INO
VARIABLE _EXT4-ORA-KIND

\ Reauthenticate both the retained discovery record and the current media
\ locator, then leave the checksum-valid target inode in C.INODE.  This is a
\ read-only authority check; staged transaction images never stand in for the
\ plan or for the raw orphan chain that the plan names.
: _EXT4-REAUTH-ORPHAN-PLAN-RECORD  ( plan-record ctx -- ior )
    _EXT4-ORA-CTX ! _EXT4-ORA-RECORD !
    _EXT4-ORA-RECORD @ 0= _EXT4-ORA-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-ORA-CTX @
    _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-ORA-INO !
    _EXT4-ORA-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-ORA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-ORA-RECORD @ _EXT4-ORA-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-ORA-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-ORA-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-ORA-CTX @ _EXT4-C.BLOCK +
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-ORA-INO @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-ORA-KIND @ _EXT4-OK-LEGACY <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-ORA-INO @ _EXT4-ORA-CTX @ _EXT4-LOAD-ORPHAN-INODE
    ?DUP IF EXIT THEN
    _EXT4-ORA-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-ORA-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-A + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

VARIABLE _EXT4-RMO-CTX
VARIABLE _EXT4-RMO-INO
VARIABLE _EXT4-RMO-RECORD

\ Resolve one modern orphan through the authenticated retained plan, then
\ reauthenticate its exact current media locator.  A missing inode or a valid
\ union member of another protocol is a non-corrupt lookup refusal.
: _EXT4-REAUTH-MODERN-ORPHAN-BY-INODE
  ( inode-number ctx -- plan-record ior )
    _EXT4-RMO-CTX ! _EXT4-RMO-INO !
    _EXT4-RMO-INO @ _EXT4-RMO-CTX @ _EXT4-ORPHAN-PLAN-FIND
    DUP IF NIP 0 SWAP EXIT THEN
    DROP DUP 0= IF DROP 0 VFS-E-NOENT EXIT THEN
    DUP _EXT4-RMO-RECORD !
    _EXT4-OE.KIND + @ _EXT4-OK-MODERN <> IF
        0 VFS-E-NOENT EXIT
    THEN
    _EXT4-RMO-RECORD @ _EXT4-RMO-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-RMO-RECORD @ 0 ;

VARIABLE _EXT4-URR-D
VARIABLE _EXT4-URR-V
VARIABLE _EXT4-URR-CTX
VARIABLE _EXT4-URR-VN
VARIABLE _EXT4-URR-RECORD
VARIABLE _EXT4-URR-IOR

\ A detached descriptor may read a durable zero-link regular inode only while
\ that exact inode remains authenticated by the mounted modern-orphan plan.
\ Namespace lookup never uses this path: the generic dentry must already be
\ unlinked, owned by this VFS, and retained by at least one live descriptor.
: _EXT4-AUTH-UNLINKED-READ  ( dentry vfs ctx -- type ior )
    _EXT4-URR-CTX ! _EXT4-URR-V ! _EXT4-URR-D !
    _EXT4-URR-D @ 0= _EXT4-URR-V @ 0= OR
    _EXT4-URR-CTX @ 0= OR IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-URR-D @ _EXT4-URR-V @ _VFS-DENTRY-OWNED? 0= IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-URR-D @ D.FLAGS @ VFS-DF-UNLINKED AND 0= IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-URR-D @ D.VNODE @ DUP _EXT4-URR-VN ! 0= IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-URR-VN @ VN.TYPE @ VFS-T-FILE <>
    _EXT4-URR-VN @ VN.NLINK @ OR
    _EXT4-URR-VN @ VN.OPEN-REFS @ 0= OR IF
        0 VFS-E-STALE EXIT
    THEN
    _EXT4-URR-VN @ VN.BID @ DUP 0= IF
        DROP 0 VFS-E-STALE EXIT
    THEN
    _EXT4-URR-D @ IN.BID @ <> IF 0 VFS-E-STALE EXIT THEN
    _EXT4-URR-CTX @ _EXT4-URR-V @
    _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING ?DUP IF 0 SWAP EXIT THEN
    _EXT4-URR-D @ IN.BID @ _EXT4-URR-CTX @
    _EXT4-REAUTH-MODERN-ORPHAN-BY-INODE
    _EXT4-URR-IOR ! _EXT4-URR-RECORD !
    _EXT4-URR-IOR @ ?DUP IF 0 SWAP EXIT THEN
    _EXT4-URR-RECORD @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-URR-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.LINKS + W@ 0= SWAP _EXT4-I.DTIME + L@ 0= AND 0= IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-OI-TYPE @ VFS-T-FILE <>
    _EXT4-URR-CTX @ _EXT4-C.R.GEN + @
    _EXT4-URR-VN @ VN.GEN @ <> OR
    _EXT4-URR-CTX @ _EXT4-C.R.SIZE + @
    _EXT4-URR-VN @ VN.SIZE-LO @ <> OR
    _EXT4-URR-VN @ VN.SIZE-HI @ OR
    _EXT4-URR-CTX @ _EXT4-C.R.BLOCKS + @
    _EXT4-URR-VN @ VN.BLOCKS @ <> OR IF
        0 VFS-E-STALE EXIT
    THEN
    0 _EXT4-URR-CTX @ _EXT4-C.R.NLINK + !
    VFS-T-FILE 0 ;

' _EXT4-AUTH-UNLINKED-READ _EXT4-DR-UNLINKED-AUTH-XT !

: _EXT4-VALIDATE-INDEXED-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-OQ-RECORD ! @ ?DUP IF
            _EXT4-OQ-RECORD @ _EXT4-OP-CTX @
            _EXT4-ORPHAN-RECORD? 0= IF
                DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-OP-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF
                UNLOOP EXIT
            THEN
            _EXT4-OQ-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN =
            _EXT4-OP-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0<> AND IF
                _EXT4-OP-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@ IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
                THEN
            THEN
        THEN
    LOOP
    0 ;

\ Authenticate and publish exact union counts without allocating the transient
\ discovery plan.  Mount can therefore finish all persistent allocations
\ before beginning its rollback-owned tail.
\ Counts taken in the current map epoch stand: only a write changes the
\ orphan file's blocks or a legacy chain's inodes.
VARIABLE _EXT4-OC-CTX
VARIABLE _EXT4-OC-EPOCH
0 _EXT4-OC-CTX !

: _EXT4-AUTHENTICATE-ORPHAN-COUNTS  ( ctx -- ior )
    0 _EXT4-OC-CTX !
    _EXT4-OP-CTX !
    0 _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.CLEAR-PENDING + !
    _EXT4-OP-CTX @ _EXT4-ENSURE-ORPHAN-AUTH-WORKSPACE
    ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-COUNT-LEGACY-ORPHANS ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-COUNT-ACTIVE-ORPHANS ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT AND 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ _EXT4-UADD?
    DUP IF
        2DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN DROP
    DUP _EXT4-OP-CTX @ _EXT4-C.INODES + @ U> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + !
    _EXT4-OP-CTX @ _EXT4-OC-CTX ! _EXT4-MAP-EPOCH @ _EXT4-OC-EPOCH !
    0 ;

\ Build the exact retained plan from authenticated counts.  Reprepare the
\ modern file because intervening journal validation may replace the shared
\ inode cache.  Counts from an earlier epoch are taken again, and a changed
\ slot count cannot reuse their sizing; counts of the current epoch stand.
: _EXT4-BUILD-AUTHENTICATED-ORPHAN-PLAN  ( ctx -- ior )
    DUP _EXT4-OP-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-OW-COUNT !
    _EXT4-OP-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-OC-CTX @ =
    _EXT4-OC-EPOCH @ _EXT4-MAP-EPOCH @ = AND 0= IF
        _EXT4-OP-CTX @ _EXT4-COUNT-ACTIVE-ORPHANS ?DUP IF EXIT THEN
        _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
        _EXT4-OW-COUNT @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-OP-CTX @
    _EXT4-ENSURE-ORPHAN-PLAN-WORKSPACE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-INDEX-ACTIVE-ORPHANS ?DUP IF EXIT THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-INDEX-LEGACY-ORPHANS ?DUP IF EXIT THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-VALIDATE-INDEXED-ORPHANS ?DUP IF EXIT THEN
    ELSE
        _EXT4-OP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT AND IF
            -1 _EXT4-OP-CTX @ _EXT4-C.O.CLEAR-PENDING + !
        THEN
    THEN
    0 ;

\ Build and authenticate the complete legacy/modern union without deciding
\ whether a caller is allowed to continue past a nonempty recovery plan.
: _EXT4-AUTHENTICATE-ORPHAN-PLAN  ( ctx -- ior )
    DUP _EXT4-AUTHENTICATE-ORPHAN-COUNTS ?DUP IF NIP EXIT THEN
    _EXT4-BUILD-AUTHENTICATED-ORPHAN-PLAN ;

\ =====================================================================
\  Typed, non-emitting orphan-recovery metadata after-images
\ =====================================================================
\
\ These private builders stop at the transaction-staging boundary.  They
\ reauthenticate every plan locator against media, compose same-home edits in
\ writer scratch, and restamp the affected ext4 checksum before replacing the
\ complete retained after-image.  They neither activate nor emit a journal
\ transaction and therefore grant no cleanup or public-write authority by
\ themselves.

VARIABLE _EXT4-JOI-NEW
VARIABLE _EXT4-JOI-RECORD
VARIABLE _EXT4-JOI-WRITER
VARIABLE _EXT4-JOI-CTX
VARIABLE _EXT4-JOI-INO
VARIABLE _EXT4-JOI-KIND
VARIABLE _EXT4-JOI-HOME
VARIABLE _EXT4-JOI-OFF
VARIABLE _EXT4-JOI-IMAGE
VARIABLE _EXT4-JOI-SNAPSHOT

: _EXT4-JTX-STAGE-ORPHAN-INODE
  ( inode-afterimage plan-record transaction -- ior )
    _EXT4-JOI-WRITER ! _EXT4-JOI-RECORD ! _EXT4-JOI-NEW !
    _EXT4-JOI-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOI-NEW @ 0= _EXT4-JOI-RECORD @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOI-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOI-CTX !
    _EXT4-JOI-RECORD @ _EXT4-JOI-CTX @ _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    \ Preserve natural C.INODE, C.BLOCK, and SCRATCH-A caller inputs before
    \ locator reauthentication overwrites those caches.  SCRATCH-B remains
    \ private and unused by non-emitting transaction staging.
    _EXT4-JOI-WRITER @ _EXT4-JWR.SCRATCH-B + @ DUP
    _EXT4-JOI-SNAPSHOT !
    _EXT4-JOI-NEW @ SWAP
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOI-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JOI-INO !
    _EXT4-JOI-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JOI-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOI-RECORD @ _EXT4-JOI-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOI-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-JOI-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-JOI-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOI-CTX @ _EXT4-C.BLOCK +
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-JOI-INO @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOI-INO @ _EXT4-JOI-CTX @ _EXT4-LOAD-ORPHAN-INODE
    ?DUP IF EXIT THEN
    _EXT4-JOI-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-JOI-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-A + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOI-SNAPSHOT @ _EXT4-I.GENERATION + L@
    _EXT4-JOI-CTX @ _EXT4-C.INODE + _EXT4-I.GENERATION + L@ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-IR-BLOCK @ _EXT4-JOI-HOME !
    _EXT4-IR-OFF @ _EXT4-JOI-OFF !
    _EXT4-JOI-CTX @ _EXT4-C.BLOCK + _EXT4-JOI-HOME @
    _EXT4-JOI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JOI-IMAGE !
    \ Different records in one table block compose, but a second full-record
    \ replacement of this same inode must not silently discard its predecessor.
    _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ +
    _EXT4-JOI-CTX @ _EXT4-C.INODE +
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JOI-SNAPSHOT @ _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ +
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ + _EXT4-JOI-INO @
    _EXT4-JOI-CTX @ _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _EXT4-JOI-IMAGE @ _EXT4-JOI-HOME @ _EXT4-JOI-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JOS-RECORD
VARIABLE _EXT4-JOS-WRITER
VARIABLE _EXT4-JOS-CTX
VARIABLE _EXT4-JOS-INO
VARIABLE _EXT4-JOS-HOME
VARIABLE _EXT4-JOS-GEN
VARIABLE _EXT4-JOS-ORPHAN-INO
VARIABLE _EXT4-JOS-SLOT
VARIABLE _EXT4-JOS-IMAGE
VARIABLE _EXT4-JOS-EA

\ =====================================================================
\  Typed, non-emitting block-free accounting after-images
\ =====================================================================

VARIABLE _EXT4-MWH-CTX
VARIABLE _EXT4-MWH-FIRST
VARIABLE _EXT4-MWH-COUNT

\ Prove that the primary super/GDT homes this operation will replace are not
\ also named as allocation metadata by any authenticated descriptor.  Read
\ admission alone permits flex_bg placement, so writable admission must make
\ this anti-alias invariant explicit before publishing an after-image.  The
\ proof reads only descriptors, so one that passed in the current map epoch
\ stands.
VARIABLE _EXT4-MWH-PASSED-CTX
VARIABLE _EXT4-MWH-PASSED-EPOCH
0 _EXT4-MWH-PASSED-CTX !

: _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES  ( ctx -- ior )
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-MWH-PASSED-CTX @ =
    _EXT4-MWH-PASSED-EPOCH @ _EXT4-MAP-EPOCH @ = AND IF DROP 0 EXIT THEN
    _EXT4-MWH-CTX !
    _EXT4-MWH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _EXT4-MWH-FIRST !
    _EXT4-MWH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ 1+
    _EXT4-MWH-COUNT !
    _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @ _EXT4-MWH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-MWH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MWH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    _EXT4-MWH-CTX @ _EXT4-MWH-PASSED-CTX !
    _EXT4-MAP-EPOCH @ _EXT4-MWH-PASSED-EPOCH !
    0 ;

VARIABLE _EXT4-MBH-HOME
VARIABLE _EXT4-MBH-OWNER
VARIABLE _EXT4-MBH-CTX
VARIABLE _EXT4-MBH-FOUND
VARIABLE _EXT4-MBH-BASE
VARIABLE _EXT4-MBH-COUNT

\ A block bitmap that will be replaced must have exactly one descriptor
\ owner and must be disjoint from every inode bitmap/table, sparse-super
\ interval, and journal extent.  Otherwise one valid-looking free operation
\ could silently mutate unrelated metadata through a checksum-valid alias.
: _EXT4-VALIDATE-BLOCK-BITMAP-HOME  ( home owner-group ctx -- ior )
    _EXT4-MBH-CTX ! _EXT4-MBH-OWNER ! _EXT4-MBH-HOME !
    _EXT4-MBH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MBH-OWNER @
    _EXT4-MBH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MBH-HOME @ 1 _EXT4-MBH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MBH-HOME @ 1 _EXT4-MBH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MBH-FOUND !
    _EXT4-MBH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MBH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-MBH-HOME @ = IF
            I _EXT4-MBH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MBH-FOUND +!
        THEN
        _EXT4-MBH-HOME @ 1
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MBH-HOME @ 1
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MBH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MBH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MBH-BASE !
            1 _EXT4-MBH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MBH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MBH-COUNT !
            _EXT4-MBH-HOME @ 1
            _EXT4-MBH-BASE @ _EXT4-MBH-COUNT @
            _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MBH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-MIH-HOME
VARIABLE _EXT4-MIH-OWNER
VARIABLE _EXT4-MIH-CTX
VARIABLE _EXT4-MIH-FOUND
VARIABLE _EXT4-MIH-BASE
VARIABLE _EXT4-MIH-COUNT

\ An inode bitmap that will be replaced has one exact descriptor owner.  It
\ may share neither another allocation role nor an inode-table or sparse-copy
\ interval, and it may not overlap the journal.  These mutation-side proofs
\ are deliberately stronger than checksum-valid read admission.
: _EXT4-VALIDATE-INODE-BITMAP-HOME  ( home owner-group ctx -- ior )
    _EXT4-MIH-CTX ! _EXT4-MIH-OWNER ! _EXT4-MIH-HOME !
    _EXT4-MIH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MIH-OWNER @
    _EXT4-MIH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MIH-HOME @ 1 _EXT4-MIH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MIH-HOME @ 1 _EXT4-MIH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MIH-FOUND !
    _EXT4-MIH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MIH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ _EXT4-MIH-HOME @ = IF
            I _EXT4-MIH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MIH-FOUND +!
        THEN
        _EXT4-MIH-HOME @ 1
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MIH-HOME @ 1
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MIH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MIH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MIH-BASE !
            1 _EXT4-MIH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MIH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MIH-COUNT !
            _EXT4-MIH-HOME @ 1
            _EXT4-MIH-BASE @ _EXT4-MIH-COUNT @
            _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MIH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-MTH-HOME
VARIABLE _EXT4-MTH-OWNER
VARIABLE _EXT4-MTH-CTX
VARIABLE _EXT4-MTH-FOUND
VARIABLE _EXT4-MTH-BASE
VARIABLE _EXT4-MTH-COUNT

\ An inode-table page that will be replaced must belong to exactly one
\ authenticated group table.  It may not also name an allocation bitmap,
\ another group's table, sparse-super/GDT storage, or a journal extent.
: _EXT4-VALIDATE-INODE-TABLE-HOME  ( home owner-group ctx -- ior )
    _EXT4-MTH-CTX ! _EXT4-MTH-OWNER ! _EXT4-MTH-HOME !
    _EXT4-MTH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MTH-OWNER @
    _EXT4-MTH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MTH-HOME @ 1 _EXT4-MTH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MTH-HOME @ 1 _EXT4-MTH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MTH-FOUND !
    _EXT4-MTH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MTH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        URANGE-OVERLAP? 0= IF
            DROP EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        IF
            I _EXT4-MTH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MTH-FOUND +!
        THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MTH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MTH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MTH-BASE !
            1 _EXT4-MTH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MTH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MTH-COUNT !
            _EXT4-MTH-HOME @ 1
            _EXT4-MTH-BASE @ _EXT4-MTH-COUNT @
            _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MTH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-FRS-FIRST
VARIABLE _EXT4-FRS-COUNT
VARIABLE _EXT4-FRS-CTX

\ Reject every journal or descriptor/geometry-authenticated static metadata
\ overlap before a mutation changes any transaction-owned after-image.
\ flex_bg means a group's bitmap/table may reside outside that group's nominal
\ interval, so the complete descriptor set is authoritative here; the
\ static-role table carries it.
: _EXT4-VALIDATE-MUTATION-RANGE-TARGETS  ( first count ctx -- ior )
    _EXT4-FRS-CTX ! _EXT4-FRS-COUNT ! _EXT4-FRS-FIRST !
    _EXT4-FRS-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-FRS-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-CTX @ _EXT4-C.FIRST + @ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
    _EXT4-FRS-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FRS-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @ _EXT4-FRS-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-FRS-CTX @ _EXT4-SR-CURRENT ?DUP IF EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @ _EXT4-SR-ALIAS? IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-FRV-RANGES
VARIABLE _EXT4-FRV-RANGE-COUNT
VARIABLE _EXT4-FRV-RANGE-CAP
VARIABLE _EXT4-FRV-RANGE-INDEX
VARIABLE _EXT4-FRV-CTX
VARIABLE _EXT4-FRV-QUERY-FIRST
VARIABLE _EXT4-FRV-QUERY-COUNT

: _EXT4-FRV-RANGE  ( index -- pair-address )
    2* CELLS _EXT4-FRV-RANGES @ + ;

: _EXT4-FRV-RANGES-ALIAS?  ( first count -- flag )
    _EXT4-FRV-QUERY-COUNT ! _EXT4-FRV-QUERY-FIRST !
    _EXT4-FRV-QUERY-COUNT @ 0= IF TRUE EXIT THEN
    _EXT4-FRV-RANGE-COUNT @ DUP 0=
    SWAP 0< OR _EXT4-FRV-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-FRV-RANGE-COUNT @ _EXT4-FRV-RANGE-CAP @ U> OR IF
        TRUE EXIT
    THEN
    _EXT4-FRV-RANGE-COUNT @ 0 ?DO
        I _EXT4-FRV-RANGE DUP @ SWAP CELL+ @
        DUP 0= IF 2DROP TRUE UNLOOP EXIT THEN
        _EXT4-FRV-QUERY-FIRST @ _EXT4-FRV-QUERY-COUNT @
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF TRUE UNLOOP EXIT THEN
    LOOP
    FALSE ;

\ Validate a complete inline extent vector without repeating geometry work
\ for each member.  Bounds and journal separation remain exact per range;
\ primary mutation homes and the flex_bg descriptor set are authenticated
\ once, then every pair is compared with the static-role table.
: _EXT4-VALIDATE-MUTATION-RANGES-TARGETS
  ( ranges range-count capacity ctx -- ior )
    _EXT4-FRV-CTX ! _EXT4-FRV-RANGE-CAP !
    _EXT4-FRV-RANGE-COUNT ! _EXT4-FRV-RANGES !
    _EXT4-FRV-CTX @ 0= _EXT4-FRV-RANGES @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-FRV-RANGE-COUNT @ DUP 0= SWAP 0< OR
    _EXT4-FRV-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-FRV-RANGE-COUNT @ _EXT4-FRV-RANGE-CAP @ U> OR IF
        VFS-E-INVALID EXIT
    THEN
    0 _EXT4-FRV-RANGE-INDEX !
    BEGIN
        _EXT4-FRV-RANGE-INDEX @ _EXT4-FRV-RANGE-COUNT @ U<
    WHILE
        _EXT4-FRV-RANGE-INDEX @ _EXT4-FRV-RANGE DUP @
        _EXT4-FRS-FIRST ! CELL+ @ _EXT4-FRS-COUNT !
        _EXT4-FRS-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
        _EXT4-FRS-FIRST @ _EXT4-FRV-CTX @ _EXT4-C.FIRST + @ U< IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRV-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @ _EXT4-FRV-CTX @
        _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
        1 _EXT4-FRV-RANGE-INDEX +!
    REPEAT
    _EXT4-FRV-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-FRV-CTX @ _EXT4-SR-CURRENT ?DUP IF EXIT THEN
    _EXT4-FRV-RANGE-COUNT @ 0 ?DO
        I _EXT4-FRV-RANGE DUP @ SWAP CELL+ @ _EXT4-SR-ALIAS? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    0 ;

' _EXT4-VALIDATE-MUTATION-RANGE-TARGETS
_EXT4-MUTATION-ROLE-XT !

\ Authenticate the complete raw modern-slot mutation target without acquiring
\ a transaction image.  The descriptor-wide mutation scan clobbers C.BLOCK,
\ so restore the orphan-file mapping and slot after that scan.  On success the
\ exact physical home, generation, owner, slot, and raw block remain current.
: _EXT4-JOS-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JOS-INO !
    _EXT4-JOS-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOS-EA !
    _EXT4-JOS-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-B + @ _EXT4-JOS-SLOT !
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JOS-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-PHYS @ DUP _EXT4-JOS-HOME !
    _EXT4-JOS-EA @ = _EXT4-JOS-EA @ 0<> AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-GEN @ _EXT4-JOS-GEN !
    _EXT4-OV-INO @ _EXT4-JOS-ORPHAN-INO !
    _EXT4-JOS-HOME @ 1 _EXT4-JOS-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JOS-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JOS-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JOS-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JOS-ORPHAN-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Clearing a modern orphan slot mutates an ordinary mapped file block, so its
\ read-side checksum is necessary but not sufficient authority.  Prove the
\ exact physical home is writable non-static storage and disjoint from the
\ target's retained external xattr before publishing its after-image.
: _EXT4-JTX-CLEAR-MODERN-ORPHAN-SLOT
  ( plan-record transaction -- ior )
    _EXT4-JOS-WRITER ! _EXT4-JOS-RECORD !
    _EXT4-JOS-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JOS-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOS-CTX !
    _EXT4-JOS-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-HOME @
    _EXT4-JOS-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JOS-IMAGE !
    _EXT4-JOS-IMAGE @ _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 _EXT4-JOS-IMAGE @ _EXT4-JOS-SLOT @ 4 * + L!
    _EXT4-JOS-IMAGE @ _EXT4-JOS-HOME @ _EXT4-JOS-ORPHAN-INO @
    _EXT4-JOS-GEN @ _EXT4-JOS-CTX @ _EXT4-RESTAMP-ORPHAN-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JOS-IMAGE @ _EXT4-JOS-HOME @ _EXT4-JOS-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JPS-WRITER
VARIABLE _EXT4-JPS-CTX
VARIABLE _EXT4-JPS-HOME
VARIABLE _EXT4-JPS-OFF
VARIABLE _EXT4-JPS-RAW
VARIABLE _EXT4-JPS-RAW-CRC
VARIABLE _EXT4-JPS-IMAGE
VARIABLE _EXT4-JPS-SUPER

\ Return a private editing copy of the primary-super block, composing with an
\ earlier transaction after-image when one exists.  Both the raw source and
\ the effective image are authenticated before the caller may edit mutable
\ fields; this is the common authority used by allocation accounting and by
\ the legacy-orphan head transition.
: _EXT4-JTX-ACQUIRE-PRIMARY-SUPER
  ( transaction -- ior )
    0 _EXT4-JPS-HOME ! 0 _EXT4-JPS-OFF ! 0 _EXT4-JPS-RAW !
    0 _EXT4-JPS-RAW-CRC ! 0 _EXT4-JPS-IMAGE ! 0 _EXT4-JPS-SUPER !
    DUP _EXT4-JPS-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JPS-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JPS-CTX !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP _EXT4-JPS-HOME !
    _EXT4-JPS-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-PRIMARY-SUPER-OFF DUP _EXT4-JPS-OFF !
    _EXT4-JPS-CTX @ _EXT4-C.BLOCK + + _EXT4-JPS-RAW !
    _EXT4-JPS-RAW @ _EXT4-JPS-CTX @ _EXT4-C.SB + 1024
    _EXT4-BYTES=? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SB.CHECKSUM + L@ _EXT4-JPS-RAW-CRC !
    _EXT4-JPS-RAW @ 0 _EXT4-JPS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-JPS-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-C.BLOCK + _EXT4-JPS-HOME @
    _EXT4-JPS-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JPS-IMAGE !
    _EXT4-JPS-IMAGE @ _EXT4-JPS-OFF @ + _EXT4-JPS-SUPER !
    _EXT4-JPS-SUPER @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ 0 _EXT4-JPS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-JPS-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JPS-RAW @ _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JPS-RAW @ _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JFB-FIRST
VARIABLE _EXT4-JFB-COUNT
VARIABLE _EXT4-JFB-WRITER
VARIABLE _EXT4-JFB-CTX
VARIABLE _EXT4-JFB-CURRENT
VARIABLE _EXT4-JFB-REMAIN
VARIABLE _EXT4-JFB-GROUP
VARIABLE _EXT4-JFB-INDEX
VARIABLE _EXT4-JFB-CHUNK
VARIABLE _EXT4-JFB-GROUP-BLOCKS
VARIABLE _EXT4-JFB-BITMAP-HOME
VARIABLE _EXT4-JFB-GDT-HOME
VARIABLE _EXT4-JFB-GDT-OFF
VARIABLE _EXT4-JFB-IMAGE
VARIABLE _EXT4-JFB-DESC
VARIABLE _EXT4-JFB-BITMAP-CRC
VARIABLE _EXT4-JFB-NEW-BITMAP-CRC
VARIABLE _EXT4-JFB-FREE
VARIABLE _EXT4-JFB-NEW-FREE
VARIABLE _EXT4-JFB-SUPER-HOME
VARIABLE _EXT4-JFB-SUPER
VARIABLE _EXT4-JFB-IOR
VARIABLE _EXT4-JFB-PUBLISHED
VARIABLE _EXT4-JFB-ABORT-IOR

\ Once this operation publishes its first complete metadata image, any later
\ failure is transaction-fatal.  Abort immediately so a caller cannot emit a
\ descriptor/bitmap prefix without the matching aggregate superblock update.
\ If local abort invariants themselves fail, latch an explicit faulted state.
: _EXT4-JFB-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JFB-IOR !
    _EXT4-JFB-PUBLISHED @ IF
        _EXT4-JFB-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JFB-ABORT-IOR ! IF
            _EXT4-JFB-ABORT-IOR @
            _EXT4-JFB-WRITER @ _EXT4-JWR.FAULT + !
            _EXT4-JWR-FAULTED
            _EXT4-JFB-WRITER @ _EXT4-JWR.STATE + !
        THEN
    THEN
    _EXT4-JFB-IOR @ ;

: _EXT4-JFB-RESET-WALK  ( -- )
    _EXT4-JFB-FIRST @ _EXT4-JFB-CURRENT !
    _EXT4-JFB-COUNT @ _EXT4-JFB-REMAIN ! ;

: _EXT4-JFB-NEXT-CHUNK  ( -- ior )
    _EXT4-JFB-CURRENT @ _EXT4-JFB-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JFB-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JFB-GROUP ! _EXT4-JFB-INDEX !
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFB-GROUP-BLOCKS !
    _EXT4-JFB-INDEX @ _EXT4-JFB-GROUP-BLOCKS @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-GROUP-BLOCKS @ _EXT4-JFB-INDEX @ -
    _EXT4-JFB-REMAIN @ MIN DUP 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFB-CHUNK !
    0 ;

: _EXT4-JFB-ADVANCE  ( -- )
    _EXT4-JFB-CHUNK @ DUP _EXT4-JFB-CURRENT +!
    NEGATE _EXT4-JFB-REMAIN +! ;

: _EXT4-JFB-DESC-BITMAP-CRC@  ( descriptor -- crc )
    DUP _EXT4-GD.BLOCK-CSUM-LO + W@
    SWAP _EXT4-GD.BLOCK-CSUM-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFB-DESC-FREE@  ( descriptor -- blocks )
    DUP _EXT4-GD.FREE-BLOCKS-LO + W@
    SWAP _EXT4-GD.FREE-BLOCKS-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFB-DESC-FREE!  ( blocks descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.FREE-BLOCKS-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.FREE-BLOCKS-HI + W! ;

: _EXT4-JFB-DESC-BITMAP-CRC!  ( crc descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.BLOCK-CSUM-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.BLOCK-CSUM-HI + W! ;

: _EXT4-JFB-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JFB-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-BLOCK-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JFB-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-JFB-DESC-BITMAP-CRC@
    _EXT4-JFB-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-JFB-DESC-FREE@ DUP _EXT4-JFB-FREE !
    _EXT4-JFB-CHUNK @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-NEW-FREE !
    _EXT4-JFB-GROUP-BLOCKS @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFB-ACQUIRE-DESC  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ DUP _EXT4-JFB-GDT-HOME !
    _EXT4-JFB-BITMAP-HOME @ = IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-OFF @ _EXT4-JFB-GDT-OFF !
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-GDT-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-GDT-OFF @ + _EXT4-JFB-DESC !
    _EXT4-JFB-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JFB-PREFLIGHT-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-BITMAP-HOME @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    \ The anti-alias scan leaves the descriptor table in C.BLOCK; restore and
    \ reauthenticate the actual bitmap before consulting any allocation bit.
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR !
    _EXT4-JFB-IOR @ IF DROP _EXT4-JFB-IOR @ EXIT THEN
    _EXT4-JFB-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFB-GROUP-BLOCKS @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-ALL-SET? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-GROUP-BLOCKS @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-ALL-SET? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ;

\ A vector caller has already proved this touched group's raw bitmap home
\ unique and disjoint from every static role.  Reload that raw home, then keep
\ the scalar allocation, retained-image, effective-descriptor, and checksum
\ checks intact for the exact member being staged.
: _EXT4-JFB-PREFLIGHT-GROUP-AFTER-HOME  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFB-GROUP-BLOCKS @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-ALL-SET? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-GROUP-BLOCKS @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-ALL-SET? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ;

: _EXT4-JFB-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JFB-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFB-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JFB-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JFB-IMAGE !
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFB-COUNT @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-NEW-FREE !
    DUP 0xFFFFFFFF U>
    SWAP _EXT4-JFB-CTX @ _EXT4-C.BLOCKS + @ U> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFB-PREFLIGHT-AFTER-TARGETS  ( -- ior )
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-PREFLIGHT-GROUP ?DUP IF EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-ACQUIRE-SUPER ;

: _EXT4-JFB-PREFLIGHT-AFTER-VECTOR-TARGETS  ( -- ior )
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-PREFLIGHT-GROUP-AFTER-HOME ?DUP IF EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-ACQUIRE-SUPER ;

: _EXT4-JFB-PREFLIGHT  ( -- ior )
    _EXT4-JFB-FIRST @ _EXT4-JFB-COUNT @ _EXT4-JFB-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JFB-PREFLIGHT-AFTER-TARGETS ;

: _EXT4-JFB-STAGE-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    DUP _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP NIP EXIT THEN
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-GROUP-BLOCKS @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-RANGE-CLEAR? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFB-NEW-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFB-NEW-FREE @ _EXT4-JFB-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JFB-NEW-BITMAP-CRC @ _EXT4-JFB-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JFB-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-GDT-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-BITMAP-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    0 ;

: _EXT4-JFB-STAGE-SUPER  ( -- ior )
    _EXT4-JFB-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFB-NEW-FREE @
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JFB-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-SUPER-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    0 ;

: _EXT4-JFB-STAGE-PREFLIGHTED  ( -- ior )
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF
            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
        THEN
        _EXT4-JFB-STAGE-GROUP ?DUP IF
            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
        THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-STAGE-SUPER ?DUP IF
        _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ Stage only allocation accounting for a nonempty physical block range.  The
\ caller still owns map removal, i_blocks changes, and any metadata revoke.
\ All semantic checks finish before the first table replacement.  A later
\ internal credit/conflict failure automatically aborts the whole transaction
\ so no partial accounting prefix remains eligible for emission.
: _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
  ( first-block count transaction -- ior )
    _EXT4-JFB-WRITER ! _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    0 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFB-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFB-CTX !
    _EXT4-JFB-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFB-STAGE-PREFLIGHTED ;

: _EXT4-JTX-STAGE-FREE-BLOCK-RANGE-AFTER-VECTOR-TARGETS
  ( first-block count transaction -- ior )
    _EXT4-JFB-WRITER ! _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    0 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFB-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFB-CTX !
    _EXT4-JFB-PREFLIGHT-AFTER-VECTOR-TARGETS ?DUP IF EXIT THEN
    _EXT4-JFB-STAGE-PREFLIGHTED ;

VARIABLE _EXT4-JBV-RANGES
VARIABLE _EXT4-JBV-RANGE-COUNT
VARIABLE _EXT4-JBV-RANGE-CAP
VARIABLE _EXT4-JBV-RANGE-INDEX
VARIABLE _EXT4-JBV-WRITER
VARIABLE _EXT4-JBV-CTX
VARIABLE _EXT4-JBV-GROUP
VARIABLE _EXT4-JBV-GROUP-FIRST
VARIABLE _EXT4-JBV-GROUP-COUNT
VARIABLE _EXT4-JBV-BITMAP-HOME
VARIABLE _EXT4-JBV-IOR
VARIABLE _EXT4-JBV-RUN-FIRST
VARIABLE _EXT4-JBV-RUN-COUNT
VARIABLE _EXT4-JBV-NEXT-FIRST
VARIABLE _EXT4-JBV-NEXT-COUNT

: _EXT4-JBV-VALIDATE-BITMAP-HOMES  ( -- ior )
    _EXT4-JBV-RANGES @ _EXT4-FRV-RANGES !
    _EXT4-JBV-RANGE-COUNT @ _EXT4-FRV-RANGE-COUNT !
    _EXT4-JBV-RANGE-CAP @ _EXT4-FRV-RANGE-CAP !
    0 _EXT4-JBV-GROUP !
    BEGIN
        _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @ _EXT4-GROUP-BLOCK-RANGE
        _EXT4-JBV-IOR ! _EXT4-JBV-GROUP-COUNT !
        _EXT4-JBV-GROUP-FIRST !
        _EXT4-JBV-IOR @ ?DUP IF EXIT THEN
        _EXT4-JBV-GROUP-FIRST @ _EXT4-JBV-GROUP-COUNT @
        _EXT4-FRV-RANGES-ALIAS? IF
            _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @
            _EXT4-LOAD-BLOCK-BITMAP
            _EXT4-JBV-IOR ! _EXT4-JBV-BITMAP-HOME !
            _EXT4-JBV-IOR @ ?DUP IF EXIT THEN
            _EXT4-JBV-BITMAP-HOME @ _EXT4-JBV-GROUP @ _EXT4-JBV-CTX @
            _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
        THEN
        1 _EXT4-JBV-GROUP +!
    REPEAT
    0 ;

\ Private exact-vector entry point for plan-bound cleanup.  The complete
\ caller-supplied vector remains the authority proved above and retained in
\ the orphan certificate/checkpoint plan.  Adjacent physical members may use
\ one allocation-accounting run: clearing the same set of bits and applying
\ their summed counters does not weaken or rewrite that exact authority, and
\ avoids repeatedly checksumming the same bitmap, descriptor, and superblock.
: _EXT4-JTX-STAGE-FREE-BLOCK-RANGES
  ( ranges range-count capacity transaction -- ior )
    _EXT4-JBV-WRITER ! _EXT4-JBV-RANGE-CAP !
    _EXT4-JBV-RANGE-COUNT ! _EXT4-JBV-RANGES !
    _EXT4-JBV-RANGES @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JBV-RANGE-COUNT @ DUP 0= SWAP 0< OR
    _EXT4-JBV-RANGE-CAP @ DUP 0= SWAP 0< OR OR
    _EXT4-JBV-RANGE-COUNT @ _EXT4-JBV-RANGE-CAP @ U> OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JBV-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JBV-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JBV-CTX ! DROP
    _EXT4-JBV-RANGES @ _EXT4-JBV-RANGE-COUNT @
    _EXT4-JBV-RANGE-CAP @ _EXT4-JBV-CTX @
    _EXT4-VALIDATE-MUTATION-RANGES-TARGETS ?DUP IF EXIT THEN
    _EXT4-JBV-VALIDATE-BITMAP-HOMES ?DUP IF EXIT THEN
    _EXT4-JBV-RANGES @ DUP @ _EXT4-JBV-RUN-FIRST !
    CELL+ @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    _EXT4-JBV-RUN-COUNT !
    1 _EXT4-JBV-RANGE-INDEX !
    BEGIN
        _EXT4-JBV-RANGE-INDEX @ _EXT4-JBV-RANGE-COUNT @ U<
    WHILE
        _EXT4-JBV-RANGE-INDEX @ 2* CELLS _EXT4-JBV-RANGES @ +
        DUP @ _EXT4-JBV-NEXT-FIRST !
        CELL+ @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
        _EXT4-JBV-NEXT-COUNT !
        _EXT4-JBV-RUN-FIRST @ _EXT4-JBV-RUN-COUNT @ _EXT4-UADD?
        DUP IF NIP EXIT THEN DROP
        _EXT4-JBV-NEXT-FIRST @ = IF
            _EXT4-JBV-RUN-COUNT @ _EXT4-JBV-NEXT-COUNT @ _EXT4-UADD?
            DUP IF NIP EXIT THEN DROP _EXT4-JBV-RUN-COUNT !
        ELSE
            _EXT4-JBV-RUN-FIRST @ _EXT4-JBV-RUN-COUNT @
            _EXT4-JBV-WRITER @
            _EXT4-JTX-STAGE-FREE-BLOCK-RANGE-AFTER-VECTOR-TARGETS
            ?DUP IF EXIT THEN
            _EXT4-JBV-NEXT-FIRST @ _EXT4-JBV-RUN-FIRST !
            _EXT4-JBV-NEXT-COUNT @ _EXT4-JBV-RUN-COUNT !
        THEN
        1 _EXT4-JBV-RANGE-INDEX +!
    REPEAT
    _EXT4-JBV-RUN-FIRST @ _EXT4-JBV-RUN-COUNT @ _EXT4-JBV-WRITER @
    _EXT4-JTX-STAGE-FREE-BLOCK-RANGE-AFTER-VECTOR-TARGETS ;

\ =====================================================================
\  Run allocation accounting
\ =====================================================================

VARIABLE _EXT4-JAB-BLOCK
VARIABLE _EXT4-JAB-COUNT
VARIABLE _EXT4-JAB-WRITER
VARIABLE _EXT4-JAB-CTX
VARIABLE _EXT4-JAB-GROUP
VARIABLE _EXT4-JAB-INDEX
VARIABLE _EXT4-JAB-GROUP-BLOCKS
VARIABLE _EXT4-JAB-BITMAP-HOME
VARIABLE _EXT4-JAB-GDT-HOME
VARIABLE _EXT4-JAB-GDT-OFF
VARIABLE _EXT4-JAB-IMAGE
VARIABLE _EXT4-JAB-DESC
VARIABLE _EXT4-JAB-UNINIT
VARIABLE _EXT4-JAB-STILL-UNINIT
VARIABLE _EXT4-JAB-BITMAP-CRC
VARIABLE _EXT4-JAB-NEW-BITMAP-CRC
VARIABLE _EXT4-JAB-GROUP-FREE
VARIABLE _EXT4-JAB-NEW-GROUP-FREE
VARIABLE _EXT4-JAB-SUPER-HOME
VARIABLE _EXT4-JAB-SUPER
VARIABLE _EXT4-JAB-NEW-SUPER-FREE
VARIABLE _EXT4-JAB-IOR
VARIABLE _EXT4-JAB-PUBLISHED
VARIABLE _EXT4-JAB-ABORT-IOR

\ Allocation accounting is an all-or-abort typed edit.  Once its first
\ complete after-image is retained, no caller may emit a bitmap/GDT/super
\ prefix after a later local failure.
: _EXT4-JAB-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JAB-IOR !
    _EXT4-JAB-PUBLISHED @ IF
        _EXT4-JAB-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JAB-ABORT-IOR ! IF
            _EXT4-JAB-ABORT-IOR @
            _EXT4-JAB-WRITER @ _EXT4-JWR.FAULT + !
            _EXT4-JWR-FAULTED
            _EXT4-JAB-WRITER @ _EXT4-JWR.STATE + !
        THEN
    THEN
    _EXT4-JAB-IOR @ ;

\ A run is accounted inside one block group.
: _EXT4-JAB-LOCATE  ( -- ior )
    _EXT4-JAB-BLOCK @ _EXT4-JAB-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JAB-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JAB-GROUP ! _EXT4-JAB-INDEX !
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JAB-GROUP-BLOCKS !
    _EXT4-JAB-INDEX @ _EXT4-JAB-COUNT @ +
    _EXT4-JAB-GROUP-BLOCKS @ U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ The effective descriptor keeps BLOCK_UNINIT only until this transaction's
\ first allocation in the group initializes its bitmap, so the flag needs a
\ raw BLOCK_UNINIT group with no bitmap image staged.  An initialized
\ descriptor must authenticate the effective bitmap.
: _EXT4-JAB-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JAB-DESC @ _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-GD.FLAGS + W@ _EXT4-BG-BLOCK-UNINIT AND 0<>
    DUP _EXT4-JAB-STILL-UNINIT ! IF
        _EXT4-JAB-UNINIT @ 0= IF
            EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JAB-BITMAP-HOME @ _EXT4-JAB-WRITER @ _EXT4-JTX-META-IMAGE
        ?DUP IF NIP EXIT THEN IF
            EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JAB-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JAB-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-STILL-UNINIT @ 0= IF
        _EXT4-JAB-DESC @ _EXT4-JFB-DESC-BITMAP-CRC@
        _EXT4-JAB-BITMAP-CRC @ <> IF
            EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JAB-DESC @ _EXT4-JFB-DESC-FREE@
    DUP _EXT4-JAB-GROUP-FREE !
    DUP _EXT4-JAB-COUNT @ U< IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JAB-GROUP-BLOCKS @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-COUNT @ - _EXT4-JAB-NEW-GROUP-FREE !
    0 ;

: _EXT4-JAB-ACQUIRE-DESC  ( -- ior )
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ DUP _EXT4-JAB-GDT-HOME !
    _EXT4-JAB-BITMAP-HOME @ = IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-OFF @ _EXT4-JAB-GDT-OFF !
    _EXT4-JAB-CTX @ _EXT4-C.BLOCK + _EXT4-JAB-GDT-HOME @
    _EXT4-JAB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JAB-IMAGE !
    _EXT4-JAB-GDT-OFF @ + _EXT4-JAB-DESC !
    _EXT4-JAB-VALIDATE-EFFECTIVE-DESC ;

\ The raw bitmap is the authenticated block, or for a BLOCK_UNINIT group the
\ bitmap the group stands for, built in writer scratch.  The run must be
\ clear in it and in the transaction's retained image.
: _EXT4-JAB-ACQUIRE-BITMAP  ( -- ior )
    _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND 0<> _EXT4-JAB-UNINIT !
    _EXT4-JAB-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JAB-BITMAP-HOME !
    _EXT4-JAB-BITMAP-HOME @ _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @
    _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    \ The descriptor-wide home proof reused C.BLOCK.  Rebuild or reload the
    \ exact raw bitmap before checking the run.
    _EXT4-JAB-UNINIT @ IF
        _EXT4-JAB-GROUP @ _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
        _EXT4-JAB-CTX @ _EXT4-BUILD-UNINIT-BLOCK-BITMAP ?DUP IF EXIT THEN
        _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    ELSE
        _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        ?DUP IF NIP EXIT THEN
        _EXT4-JAB-BITMAP-HOME @ <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JAB-CTX @ _EXT4-C.BLOCK +
    THEN
    DUP _EXT4-JAB-GROUP-BLOCKS @ _EXT4-JAB-INDEX @ _EXT4-JAB-COUNT @
    BITSET-ALL-CLEAR? 0= IF
        2DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    _EXT4-JAB-BITMAP-HOME @ _EXT4-JAB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JAB-IMAGE !
    _EXT4-JAB-GROUP-BLOCKS @ _EXT4-JAB-INDEX @ _EXT4-JAB-COUNT @
    BITSET-ALL-CLEAR? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JAB-IMAGE @ _EXT4-JAB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JAB-BITMAP-CRC !
    0 ;

: _EXT4-JAB-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JAB-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JAB-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JAB-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JAB-IMAGE !
    _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    DUP _EXT4-JAB-COUNT @ U< IF DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JAB-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-COUNT @ - _EXT4-JAB-NEW-SUPER-FREE !
    0 ;

: _EXT4-JAB-PREFLIGHT  ( -- ior )
    _EXT4-JAB-LOCATE ?DUP IF EXIT THEN
    _EXT4-JAB-BLOCK @ _EXT4-JAB-COUNT @ _EXT4-JAB-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JAB-ACQUIRE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JAB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JAB-ACQUIRE-SUPER ;

: _EXT4-JAB-STAGE-GROUP  ( -- ior )
    _EXT4-JAB-ACQUIRE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JAB-IMAGE @
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-GROUP-BLOCKS @ _EXT4-JAB-INDEX @ _EXT4-JAB-COUNT @
    BITSET-RANGE-SET? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JAB-NEW-BITMAP-CRC !
    _EXT4-JAB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JAB-NEW-GROUP-FREE @
    _EXT4-JAB-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JAB-NEW-BITMAP-CRC @ _EXT4-JAB-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JAB-DESC @ _EXT4-GD.FLAGS + DUP W@
    _EXT4-BG-BLOCK-UNINIT INVERT AND SWAP W!
    _EXT4-JAB-DESC @ _EXT4-JAB-GROUP @ _EXT4-JAB-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    \ Retain homes in bitmap/GDT order.  This order is not a crash-safety
    \ dependency, but gives checkpoint qualification a deterministic role
    \ sequence for the new allocation topology.
    _EXT4-JAB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JAB-BITMAP-HOME @ _EXT4-JAB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JAB-PUBLISHED !
    _EXT4-JAB-IMAGE @ _EXT4-JAB-GDT-HOME @ _EXT4-JAB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JAB-PUBLISHED !
    0 ;

: _EXT4-JAB-STAGE-SUPER  ( -- ior )
    _EXT4-JAB-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JAB-NEW-SUPER-FREE @
    _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JAB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JAB-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JAB-IMAGE @ _EXT4-JAB-SUPER-HOME @ _EXT4-JAB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JAB-PUBLISHED !
    0 ;

\ Stage allocation accounting for one run of free blocks inside a single
\ group: the run's bits in the block bitmap, the group's free count, bitmap
\ checksum and BLOCK_UNINIT flag in its primary descriptor, and the primary
\ superblock's free count.  The first allocation in a BLOCK_UNINIT group
\ stages the bitmap that group stands for, with the run set.  The caller
\ still owns choosing the run, proving its homes, its data and map, and
\ i_blocks; this word neither emits nor checkpoints the transaction.
: _EXT4-JTX-STAGE-ALLOCATE-RANGE  ( first count transaction -- ior )
    _EXT4-JAB-WRITER ! _EXT4-JAB-COUNT ! _EXT4-JAB-BLOCK !
    0 _EXT4-JAB-PUBLISHED !
    _EXT4-JAB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JAB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JAB-CTX !
    _EXT4-JAB-COUNT @ 0> 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JAB-BLOCK @ _EXT4-JAB-CTX @ _EXT4-C.FIRST + @ U<
    _EXT4-JAB-BLOCK @ _EXT4-JAB-COUNT @
    _EXT4-JAB-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JAB-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JAB-STAGE-GROUP ?DUP IF
        _EXT4-JAB-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JAB-STAGE-SUPER ?DUP IF
        _EXT4-JAB-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ =====================================================================
\  Transaction-aware free-run search
\ =====================================================================

VARIABLE _EXT4-FFR-GOAL
VARIABLE _EXT4-FFR-MAX
VARIABLE _EXT4-FFR-WRITER
VARIABLE _EXT4-FFR-CTX
VARIABLE _EXT4-FFR-GROUP
VARIABLE _EXT4-FFR-START
VARIABLE _EXT4-FFR-VISITED
VARIABLE _EXT4-FFR-GROUP-BLOCKS
VARIABLE _EXT4-FFR-FREE
VARIABLE _EXT4-FFR-RAW-UNINIT
VARIABLE _EXT4-FFR-UNINIT
VARIABLE _EXT4-FFR-BITMAP-HOME
VARIABLE _EXT4-FFR-BITMAP
VARIABLE _EXT4-FFR-FIRST
VARIABLE _EXT4-FFR-LENGTH

\ The group's free count and BLOCK_UNINIT flag as this transaction stages
\ its primary descriptor page.  Only a raw BLOCK_UNINIT group may still carry
\ the flag.
: _EXT4-FFR-DESC  ( -- ior )
    _EXT4-FFR-GROUP @ _EXT4-FFR-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND 0<> _EXT4-FFR-RAW-UNINIT !
    _EXT4-FFR-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-FFR-BITMAP-HOME !
    _EXT4-FFR-CTX @ _EXT4-C.BLOCK + _EXT4-GD-BLOCK @
    _EXT4-FFR-WRITER @ _EXT4-JTX-META-ACQUIRE ?DUP IF NIP EXIT THEN
    _EXT4-GD-OFF @ +
    DUP _EXT4-FFR-GROUP @ _EXT4-FFR-CTX @ _EXT4-GROUP-DESC-CHECKSUM?
    ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-FFR-BITMAP-HOME @ <> IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JFB-DESC-FREE@ _EXT4-FFR-FREE !
    _EXT4-GD.FLAGS + W@ _EXT4-BG-BLOCK-UNINIT AND 0<> _EXT4-FFR-UNINIT !
    _EXT4-FFR-UNINIT @ _EXT4-FFR-RAW-UNINIT @ 0= AND IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FFR-FREE @ _EXT4-FFR-GROUP-BLOCKS @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ The group's bitmap as this transaction stages it.  The raw source is the
\ authenticated block, or the built bitmap of a BLOCK_UNINIT group; a group
\ this transaction already initialized supplies its retained image.  The
\ clear bits must match the effective free count exactly.
: _EXT4-FFR-LOAD-BITMAP  ( -- ior )
    _EXT4-FFR-RAW-UNINIT @ IF
        _EXT4-FFR-UNINIT @ IF
            _EXT4-FFR-BITMAP-HOME @ _EXT4-FFR-WRITER @ _EXT4-JTX-META-IMAGE
            ?DUP IF NIP EXIT THEN IF
                EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-FFR-GROUP @ _EXT4-FFR-WRITER @ _EXT4-JWR.SCRATCH-B + @
        _EXT4-FFR-CTX @ _EXT4-BUILD-UNINIT-BLOCK-BITMAP ?DUP IF EXIT THEN
        _EXT4-FFR-WRITER @ _EXT4-JWR.SCRATCH-B + @
    ELSE
        _EXT4-FFR-GROUP @ _EXT4-FFR-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        ?DUP IF NIP EXIT THEN
        _EXT4-FFR-BITMAP-HOME @ <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-FFR-CTX @ _EXT4-C.BLOCK +
    THEN
    _EXT4-FFR-BITMAP-HOME @ _EXT4-FFR-WRITER @ _EXT4-JTX-META-ACQUIRE
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-FFR-BITMAP !
    _EXT4-FFR-GROUP-BLOCKS @ BITSET-COUNT-SET? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FFR-GROUP-BLOCKS @ SWAP - _EXT4-FFR-FREE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-FFR-SCAN-GROUP  ( -- found? ior )
    _EXT4-FFR-GROUP @ _EXT4-FFR-CTX @ _EXT4-GROUP-BLOCK-COUNT
    ?DUP IF NIP FALSE SWAP EXIT THEN
    _EXT4-FFR-GROUP-BLOCKS !
    _EXT4-FFR-START @ _EXT4-FFR-GROUP-BLOCKS @ U< 0= IF FALSE 0 EXIT THEN
    _EXT4-FFR-DESC ?DUP IF FALSE SWAP EXIT THEN
    _EXT4-FFR-FREE @ 0= IF FALSE 0 EXIT THEN
    _EXT4-FFR-LOAD-BITMAP ?DUP IF FALSE SWAP EXIT THEN
    _EXT4-FFR-BITMAP @ _EXT4-FFR-GROUP-BLOCKS @
    _EXT4-FFR-START @ _EXT4-FFR-MAX @ BITSET-CLEAR-RUN? 0= IF
        2DROP DROP FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF 2DROP FALSE 0 EXIT THEN
    _EXT4-FFR-LENGTH !
    _EXT4-FFR-GROUP @ _EXT4-FFR-CTX @ _EXT4-C.BPG + @ *
    _EXT4-FFR-CTX @ _EXT4-C.FIRST + @ + + _EXT4-FFR-FIRST !
    _EXT4-FFR-FIRST @ _EXT4-FFR-LENGTH @ _EXT4-FFR-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF FALSE SWAP EXIT THEN
    TRUE 0 ;

\ The first free run of at most MAX blocks in the transaction's view of the
\ bitmaps: in GOAL's group from GOAL, then in each following group with
\ wraparound, then from the start of GOAL's group.  A run stays inside one
\ group, BLOCK_UNINIT groups count with the bitmaps they stand for, and a
\ bitmap that offers a block in the journal or a static metadata role is
\ corrupt.  COUNT zero means no group has a free block.
: _EXT4-JTX-FIND-FREE-RUN  ( goal max transaction -- first count ior )
    _EXT4-FFR-WRITER ! _EXT4-FFR-MAX ! _EXT4-FFR-GOAL !
    _EXT4-FFR-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF 0 0 ROT EXIT THEN
    _EXT4-FFR-WRITER @ _EXT4-JWR.CTX + @ _EXT4-FFR-CTX !
    _EXT4-FFR-MAX @ 0> 0= IF 0 0 VFS-E-INVALID EXIT THEN
    _EXT4-FFR-GOAL @ _EXT4-FFR-CTX @ _EXT4-C.FIRST + @ MAX
    DUP _EXT4-FFR-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        DROP _EXT4-FFR-CTX @ _EXT4-C.FIRST + @
    THEN
    _EXT4-FFR-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-FFR-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-FFR-GROUP ! _EXT4-FFR-START !
    0 _EXT4-FFR-VISITED !
    BEGIN
        _EXT4-FFR-VISITED @ _EXT4-FFR-CTX @ _EXT4-C.GROUPS + @ U> 0=
    WHILE
        _EXT4-FFR-SCAN-GROUP ?DUP IF NIP 0 0 ROT EXIT THEN
        IF _EXT4-FFR-FIRST @ _EXT4-FFR-LENGTH @ 0 EXIT THEN
        1 _EXT4-FFR-VISITED +!
        _EXT4-FFR-GROUP @ 1+
        DUP _EXT4-FFR-CTX @ _EXT4-C.GROUPS + @ = IF DROP 0 THEN
        _EXT4-FFR-GROUP !
        0 _EXT4-FFR-START !
    REPEAT
    0 0 0 ;


\ Prove that no proposed release range names any storage owned by the modern
\ orphan file.  Publish the exact candidate vector while the complete reader
\ validates the orphan inode's extent or legacy map.  The ordinary allocation
\ checks then reject aliases through leaf data, preallocation beyond EOF,
\ external extent nodes, and legacy indirect metadata without flattening that
\ geometry into another fixed table.  Check an external xattr block under the
\ same scope, authenticate every logical orphan-block tail, withdraw the scope
\ on every return, and finally restore the target plan record in C.INODE.

\ =====================================================================
\  Plan-bound unlinked inode allocation release
\ =====================================================================

VARIABLE _EXT4-JFI-RECORD
VARIABLE _EXT4-JFI-WRITER
VARIABLE _EXT4-JFI-CTX
VARIABLE _EXT4-JFI-INO
VARIABLE _EXT4-JFI-INODE
VARIABLE _EXT4-JFI-GROUP
VARIABLE _EXT4-JFI-INDEX
VARIABLE _EXT4-JFI-GROUP-INODES
VARIABLE _EXT4-JFI-INODE-TABLE
VARIABLE _EXT4-JFI-INODE-HOME
VARIABLE _EXT4-JFI-INODE-OFF
VARIABLE _EXT4-JFI-BITMAP-HOME
VARIABLE _EXT4-JFI-GDT-HOME
VARIABLE _EXT4-JFI-GDT-OFF
VARIABLE _EXT4-JFI-IMAGE
VARIABLE _EXT4-JFI-DESC
VARIABLE _EXT4-JFI-BITMAP-CRC
VARIABLE _EXT4-JFI-NEW-BITMAP-CRC
VARIABLE _EXT4-JFI-GROUP-FREE
VARIABLE _EXT4-JFI-NEW-GROUP-FREE
VARIABLE _EXT4-JFI-SUPER-HOME
VARIABLE _EXT4-JFI-SUPER
VARIABLE _EXT4-JFI-NEW-SUPER-FREE
VARIABLE _EXT4-JFI-IOR
VARIABLE _EXT4-JFI-PUBLISHED
VARIABLE _EXT4-JFI-ABORT-IOR
VARIABLE _EXT4-JFI-DATA-ENTRIES
VARIABLE _EXT4-JFI-DATA-BLOCKS
VARIABLE _EXT4-JFI-DATA-MAP-KIND
VARIABLE _EXT4-JFI-EA
VARIABLE _EXT4-JFI-EA-ACTION
VARIABLE _EXT4-JFI-EA-REFCOUNT
VARIABLE _EXT4-JFI-EA-AFTER-CRC
VARIABLE _EXT4-JFI-EA-AFTER-VERIFIED
VARIABLE _EXT4-JFI-EA-IMAGE
VARIABLE _EXT4-JFI-RANGE-EXPECTED
VARIABLE _EXT4-JFI-PROSPECTIVE
VARIABLE _EXT4-JFI-PROSPECTIVE-GEN
VARIABLE _EXT4-JFI-DIRECTORY
VARIABLE _EXT4-JFI-USED-DIRS
CREATE _EXT4-JFI-EA-RANGE
2 CELLS ALLOT

\ The links an inode holds before its last link goes: one for a regular
\ file, two for an empty directory, its parent's record and its `.`.
: _EXT4-JFI-PROSPECTIVE-LINKS  ( inode -- links )
    _EXT4-I.MODE + W@ 0xF000 AND 0x4000 = IF 2 ELSE 1 THEN ;

: _EXT4-JFI-REAUTH-CURRENT  ( -- ior )
    _EXT4-JFI-PROSPECTIVE @ IF
        _EXT4-JFI-INO @ _EXT4-JFI-CTX @
        _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
        _EXT4-JFI-CTX @ _EXT4-C.INODE + DUP _EXT4-JFI-INODE !
        DUP _EXT4-I.GENERATION + L@
        _EXT4-JFI-PROSPECTIVE-GEN @ <> IF
            DROP VFS-E-CONFLICT EXIT
        THEN
        DUP _EXT4-I.DTIME + L@ IF DROP VFS-E-CONFLICT EXIT THEN
        DUP _EXT4-I.LINKS + W@ SWAP _EXT4-JFI-PROSPECTIVE-LINKS <> IF
            VFS-E-CONFLICT EXIT
        THEN
        0 EXIT
    THEN
    _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-C.INODE + DUP _EXT4-JFI-INODE !
    _EXT4-I.LINKS + W@ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

: _EXT4-JFI-RANGES  ( -- ranges )
    _EXT4-JFI-CTX @ _EXT4-C.MUTATION-RANGES + @ ;

: _EXT4-JFI-RANGE-CAP  ( -- capacity )
    _EXT4-JFI-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @ ;

: _EXT4-JFI-RANGE  ( index -- pair-address )
    2* CELLS _EXT4-JFI-RANGES + ;

: _EXT4-JFI-EA-RELEASE?  ( -- flag )
    _EXT4-JFI-EA-ACTION @ _EXT4-JEA-RELEASE = ;

: _EXT4-JFI-EA-REFDEC?  ( -- flag )
    _EXT4-JFI-EA-ACTION @ _EXT4-JEA-REFDEC = ;

: _EXT4-JFI-RANGE-COUNT  ( -- count )  _EXT4-JFI-DATA-ENTRIES @ ;

: _EXT4-JFI-RANGE-BLOCKS  ( -- blocks )  _EXT4-JFI-DATA-BLOCKS @ ;

: _EXT4-JFI-RELEASE-RANGE-COUNT  ( -- count )
    _EXT4-JFI-RANGE-COUNT
    _EXT4-JFI-EA-RELEASE? IF 1+ THEN ;

: _EXT4-JFI-RELEASE-RANGE  ( index -- pair-address )
    DUP _EXT4-JFI-RANGE-COUNT U< IF
        _EXT4-JFI-RANGE EXIT
    THEN
    DROP _EXT4-JFI-EA-RANGE ;

: _EXT4-JFI-ACCOUNTED-BLOCKS  ( -- blocks )
    _EXT4-JFI-RANGE-BLOCKS
    _EXT4-JFI-EA @ IF 1+ THEN ;

: _EXT4-JFI-RELEASE-BLOCKS  ( -- blocks )
    _EXT4-JFI-RANGE-BLOCKS
    _EXT4-JFI-EA-RELEASE? IF 1+ THEN ;

\ A deletion revokes its xattr block when it releases it.  The release
\ passes before it revoke the map blocks they free.
: _EXT4-JFI-REVOKE-COUNT  ( -- count )
    _EXT4-JFI-EA-RELEASE? 1 AND ;

VARIABLE _EXT4-JRV-WRITER

\ A deletion folded into a release pass takes as its vector the runs the
\ pass freed, which stay in the mutation range workspace where the release
\ recorded them.  Checkpoint verification reloads them from the
\ certificate.
VARIABLE _EXT4-JFI-RELEASED
VARIABLE _EXT4-JFI-RELEASED-RUNS
VARIABLE _EXT4-JFI-RELEASED-BLOCKS

\ True when BLOCK lies inside one of the vector's data runs.
: _EXT4-JFI-IN-RUNS?  ( block -- flag )
    _EXT4-JFI-DATA-ENTRIES @ 0 ?DO
        DUP I _EXT4-JFI-RANGE @ - I _EXT4-JFI-RANGE CELL+ @ U< IF
            DROP TRUE UNLOOP EXIT
        THEN
    LOOP
    DROP FALSE ;

\ A released vector's revokes are the tree nodes the release freed, each
\ inside one of its runs, then a released xattr block.
: _EXT4-JFI-RELEASED-REVOKES?  ( -- flag )
    _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    DUP _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U> IF
        DROP FALSE EXIT
    THEN
    _EXT4-JFI-EA-RELEASE? IF
        DUP 0= IF DROP FALSE EXIT THEN
        1- DUP _EXT4-JRV-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        DUP @ _EXT4-JFI-EA @ <> SWAP CELL+ @ _EXT4-JE-ACTIVE <> OR IF
            DROP FALSE EXIT
        THEN
    THEN
    0 ?DO
        I _EXT4-JRV-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        DUP CELL+ @ _EXT4-JE-ACTIVE <> IF DROP FALSE UNLOOP EXIT THEN
        @ _EXT4-JFI-IN-RUNS? 0= IF FALSE UNLOOP EXIT THEN
    LOOP
    TRUE ;

\ Prove the exact retained revoke vector.  A deletion of an empty map
\ revokes only an xattr block it releases, and one folded into a release
\ pass keeps the pass's own revokes before it.  Data blocks and
\ shared-xattr decrements are never revoked.
: _EXT4-JFI-REVOKES-EXACT?  ( writer -- flag )
    _EXT4-JRV-WRITER !
    _EXT4-JFI-EA-RELEASE? _EXT4-JFI-EA @ 0= AND IF FALSE EXIT THEN
    _EXT4-JFI-DATA-MAP-KIND @ _EXT4-JDM-RELEASED = IF
        _EXT4-JFI-RELEASED-REVOKES? EXIT
    THEN
    _EXT4-JFI-REVOKE-COUNT
    DUP _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        DROP FALSE EXIT
    THEN
    DUP
    _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <>
    OVER _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-USED + @ <> OR
    SWAP _EXT4-JRV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
        FALSE EXIT
    THEN
    _EXT4-JFI-EA-RELEASE? IF
        0 _EXT4-JRV-WRITER @ _EXT4-JWR-REVOKE-ENTRY DUP @ _EXT4-JFI-EA @ <>
        SWAP CELL+ @ _EXT4-JE-ACTIVE <> OR IF FALSE EXIT THEN
    THEN
    TRUE ;

VARIABLE _EXT4-JFO-CTX
VARIABLE _EXT4-JFO-TARGET-INO
VARIABLE _EXT4-JFO-GROUP
VARIABLE _EXT4-JFO-GROUP-INODES
VARIABLE _EXT4-JFO-GROUP-BASE
VARIABLE _EXT4-JFO-INO
VARIABLE _EXT4-JFO-INODE
VARIABLE _EXT4-JFO-NLINK
VARIABLE _EXT4-JFO-TYPE
VARIABLE _EXT4-JFO-IOR
VARIABLE _EXT4-JFO-INODE-TABLE

VARIABLE _EXT4-MPH-FIRST
VARIABLE _EXT4-MPH-COUNT
VARIABLE _EXT4-MPH-CTX
VARIABLE _EXT4-MPH-ROOT

\ Activation, emission, checkpoint cleanup, and deactivation may replace the
\ primary superblock and any block in the authenticated journal extent tuple.
\ Test one inode-owned range against that complete protocol-home set without
\ flattening its bounded, possibly discontiguous extents into a fixed table.
: _EXT4-MUTATION-PROTOCOL-HOME-ALIASES?  ( first count ctx -- flag )
    _EXT4-MPH-CTX ! _EXT4-MPH-COUNT ! _EXT4-MPH-FIRST !
    _EXT4-MPH-FIRST @ _EXT4-MPH-COUNT @
    _EXT4-MPH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK 1
    _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF TRUE EXIT THEN
    _EXT4-MPH-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SB.JOURNAL-BLOCKS + DUP _EXT4-MPH-ROOT !
    2 + W@ 0 ?DO
        _EXT4-MPH-FIRST @ _EXT4-MPH-COUNT @
        _EXT4-MPH-ROOT @ 12 I 12 * + + DUP
        8 + L@ SWAP 4 + W@
        _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF TRUE UNLOOP EXIT THEN
    LOOP
    FALSE ;

' _EXT4-MUTATION-PROTOCOL-HOME-ALIASES?
_EXT4-MUTATION-PROTOCOL-XT !

: _EXT4-JFO-REQUIRE-EMPTY-RESERVED  ( -- ior )
    _EXT4-JFO-INODE @ _EXT4-I.FILE-ACL-HI + W@
    _EXT4-JFO-INODE @ _EXT4-I.FILE-ACL-LO + L@ OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.BLOCKS-LO + L@
    _EXT4-JFO-INODE @ _EXT4-I.BLOCKS-HI + W@ OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.BLOCK + 60 _EXT4-BYTES-ZERO? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ An inode's external xattr block must be allocated.  Other inodes may
\ share it, so the ownership proof lists the reference instead of claiming
\ the block.
: _EXT4-JFO-REQUIRE-XATTR-BLOCK  ( physical-block -- ior )
    DUP EXT4-D-DATA-MAP _EXT4-JFO-CTX @ _EXT4-REQUIRE-ALLOCATED-BLOCK
    ?DUP IF NIP EXIT THEN
    _EXT4-OWN-MODE @ IF _EXT4-OWN-LIST-EA EXIT THEN
    DROP 0 ;

\ Validate the loaded record's complete map and xattr reference through the
\ ordinary validators, which note its blocks in an open claim scope and
\ refuse a protocol home while the protocol scope is published.  Inode 1
\ may own a legacy bad-block map even with mode zero; other mode-zero reserved
\ records must be storage-empty.  Fast symlink and device payload bytes are
\ interpreted by the normal inode validator rather than mistaken for maps.
: _EXT4-JFO-CHECK-CURRENT-INODE  ( -- ior )
    _EXT4-JFO-CTX @ _EXT4-C.INODE + DUP _EXT4-JFO-INODE !
    DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ ?DUP IF
        _EXT4-JFO-REQUIRE-XATTR-BLOCK ?DUP IF EXIT THEN
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.MODE + W@ 0xF000 AND 0= IF
        _EXT4-JFO-INO @ 1 = IF
            _EXT4-JFO-CTX @ _EXT4-VALIDATE-LEGACY-MAP EXIT
        THEN
        _EXT4-JFO-INO @
        _EXT4-JFO-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFO-REQUIRE-EMPTY-RESERVED EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.LINKS + W@ DUP _EXT4-JFO-NLINK !
    0= IF 1 _EXT4-JFO-INODE @ _EXT4-I.LINKS + W! THEN
    _EXT4-JFO-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JFO-IOR ! _EXT4-JFO-TYPE !
    _EXT4-JFO-NLINK @ 0= IF
        0 _EXT4-JFO-INODE @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-JFO-IOR @ ;

\ The group bitmap copy is already checksum-authenticated and the caller only
\ reaches this word for a set bit.  Load the record directly from the retained
\ table home, then apply the orphan-aware dtime bound.  This avoids rereading
\ and rechecksumming the same inode bitmap for every allocated inode.
: _EXT4-JFO-LOAD-CURRENT-INODE  ( -- ior )
    _EXT4-JFO-INO @ _EXT4-JFO-CTX @
    _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JFO-GROUP @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE-TABLE @ _EXT4-LOAD-INODE-RECORD-RAW ?DUP IF EXIT THEN
    _EXT4-JFO-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
    _EXT4-JFO-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFO-SCAN-GROUP  ( -- ior )
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-LOAD-DESC ?DUP IF
        EXIT
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF 0 EXIT THEN
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-GROUP-INODE-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFO-GROUP-INODES !
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-LOAD-INODE-BITMAP
    DUP IF NIP EXIT THEN 2DROP
    _EXT4-JFO-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFO-INODE-TABLE !
    _EXT4-JFO-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFO-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFO-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-JFO-GROUP-BASE !
    _EXT4-JFO-GROUP-INODES @ 0 ?DO
        _EXT4-JFO-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JFO-GROUP-INODES @ I BITSET-TEST? 0= IF
            DROP EXT4-D-BOUNDS _EXT4-CORRUPT UNLOOP EXIT
        THEN
        IF
            _EXT4-JFO-GROUP-BASE @ I + 1+ DUP _EXT4-JFO-INO !
            _EXT4-JFO-TARGET-INO @ <> IF
                _EXT4-JFO-LOAD-CURRENT-INODE ?DUP IF UNLOOP EXIT THEN
                _EXT4-JFO-CHECK-CURRENT-INODE ?DUP IF UNLOOP EXIT THEN
            THEN
        THEN
    LOOP
    0 ;

\ Check every allocated inode but TARGET-INO, which is zero when the walk
\ excludes none.  One walk reads each descriptor page, bitmap, inode-table
\ block, and map block from media once; the walk itself writes nothing.
: _EXT4-JFO-SCAN-INODES  ( -- ior )
    _EXT4-JFO-CTX @ _EXT4-PROOF-SCOPE-OPEN
    0 _EXT4-JFO-GROUP !
    BEGIN
        _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JFO-SCAN-GROUP ?DUP IF _EXT4-PROOF-SCOPE-CLOSE EXIT THEN
        1 _EXT4-JFO-GROUP +!
    REPEAT
    _EXT4-PROOF-SCOPE-CLOSE 0 ;

\ =====================================================================
\  Block ownership proof
\ =====================================================================
\
\ Before a mount's first write, prove that the block bitmaps hold exactly
\ the blocks the fixed metadata and the allocated inodes own, each owned
\ once.  The fixed metadata are every group's block and inode bitmaps and
\ inode table, wherever its descriptor places them, and the superblock and
\ descriptor-table copies each sparse group holds; the resize inode owns
\ the reserved descriptor blocks.  One walk of every allocated inode claims
\ its map through the ordinary validators, so a block claimed twice, by two
\ owners or twice by one, refuses.  An external xattr block may be shared:
\ the walk lists every reference, and each listed block is claimed once and
\ must carry a reference count equal to the inodes that name it.  Every
\ group's block bitmap, or the one a BLOCK_UNINIT group stands for, must
\ then equal the claims in the group's blocks.  Nothing else writes a
\ mounted volume, and each later transaction proves that it changes maps by
\ exactly the blocks it allocates and frees, so the proof stands for the
\ rest of the mount.  Its claim map, one bit per block, is the mount's
\ claim workspace, cleared when the proof ends; the reference list grows at
\ the top of the mount arena and is rolled back.

VARIABLE _EXT4-BOP-CTX
VARIABLE _EXT4-BOP-ARENA
VARIABLE _EXT4-BOP-MARK
VARIABLE _EXT4-BOP-MAP
VARIABLE _EXT4-BOP-BUF
VARIABLE _EXT4-BOP-GROUP
VARIABLE _EXT4-BOP-BLOCKS
VARIABLE _EXT4-BOP-LIMIT
VARIABLE _EXT4-BOP-IOR
VARIABLE _EXT4-BOP-AT
VARIABLE _EXT4-BOP-RUN
VARIABLE _EXT4-BOP-EA
VARIABLE _EXT4-BOP-A
VARIABLE _EXT4-BOP-B
VARIABLE _EXT4-BOP-N

\ Claim the fixed metadata GROUP's descriptor places, and the superblock and
\ descriptor-table copies a sparse group holds.
: _EXT4-BOP-CLAIM-GROUP  ( group -- ior )
    DUP _EXT4-BOP-GROUP ! _EXT4-BOP-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
    _EXT4-OWN-NOTE ?DUP IF EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-BITMAP-LO + L@ 1
    _EXT4-OWN-NOTE ?DUP IF EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-GD-SPAN @ _EXT4-OWN-NOTE ?DUP IF EXIT THEN
    _EXT4-BOP-GROUP @ _EXT4-SPARSE-GROUP? 0= IF 0 EXIT THEN
    _EXT4-BOP-GROUP @ _EXT4-BOP-CTX @ _EXT4-C.BPG + @ *
    _EXT4-BOP-CTX @ _EXT4-C.FIRST + @ +
    _EXT4-BOP-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ 1+
    _EXT4-OWN-NOTE ;

VARIABLE _EXT4-CS-BASE
VARIABLE _EXT4-CS-N
VARIABLE _EXT4-CS-GAP
VARIABLE _EXT4-CS-V
VARIABLE _EXT4-CS-J

: _EXT4-CS@  ( index -- value )  CELLS _EXT4-CS-BASE @ + @ ;
: _EXT4-CS!  ( value index -- )  CELLS _EXT4-CS-BASE @ + ! ;

\ Sort N cells at BASE into ascending unsigned order, by Shell sort with
\ Knuth's gaps.
: _EXT4-SORT-CELLS  ( base n -- )
    _EXT4-CS-N ! _EXT4-CS-BASE !
    1 BEGIN DUP 3 * 1+ _EXT4-CS-N @ U< WHILE 3 * 1+ REPEAT _EXT4-CS-GAP !
    BEGIN _EXT4-CS-GAP @ WHILE
        _EXT4-CS-N @ _EXT4-CS-GAP @ ?DO
            I _EXT4-CS@ _EXT4-CS-V ! I _EXT4-CS-J !
            BEGIN
                _EXT4-CS-J @ _EXT4-CS-GAP @ U< 0= DUP IF
                    DROP _EXT4-CS-J @ _EXT4-CS-GAP @ - _EXT4-CS@
                    _EXT4-CS-V @ U>
                THEN
            WHILE
                _EXT4-CS-J @ _EXT4-CS-GAP @ - _EXT4-CS@
                _EXT4-CS-J @ _EXT4-CS!
                _EXT4-CS-GAP @ NEGATE _EXT4-CS-J +!
            REPEAT
            _EXT4-CS-V @ _EXT4-CS-J @ _EXT4-CS!
        LOOP
        _EXT4-CS-GAP @ 3 / _EXT4-CS-GAP !
    REPEAT ;

\ Claim each listed xattr block once.  Its reference count must equal the
\ inodes that name it.
: _EXT4-BOP-CLAIM-EAS  ( -- ior )
    _EXT4-OWN-EA-LIST @ _EXT4-OWN-EA-COUNT @ _EXT4-SORT-CELLS
    0 _EXT4-BOP-AT !
    BEGIN _EXT4-BOP-AT @ _EXT4-OWN-EA-COUNT @ U< WHILE
        _EXT4-BOP-AT @ CELLS _EXT4-OWN-EA-LIST @ + @ _EXT4-BOP-EA !
        1 _EXT4-BOP-RUN !
        BEGIN
            _EXT4-BOP-AT @ _EXT4-BOP-RUN @ +
            DUP _EXT4-OWN-EA-COUNT @ U< IF
                CELLS _EXT4-OWN-EA-LIST @ + @ _EXT4-BOP-EA @ =
            ELSE
                DROP FALSE
            THEN
        WHILE
            1 _EXT4-BOP-RUN +!
        REPEAT
        _EXT4-BOP-EA @ 1 TRUE _EXT4-OWN-SPAN ?DUP IF EXIT THEN
        _EXT4-BOP-EA @ _EXT4-BOP-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
        _EXT4-BOP-CTX @ _EXT4-C.BLOCK + 4 + L@ _EXT4-BOP-RUN @ <> IF
            EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        _EXT4-BOP-RUN @ _EXT4-BOP-AT +!
    REPEAT 0 ;

\ Whether the first BITS bits of A and B agree.
: _EXT4-BOP-BITS=?  ( a b bits -- flag )
    _EXT4-BOP-N ! _EXT4-BOP-B ! _EXT4-BOP-A !
    _EXT4-BOP-A @ _EXT4-BOP-B @ _EXT4-BOP-N @ 8 / _EXT4-BYTES=? 0= IF
        FALSE EXIT
    THEN
    _EXT4-BOP-N @ 8 MOD 0= IF TRUE EXIT THEN
    _EXT4-BOP-A @ _EXT4-BOP-N @ 8 / + C@
    _EXT4-BOP-B @ _EXT4-BOP-N @ 8 / + C@ XOR
    1 _EXT4-BOP-N @ 8 MOD LSHIFT 1- AND 0= ;

\ The claims in GROUP's blocks must equal its block bitmap, or the bitmap a
\ BLOCK_UNINIT group stands for.  A group spans one bitmap block of bits, so
\ its claims start GROUP blocks into the claim map.
: _EXT4-BOP-COMPARE-GROUP  ( group -- ior )
    DUP _EXT4-BOP-GROUP ! _EXT4-BOP-CTX @ _EXT4-GROUP-BLOCK-COUNT
    ?DUP IF NIP EXIT THEN _EXT4-BOP-BLOCKS !
    _EXT4-BOP-GROUP @ _EXT4-BOP-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF
        _EXT4-BOP-GROUP @ _EXT4-BOP-BUF @ _EXT4-BOP-CTX @
        _EXT4-BUILD-UNINIT-BLOCK-BITMAP ?DUP IF EXIT THEN
        _EXT4-BOP-BUF @
    ELSE
        _EXT4-BOP-GROUP @ _EXT4-BOP-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        ?DUP IF NIP EXIT THEN DROP
        _EXT4-BOP-CTX @ _EXT4-C.BLOCK +
    THEN
    _EXT4-BOP-GROUP @ _EXT4-BOP-CTX @ _EXT4-C.BSIZE + @ *
    _EXT4-BOP-MAP @ +
    _EXT4-BOP-BLOCKS @ _EXT4-BOP-BITS=? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-BOP-BODY  ( -- ior )
    _EXT4-BOP-CTX @ _EXT4-PROOF-SCOPE-OPEN
    _EXT4-BOP-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-BOP-CLAIM-GROUP ?DUP IF
            _EXT4-PROOF-SCOPE-CLOSE UNLOOP EXIT
        THEN
    LOOP
    _EXT4-PROOF-SCOPE-CLOSE
    _EXT4-BOP-CTX @ _EXT4-JFO-CTX !
    0 _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-BOP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-JFO-SCAN-INODES
    _EXT4-BOP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    ?DUP IF EXIT THEN
    _EXT4-BOP-CLAIM-EAS ?DUP IF EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-PROOF-SCOPE-OPEN
    _EXT4-BOP-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-BOP-COMPARE-GROUP ?DUP IF
            _EXT4-PROOF-SCOPE-CLOSE UNLOOP EXIT
        THEN
    LOOP
    _EXT4-PROOF-SCOPE-CLOSE 0 ;

\ Prove block ownership for CTX's mount, once: a proved mount answers at
\ once, and a refusal leaves the proof to be attempted again.
: _EXT4-PROVE-OWNERSHIP  ( ctx -- ior )
    DUP _EXT4-BOP-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-C.OWNERSHIP + @ -1 = IF 0 EXIT THEN
    0 _EXT4-BOP-CTX @ _EXT4-C.OWNERSHIP + !
    1 _EXT4-MAP-EPOCH +!
    _EXT4-OWN-MAP @ _EXT4-OWN-EA-ARENA @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-C.ARENA + @ DUP _EXT4-BOP-ARENA !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-BOP-CTX @ _EXT4-C.CLAIM-WORKSPACE + @ DUP _EXT4-BOP-MAP !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-BOP-MAP @ _EXT4-BOP-CTX @ _EXT4-OWN-BYTES + _EXT4-BOP-BUF !
    _EXT4-BOP-ARENA @ ARENA-SNAP _EXT4-BOP-MARK !
    _EXT4-BOP-ARENA @ _EXT4-OWN-EA-ARENA !
    _EXT4-BOP-MARK @ _EXT4-OWN-EA-LIST ! 0 _EXT4-OWN-EA-COUNT !
    _EXT4-BOP-MAP @ 1 _EXT4-BOP-CTX @ _EXT4-OWN-OPEN DUP 0= IF
        DROP _EXT4-BOP-BODY
    THEN
    _EXT4-BOP-IOR !
    _EXT4-OWN-CLOSE
    0 _EXT4-OWN-EA-ARENA ! 0 _EXT4-OWN-EA-LIST ! 0 _EXT4-OWN-EA-COUNT !
    _EXT4-BOP-ARENA @ _EXT4-BOP-MARK @ ARENA-ROLLBACK
    _EXT4-BOP-MAP @ _EXT4-BOP-CTX @ _EXT4-OWN-BYTES 0 FILL
    _EXT4-BOP-IOR @ 0= IF -1 _EXT4-BOP-CTX @ _EXT4-C.OWNERSHIP + ! THEN
    _EXT4-BOP-IOR @ ;

\ ---------------------------------------------------------------------
\  Transaction map check
\ ---------------------------------------------------------------------
\
\ Before a transaction commits, the maps it changes must differ from their
\ old selves by exactly the blocks it allocates and frees, so the mount's
\ ownership proof still stands after it.  The check opens a claim map over
\ the volume and claims each changed map as it stood before the
\ transaction.  Each block bitmap the transaction changes then claims the
\ blocks it sets and releases the blocks it clears.  Each map as the
\ transaction stages it, read through the transaction, must then release
\ every claim that is left, and nothing more, so a block mapped by mistake,
\ a block dropped without being freed, and a block mapped twice all refuse.
\ The claim map is the mount's claim workspace.  A mount cleanup writer owns
\ the end of the mount arena while it stages, so the check allocates nothing.

VARIABLE _EXT4-NMC-CTX
VARIABLE _EXT4-NMC-TX
VARIABLE _EXT4-NMC-OPENED
VARIABLE _EXT4-NMC-BUF
VARIABLE _EXT4-NMC-PAGE
VARIABLE _EXT4-NMC-IMAGE
VARIABLE _EXT4-NMC-GROUP
VARIABLE _EXT4-NMC-DESC
VARIABLE _EXT4-NMC-AFTER
VARIABLE _EXT4-NMC-BEFORE
VARIABLE _EXT4-NMC-FIRST
VARIABLE _EXT4-NMC-BASE
VARIABLE _EXT4-NMC-BITS
VARIABLE _EXT4-NMC-CLAIM
VARIABLE _EXT4-NMC-A
VARIABLE _EXT4-NMC-B

\ Open the check of TRANSACTION on CTX over the mount's claim workspace,
\ whose map is clear, claiming.
: _EXT4-NMC-OPEN  ( ctx transaction -- ior )
    _EXT4-NMC-TX ! DUP _EXT4-NMC-CTX ! 0 _EXT4-NMC-OPENED !
    _EXT4-C.CLAIM-WORKSPACE + @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-NMC-CTX @ _EXT4-OWN-BYTES + _EXT4-NMC-BUF !
    1 _EXT4-NMC-CTX @ _EXT4-OWN-OPEN ?DUP IF EXIT THEN
    -1 _EXT4-NMC-OPENED ! 0 ;

\ End the check.  Unless an earlier step failed, every claim must have been
\ released, which leaves the map clear; a failed check clears it.
: _EXT4-NMC-CLOSE  ( ior -- ior )
    0 _EXT4-EV-IMAGE-XT !
    _EXT4-NMC-OPENED @ 0= IF EXIT THEN
    DUP 0= _EXT4-OWN-COUNT @ 0<> AND IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT
    THEN
    DUP IF _EXT4-OWN-MAP @ _EXT4-NMC-CTX @ _EXT4-OWN-BYTES 0 FILL THEN
    _EXT4-OWN-CLOSE
    0 _EXT4-NMC-OPENED ! ;

\ Claim (NMC-CLAIM true) or release each block whose bit is set in BITS,
\ in the claim-map cell whose first block is NMC-BASE.
: _EXT4-NMC-CELL  ( bits -- ior )
    DUP -1 = IF
        DROP _EXT4-NMC-BASE @ 64 _EXT4-NMC-CLAIM @ _EXT4-OWN-SPAN EXIT
    THEN
    _EXT4-NMC-BITS !
    64 0 DO
        _EXT4-NMC-BITS @ I RSHIFT 1 AND IF
            _EXT4-NMC-BASE @ I + 1 _EXT4-NMC-CLAIM @ _EXT4-OWN-SPAN
            ?DUP IF UNLOOP EXIT THEN
        THEN
    LOOP 0 ;

\ Apply GROUP's block-bitmap change from BEFORE to AFTER: claim each block
\ whose bit it sets and release each block whose bit it clears.
: _EXT4-NMC-APPLY  ( before after group -- ior )
    _EXT4-NMC-CTX @ _EXT4-C.BPG + @ *
    _EXT4-NMC-CTX @ _EXT4-C.FIRST + @ + _EXT4-NMC-FIRST !
    _EXT4-NMC-AFTER ! _EXT4-NMC-BEFORE !
    _EXT4-NMC-CTX @ _EXT4-C.BSIZE + @ 8 / 0 DO
        I CELLS _EXT4-NMC-BEFORE @ + @ _EXT4-NMC-B !
        I CELLS _EXT4-NMC-AFTER @ + @ _EXT4-NMC-A !
        _EXT4-NMC-A @ _EXT4-NMC-B @ <> IF
            _EXT4-NMC-FIRST @ I 64 * + _EXT4-NMC-BASE !
            TRUE _EXT4-NMC-CLAIM !
            _EXT4-NMC-A @ _EXT4-NMC-B @ INVERT AND ?DUP IF
                _EXT4-NMC-CELL ?DUP IF UNLOOP EXIT THEN
            THEN
            FALSE _EXT4-NMC-CLAIM !
            _EXT4-NMC-B @ _EXT4-NMC-A @ INVERT AND ?DUP IF
                _EXT4-NMC-CELL ?DUP IF UNLOOP EXIT THEN
            THEN
        THEN
    LOOP 0 ;

\ GROUP's change, when the transaction's descriptor for it differs from the
\ one on media and the transaction stages its block bitmap.  The bitmap's
\ media image is the pre-image, or for a BLOCK_UNINIT group the one the
\ group stands for.
: _EXT4-NMC-GROUP-DELTA  ( group -- ior )
    DUP _EXT4-NMC-GROUP ! _EXT4-NMC-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-NMC-GROUP @
    _EXT4-NMC-CTX @ _EXT4-C.BSIZE + @ _EXT4-DESC-SIZE / MOD
    _EXT4-DESC-SIZE * _EXT4-NMC-IMAGE @ + _EXT4-NMC-DESC !
    _EXT4-NMC-DESC @ _EXT4-NMC-CTX @ _EXT4-C.DESC + _EXT4-DESC-SIZE
    _EXT4-BYTES=? IF 0 EXIT THEN
    _EXT4-NMC-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-NMC-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-NMC-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-NMC-TX @ _EXT4-JTX-META-IMAGE ?DUP IF NIP EXIT THEN
    ?DUP 0= IF 0 EXIT THEN
    _EXT4-NMC-AFTER !
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF
        _EXT4-NMC-GROUP @ _EXT4-NMC-BUF @ _EXT4-NMC-CTX @
        _EXT4-BUILD-UNINIT-BLOCK-BITMAP ?DUP IF EXIT THEN
    ELSE
        _EXT4-NMC-GROUP @ _EXT4-NMC-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        ?DUP IF NIP EXIT THEN DROP
        _EXT4-NMC-CTX @ _EXT4-C.BLOCK + _EXT4-NMC-BUF @
        _EXT4-NMC-CTX @ _EXT4-C.BSIZE + @ MOVE
    THEN
    _EXT4-NMC-BUF @ _EXT4-NMC-AFTER @ _EXT4-NMC-GROUP @ _EXT4-NMC-APPLY ;

\ Apply every block-bitmap change the transaction stages.  A bitmap that
\ changes changes its checksum in its group's descriptor, so the descriptors
\ the transaction's descriptor-table pages change name every such bitmap.
: _EXT4-NMC-DELTAS  ( -- ior )
    1 _EXT4-OWN-MODE !
    _EXT4-NMC-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ 0 ?DO
        I _EXT4-NMC-PAGE !
        _EXT4-NMC-CTX @ _EXT4-GDT-BASE I +
        _EXT4-NMC-TX @ _EXT4-JTX-META-IMAGE ?DUP IF NIP UNLOOP EXIT THEN
        ?DUP IF
            _EXT4-NMC-IMAGE !
            _EXT4-NMC-CTX @ _EXT4-C.BSIZE + @ _EXT4-DESC-SIZE / 0 ?DO
                _EXT4-NMC-PAGE @
                _EXT4-NMC-CTX @ _EXT4-C.BSIZE + @ _EXT4-DESC-SIZE / * I +
                DUP _EXT4-NMC-CTX @ _EXT4-C.GROUPS + @ U< IF
                    _EXT4-NMC-GROUP-DELTA ?DUP IF UNLOOP UNLOOP EXIT THEN
                ELSE
                    DROP
                THEN
            LOOP
        THEN
    LOOP 0 ;

: _EXT4-NMC-NODE-IMAGE  ( block -- image ior )
    _EXT4-NMC-TX @ _EXT4-JTX-META-IMAGE ;

\ A family names each inode record its transaction stages by inode number,
\ inode-table home and offset, and kind: kept by the transaction, created
\ by it, or freed by it.  A kept record whose type, block count, flags, map
\ and xattr block stay as they are keeps its map, so it is passed over.  The
\ first refusal is kept, and the steps after it do nothing.
0 CONSTANT _EXT4-NMC-RETAINED
1 CONSTANT _EXT4-NMC-CREATED
2 CONSTANT _EXT4-NMC-FREED

VARIABLE _EXT4-NMC-IOR
VARIABLE _EXT4-NMC-INO
VARIABLE _EXT4-NMC-HOME
VARIABLE _EXT4-NMC-OFF
VARIABLE _EXT4-NMC-KIND
VARIABLE _EXT4-NMC-IN

\ Note the map of the record in C.INODE as its type defines it.  As the
\ inode reader holds, a device, fifo, socket or fast symlink maps nothing.
: _EXT4-NMC-WALK  ( -- ior )
    _EXT4-NMC-CTX @ _EXT4-C.INODE + DUP _EXT4-NMC-IN !
    _EXT4-I.MODE + W@ 0xF000 AND
    DUP 0x8000 = OVER 0x4000 = OR IF
        DROP
    ELSE DUP 0xA000 = IF
        DROP _EXT4-NMC-IN @ _EXT4-NMC-CTX @ _EXT4-DECODE-I-BLOCKS
        ?DUP IF NIP EXIT THEN
        _EXT4-NMC-IN @ _EXT4-I.FILE-ACL-LO + L@ IF
            _EXT4-NMC-CTX @ _EXT4-C.SPB + @ -
        THEN
        0= IF 0 EXIT THEN
    ELSE
        DUP 0x1000 = OVER 0x2000 = OR OVER 0x6000 = OR
        SWAP 0xC000 = OR 0= IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
        _EXT4-NMC-IN @ _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        0 EXIT
    THEN THEN
    _EXT4-NMC-IN @ _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND IF
        _EXT4-NMC-CTX @ _EXT4-VALIDATE-EXTENT-TREE
    ELSE
        _EXT4-NMC-CTX @ _EXT4-VALIDATE-LEGACY-MAP
    THEN ;

\ Load the named inode as media holds it into C.INODE, from the named home.
: _EXT4-NMC-MEDIA-RECORD  ( -- ior )
    _EXT4-NMC-INO @ _EXT4-NMC-CTX @ _EXT4-LOAD-ORPHAN-INODE ?DUP IF EXIT THEN
    _EXT4-IR-BLOCK @ _EXT4-NMC-HOME @ <>
    _EXT4-IR-OFF @ _EXT4-NMC-OFF @ <> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ The record the transaction stages at the named home and offset, or zero
\ when it leaves the home alone.
: _EXT4-NMC-STAGED  ( -- record ior )
    _EXT4-NMC-HOME @ _EXT4-NMC-TX @ _EXT4-JTX-META-IMAGE ?DUP IF EXIT THEN
    DUP IF _EXT4-NMC-OFF @ + THEN 0 ;

\ Whether RECORD maps what C.INODE does: the same file type, block count,
\ flags, xattr block and map.  The eight bytes from i_blocks_lo hold the
\ low block count and the flags, and the four from i_blocks_high the high
\ block count and the high xattr block.
: _EXT4-NMC-SAME-MAP?  ( record -- flag )
    _EXT4-NMC-CTX @ _EXT4-C.INODE + _EXT4-NMC-IN !
    DUP _EXT4-I.MODE + W@ _EXT4-NMC-IN @ _EXT4-I.MODE + W@ XOR
    0xF000 AND IF DROP FALSE EXIT THEN
    DUP _EXT4-I.BLOCKS-LO + _EXT4-NMC-IN @ _EXT4-I.BLOCKS-LO + 8
    _EXT4-BYTES=? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-I.FILE-ACL-LO + L@ _EXT4-NMC-IN @ _EXT4-I.FILE-ACL-LO + L@
    <> IF DROP FALSE EXIT THEN
    DUP _EXT4-I.BLOCKS-HI + _EXT4-NMC-IN @ _EXT4-I.BLOCKS-HI + 4
    _EXT4-BYTES=? 0= IF DROP FALSE EXIT THEN
    _EXT4-I.BLOCK + _EXT4-NMC-IN @ _EXT4-I.BLOCK + 60 _EXT4-BYTES=? ;

\ Whether the transaction changes the map of the kept record whose media
\ image C.INODE holds.  No transaction moves a kept inode's xattr block.
: _EXT4-NMC-CHANGED?  ( -- flag ior )
    _EXT4-NMC-STAGED ?DUP IF EXIT THEN
    DUP 0= IF 0 EXIT THEN
    DUP _EXT4-NMC-SAME-MAP? IF DROP FALSE 0 EXIT THEN
    DUP _EXT4-I.FILE-ACL-LO + L@
    _EXT4-NMC-CTX @ _EXT4-C.INODE + _EXT4-I.FILE-ACL-LO + L@ <>
    SWAP _EXT4-I.FILE-ACL-HI + W@
    _EXT4-NMC-CTX @ _EXT4-C.INODE + _EXT4-I.FILE-ACL-HI + W@ <> OR IF
        FALSE EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    TRUE 0 ;

\ Release the map of the record in C.INODE, the named inode as the
\ transaction stages it, reading its tree nodes through the transaction.
: _EXT4-NMC-RELEASE-CURRENT  ( -- ior )
    _EXT4-NMC-INO @ _EXT4-IR-INO !
    -1 _EXT4-OWN-MODE !
    ['] _EXT4-NMC-NODE-IMAGE _EXT4-EV-IMAGE-XT !
    _EXT4-NMC-WALK
    0 _EXT4-EV-IMAGE-XT ! 0 _EXT4-OWN-MODE ! ;

\ Release the map inode INO has once the transaction lands: the record it
\ stages at HOME and OFFSET, or the one on media when it leaves that home
\ alone.
: _EXT4-NMC-RELEASE  ( ino home offset -- ior )
    _EXT4-NMC-OFF ! _EXT4-NMC-HOME ! _EXT4-NMC-INO !
    _EXT4-NMC-STAGED ?DUP IF NIP EXIT THEN
    ?DUP IF
        _EXT4-NMC-CTX @ _EXT4-C.INODE + _EXT4-NMC-CTX @ _EXT4-C.ISIZE + @ MOVE
    ELSE
        _EXT4-NMC-MEDIA-RECORD ?DUP IF EXIT THEN
    THEN
    _EXT4-NMC-RELEASE-CURRENT ;

\ Before the bitmap changes: claim the map inode INO holds on media, which
\ a freed inode gives up and a kept one gives up when the transaction
\ changes its map.
: _EXT4-NMC-OLD  ( ino home offset kind -- )
    _EXT4-NMC-KIND ! _EXT4-NMC-OFF ! _EXT4-NMC-HOME ! _EXT4-NMC-INO !
    _EXT4-NMC-IOR @ IF EXIT THEN
    _EXT4-NMC-KIND @ _EXT4-NMC-CREATED = IF EXIT THEN
    _EXT4-NMC-MEDIA-RECORD ?DUP IF _EXT4-NMC-IOR ! EXIT THEN
    _EXT4-NMC-KIND @ _EXT4-NMC-RETAINED = IF
        _EXT4-NMC-CHANGED? ?DUP IF _EXT4-NMC-IOR ! DROP EXIT THEN
        0= IF EXIT THEN
    THEN
    1 _EXT4-OWN-MODE ! _EXT4-NMC-WALK _EXT4-NMC-IOR !
    0 _EXT4-OWN-MODE ! ;

\ After the bitmap changes: release the map inode INO has as the
\ transaction stages it, which a created inode takes and a kept one takes
\ when the transaction changes its map.  A created inode has no xattr
\ block.
: _EXT4-NMC-NEW  ( ino home offset kind -- )
    _EXT4-NMC-KIND ! _EXT4-NMC-OFF ! _EXT4-NMC-HOME ! _EXT4-NMC-INO !
    _EXT4-NMC-IOR @ IF EXIT THEN
    _EXT4-NMC-KIND @ _EXT4-NMC-FREED = IF EXIT THEN
    _EXT4-NMC-KIND @ _EXT4-NMC-RETAINED = IF
        _EXT4-NMC-MEDIA-RECORD ?DUP IF _EXT4-NMC-IOR ! EXIT THEN
        _EXT4-NMC-CHANGED? ?DUP IF _EXT4-NMC-IOR ! DROP EXIT THEN
        0= IF EXIT THEN
    THEN
    _EXT4-NMC-STAGED ?DUP IF _EXT4-NMC-IOR ! DROP EXIT THEN
    ?DUP 0= IF EXT4-D-DATA-MAP _EXT4-CORRUPT _EXT4-NMC-IOR ! EXIT THEN
    _EXT4-NMC-CTX @ _EXT4-C.INODE + _EXT4-NMC-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-NMC-KIND @ _EXT4-NMC-CREATED = IF
        _EXT4-NMC-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FILE-ACL-LO + L@
        SWAP _EXT4-I.FILE-ACL-HI + W@ OR IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT _EXT4-NMC-IOR ! EXIT
        THEN
    THEN
    _EXT4-NMC-RELEASE-CURRENT _EXT4-NMC-IOR ! ;

\ Open a family's check of TRANSACTION on CTX.
: _EXT4-NMC-BEGIN  ( ctx transaction -- ior )
    0 _EXT4-NMC-IOR ! _EXT4-NMC-OPEN ;

\ Apply the transaction's block-bitmap changes, between the two phases.
: _EXT4-NMC-BITMAPS  ( -- )
    _EXT4-NMC-IOR @ IF EXIT THEN
    _EXT4-NMC-DELTAS _EXT4-NMC-IOR ! ;

\ Claim BLOCK, which the family frees outside any inode's map.
: _EXT4-NMC-CLAIM-BLOCK  ( block -- )
    _EXT4-NMC-IOR @ IF DROP EXIT THEN
    1 TRUE _EXT4-OWN-SPAN _EXT4-NMC-IOR ! ;

\ End a family's check with its first refusal, if any.
: _EXT4-NMC-END  ( -- ior )
    _EXT4-NMC-IOR @ _EXT4-NMC-CLOSE ;

VARIABLE _EXT4-RPH-CTX
VARIABLE _EXT4-RPH-MAP-LIMIT
VARIABLE _EXT4-RPH-IOR

\ Certify every activation/emission/reset home before a clean journal becomes
\ writable.  Inode 8 is the sole excluded record: journal authentication has
\ already required its checksum-covered, self-contained exact extent tuple,
\ disjoint primary-super role, and zero external-xattr pointer.  Every other
\ allocated inode is checked through the ordinary complete map/xattr parser
\ while the protocol-home predicate is published.  The certificate lives in
\ this mounted context and is invalidated by the next mount-state reset.
: _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS-IMPL  ( ctx -- ior )
    DUP _EXT4-RPH-CTX ! 0= IF VFS-E-INVALID EXIT THEN
    0 _EXT4-RPH-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + !
    _EXT4-MUTATION-MAP-TARGET @
    _EXT4-MUTATION-MAP-ACTIVE @ OR
    _EXT4-MUTATION-MAP-HITS @ OR
    _EXT4-MUTATION-PROTOCOL-CTX @ OR
    _EXT4-MUTATION-PROTOCOL-ACTIVE @ OR
    _EXT4-OWN-MAP @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-RPH-CTX @ _EXT4-JFO-CTX !
    _EXT4-JOURNAL-INODE _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-RPH-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-RPH-CTX @ _EXT4-MUTATION-PROTOCOL-CTX !
    -1 _EXT4-MUTATION-PROTOCOL-ACTIVE !
    _EXT4-JFO-SCAN-INODES _EXT4-RPH-IOR !
    0 _EXT4-MUTATION-PROTOCOL-ACTIVE !
    0 _EXT4-MUTATION-PROTOCOL-CTX !
    _EXT4-RPH-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-RPH-IOR @ 0= IF
        -1 _EXT4-RPH-CTX @ _EXT4-C.J.PROTOCOL-OWNERS + !
    THEN
    _EXT4-RPH-IOR @ ;

' _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS-IMPL
_EXT4-MUTATION-PROTOCOL-PROOF-XT !

: _EXT4-JFI-XATTR-PREFLIGHT  ( -- ior )
    \ Inline values die with the inode allocation bit.  Authenticate an
    \ external block through the ordinary read-side walker, then classify its
    \ exact disposition: refcount one releases the allocation; a larger valid
    \ refcount retains the block and stages a checksum-covered decrement.
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-RANGE-COUNT 0 ?DO
            _EXT4-JFI-EA @ 1 I _EXT4-JFI-RANGE
            DUP @ SWAP CELL+ @ _EXT4-BLOCK-RANGES-ALIAS-OR-INVALID? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        LOOP
    THEN
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    _EXT4-JFI-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF EXIT THEN
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-CTX @ _EXT4-C.BLOCK + 4 + L@
        DUP _EXT4-JFI-EA-REFCOUNT !
        DUP 0= OVER _EXT4-XATTR-REFCOUNT-MAX U> OR IF
            DROP EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        1 = IF
            _EXT4-JEA-RELEASE
        ELSE
            _EXT4-JEA-REFDEC
        THEN _EXT4-JFI-EA-ACTION !
        _EXT4-JFI-EA-REFCOUNT @
        _EXT4-JFI-CTX @ _EXT4-C.INODES + @ U> IF
            EXT4-D-XATTR _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFI-EA @ 1 _EXT4-JFI-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JFI-DATA-CLEAR  ( -- )
    0 _EXT4-JFI-DATA-ENTRIES !
    0 _EXT4-JFI-DATA-BLOCKS !
    _EXT4-JDM-NONE _EXT4-JFI-DATA-MAP-KIND ! ;

: _EXT4-JFI-DATA-RESET  ( -- )
    _EXT4-JFI-DATA-CLEAR
    _EXT4-JFI-RANGES
    _EXT4-JFI-RANGE-CAP 2* CELLS 0 FILL ;

\ The inode's block count holds the vector's blocks and its xattr block.
: _EXT4-JFI-REQUIRE-ACCOUNTED  ( -- ior )
    _EXT4-JFI-INODE @ _EXT4-JFI-CTX @ _EXT4-DECODE-I-BLOCKS
    DUP IF NIP EXIT THEN DROP
    _EXT4-JFI-ACCOUNTED-BLOCKS _EXT4-JFI-CTX @ _EXT4-C.SPB + @ * <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Take the released runs as the vector, which must hold exactly the blocks
\ the release freed.  Each earlier pass took its own runs off the inode's
\ block count, which now holds this pass's runs and the xattr block.
: _EXT4-JFI-DATA-RELEASED  ( -- ior )
    _EXT4-JFI-DATA-CLEAR
    _EXT4-JFI-RELEASED-RUNS @ DUP 0= OVER _EXT4-JFI-RANGE-CAP U> OR IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFI-DATA-ENTRIES !
    0 _EXT4-JFI-DATA-ENTRIES @ 0 ?DO I _EXT4-JFI-RANGE CELL+ @ + LOOP
    DUP _EXT4-JFI-RELEASED-BLOCKS @ <> IF DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-DATA-BLOCKS !
    _EXT4-JDM-RELEASED _EXT4-JFI-DATA-MAP-KIND !
    _EXT4-JFI-REQUIRE-ACCOUNTED ;

\ True when the deletion's map maps blocks.  Release passes free them
\ before the inode is deleted, so the authority of the unlink that inserts
\ its record holds no release vector for them.  The deletion itself comes
\ only once the map is empty.
: _EXT4-JFI-PASSES?  ( -- flag )
    _EXT4-JFI-INODE @ _EXT4-MAP-MAPS? ;

\ A deletion of an empty map frees no data, and the inode's block count
\ holds at most its xattr block.
: _EXT4-JFI-DATA-PREFLIGHT  ( -- ior )
    _EXT4-JFI-DATA-RESET _EXT4-JFI-REQUIRE-ACCOUNTED ;

VARIABLE _EXT4-JFI-CP-WRITER

: _EXT4-JFI-EA-POST-REFCOUNT  ( -- count )
    _EXT4-JFI-EA-REFDEC? IF _EXT4-JFI-EA-REFCOUNT @ 1- ELSE 0 THEN ;

: _EXT4-JFI-CP-RANGES-MATCH?  ( writer -- flag )
    DUP _EXT4-JFI-CP-WRITER !
    _EXT4-JWR.CP-DELETE-RANGE-CAP + @
    _EXT4-JFI-RANGE-COUNT U< IF
        FALSE EXIT
    THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @
    _EXT4-JFI-RANGE-COUNT <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DELETE-BLOCKS + @
    _EXT4-JFI-RANGE-BLOCKS <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @
    _EXT4-JFI-DATA-MAP-KIND @ <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JFI-EA @ <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-ACTION + @
    _EXT4-JFI-EA-ACTION @ <> IF FALSE EXIT THEN
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @
    _EXT4-JFI-EA-POST-REFCOUNT <> IF FALSE EXIT THEN
    _EXT4-JFI-EA-AFTER-VERIFIED @ IF
        _EXT4-JFI-EA-AFTER-CRC @
        _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-CRC + @ <> IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JFI-RANGE-COUNT 0 ?DO
        I _EXT4-JFI-RANGE @
        I _EXT4-JFI-CP-WRITER @ _EXT4-JWR-CP-DELETE-RANGE @ <> IF
            FALSE UNLOOP EXIT
        THEN
        I _EXT4-JFI-RANGE CELL+ @
        I _EXT4-JFI-CP-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE CELL+ @ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFI-STORE-CP-RANGES  ( writer -- )
    DUP _EXT4-JFI-CP-WRITER !
    _EXT4-JFI-RANGE-COUNT
    OVER _EXT4-JWR.CP-DELETE-RANGE-COUNT + !
    _EXT4-JFI-RANGE-BLOCKS
    SWAP _EXT4-JWR.CP-DELETE-BLOCKS + !
    _EXT4-JFI-EA @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-HOME + !
    _EXT4-JFI-EA-ACTION @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-ACTION + !
    _EXT4-JFI-EA-POST-REFCOUNT
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + !
    _EXT4-JFI-EA-AFTER-CRC @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-EA-CRC + !
    _EXT4-JFI-DATA-MAP-KIND @
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + !
    _EXT4-JFI-CP-WRITER @ _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JFI-RANGE-COUNT 0 ?DO
        I _EXT4-JFI-RANGE @
        I _EXT4-JFI-CP-WRITER @ _EXT4-JWR-CP-DELETE-RANGE !
        I _EXT4-JFI-RANGE CELL+ @
        I _EXT4-JFI-CP-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE CELL+ !
    LOOP ;

: _EXT4-DESC-USED-DIRS@  ( descriptor -- directories )
    DUP _EXT4-GD.USED-DIRS-LO + W@
    SWAP _EXT4-GD.USED-DIRS-HI + W@ 16 LSHIFT OR ;

: _EXT4-DESC-USED-DIRS!  ( directories descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.USED-DIRS-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.USED-DIRS-HI + W! ;

\ Authenticate the deletion of one unlinked regular file or directory.  Its
\ map is empty, or the release pass that freed the rest of it in this
\ transaction hands over the runs it freed, or it still maps blocks, which
\ release passes free before the deletion stages.  Bind the released runs
\ and the explicit external-xattr disposition into the release authority.
\ Structurally valid resident inline xattrs die with the inode allocation
\ bit.  A directory's deletion also lowers its group's used-directory
\ count, as ext4_free_inode does.
: _EXT4-JFI-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JFI-CTX @ 0=
    _EXT4-JFI-RECORD @ 0= _EXT4-JFI-PROSPECTIVE @ 0= AND OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFI-PROSPECTIVE @ 0= IF
        _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ _EXT4-JFI-INO !
    THEN
    _EXT4-JFI-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-MUTATION-RANGE-WORKSPACE-CAPACITY
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-RANGE-EXPECTED !
    _EXT4-JFI-RANGES 0=
    _EXT4-JFI-RANGE-CAP _EXT4-JFI-RANGE-EXPECTED @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JFI-EA !
    _EXT4-JEA-NONE _EXT4-JFI-EA-ACTION !
    0 _EXT4-JFI-EA-REFCOUNT !
    0 _EXT4-JFI-EA-AFTER-CRC !
    0 _EXT4-JFI-EA-AFTER-VERIFIED !
    _EXT4-JFI-EA-RANGE 2 CELLS 0 FILL
    _EXT4-JFI-REAUTH-CURRENT ?DUP IF EXIT THEN
    _EXT4-JFI-INO @
    DUP _EXT4-JFI-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-JFI-CTX @ _EXT4-C.INODE + DUP _EXT4-JFI-INODE !
    DUP _EXT4-I.MODE + W@ 0xF000 AND
    DUP 0x4000 = _EXT4-JFI-DIRECTORY !
    DUP 0x8000 <> SWAP 0x4000 <> AND IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    \ Linux recovery deletes an unlinked inode whatever its i_size, and
    \ release passes free its whole map, so any size is valid here.  The
    \ signed-host overflow shape stays corrupt on every reauthentication.
    DUP _EXT4-I.SIZE-HI + L@ 0x80000000 AND IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-I.FLAGS + L@ _EXT4-JOURNAL-DATA-FL AND IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-LO + L@ DUP _EXT4-JFI-EA ! ?DUP IF
        _EXT4-JFI-EA-RANGE !
        1 _EXT4-JFI-EA-RANGE CELL+ !
    THEN
    DROP
    _EXT4-JFI-RELEASED @ IF
        _EXT4-JFI-DATA-RELEASED ?DUP IF EXIT THEN
    ELSE _EXT4-JFI-PASSES? IF
        _EXT4-JFI-DATA-RESET
    ELSE
        _EXT4-JFI-DATA-PREFLIGHT ?DUP IF EXIT THEN
    THEN THEN
    _EXT4-JFI-XATTR-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-REAUTH-CURRENT ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JFI-GROUP !
    _EXT4-IR-INDEX @ _EXT4-JFI-INDEX !
    _EXT4-IR-BLOCK @ _EXT4-JFI-INODE-HOME !
    _EXT4-IR-OFF @ _EXT4-JFI-INODE-OFF !
    _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE !
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-GROUP-INODE-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-GROUP-INODES !
    _EXT4-JFI-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR ! _EXT4-JFI-BITMAP-HOME !
    _EXT4-JFI-IOR @ ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME !
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF !
    _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-VALIDATE-INODE-BITMAP-HOME ?DUP IF EXIT THEN
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR !
    _EXT4-JFI-IOR @ IF DROP _EXT4-JFI-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME @ <>
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DIRECTORY @ IF
        _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-DESC-USED-DIRS@ 0= IF
            EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @ BITSET-TEST? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JFP-IOR

\ Qualify the exact future deletion while the inode still holds its last
\ link, or a directory its two, and no durable orphan record exists.  The
\ shared JFI core remains inode-oriented; retained-plan identity is
\ required only by the ordinary zero-link wrapper.
: _EXT4-JFI-AUTH-PROSPECTIVE
  ( inode-number expected-generation ctx -- ior )
    _EXT4-JFI-CTX ! _EXT4-JFI-PROSPECTIVE-GEN ! _EXT4-JFI-INO !
    _EXT4-JFI-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    0 _EXT4-JFI-RECORD ! FALSE _EXT4-JFI-RELEASED !
    -1 _EXT4-JFI-PROSPECTIVE !
    _EXT4-JFI-AUTH-PREFLIGHT _EXT4-JFP-IOR !
    0 _EXT4-JFI-PROSPECTIVE !
    _EXT4-JFP-IOR @ ;

: _EXT4-JFI-DESC-BITMAP-CRC@  ( descriptor -- crc )
    DUP _EXT4-GD.INODE-CSUM-LO + W@
    SWAP _EXT4-GD.INODE-CSUM-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFI-DESC-BITMAP-CRC!  ( crc descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.INODE-CSUM-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.INODE-CSUM-HI + W! ;

: _EXT4-JFI-DESC-FREE@  ( descriptor -- inodes )
    DUP _EXT4-GD.FREE-INODES-LO + W@
    SWAP _EXT4-GD.FREE-INODES-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFI-DESC-FREE!  ( inodes descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.FREE-INODES-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.FREE-INODES-HI + W! ;

: _EXT4-JFI-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JFI-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-INODE-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _EXT4-JFI-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-DESC-FREE@ DUP _EXT4-JFI-GROUP-FREE !
    1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFI-NEW-GROUP-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-DESC-USED-DIRS@ DUP _EXT4-JFI-USED-DIRS !
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-GROUP-FREE @ - U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DIRECTORY @ _EXT4-JFI-USED-DIRS @ 0= AND IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-ACQUIRE-DESC  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME @ <>
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-GDT-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-GDT-OFF @ + _EXT4-JFI-DESC !
    _EXT4-JFI-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JFI-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JFI-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFI-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JFI-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JFI-IMAGE !
    _EXT4-JFI-SUPER @ _EXT4-SB.FREE-INODES + L@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-NEW-SUPER-FREE !
    _EXT4-JFI-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-PREFLIGHT  ( -- ior )
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-RELEASED @ 0= IF
        _EXT4-JFI-REVOKE-COUNT
        _EXT4-JFI-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <> IF
            VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-BITMAP-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @ BITSET-TEST? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFI-BITMAP-CRC !
    _EXT4-JFI-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-ACQUIRE-SUPER ;

: _EXT4-JFI-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JFI-IOR !
    _EXT4-JFI-PUBLISHED @ IF
        _EXT4-JFI-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP _EXT4-JFI-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JFI-ABORT-IOR ! IF
                _EXT4-JFI-ABORT-IOR @ _EXT4-JFI-WRITER @
                _EXT4-JWR-LATCH-FAULT DROP
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JFI-IOR @ _EXT4-JFI-WRITER @
                _EXT4-JWR-LATCH-FAULT DROP
            THEN
        THEN
    THEN
    _EXT4-JFI-IOR @ ;

: _EXT4-JFI-STAGE-GROUP  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR !
    _EXT4-JFI-IOR @ IF DROP _EXT4-JFI-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-BITMAP-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    DUP _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP NIP EXIT THEN
    _EXT4-JFI-BITMAP-CRC !
    DUP _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @ BITSET-TEST? 0= IF
        2DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @
    BITSET-BIT-CLEAR? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFI-NEW-BITMAP-CRC !
    _EXT4-JFI-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-GROUP-FREE @ _EXT4-JFI-DESC @ _EXT4-JFI-DESC-FREE!
    _EXT4-JFI-NEW-BITMAP-CRC @ _EXT4-JFI-DESC @
    _EXT4-JFI-DESC-BITMAP-CRC!
    _EXT4-JFI-DIRECTORY @ IF
        _EXT4-JFI-USED-DIRS @ 1- _EXT4-JFI-DESC @ _EXT4-DESC-USED-DIRS!
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-GDT-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

: _EXT4-JFI-STAGE-SUPER  ( -- ior )
    _EXT4-JFI-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-SUPER-FREE @
    _EXT4-JFI-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JFI-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-SUPER-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

: _EXT4-JFI-STAGE-INODE  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JFI-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-INODE-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-INODE-OFF @ + _EXT4-JFI-INODE @
    _EXT4-JFI-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-INODE-OFF @ +
    _EXT4-JFI-CTX @ _EXT4-C.ISIZE + @ 0 FILL
    _EXT4-JFI-IMAGE @ _EXT4-JFI-INODE-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

\ Retain a shared external-xattr allocation and stage only its reference
\ release.  Reloading through the structural/checksum parser makes the
\ preflight refcount a conflict fence; the retained image begins as an exact
\ raw copy, then changes only h_refcount and h_checksum.
: _EXT4-JFI-STAGE-EA-REFDEC  ( -- ior )
    _EXT4-JFI-EA-REFDEC? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-EA @ _EXT4-JFI-CTX @ _EXT4-LOAD-XATTR-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + 4 + L@
    _EXT4-JFI-EA-REFCOUNT @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-EA @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-EA-IMAGE !
    4 + L@ _EXT4-JFI-EA-REFCOUNT @ <> IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JFI-EA-REFCOUNT @ 1- _EXT4-JFI-EA-IMAGE @ 4 + L!
    _EXT4-JFI-EA-IMAGE @ _EXT4-JFI-EA @ _EXT4-JFI-CTX @
    _EXT4-STAMP-XATTR-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFI-EA-IMAGE @ _EXT4-JFI-EA @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    _EXT4-JFI-EA-IMAGE @ _EXT4-JFI-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFI-EA-AFTER-CRC !
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

\ Release allocation authority for one exact unlinked regular-file orphan
\ whose map is empty, or whose release pass in the same transaction freed
\ the rest of it.  First replace its authenticated inode record with zeros
\ so ordinary ext4 tools see a clean free record; then release an optional
\ unique external-xattr block and the inode allocation bit in the same
\ transaction.
: _EXT4-JTX-STAGE-FREE-ORPHAN-INODE
  ( plan-record transaction -- ior )
    _EXT4-JFI-WRITER ! _EXT4-JFI-RECORD !
    0 _EXT4-JFI-PUBLISHED !
    _EXT4-JFI-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFI-CTX !
    _EXT4-JFI-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-STAGE-INODE ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-EA-RELEASE? IF
            _EXT4-JFI-EA @ 1 _EXT4-JFI-WRITER @
            _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
            ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
            -1 _EXT4-JFI-PUBLISHED !
            _EXT4-JFI-EA @ _EXT4-JFI-WRITER @ _EXT4-JTX-REVOKE
            ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
            -1 _EXT4-JFI-PUBLISHED !
        ELSE
            _EXT4-JFI-STAGE-EA-REFDEC
            ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
        THEN
    THEN
    _EXT4-JFI-WRITER @ _EXT4-JFI-REVOKES-EXACT? 0= IF
        VFS-E-CORRUPT _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-STAGE-GROUP ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-STAGE-SUPER ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ =====================================================================
\  Orphan cleanup staging state
\ =====================================================================

\ An inode holds an empty map in the representation its raw image
\ authenticated: a canonical empty inline extent root, or an exact all-zero
\ legacy i_block array.  Comparing the EXTENTS flag across both images
\ prevents a staged representation switch.
: _EXT4-EMPTY-MAP?  ( expected-extents? inode -- flag )
    OVER
    OVER _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<> <> IF
        2DROP FALSE EXIT
    THEN
    OVER IF
        NIP _EXT4-I.BLOCK + DUP
        W@ _EXT4-EXTENT-MAGIC =
        OVER 2 + W@ 0= AND
        OVER 4 + W@ _EXT4-RESIDENT-EXTENT-ENTRY-MAX = AND
        OVER 6 + W@ 0= AND
        SWAP 12 + 48 _EXT4-BYTES-ZERO? AND
    ELSE
        NIP _EXT4-I.BLOCK + 60 _EXT4-BYTES-ZERO?
    THEN ;

VARIABLE _EXT4-JFC-RECORD
VARIABLE _EXT4-JFC-WRITER
VARIABLE _EXT4-JFC-CTX
VARIABLE _EXT4-JFC-INO
VARIABLE _EXT4-JFC-LOGICAL
VARIABLE _EXT4-JFC-SLOT
VARIABLE _EXT4-JFC-TARGET-GEN
VARIABLE _EXT4-JFC-TARGET-HOME
VARIABLE _EXT4-JFC-TARGET-OFF
VARIABLE _EXT4-JFC-TARGET-ENTRIES
VARIABLE _EXT4-JFC-O-HOME
VARIABLE _EXT4-JFC-O-GEN
VARIABLE _EXT4-JFC-INDEX
VARIABLE _EXT4-JFC-FOUND
VARIABLE _EXT4-JFC-IOR
VARIABLE _EXT4-JFC-ENTRY
VARIABLE _EXT4-JFC-IMAGE
VARIABLE _EXT4-JFC-TARGET-CRC
VARIABLE _EXT4-JFC-ORPHAN-CRC
VARIABLE _EXT4-JFC-ABORT-IOR
VARIABLE _EXT4-JFC-KIND
VARIABLE _EXT4-JFC-MODE
VARIABLE _EXT4-JFC-SUPER
VARIABLE _EXT4-JFC-DELETE
VARIABLE _EXT4-JFC-INODE-BITMAP-HOME
VARIABLE _EXT4-JFC-INODE-BITMAP-CRC
VARIABLE _EXT4-JFC-INODE-GDT-HOME
VARIABLE _EXT4-JFC-INODE-GDT-OFF
VARIABLE _EXT4-JFC-INODE-GDT-CRC
VARIABLE _EXT4-JFC-INODE-SUPER-CRC

: _EXT4-JFC-FIND-META  ( home writer -- ior )
    DUP _EXT4-JFC-WRITER ! >R
    R@ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    R@ _EXT4-JWR.META-HASH + @
    R@ _EXT4-JWR.META-SLOTS + @
    R@ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND
    _EXT4-JFC-IOR ! _EXT4-JFC-FOUND ! _EXT4-JFC-INDEX !
    R> DROP
    _EXT4-JFC-IOR @ ?DUP IF EXIT THEN
    0 _EXT4-JFC-ENTRY ! 0 _EXT4-JFC-IMAGE !
    _EXT4-JFC-FOUND @ 0= IF 0 EXIT THEN
    _EXT4-JFC-INDEX @ _EXT4-JFC-WRITER @ _EXT4-JWR-META-ENTRY
    DUP _EXT4-JFC-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-INDEX @ _EXT4-JFC-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JFC-IMAGE ! _EXT4-JFC-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ =====================================================================
\  Modern orphan insertion for a truncate across transactions
\ =====================================================================
\
\ A truncate whose release does not fit one transaction first commits the
\ linked inode's new size and times together with one modern orphan-file
\ slot and the primary ORPHAN_PRESENT bit.  The old map and block count stay
\ intact until release passes free the blocks past the new EOF, and mount
\ recovery runs the same passes when a crash interrupts them.  The union
\ must be empty, so the insertion always publishes ORPHAN_PRESENT.  A
\ dedicated checkpoint certificate proves the empty union and the exact
\ newly recoverable orphan.  The caller proves that no inode, the target
\ included, maps the inode-table home or superblock the insertion writes,
\ and that the target's tree does not map the orphan block.

VARIABLE _EXT4-JTA-WRITER
VARIABLE _EXT4-JTA-CTX
VARIABLE _EXT4-JTA-NEW
VARIABLE _EXT4-JTA-OLD
VARIABLE _EXT4-JTA-INO
VARIABLE _EXT4-JTA-GEN
VARIABLE _EXT4-JTA-SECONDS
VARIABLE _EXT4-JTA-NSEC
VARIABLE _EXT4-JTA-O-LOGICAL
VARIABLE _EXT4-JTA-O-SLOT
VARIABLE _EXT4-JTA-O-HOME
VARIABLE _EXT4-JTA-O-GEN
VARIABLE _EXT4-JTA-O-INO
VARIABLE _EXT4-JTA-O-ENTRIES
VARIABLE _EXT4-JTA-O-FOUND
VARIABLE _EXT4-JTA-O-IMAGE
VARIABLE _EXT4-JTA-TARGET-IMAGE
VARIABLE _EXT4-JTA-SUPER-IMAGE
VARIABLE _EXT4-JTA-RECORD
VARIABLE _EXT4-JTA-IOR
VARIABLE _EXT4-JTA-TARGET-CRC
VARIABLE _EXT4-JTA-ORPHAN-CRC
VARIABLE _EXT4-JTA-SUPER-CRC
VARIABLE _EXT4-JTA-COMPARE-OFF
VARIABLE _EXT4-JTA-V
VARIABLE _EXT4-JTA-MODE
VARIABLE _EXT4-JTA-META
VARIABLE _EXT4-JTA-PRE-ACTIVE
VARIABLE _EXT4-JTA-PRE-MODERN
VARIABLE _EXT4-JTA-PRE-LEGACY
VARIABLE _EXT4-JTA-PRESENT
VARIABLE _EXT4-JTA-RAW-COUNT
VARIABLE _EXT4-JTA-PLAN-COUNT
VARIABLE _EXT4-JTA-SCAN-INO
VARIABLE _EXT4-JTA-SCAN-RECORD
VARIABLE _EXT4-JTA-EA
VARIABLE _EXT4-JTA-ENTRIES
VARIABLE _EXT4-JTA-GROUP
VARIABLE _EXT4-JTA-INODE-HOME
VARIABLE _EXT4-JTA-INODE-OFF
CREATE _EXT4-JTA-EXPECTED-INODE _EXT4-MAX-INODE ALLOT
CREATE _EXT4-JTA-EXPECTED-SUPER _EXT4-MAX-BLOCK ALLOT

\ Classify the exact mounted pre-union without allocating.  The insertion
\ needs an empty modern union, three homes, and room in the retained runtime
\ plan before a journal transaction can become durable.
: _EXT4-MEASURE-MODERN-ORPHAN-ADD  ( ctx vfs -- meta-credit ior )
    _EXT4-JTA-V ! _EXT4-JTA-CTX !
    _EXT4-JTA-CTX @ 0= _EXT4-JTA-V @ 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JTA-V @ _EXT4-CTX _EXT4-JTA-CTX @ <> IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-JTA-V @
    _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.O.ACTIVE + @ DUP
    _EXT4-JTA-PRE-ACTIVE ! 0< IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ DUP
    _EXT4-JTA-PRE-MODERN ! 0< IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ DUP
    _EXT4-JTA-PRE-LEGACY ! 0< IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-PRE-MODERN @ _EXT4-JTA-PRE-LEGACY @ _EXT4-UADD?
    DUP IF 2DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN DROP
    _EXT4-JTA-PRE-ACTIVE @ <> IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.O.CLEAR-PENDING + @ IF
        0 EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-ORPHAN-PRESENT AND 0<> _EXT4-JTA-PRESENT !
    _EXT4-JTA-PRE-LEGACY @
    _EXT4-JTA-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ OR IF
        0 EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JTA-PRE-ACTIVE @ IF 0 VFS-E-BUSY EXIT THEN
    _EXT4-JTA-PRE-MODERN @ _EXT4-JTA-PRESENT @ OR IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ 0= IF
        0 VFS-E-NOSPC EXIT
    THEN
    3 0 ;

: _EXT4-JTA-CLASSIFY-PRESTATE  ( -- ior )
    _EXT4-JTA-CTX @ _EXT4-IO-VFS @
    _EXT4-MEASURE-MODERN-ORPHAN-ADD
    DUP IF NIP EXIT THEN DROP _EXT4-JTA-META !
    _EXT4-JCPM-ORPHAN-MODERN-ADD-FIRST _EXT4-JTA-MODE !
    0 ;

: _EXT4-JTA-REQUIRE-FRESH-EXACT  ( -- ior )
    _EXT4-JTA-CLASSIFY-PRESTATE ?DUP IF EXIT THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JTA-META @ <>
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-CREDIT + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JTA-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Authenticate the linked regular target directly: a pure extent inode whose
\ complete tree validates at any depth, with the expected generation, the
\ sealed old size and a valid external xattr block when it has one.  The new
\ size is smaller, so the truncate releases at least the old EOF's block
\ range past the new EOF.
: _EXT4-JTA-LOAD-TARGET  ( -- ior )
    _EXT4-JTA-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTA-INO @
    _EXT4-JTA-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-INO @ 8 =
    _EXT4-JTA-INO @ _EXT4-JTA-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JTA-GEN @ 0xFFFFFFFF U> IF VFS-E-INVALID EXIT THEN
    _EXT4-JTA-INO @ _EXT4-JTA-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JTA-IOR ! VFS-T-FILE <> IF
        _EXT4-JTA-IOR @ ?DUP IF EXIT THEN
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JTA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.INODE +
    DUP _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL <> IF
        DROP EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.GENERATION + L@ _EXT4-JTA-GEN @ <> IF
        DROP VFS-E-STALE EXIT
    THEN
    DUP _EXT4-I.LINKS + W@ 0= IF DROP VFS-E-STALE EXIT THEN
    DUP _EXT4-I.FILE-ACL-HI + W@ IF DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-I.FILE-ACL-LO + L@ _EXT4-JTA-EA !
    _EXT4-I.BLOCK + 2 + W@ _EXT4-JTA-ENTRIES !
    _EXT4-JTA-CTX @ _EXT4-C.R.SIZE + @ _EXT4-JTA-OLD @ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-JTA-NEW @ _EXT4-JTA-OLD @ U< 0= IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-IR-GROUP @ _EXT4-JTA-GROUP !
    _EXT4-IR-BLOCK @ _EXT4-JTA-INODE-HOME !
    _EXT4-IR-OFF @ _EXT4-JTA-INODE-OFF !
    _EXT4-JTA-EA @ IF
        _EXT4-JTA-EA @ 1 _EXT4-JTA-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
        _EXT4-JTA-EA @ EXT4-D-XATTR _EXT4-JTA-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
        _EXT4-JTA-EA @ _EXT4-JTA-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
        _EXT4-JTA-INO @ _EXT4-JTA-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    THEN
    _EXT4-JTA-INODE-HOME @ _EXT4-JTA-GROUP @ _EXT4-JTA-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ;

\ Choose the first empty slot in orphan-file order, after proving that the
\ raw slots and the retained plan agree and that the target is not already
\ an orphan.
: _EXT4-JTA-FIND-EMPTY-SLOT  ( -- ior )
    _EXT4-JTA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.BSIZE + @ 8 - 4 /
    _EXT4-JTA-O-ENTRIES !
    0 _EXT4-JTA-O-FOUND ! 0 _EXT4-JTA-RAW-COUNT !
    0 _EXT4-JTA-PLAN-COUNT !
    _EXT4-JTA-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JTA-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-JTA-SCAN-RECORD ! @ DUP _EXT4-JTA-SCAN-INO ! IF
            1 _EXT4-JTA-PLAN-COUNT +!
            _EXT4-JTA-SCAN-RECORD @ _EXT4-JTA-CTX @
            _EXT4-ORPHAN-RECORD? 0= IF
                EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-JTA-SCAN-RECORD @ _EXT4-OE.KIND + @
            _EXT4-OK-MODERN <> IF
                EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-JTA-SCAN-INO @ _EXT4-JTA-INO @ = IF
                VFS-E-CONFLICT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-JTA-PLAN-COUNT @ _EXT4-JTA-PRE-ACTIVE @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-JTA-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-JTA-O-ENTRIES @ 0 ?DO
            _EXT4-JTA-CTX @ _EXT4-C.BLOCK + I 4 * + L@
            DUP _EXT4-JTA-SCAN-INO ! IF
                1 _EXT4-JTA-RAW-COUNT +!
                _EXT4-JTA-SCAN-INO @ _EXT4-JTA-INO @ = IF
                    VFS-E-CONFLICT UNLOOP UNLOOP EXIT
                THEN
                _EXT4-JTA-SCAN-INO @ _EXT4-JTA-CTX @
                _EXT4-ORPHAN-PLAN-FIND
                _EXT4-JTA-IOR ! _EXT4-JTA-SCAN-RECORD !
                _EXT4-JTA-IOR @ ?DUP IF UNLOOP UNLOOP EXIT THEN
                _EXT4-JTA-SCAN-RECORD @ 0= IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                    UNLOOP UNLOOP EXIT
                THEN
                _EXT4-JTA-SCAN-RECORD @ _EXT4-OE.KIND + @
                _EXT4-OK-MODERN <>
                _EXT4-JTA-SCAN-RECORD @ _EXT4-OE.LOCATOR-A + @ J <>
                OR
                _EXT4-JTA-SCAN-RECORD @ _EXT4-OE.LOCATOR-B + @ I <>
                OR IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                    UNLOOP UNLOOP EXIT
                THEN
            ELSE
                _EXT4-JTA-O-FOUND @ 0= IF
                    -1 _EXT4-JTA-O-FOUND !
                    J _EXT4-JTA-O-LOGICAL ! I _EXT4-JTA-O-SLOT !
                    _EXT4-OV-PHYS @ _EXT4-JTA-O-HOME !
                    _EXT4-OV-GEN @ _EXT4-JTA-O-GEN !
                    _EXT4-OV-INO @ _EXT4-JTA-O-INO !
                THEN
            THEN
        LOOP
    LOOP
    _EXT4-JTA-RAW-COUNT @ _EXT4-JTA-PRE-ACTIVE @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-O-FOUND @ 0= IF VFS-E-NOSPC EXIT THEN
    _EXT4-JTA-O-HOME @ 1 _EXT4-JTA-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JTA-O-HOME @ _EXT4-JTA-INODE-HOME @ =
    _EXT4-JTA-O-HOME @ _EXT4-JTA-CTX @
    _EXT4-PRIMARY-SUPER-BLOCK = OR
    _EXT4-JTA-EA @ IF
        _EXT4-JTA-O-HOME @ _EXT4-JTA-EA @ = OR
    THEN IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JTA-O-LOGICAL @ _EXT4-JTA-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JTA-O-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JTA-O-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JTA-O-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JTA-O-SLOT @ 4 * + L@ IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-LOAD-TARGET ;

: _EXT4-JTA-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JTA-LOAD-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-FIND-EMPTY-SLOT ;

\ The target's after-image: the new size and the sealed times, its map and
\ block count unchanged.
: _EXT4-JTA-SET-TARGET  ( record -- ior )
    DUP _EXT4-JTA-RECORD !
    _EXT4-JTA-NEW @ 0xFFFFFFFF AND OVER _EXT4-I.SIZE-LO + L!
    _EXT4-JTA-NEW @ 32 RSHIFT SWAP _EXT4-I.SIZE-HI + L!
    _EXT4-JTA-SECONDS @ _EXT4-JTA-NSEC @ _EXT4-JTA-RECORD @
    _EXT4-JTA-CTX @ _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _EXT4-JTA-RECORD @ _EXT4-JTA-INO @ _EXT4-JTA-CTX @
    _EXT4-RESTAMP-INODE ;

: _EXT4-JTA-STAGE-TARGET  ( -- ior )
    _EXT4-JTA-LOAD-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-INODE-HOME @ _EXT4-JTA-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-INODE-HOME @
    _EXT4-JTA-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JTA-TARGET-IMAGE !
    _EXT4-JTA-INODE-OFF @ +
    DUP _EXT4-JTA-CTX @ _EXT4-C.INODE +
    _EXT4-JTA-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JTA-SET-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-TARGET-IMAGE @ _EXT4-JTA-INODE-HOME @
    _EXT4-JTA-WRITER @ _EXT4-JTX-META-REPLACE ;

: _EXT4-JTA-STAGE-ORPHAN  ( -- ior )
    _EXT4-JTA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JTA-O-LOGICAL @ _EXT4-JTA-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JTA-O-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JTA-O-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JTA-O-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-O-HOME @
    _EXT4-JTA-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JTA-O-IMAGE !
    DUP _EXT4-JTA-O-SLOT @ 4 * + L@ IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DROP
    _EXT4-JTA-INO @
    _EXT4-JTA-O-IMAGE @ _EXT4-JTA-O-SLOT @ 4 * + L!
    _EXT4-JTA-O-IMAGE @ _EXT4-JTA-O-HOME @ _EXT4-JTA-O-INO @
    _EXT4-JTA-O-GEN @ _EXT4-JTA-CTX @ _EXT4-RESTAMP-ORPHAN-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JTA-O-IMAGE @ _EXT4-JTA-O-HOME @ _EXT4-JTA-WRITER @
    _EXT4-JTX-META-REPLACE ;

: _EXT4-JTA-STAGE-SUPER  ( -- ior )
    _EXT4-JTA-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JTA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.RO-COMPAT + DUP L@
    _EXT4-RO-ORPHAN-PRESENT AND IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DUP L@ _EXT4-RO-ORPHAN-PRESENT OR SWAP L!
    _EXT4-JPS-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JPS-IMAGE @ DUP _EXT4-JTA-SUPER-IMAGE !
    _EXT4-JPS-HOME @ _EXT4-JTA-WRITER @ _EXT4-JTX-META-REPLACE ;

: _EXT4-JTA-CAPTURE-META-CRC  ( home -- crc ior )
    _EXT4-JTA-WRITER @ _EXT4-JFC-FIND-META ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ 0 ;

: _EXT4-JTA-SEAL  ( -- ior )
    _EXT4-JTA-LOAD-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-USED + @ _EXT4-JTA-META @ <>
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JTA-META @ <> OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-INODE-HOME @ _EXT4-JTA-CAPTURE-META-CRC
    _EXT4-JTA-IOR ! _EXT4-JTA-TARGET-CRC !
    _EXT4-JTA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JTA-O-HOME @ _EXT4-JTA-CAPTURE-META-CRC
    _EXT4-JTA-IOR ! _EXT4-JTA-ORPHAN-CRC !
    _EXT4-JTA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JTA-CAPTURE-META-CRC
    _EXT4-JTA-IOR ! _EXT4-JTA-SUPER-CRC !
    _EXT4-JTA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JTA-WRITER @ _EXT4-JWR.EPOCH + @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-EPOCH + !
    _EXT4-JTA-INO @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-INO + !
    _EXT4-JTA-O-LOGICAL @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + !
    _EXT4-JTA-O-SLOT @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-SLOT + !
    _EXT4-JTA-O-HOME @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-HOME + !
    _EXT4-JTA-O-GEN @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-GEN + !
    _EXT4-JTA-GEN @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + !
    _EXT4-JTA-INODE-HOME @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + !
    _EXT4-JTA-INODE-OFF @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + !
    _EXT4-JTA-TARGET-CRC @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + !
    _EXT4-JTA-ORPHAN-CRC @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + !
    _EXT4-JTA-ENTRIES @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + !
    _EXT4-JTA-SECONDS @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-SECONDS + !
    _EXT4-JTA-NSEC @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-NSEC + !
    _EXT4-JTA-SUPER-CRC @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-SUPER-CRC + !
    _EXT4-JTA-PRE-ACTIVE @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + !
    _EXT4-JTA-PRE-MODERN @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-PRE-MODERN + !
    _EXT4-JTA-PRE-LEGACY @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + !
    _EXT4-JTA-NEW @ 0xFFFFFFFF AND
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-LO + !
    _EXT4-JTA-NEW @ 32 RSHIFT
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-HI + !
    _EXT4-JTA-MODE @ _EXT4-JTA-WRITER @ _EXT4-JWR.CP-MODE + !
    _EXT4-JTA-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF
        _EXT4-JTA-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Stage the insertion that publishes a linked target's smaller size NEW in
\ place of OLD, behind its orphan record.
: _EXT4-JTX-STAGE-MODERN-ORPHAN-TRUNCATE
  ( new-size old-size inode-number expected-generation seconds nsec
    transaction -- ior )
    _EXT4-JTA-WRITER ! _EXT4-JTA-NSEC ! _EXT4-JTA-SECONDS !
    _EXT4-JTA-GEN ! _EXT4-JTA-INO ! _EXT4-JTA-OLD ! _EXT4-JTA-NEW !
    _EXT4-JTA-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JTA-CTX !
    _EXT4-JTA-REQUIRE-FRESH-EXACT ?DUP IF EXIT THEN
    _EXT4-JTA-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JTA-STAGE-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-STAGE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JTA-STAGE-SUPER ?DUP IF EXIT THEN
    _EXT4-JTA-SEAL ;

\ Rebuild every typed after-image from current pre-checkpoint media.  The
\ certificate freezes locators, the new size and the timestamps; full-block
\ comparisons prove that no unrelated inode, orphan-file or superblock byte
\ acquired authority.
: _EXT4-JTA-REQUIRE-SEALED-PRESTATE  ( writer -- ior )
    DUP _EXT4-JTA-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JTA-CTX !
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-ADD? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-INO + @ _EXT4-JTA-INO !
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ _EXT4-JTA-GEN !
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-SECONDS + @
    _EXT4-JTA-SECONDS !
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-NSEC + @ _EXT4-JTA-NSEC !
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-HI + @ 32 LSHIFT
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-LO + @ OR
    _EXT4-JTA-NEW !
    _EXT4-JTA-INO @ _EXT4-JTA-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JTA-IOR ! DROP
    _EXT4-JTA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.R.SIZE + @ _EXT4-JTA-OLD !
    _EXT4-JTA-CLASSIFY-PRESTATE ?DUP IF EXIT THEN
    _EXT4-JTA-MODE @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-MODE + @ <>
    _EXT4-JTA-META @
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-CREDIT + @ <> OR
    _EXT4-JTA-PRE-ACTIVE @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ <> OR
    _EXT4-JTA-PRE-MODERN @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ <> OR
    _EXT4-JTA-PRE-LEGACY @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JTA-O-LOGICAL @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <>
    _EXT4-JTA-O-SLOT @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> OR
    _EXT4-JTA-O-HOME @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> OR
    _EXT4-JTA-O-GEN @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> OR
    _EXT4-JTA-INODE-HOME @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <> OR
    _EXT4-JTA-INODE-OFF @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ <> OR
    _EXT4-JTA-ENTRIES @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JTA-STAGED?  ( writer -- ior )
    _EXT4-JTA-REQUIRE-SEALED-PRESTATE ?DUP IF EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JTA-O-LOGICAL @ _EXT4-JTA-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JTA-O-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JTA-O-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JTA-O-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JTA-O-SLOT @ 4 * + L@ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JTA-O-HOME @ _EXT4-JTA-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ DUP _EXT4-JTA-O-IMAGE !
    _EXT4-JTA-O-SLOT @ 4 * + L@ _EXT4-JTA-INO @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-O-IMAGE @
    _EXT4-JTA-O-SLOT @ 4 * _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-O-SLOT @ 4 * 4 + _EXT4-JTA-COMPARE-OFF !
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-COMPARE-OFF @ +
    _EXT4-JTA-O-IMAGE @ _EXT4-JTA-COMPARE-OFF @ +
    _EXT4-JTA-CTX @ _EXT4-C.BSIZE + @ 4 -
    _EXT4-JTA-COMPARE-OFF @ -
    _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JTA-O-IMAGE @ _EXT4-JTA-O-HOME @ _EXT4-JTA-O-INO @
    _EXT4-JTA-O-GEN @ _EXT4-JTA-CTX @
    _EXT4-ORPHAN-BLOCK-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-LOAD-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-INODE-HOME @ _EXT4-JTA-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JTA-INODE-HOME @ _EXT4-JTA-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JTA-TARGET-IMAGE !
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-TARGET-IMAGE @
    _EXT4-JTA-INODE-OFF @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-INODE-OFF @ _EXT4-JTA-CTX @ _EXT4-C.ISIZE + @ +
    _EXT4-JTA-COMPARE-OFF !
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-COMPARE-OFF @ +
    _EXT4-JTA-TARGET-IMAGE @ _EXT4-JTA-COMPARE-OFF @ +
    _EXT4-JTA-CTX @ _EXT4-C.BSIZE + @ _EXT4-JTA-COMPARE-OFF @ -
    _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.INODE + _EXT4-JTA-EXPECTED-INODE
    _EXT4-JTA-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JTA-EXPECTED-INODE _EXT4-JTA-SET-TARGET ?DUP IF EXIT THEN
    _EXT4-JTA-EXPECTED-INODE
    _EXT4-JTA-TARGET-IMAGE @ _EXT4-JTA-INODE-OFF @ +
    _EXT4-JTA-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP
    _EXT4-JTA-CTX @ _EXT4-READ-BLOCK ?DUP IF NIP EXIT THEN
    _EXT4-JTA-CTX @ _EXT4-C.BLOCK + _EXT4-JTA-EXPECTED-SUPER
    _EXT4-JTA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JTA-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JTA-WRITER @ _EXT4-JWR.CP-ADD-SUPER-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JTA-SUPER-IMAGE !
    _EXT4-JTA-EXPECTED-SUPER _EXT4-JTA-CTX @
    _EXT4-PRIMARY-SUPER-OFF + _EXT4-SB.RO-COMPAT + DUP L@
    _EXT4-RO-ORPHAN-PRESENT AND IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP L@ _EXT4-RO-ORPHAN-PRESENT OR SWAP L!
    _EXT4-JTA-EXPECTED-SUPER _EXT4-JTA-CTX @
    _EXT4-PRIMARY-SUPER-OFF + _EXT4-STAMP-SUPER-CHECKSUM
    ?DUP IF EXIT THEN
    _EXT4-JTA-EXPECTED-SUPER _EXT4-JTA-SUPER-IMAGE @
    _EXT4-JTA-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-USED + @ _EXT4-JTA-META @ <>
    _EXT4-JTA-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JTA-META @ <> OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR
    _EXT4-JTA-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ =====================================================================
\  Modern orphan insertion for final-link unlink
\ =====================================================================
\
\ Unlike linked truncate ADD, this authority is derived from JFI's complete
\ inode-oriented future-deletion proof.  The initial lifetime slice admits an
\ authenticated empty union only, so the published orphan is the sole zero-
\ link record and ADD always owns ORPHAN_PRESENT.

\ A caller constructing a depth-zero or depth-one HTree root supplies the root
\ image and its authenticated logical-block count.  Validate the same root
\ geometry and entry array consumed by read traversal before replacing only
\ the checksum field.  The checksum is committed after every CRC operation
\ succeeds, so a capability failure does not partially restamp the image.
VARIABLE _EXT4-RDX-BLOCK
VARIABLE _EXT4-RDX-INO
VARIABLE _EXT4-RDX-PARINO
VARIABLE _EXT4-RDX-GEN
VARIABLE _EXT4-RDX-DIR-BLOCKS
VARIABLE _EXT4-RDX-CTX
VARIABLE _EXT4-RDX-ENTRY
VARIABLE _EXT4-RDX-TAIL

: _EXT4-RESTAMP-DX-ROOT
  ( block dir-inum parent-inum generation dir-blocks ctx -- ior )
    _EXT4-RDX-CTX ! _EXT4-RDX-DIR-BLOCKS ! _EXT4-RDX-GEN !
    _EXT4-RDX-PARINO ! _EXT4-RDX-INO ! _EXT4-RDX-BLOCK !
    _EXT4-RDX-BLOCK @ 0= _EXT4-RDX-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-RDX-INO @ 0=
    _EXT4-RDX-INO @ _EXT4-RDX-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDX-PARINO @ 0=
    _EXT4-RDX-PARINO @ _EXT4-RDX-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDX-GEN @ 0xFFFFFFFF U> IF VFS-E-INVALID EXIT THEN
    _EXT4-RDX-DIR-BLOCKS @ 2 U<
    _EXT4-RDX-DIR-BLOCKS @ 0x10000000 U> OR
    _EXT4-RDX-DIR-BLOCKS @
        _EXT4-RDX-CTX @ _EXT4-C.BLOCKS + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDX-BLOCK @
    DUP L@ _EXT4-RDX-INO @ <>
    OVER 4 + W@ 12 <> OR
    OVER 6 + C@ 1 <> OR
    OVER 7 + C@ 2 <> OR
    OVER 8 + C@ [CHAR] . <> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP 12 + L@ _EXT4-RDX-PARINO @ <>
    OVER 16 + W@ _EXT4-RDX-CTX @ _EXT4-C.BSIZE + @ 12 - <> OR
    OVER 18 + C@ 2 <> OR
    OVER 19 + C@ 2 <> OR
    OVER 20 + C@ [CHAR] . <> OR
    OVER 21 + C@ [CHAR] . <> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP 24 + L@ IF DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    DUP 29 + C@ 8 <>
    OVER 30 + C@ 1 U> OR
    OVER 31 + C@ 0<> OR IF
        DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-RDX-BLOCK @ 30 + C@ IF
        _EXT4-RDX-DIR-BLOCKS @ 3 U< IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-RDX-CTX @ _EXT4-RDX-BLOCK @ 28 + C@
    _EXT4-DIRHASH-POLICY DUP IF NIP EXIT THEN 2DROP
    _EXT4-RDX-BLOCK @ 32 + DUP _EXT4-RDX-ENTRY !
    _EXT4-RDX-CTX @ _EXT4-C.BSIZE + @ 40 - 8 /
    _EXT4-RDX-DIR-BLOCKS @ _EXT4-RDX-CTX @
    _EXT4-VALIDATE-DX-ENTRIES ?DUP IF EXIT THEN
    _EXT4-RDX-ENTRY @ _EXT4-DX-LIMIT @ 8 * + DUP _EXT4-RDX-TAIL !
    _EXT4-RDX-BLOCK @ _EXT4-RDX-CTX @ _EXT4-C.BSIZE + @ + 8 - <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDX-TAIL @ L@ IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDX-INO @ _EXT4-RDX-CTX @ _EXT4-C.TMP + L!
    _EXT4-RDX-GEN @ _EXT4-RDX-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-RDX-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RDX-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-RDX-BLOCK @
    _EXT4-RDX-ENTRY @ _EXT4-RDX-BLOCK @ - _EXT4-DX-COUNT @ 8 * +
    _EXT4-CRC-ADD ?DUP IF EXIT THEN
    0 _EXT4-RDX-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-RDX-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-RDX-CTX @ _EXT4-C.TMP 8 + + 8 _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-RDX-TAIL @ 4 + L!
    0 ;

\ An HTree index node an insert builds or edits has no checksummed preimage
\ of its own.  Validate its complete fake-dirent header and entry vector,
\ then checksum it from the parent inode identity exactly as read-side
\ DX-node authentication does.  Commit only the checksum field after all CRC
\ capability calls succeed.
VARIABLE _EXT4-RDN-BLOCK
VARIABLE _EXT4-RDN-INO
VARIABLE _EXT4-RDN-GEN
VARIABLE _EXT4-RDN-DIR-BLOCKS
VARIABLE _EXT4-RDN-CTX
VARIABLE _EXT4-RDN-ENTRY
VARIABLE _EXT4-RDN-TAIL

: _EXT4-RESTAMP-DX-NODE
  ( block dir-inum generation dir-blocks ctx -- ior )
    _EXT4-RDN-CTX ! _EXT4-RDN-DIR-BLOCKS ! _EXT4-RDN-GEN !
    _EXT4-RDN-INO ! _EXT4-RDN-BLOCK !
    _EXT4-RDN-BLOCK @ 0= _EXT4-RDN-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-RDN-INO @ 0=
    _EXT4-RDN-INO @ _EXT4-RDN-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDN-GEN @ 0xFFFFFFFF U> IF VFS-E-INVALID EXIT THEN
    _EXT4-RDN-DIR-BLOCKS @ 3 U<
    _EXT4-RDN-DIR-BLOCKS @ 0x10000000 U> OR
    _EXT4-RDN-DIR-BLOCKS @
        _EXT4-RDN-CTX @ _EXT4-C.BLOCKS + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDN-BLOCK @
    DUP L@ 0<>
    OVER 4 + W@ _EXT4-RDN-CTX @ _EXT4-C.BSIZE + @ <> OR
    OVER 6 + C@ 0<> OR
    SWAP 7 + C@ 0<> OR IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDN-BLOCK @ 8 + DUP _EXT4-RDN-ENTRY !
    _EXT4-RDN-CTX @ _EXT4-C.BSIZE + @ 16 - 8 /
    _EXT4-RDN-DIR-BLOCKS @ _EXT4-RDN-CTX @
    _EXT4-VALIDATE-DX-ENTRIES ?DUP IF EXIT THEN
    _EXT4-RDN-ENTRY @ _EXT4-DX-LIMIT @ 8 * + DUP _EXT4-RDN-TAIL !
    _EXT4-RDN-BLOCK @ _EXT4-RDN-CTX @ _EXT4-C.BSIZE + @ + 8 - <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDN-TAIL @ L@ IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RDN-INO @ _EXT4-RDN-CTX @ _EXT4-C.TMP + L!
    _EXT4-RDN-GEN @ _EXT4-RDN-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-RDN-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RDN-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-RDN-BLOCK @
    _EXT4-RDN-ENTRY @ _EXT4-RDN-BLOCK @ - _EXT4-DX-COUNT @ 8 * +
    _EXT4-CRC-ADD ?DUP IF EXIT THEN
    0 _EXT4-RDN-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-RDN-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-RDN-CTX @ _EXT4-C.TMP 8 + + 8 _EXT4-CRC-ADD
    ?DUP IF EXIT THEN
    _EXT4-CRC@ _EXT4-RDN-TAIL @ 4 + L!
    0 ;

\ Restamp one external extent node, leaf or index, after a deterministic
\ local edit.  The node may name a transaction-owned block whose allocation
\ bitmap afterimage has not been staged yet, so this constructor validates
\ the resident geometry but deliberately does not invoke the allocation-aware
\ extent walker on the afterimage.
VARIABLE _EXT4-REL-BLOCK
VARIABLE _EXT4-REL-INO
VARIABLE _EXT4-REL-GEN
VARIABLE _EXT4-REL-CTX
VARIABLE _EXT4-REL-MAX

: _EXT4-RESTAMP-EXTENT-NODE  ( block inode generation ctx -- ior )
    _EXT4-REL-CTX ! _EXT4-REL-GEN ! _EXT4-REL-INO ! _EXT4-REL-BLOCK !
    _EXT4-REL-BLOCK @ 0= _EXT4-REL-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-REL-INO @ 0=
    _EXT4-REL-INO @ _EXT4-REL-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-REL-GEN @ 0xFFFFFFFF U> IF VFS-E-INVALID EXIT THEN
    _EXT4-REL-CTX @ _EXT4-C.BSIZE + @ DUP 12 U< IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    12 - 12 / DUP _EXT4-REL-MAX ! 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-REL-BLOCK @ W@ _EXT4-EXTENT-MAGIC <>
    _EXT4-REL-BLOCK @ 2 + W@ DUP 0=
        SWAP _EXT4-REL-MAX @ U> OR OR
    _EXT4-REL-BLOCK @ 4 + W@ _EXT4-REL-MAX @ <> OR
    _EXT4-REL-BLOCK @ 6 + W@ _EXT4-MAX-EXTENT-DEPTH 1- U> OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-REL-INO @ _EXT4-REL-CTX @ _EXT4-C.TMP + L!
    _EXT4-REL-GEN @ _EXT4-REL-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-REL-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-REL-CTX @ _EXT4-C.TMP + 8 _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-REL-BLOCK @ _EXT4-REL-MAX @ 12 * 12 +
    _EXT4-CRC-ADD ?DUP IF EXIT THEN
    _EXT4-CRC@
    _EXT4-REL-BLOCK @ _EXT4-REL-MAX @ 12 * 12 + + L!
    0 ;

