: _EXT4-JUA-REQUIRE-EMPTY-PRESTATE  ( -- ior )
    _EXT4-JUA-CTX @ _EXT4-JUA-V @
    _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JUA-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-JUA-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-JUA-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JUA-CTX @ _EXT4-C.SB + DUP
    _EXT4-SB.LAST-ORPHAN + L@
    SWAP _EXT4-SB.RO-COMPAT + L@ _EXT4-RO-ORPHAN-PRESENT AND OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JUA-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ 1 U< IF
        VFS-E-NOSPC EXIT
    THEN
    0 _EXT4-JUA-PLAN-COUNT !
    _EXT4-JUA-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JUA-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-JUA-SCAN-RECORD ! @ IF
            1 _EXT4-JUA-PLAN-COUNT +!
        THEN
    LOOP
    _EXT4-JUA-PLAN-COUNT @ IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JUA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ 8 - 4 /
    DUP _EXT4-JUA-ENTRIES ! 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-BLOCKS @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-JUA-RAW-COUNT !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-JUA-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-JUA-ENTRIES @ 0 ?DO
            _EXT4-JUA-CTX @ _EXT4-C.BLOCK + I 4 * + L@ IF
                1 _EXT4-JUA-RAW-COUNT +!
            THEN
        LOOP
    LOOP
    _EXT4-JUA-RAW-COUNT @ IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-JUA-O-LOGICAL ! 0 _EXT4-JUA-O-SLOT !
    0 _EXT4-JUA-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JUA-O-HOME !
    _EXT4-OV-GEN @ _EXT4-JUA-O-GEN !
    _EXT4-OV-INO @ _EXT4-JUA-O-INO !
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK + L@ IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JUA-O-HOME @ 1 _EXT4-JUA-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ;

: _EXT4-JUA-AUTH-PREFLIGHT
  ( inode-number expected-generation ctx vfs -- ior )
    _EXT4-JUA-V ! _EXT4-JUA-CTX ! _EXT4-JUA-GEN ! _EXT4-JUA-INO !
    _EXT4-JUA-CTX @ 0= _EXT4-JUA-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-JUA-V @
    _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING ?DUP IF EXIT THEN
    _EXT4-JUA-REQUIRE-EMPTY-PRESTATE ?DUP IF EXIT THEN
    _EXT4-JUA-INO @ _EXT4-JUA-GEN @ _EXT4-JUA-CTX @
    _EXT4-JFI-AUTH-PROSPECTIVE ?DUP IF EXIT THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JUA-O-HOME @ =
    _EXT4-JFI-INODE-HOME @ _EXT4-JUA-CTX @
    _EXT4-PRIMARY-SUPER-BLOCK = OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-EA @ ?DUP IF
        DUP _EXT4-JFI-INODE-HOME @ =
        OVER _EXT4-JUA-O-HOME @ = OR
        SWAP _EXT4-JUA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = OR IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JFI-INODE @ _EXT4-I.SIZE-LO + L@ _EXT4-JUA-SIZE-LO !
    _EXT4-JFI-INODE @ _EXT4-I.SIZE-HI + L@ _EXT4-JUA-SIZE-HI !
    0 ;

: _EXT4-JUA-STAGE-ORPHAN  ( -- ior )
    _EXT4-JUA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JUA-O-LOGICAL @ _EXT4-JUA-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JUA-O-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JUA-O-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JUA-O-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK + _EXT4-JUA-O-HOME @
    _EXT4-JUA-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JUA-O-IMAGE !
    DUP _EXT4-JUA-O-SLOT @ 4 * + L@ IF DROP VFS-E-CONFLICT EXIT THEN
    DROP
    _EXT4-JUA-INO @
    _EXT4-JUA-O-IMAGE @ _EXT4-JUA-O-SLOT @ 4 * + L!
    _EXT4-JUA-O-IMAGE @ _EXT4-JUA-O-HOME @ _EXT4-JUA-O-INO @
    _EXT4-JUA-O-GEN @ _EXT4-JUA-CTX @ _EXT4-RESTAMP-ORPHAN-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JUA-O-IMAGE @ _EXT4-JUA-O-HOME @ _EXT4-JUA-WRITER @
    _EXT4-JTX-META-REPLACE ;

: _EXT4-JUA-STAGE-SUPER  ( -- ior )
    _EXT4-JUA-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JUA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.RO-COMPAT + DUP L@
    _EXT4-RO-ORPHAN-PRESENT AND IF DROP VFS-E-CONFLICT EXIT THEN
    DUP L@ _EXT4-RO-ORPHAN-PRESENT OR SWAP L!
    _EXT4-JPS-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JPS-IMAGE @ DUP _EXT4-JUA-SUPER-IMAGE !
    _EXT4-JPS-HOME @ _EXT4-JUA-WRITER @ _EXT4-JTX-META-REPLACE ;

: _EXT4-JUA-CAPTURE-META-CRC  ( home -- crc ior )
    _EXT4-JUA-WRITER @ _EXT4-JFC-FIND-META ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ 0 ;

: _EXT4-JUA-SEAL  ( -- ior )
    _EXT4-JUA-INO @ _EXT4-JUA-GEN @ _EXT4-JUA-CTX @ _EXT4-JUA-V @
    _EXT4-JUA-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JUA-WRITER @ _EXT4-JWR.META-CREDIT + @ _EXT4-JUA-META @ <>
    _EXT4-JUA-WRITER @ _EXT4-JWR.META-USED + @ _EXT4-JUA-META @ <> OR
    _EXT4-JUA-WRITER @ _EXT4-JWR.META-ACTIVE + @ _EXT4-JUA-META @ <> OR
    _EXT4-JUA-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JUA-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JUA-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JUA-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR
    _EXT4-JUA-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JUA-CAPTURE-META-CRC
    _EXT4-JUA-IOR ! _EXT4-JUA-TARGET-CRC !
    _EXT4-JUA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JUA-O-HOME @ _EXT4-JUA-CAPTURE-META-CRC
    _EXT4-JUA-IOR ! _EXT4-JUA-ORPHAN-CRC !
    _EXT4-JUA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JUA-CAPTURE-META-CRC
    _EXT4-JUA-IOR ! _EXT4-JUA-SUPER-CRC !
    _EXT4-JUA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JUA-WRITER @ _EXT4-JWR.EPOCH + @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-EPOCH + !
    _EXT4-JUA-INO @ _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-INO + !
    _EXT4-JUA-O-LOGICAL @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + !
    _EXT4-JUA-O-SLOT @ _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-SLOT + !
    _EXT4-JUA-O-HOME @ _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-HOME + !
    _EXT4-JUA-O-GEN @ _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-GEN + !
    _EXT4-JUA-GEN @ _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + !
    _EXT4-JFI-INODE-HOME @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + !
    _EXT4-JFI-INODE-OFF @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + !
    _EXT4-JUA-TARGET-CRC @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + !
    _EXT4-JUA-ORPHAN-CRC @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + !
    _EXT4-JFI-DATA-ENTRIES @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + !
    _EXT4-JUA-SECONDS @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ADD-SECONDS + !
    _EXT4-JUA-NSEC @ _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ADD-NSEC + !
    _EXT4-JUA-SUPER-CRC @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ADD-SUPER-CRC + !
    0 _EXT4-JUA-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + !
    0 _EXT4-JUA-WRITER @ _EXT4-JWR.CP-PRE-MODERN + !
    0 _EXT4-JUA-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + !
    _EXT4-JUA-WRITER @ _EXT4-JFI-STORE-CP-RANGES
    _EXT4-JUA-PARENT-INO @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ADD-PARENT-INO + !
