    _EXT4-JUA-SIZE-HI !
    _EXT4-JUA-WRITER @ _EXT4-JWR.META-CREDIT + @ _EXT4-JUA-META !
    _EXT4-JUA-INO @ _EXT4-JUA-GEN @ _EXT4-JUA-CTX @ _EXT4-JUA-V @
    _EXT4-JUA-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-DIRECTORY @ _EXT4-JUA-DIRECTORY !
    _EXT4-JUA-O-LOGICAL @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <>
    _EXT4-JUA-O-SLOT @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> OR
    _EXT4-JUA-O-HOME @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> OR
    _EXT4-JUA-O-GEN @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> OR
    _EXT4-JFI-INODE-HOME @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <> OR
    _EXT4-JFI-INODE-OFF @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ <> OR
    _EXT4-JUA-SIZE-LO @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-LO + @ <> OR
    _EXT4-JUA-SIZE-HI @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-HI + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JUA-WRITER @ _EXT4-JFI-CP-RANGES-MATCH? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DATA-ENTRIES @
    _EXT4-JUA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JUA-FIND-META-IMAGE  ( home -- image ior )
    _EXT4-JUA-WRITER @ _EXT4-JFC-FIND-META ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ 0 ;

\ Load a payload inode's current record, at its sealed table home and of its
\ sealed kind, into the context's inode buffer.
: _EXT4-JUA-LOAD-PRESTATE  ( ino gen home offset type -- ior )
    _EXT4-JUA-PRE-TYPE ! _EXT4-JUA-PRE-OFF ! _EXT4-JUA-PRE-HOME !
    _EXT4-JUA-PRE-GEN ! _EXT4-JUA-PRE-INO !
    _EXT4-JUA-PRE-INO @ _EXT4-JUA-CTX @ _EXT4-LOAD-INODE
    ?DUP IF EXIT THEN
    _EXT4-IR-BLOCK @ _EXT4-JUA-PRE-HOME @ <>
    _EXT4-IR-OFF @ _EXT4-JUA-PRE-OFF @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JUA-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JUA-IOR ! _EXT4-JUA-PRE-TYPE @ <> IF
        _EXT4-JUA-IOR @ ?DUP IF EXIT THEN VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JUA-IOR @ ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.INODE + DUP _EXT4-JUA-PRE-INODE !
    DUP _EXT4-I.GENERATION + L@ _EXT4-JUA-PRE-GEN @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-I.LINKS + W@ 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JUA-LOAD-PARENT-PRESTATE  ( -- ior )
    _EXT4-JUA-PARENT-INO @ _EXT4-JUA-PARENT-GEN @
    _EXT4-JUA-PARENT-HOME @ _EXT4-JUA-PARENT-OFF @ VFS-T-DIR
    _EXT4-JUA-LOAD-PRESTATE ;

\ The target's record loses its last link, a regular file's one or an
\ empty directory's two.
: _EXT4-JUA-APPLY-TARGET-EXPECTED  ( -- ior )
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JFI-INODE-OFF @ +
    DUP _EXT4-JUA-RECORD !
    _EXT4-JFI-INODE @ _EXT4-JUA-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JUA-RECORD @ DUP _EXT4-I.LINKS + W@
    _EXT4-JUA-DIRECTORY @ IF 2 ELSE 1 THEN <> IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DUP _EXT4-I.SIZE-LO + L@ _EXT4-JUA-SIZE-LO @ <>
    OVER _EXT4-I.SIZE-HI + L@ _EXT4-JUA-SIZE-HI @ <> OR IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    0 OVER _EXT4-I.LINKS + W!
    DROP
    _EXT4-JUA-SECONDS @ _EXT4-JUA-NSEC @ _EXT4-JUA-RECORD @
    _EXT4-JUA-CTX @ _EXT4-SET-INODE-CTIME ?DUP IF EXIT THEN
    _EXT4-JUA-RECORD @ _EXT4-JUA-INO @ _EXT4-JUA-CTX @
    _EXT4-RESTAMP-INODE ;

VARIABLE _EXT4-JUA-ENTRIES-CHANGED

\ Stamp the loaded inode's record in the expected block with the sealed time:
\ with ENTRIES? a directory whose entries changed takes it as its
\ modification and change time, and otherwise a renamed inode takes it as
\ its change time.  The record's link count changes by DELTA: a parent loses
\ the `..` of a removed or departing child directory and gains an arriving
\ one's.
: _EXT4-JUA-APPLY-TIMES-EXPECTED  ( delta entries? -- ior )
    _EXT4-JUA-ENTRIES-CHANGED !
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-PRE-OFF @ +
    DUP _EXT4-JUA-RECORD !
    _EXT4-JUA-PRE-INODE @ _EXT4-JUA-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF DROP VFS-E-CONFLICT EXIT THEN
    _EXT4-JUA-RECORD @ _EXT4-I.LINKS + DUP W@ ROT + SWAP W!
    _EXT4-JUA-SECONDS @ _EXT4-JUA-NSEC @ _EXT4-JUA-RECORD @
    _EXT4-JUA-CTX @
    _EXT4-JUA-ENTRIES-CHANGED @ IF
        _EXT4-SET-INODE-MTIME-CTIME
    ELSE
        _EXT4-SET-INODE-CTIME
    THEN ?DUP IF EXIT THEN
    _EXT4-JUA-RECORD @ _EXT4-JUA-PRE-INO @ _EXT4-JUA-CTX @
    _EXT4-RESTAMP-INODE ;

\ A rename's source has the target's type: the VFS layer replaces a regular
\ file only with a regular file and an empty directory only with a
\ directory, and the source's typed prestate load proves it.
: _EXT4-JUA-SOURCE-TYPE  ( -- type )
    _EXT4-JUA-DIRECTORY @ IF VFS-T-DIR ELSE VFS-T-FILE THEN ;

\ The target's parent loses a removed directory's `..` link, unless a
\ directory arriving from another parent takes the target's name.  The old
\ parent loses a departing directory's.
: _EXT4-JUA-PARENT-LINKS  ( -- delta )
    _EXT4-JUA-DIRECTORY @ 0= IF 0 EXIT THEN
    _EXT4-JUA-OLD-PARENT-INO @ IF 0 ELSE -1 THEN ;

: _EXT4-JUA-OLD-PARENT-LINKS  ( -- delta )
    _EXT4-JUA-DIRECTORY @ IF -1 ELSE 0 THEN ;

: _EXT4-JUA-REQUIRE-EXPECTED-HOME  ( home -- ior )
    _EXT4-JUA-FIND-META-IMAGE
    DUP IF NIP EXIT THEN DROP _EXT4-JUA-IMAGE !
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-IMAGE @
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Rebuild one inode-table home from its current block and every edit the
\ payload names in it, and require the journaled image.  The target's edit
\ comes first, while the context's inode buffer still holds the target.
: _EXT4-JUA-REQUIRE-INODE-HOME  ( home -- ior )
    DUP _EXT4-JUA-AT-HOME !
    _EXT4-JUA-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK + _EXT4-JUA-EXPECTED-BLOCK
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JUA-AT-HOME @ _EXT4-JFI-INODE-HOME @ = IF
        _EXT4-JUA-APPLY-TARGET-EXPECTED ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-SOURCE-INO @
    _EXT4-JUA-AT-HOME @ _EXT4-JUA-SOURCE-HOME @ = AND IF
        _EXT4-JUA-SOURCE-INO @ _EXT4-JUA-SOURCE-GEN @
        _EXT4-JUA-SOURCE-HOME @ _EXT4-JUA-SOURCE-OFF @
        _EXT4-JUA-SOURCE-TYPE _EXT4-JUA-LOAD-PRESTATE ?DUP IF EXIT THEN
        0 FALSE _EXT4-JUA-APPLY-TIMES-EXPECTED ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-AT-HOME @ _EXT4-JUA-PARENT-HOME @ = IF
        _EXT4-JUA-LOAD-PARENT-PRESTATE ?DUP IF EXIT THEN
        _EXT4-JUA-PARENT-LINKS TRUE _EXT4-JUA-APPLY-TIMES-EXPECTED
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-OLD-PARENT-INO @
    _EXT4-JUA-AT-HOME @ _EXT4-JUA-OLD-PARENT-HOME @ = AND IF
        _EXT4-JUA-OLD-PARENT-INO @ _EXT4-JUA-OLD-PARENT-GEN @
        _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-OLD-PARENT-OFF @
        VFS-T-DIR _EXT4-JUA-LOAD-PRESTATE ?DUP IF EXIT THEN
        _EXT4-JUA-OLD-PARENT-LINKS TRUE _EXT4-JUA-APPLY-TIMES-EXPECTED
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-AT-HOME @ _EXT4-JUA-REQUIRE-EXPECTED-HOME ?DUP IF EXIT THEN
    _EXT4-JUA-AT-HOME @ _EXT4-JFI-INODE-HOME @ = IF
        _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JUA-TARGET-CRC @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Every inode-table home the payload names, each once: the target's first,
\ then the parent's, and a rename's source's and old parent's.
: _EXT4-JUA-REQUIRE-INODE-AFTERIMAGES  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JUA-REQUIRE-INODE-HOME ?DUP IF EXIT THEN
    _EXT4-JUA-PARENT-HOME @ _EXT4-JFI-INODE-HOME @ <> IF
        _EXT4-JUA-PARENT-HOME @ _EXT4-JUA-REQUIRE-INODE-HOME
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-SOURCE-INO @ 0= IF 0 EXIT THEN
    _EXT4-JUA-SOURCE-HOME @ _EXT4-JFI-INODE-HOME @ <>
    _EXT4-JUA-SOURCE-HOME @ _EXT4-JUA-PARENT-HOME @ <> AND IF
        _EXT4-JUA-SOURCE-HOME @ _EXT4-JUA-REQUIRE-INODE-HOME
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-OLD-PARENT-INO @ 0= IF 0 EXIT THEN
    _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JFI-INODE-HOME @ <>
    _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-PARENT-HOME @ <> AND
    _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-SOURCE-HOME @ <> AND IF
        _EXT4-JUA-OLD-PARENT-HOME @ _EXT4-JUA-REQUIRE-INODE-HOME EXIT
    THEN
    0 ;

\ Read and validate one block of the named directory, and begin its expected
\ image.
: _EXT4-JUA-LOAD-DIRECTORY  ( home ino gen -- ior )
    _EXT4-JUA-AT-GEN ! _EXT4-JUA-AT-INO ! _EXT4-JUA-AT-HOME !
    _EXT4-JUA-AT-HOME @ _EXT4-JUA-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JUA-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JUA-AT-INO @ _EXT4-JUA-AT-GEN @ _EXT4-JUA-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.DIR-BLOCK + _EXT4-JUA-EXPECTED-BLOCK
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 ;

\ Whether OFFSET starts a record of the validated directory block.
: _EXT4-JUA-RECORD-START?  ( offset -- flag )
    0 _EXT4-JUA-INDEX !
    BEGIN DUP _EXT4-JUA-INDEX @ U> WHILE
        _EXT4-JUA-CTX @ _EXT4-C.DIR-BLOCK + _EXT4-JUA-INDEX @ +
        4 + W@ _EXT4-JUA-INDEX +!
    REPEAT
    _EXT4-JUA-INDEX @ = ;

\ Whether the expected image holds at CUT-OFF the live record for CUT-INO
\ of CUT-REC bytes, typed as a directory with CUT-DIR or else as a
\ regular file.
: _EXT4-JUA-CUT-TARGET?  ( -- flag )
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-CUT-OFF @ + DUP
    _EXT4-JUA-DIR-TARGET !
    DUP L@ _EXT4-JUA-CUT-INO @ =
    OVER 4 + W@ _EXT4-JUA-CUT-REC @ = AND
    OVER 6 + C@ 0<> AND
    SWAP 7 + C@ _EXT4-JUA-CUT-DIR @ IF 2 = ELSE 1 U> 0= THEN AND ;

\ Join the live record for INO of REC bytes at OFFSET to its predecessor,
\ live or unused, of PREV-REC bytes at PREV-OFFSET in the expected image.
: _EXT4-JUA-SPLICE-EXPECTED  ( prev-offset prev-rec offset rec ino -- ior )
    _EXT4-JUA-CUT-INO ! _EXT4-JUA-CUT-REC ! _EXT4-JUA-CUT-OFF !
    _EXT4-JUA-CUT-PREV-REC ! _EXT4-JUA-CUT-PREV-OFF !
    _EXT4-JUA-CUT-PREV-OFF @ _EXT4-JUA-RECORD-START? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-CUT-PREV-OFF @ + DUP
    _EXT4-JUA-DIR-PREV !
    4 + W@ _EXT4-JUA-CUT-PREV-REC @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JUA-CUT-TARGET? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JUA-CUT-PREV-REC @ _EXT4-JUA-CUT-REC @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP 0xFFFF U> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JUA-DIR-PREV @ 4 + W!
    _EXT4-JUA-DIR-TARGET @ _EXT4-JUA-CUT-REC @ 0 FILL
    0 ;

\ Stamp the expected directory image for its directory and require the
\ journaled image.
: _EXT4-JUA-REQUIRE-DIRECTORY-HOME  ( -- ior )
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-AT-INO @ _EXT4-JUA-AT-GEN @
    _EXT4-JUA-CTX @ _EXT4-RESTAMP-DIR-BLOCK ?DUP IF EXIT THEN
    _EXT4-JUA-AT-HOME @ _EXT4-JUA-REQUIRE-EXPECTED-HOME ;

\ Leave the live record for INO of REC bytes, the first of its block,
\ unused in the expected image: its inode and every byte from its name
\ length to its end cleared.
: _EXT4-JUA-BLANK-EXPECTED  ( rec ino -- ior )
    _EXT4-JUA-CUT-INO ! _EXT4-JUA-CUT-REC ! 0 _EXT4-JUA-CUT-OFF !
    _EXT4-JUA-CUT-TARGET? 0= IF VFS-E-CORRUPT EXIT THEN
    0 _EXT4-JUA-DIR-TARGET @ L!
    _EXT4-JUA-DIR-TARGET @ 6 + _EXT4-JUA-CUT-REC @ 6 - 0 FILL
    0 ;

\ Take the live record for INO of REC bytes at OFFSET out of the expected
\ image as a removal does: it joins its predecessor of PREV-REC bytes at
\ PREV-OFFSET, or with no predecessor, as its block's first record, becomes
\ unused.
: _EXT4-JUA-CUT-EXPECTED  ( prev-offset prev-rec offset rec ino -- ior )
    3 PICK IF _EXT4-JUA-SPLICE-EXPECTED EXIT THEN
    >R NIP NIP NIP R> _EXT4-JUA-BLANK-EXPECTED ;

\ The removal's directory block: the target's record joins its
\ predecessor, or as the block's first record becomes unused.
: _EXT4-JUA-REQUIRE-DIRECTORY-AFTERIMAGE  ( -- ior )
    _EXT4-JUA-DIR-HOME @ _EXT4-JUA-PARENT-INO @ _EXT4-JUA-PARENT-GEN @
    _EXT4-JUA-LOAD-DIRECTORY ?DUP IF EXIT THEN
    _EXT4-JUA-DIRECTORY @ _EXT4-JUA-CUT-DIR !
    _EXT4-JUA-PREV-OFF @ _EXT4-JUA-PREV-REC @
    _EXT4-JUA-TARGET-OFF @ _EXT4-JUA-TARGET-REC @ _EXT4-JUA-INO @
    _EXT4-JUA-CUT-EXPECTED ?DUP IF EXIT THEN
    _EXT4-JUA-REQUIRE-DIRECTORY-HOME ;

\ A rename over the target: the target's record names the source and keeps
\ its name, length and type, and the source's record of the same type
\ leaves its block, the same one or its own directory block, as a removal's
\ record does.
: _EXT4-JUA-REQUIRE-RENAME-DIRECTORIES  ( -- ior )
    _EXT4-JUA-DIR-HOME @ _EXT4-JUA-PARENT-INO @ _EXT4-JUA-PARENT-GEN @
    _EXT4-JUA-LOAD-DIRECTORY ?DUP IF EXIT THEN
    _EXT4-JUA-TARGET-OFF @ _EXT4-JUA-RECORD-START? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JUA-DIRECTORY @ _EXT4-JUA-CUT-DIR !
    _EXT4-JUA-TARGET-OFF @ _EXT4-JUA-CUT-OFF !
    _EXT4-JUA-TARGET-REC @ _EXT4-JUA-CUT-REC !
    _EXT4-JUA-INO @ _EXT4-JUA-CUT-INO !
    _EXT4-JUA-CUT-TARGET? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JUA-SOURCE-INO @ _EXT4-JUA-DIR-TARGET @ L!
    _EXT4-JUA-OLD-DIR-HOME @ _EXT4-JUA-DIR-HOME @ <> IF
        _EXT4-JUA-REQUIRE-DIRECTORY-HOME ?DUP IF EXIT THEN
        _EXT4-JUA-OLD-DIR-HOME @
        _EXT4-JUA-OLD-PARENT-INO @ IF
            _EXT4-JUA-OLD-PARENT-INO @ _EXT4-JUA-OLD-PARENT-GEN @
        ELSE
            _EXT4-JUA-PARENT-INO @ _EXT4-JUA-PARENT-GEN @
        THEN
        _EXT4-JUA-LOAD-DIRECTORY ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-OLD-PREV-OFF @ _EXT4-JUA-OLD-PREV-REC @
    _EXT4-JUA-OLD-SOURCE-OFF @ _EXT4-JUA-OLD-SOURCE-REC @
    _EXT4-JUA-SOURCE-INO @ _EXT4-JUA-CUT-EXPECTED ?DUP IF EXIT THEN
    _EXT4-JUA-REQUIRE-DIRECTORY-HOME ;

VARIABLE _EXT4-DDD-BLOCK
VARIABLE _EXT4-DDD-PARENT

\ The offset of the `..` record in the validated linear block 0 of a
\ directory: its first record `.` names INO and its second, `..`, names
\ PARENT.  Any other block gives zero.
: _EXT4-DIR-DOTDOT  ( block ino parent -- offset )
    _EXT4-DDD-PARENT ! SWAP DUP _EXT4-DDD-BLOCK !
    DUP L@ ROT <> OVER 6 + C@ 1 <> OR
    SWAP 8 + C@ [CHAR] . <> OR IF 0 EXIT THEN
    _EXT4-DDD-BLOCK @ 4 + W@
    _EXT4-DDD-BLOCK @ OVER +
    DUP L@ _EXT4-DDD-PARENT @ <> OVER 6 + C@ 2 <> OR
    SWAP 8 + W@ 0x2E2E <> OR IF DROP 0 THEN ;

VARIABLE _EXT4-JUA-CHILD-BLOCKS
VARIABLE _EXT4-JUA-CHILD-INDEXED
VARIABLE _EXT4-JUA-DOTDOT

\ A directory the rename moves to another parent names the new parent in
\ its block 0, the child home: the `..` record after `.` in a checksummed
\ leaf, restamped with the dirent tail, or the `..` entry of a DX root,
\ restamped with the DX tail.  The block on media names the moved directory
\ in `.` and the old parent in `..`.
: _EXT4-JUA-REQUIRE-CHILD-AFTERIMAGE  ( -- ior )
    _EXT4-JUA-SOURCE-INO @ _EXT4-JUA-SOURCE-GEN @
    _EXT4-JUA-SOURCE-HOME @ _EXT4-JUA-SOURCE-OFF @ VFS-T-DIR
    _EXT4-JUA-LOAD-PRESTATE ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.R.SIZE + @
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ / _EXT4-JUA-CHILD-BLOCKS !
    _EXT4-JUA-CTX @ _EXT4-C.INODE + _EXT4-I.FLAGS + L@
    _EXT4-INDEX-FL AND 0<> _EXT4-JUA-CHILD-INDEXED !
    _EXT4-JUA-CHILD-HOME @ _EXT4-JUA-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK +
    _EXT4-JUA-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JUA-CHILD-INDEXED @ IF
        _EXT4-JUA-SOURCE-INO @ _EXT4-DX-DIRINO !
        _EXT4-JUA-OLD-PARENT-INO @ _EXT4-DX-PARINO !
        _EXT4-JUA-SOURCE-GEN @ _EXT4-DX-GEN !
        _EXT4-JUA-CTX @ _EXT4-JUA-CHILD-BLOCKS @ _EXT4-VALIDATE-DX-ROOT
        ?DUP IF EXIT THEN
        12 _EXT4-JUA-DOTDOT !
    ELSE
        _EXT4-JUA-SOURCE-INO @ _EXT4-JUA-SOURCE-GEN @ _EXT4-JUA-CTX @
        _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
        _EXT4-JUA-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JUA-SOURCE-INO @ _EXT4-JUA-OLD-PARENT-INO @ _EXT4-DIR-DOTDOT
        DUP _EXT4-JUA-DOTDOT ! 0= IF VFS-E-CORRUPT EXIT THEN
    THEN
    _EXT4-JUA-CTX @ _EXT4-C.DIR-BLOCK + _EXT4-JUA-EXPECTED-BLOCK
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JUA-PARENT-INO @
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-DOTDOT @ + L!
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-SOURCE-INO @
    _EXT4-JUA-CHILD-INDEXED @ IF
        _EXT4-JUA-PARENT-INO @ _EXT4-JUA-SOURCE-GEN @
        _EXT4-JUA-CHILD-BLOCKS @ _EXT4-JUA-CTX @ _EXT4-RESTAMP-DX-ROOT
    ELSE
        _EXT4-JUA-SOURCE-GEN @ _EXT4-JUA-CTX @ _EXT4-RESTAMP-DIR-BLOCK
    THEN ?DUP IF EXIT THEN
    _EXT4-JUA-CHILD-HOME @ _EXT4-JUA-REQUIRE-EXPECTED-HOME ;

: _EXT4-JUA-REQUIRE-ORPHAN-AFTERIMAGE  ( -- ior )
    _EXT4-JUA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JUA-O-LOGICAL @ _EXT4-JUA-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JUA-O-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JUA-O-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JUA-O-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK + _EXT4-JUA-EXPECTED-BLOCK
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-O-SLOT @ 4 * + L@ IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JUA-INO @
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-O-SLOT @ 4 * + L!
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-O-HOME @ _EXT4-JUA-O-INO @
    _EXT4-JUA-O-GEN @ _EXT4-JUA-CTX @ _EXT4-RESTAMP-ORPHAN-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JUA-O-HOME @ _EXT4-JUA-REQUIRE-EXPECTED-HOME
    ?DUP IF EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JUA-ORPHAN-CRC @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JUA-REQUIRE-SUPER-AFTERIMAGE  ( -- ior )
    _EXT4-JUA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JUA-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-C.BLOCK + _EXT4-JUA-EXPECTED-BLOCK
    _EXT4-JUA-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-CTX @
    _EXT4-PRIMARY-SUPER-OFF + _EXT4-SB.RO-COMPAT + DUP L@
    _EXT4-RO-ORPHAN-PRESENT AND IF DROP VFS-E-CORRUPT EXIT THEN
    DUP L@ _EXT4-RO-ORPHAN-PRESENT OR SWAP L!
    _EXT4-JUA-EXPECTED-BLOCK _EXT4-JUA-CTX @
    _EXT4-PRIMARY-SUPER-OFF + _EXT4-STAMP-SUPER-CHECKSUM
    ?DUP IF EXIT THEN
    _EXT4-JUA-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JUA-REQUIRE-EXPECTED-HOME ?DUP IF EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JUA-SUPER-CRC @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ A directory moving across parents names its block 0, and nothing else
\ names a child home.
: _EXT4-JUA-STAGED?  ( writer -- ior )
    _EXT4-JUA-LOAD-SEALED-PRESTATE ?DUP IF EXIT THEN
    _EXT4-JUA-DIRECTORY @ _EXT4-JUA-OLD-PARENT-INO @ 0<> AND
    _EXT4-JUA-CHILD-HOME @ 0<> <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JUA-REQUIRE-INODE-AFTERIMAGES ?DUP IF EXIT THEN
    _EXT4-JUA-SOURCE-INO @ IF
        _EXT4-JUA-REQUIRE-RENAME-DIRECTORIES
    ELSE
        _EXT4-JUA-REQUIRE-DIRECTORY-AFTERIMAGE
    THEN ?DUP IF EXIT THEN
    _EXT4-JUA-CHILD-HOME @ IF
        _EXT4-JUA-REQUIRE-CHILD-AFTERIMAGE ?DUP IF EXIT THEN
    THEN
    _EXT4-JUA-REQUIRE-ORPHAN-AFTERIMAGE ?DUP IF EXIT THEN
    _EXT4-JUA-REQUIRE-SUPER-AFTERIMAGE ?DUP IF EXIT THEN
    _EXT4-JUA-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JFD-RECORD
VARIABLE _EXT4-JFD-WRITER
VARIABLE _EXT4-JFD-CTX
VARIABLE _EXT4-JFD-RAW-DESC
VARIABLE _EXT4-JFD-STAGED-DESC
VARIABLE _EXT4-JFD-RAW-GROUP-FREE
VARIABLE _EXT4-JFD-EXPECTED-GROUP-FREE
VARIABLE _EXT4-JFD-RAW-SUPER-FREE
VARIABLE _EXT4-JFD-EXPECTED-SUPER-FREE
VARIABLE _EXT4-JFD-BITMAP-CHECKSUM
VARIABLE _EXT4-JFD-COMPARE-OFF
VARIABLE _EXT4-JFD-COMPARE-LEN
VARIABLE _EXT4-JFD-RAW-GDT
VARIABLE _EXT4-JFD-STAGED-GDT
VARIABLE _EXT4-JFD-RAW-SUPER-HOME
VARIABLE _EXT4-JFD-STAGED-SUPER-HOME
VARIABLE _EXT4-JFD-RAW-SUPER
VARIABLE _EXT4-JFD-RAW-TARGET-HOME
VARIABLE _EXT4-JFD-STAGED-TARGET-HOME

: _EXT4-JFD-TARGET-HOME-EXACT?  ( -- flag )
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ 0 ?DO
        _EXT4-JFD-RAW-TARGET-HOME @ I + C@
        I _EXT4-JFI-INODE-OFF @ >=
        I _EXT4-JFI-INODE-OFF @
        _EXT4-JFD-CTX @ _EXT4-C.ISIZE + @ + U< AND IF
            DROP 0
        THEN
        _EXT4-JFD-STAGED-TARGET-HOME @ I + C@ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFD-REQUIRE-ZERO-TARGET  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JFD-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JFD-RAW-TARGET-HOME !
    _EXT4-JFI-INODE-OFF @ + _EXT4-JFI-INODE @
    _EXT4-JFD-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-TARGET-CRC !
    _EXT4-JFC-IMAGE @ _EXT4-JFD-STAGED-TARGET-HOME !
    _EXT4-JFD-TARGET-HOME-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JFD-REQUIRE-BITMAP-EXACT  ( raw staged -- ior )
    \ The raw bitmap is a transient authenticated read cache and is not used
    \ again before the next block read.  Apply its one permitted logical-bit
    \ change in place, then compare every physical byte so format padding
    \ remains authoritative.
    OVER _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @
    BITSET-BIT-CLEAR? 0= IF
        2DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFD-DESC-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-DESC @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-GDT-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-GDT @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-GDT @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

\ The bytes of a deleted directory's used-directory count, which lead the
\ ranges at 0x10 and 0x30 that a deletion keeps.
: _EXT4-JFD-USED-DIRS-SPAN  ( -- bytes )
    _EXT4-JFI-DIRECTORY @ IF 2 ELSE 0 THEN ;

: _EXT4-JFD-GDT-EXACT?  ( -- flag )
    \ Permit only the target descriptor's free-inode count, inode-bitmap
    \ checksum, and descriptor checksum, and a directory's used-directory
    \ count.  Other descriptors and page padding are just as authoritative
    \ as the target descriptor itself.
    0 _EXT4-JFI-GDT-OFF @ 0x0E + _EXT4-JFD-GDT-RANGE-UNCHANGED?
    _EXT4-JFI-GDT-OFF @ 0x10 + _EXT4-JFD-USED-DIRS-SPAN +
    0x0A _EXT4-JFD-USED-DIRS-SPAN -
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x1C + 0x02
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x20 + 0x0E
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x30 + _EXT4-JFD-USED-DIRS-SPAN +
    0x0A _EXT4-JFD-USED-DIRS-SPAN -
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x3C + DUP
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND ;

: _EXT4-JFD-SUPER-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-SUPER-HOME-EXACT?  ( -- flag )
    \ Bytes before the embedded superblock are part of block zero on 2K/4K
    \ filesystems.  Preserve them along with every super field except the
    \ free-inode count, the legacy head transition, and the checksum stamp.
    0 _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x10 +
    _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED?
    0x14
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0xE8 0x14 -
    ELSE
        0x3FC 0x14 -
    THEN
    _EXT4-JFD-SUPER-RANGE-UNCHANGED? AND
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0xEC 0x3FC 0xEC - _EXT4-JFD-SUPER-RANGE-UNCHANGED? AND
    THEN
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x400 + DUP
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED? AND ;

: _EXT4-JFD-DESC-UNCHANGED?  ( -- flag )
    \ The only semantic changes are the split free-inode counter, the split
    \ inode-bitmap checksum, and a directory's split used-directory count.
    \ The descriptor checksum is restamped.  Compare every remaining byte,
    \ including exclude-bitmap and reserved fields, instead of maintaining a
    \ permissive list of named fields.
    0x00 0x0E _EXT4-JFD-DESC-RANGE-UNCHANGED?
    0x10 _EXT4-JFD-USED-DIRS-SPAN + 0x0A _EXT4-JFD-USED-DIRS-SPAN -
    _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x1C 0x02 _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x20 0x0E _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x30 _EXT4-JFD-USED-DIRS-SPAN + 0x0A _EXT4-JFD-USED-DIRS-SPAN -
    _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x3C 0x04 _EXT4-JFD-DESC-RANGE-UNCHANGED? AND ;

\ Reconstruct the sole permitted shared-xattr transition from authenticated
\ raw media and require the retained journal image to match byte for byte.
\ This binds the staged action to h_refcount-1 and the corresponding checksum,
\ while every entry, value, hash, and reserved byte remains unchanged.
: _EXT4-JFD-REQUIRE-EA-REFDEC  ( -- ior )
    _EXT4-JFI-EA-REFDEC? 0= IF
        0 _EXT4-JFI-EA-AFTER-CRC !
        -1 _EXT4-JFI-EA-AFTER-VERIFIED ! 0 EXIT
    THEN
    _EXT4-JFI-EA @ _EXT4-JFD-CTX @ _EXT4-LOAD-XATTR-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + 4 + L@
    _EXT4-JFI-EA-REFCOUNT @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFI-EA-POST-REFCOUNT
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK + 4 + L!
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-EA @ _EXT4-JFD-CTX @ _EXT4-STAMP-XATTR-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFI-EA @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-JFC-IMAGE @
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFD-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-JFI-EA-AFTER-CRC !
    _EXT4-JFC-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
    -1 _EXT4-JFI-EA-AFTER-VERIFIED !
    0 ;

\ Rebuild raw unlinked-inode authority, then prove the complete staged
\ allocation transition: one cleared bitmap bit, its matching descriptor
\ checksum/counter update, and the matching primary-super counter update.
: _EXT4-JFD-VERIFY-EMPTY-STAGED  ( plan-record writer -- ior )
    DUP _EXT4-JFD-WRITER ! _EXT4-JFC-WRITER !
    _EXT4-JFD-RECORD !
    _EXT4-JFD-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JFD-CTX !
    _EXT4-JFI-CTX !
    _EXT4-JFD-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFD-WRITER @ _EXT4-JFI-REVOKES-EXACT? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.DESC + DUP _EXT4-JFD-RAW-DESC !
    _EXT4-JFI-DESC-FREE@ DUP _EXT4-JFD-RAW-GROUP-FREE !
    1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-EXPECTED-GROUP-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-INODES + L@
    DUP _EXT4-JFD-RAW-SUPER-FREE ! 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFD-EXPECTED-SUPER-FREE !
    _EXT4-JFD-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-BITMAP-CRC !
    _EXT4-JFC-IMAGE @ DUP
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @ BITSET-TEST? 0= IF
        2DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + SWAP
    _EXT4-JFD-REQUIRE-BITMAP-EXACT ?DUP IF EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFD-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JFD-BITMAP-CHECKSUM !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFD-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JFD-RAW-GDT !
    _EXT4-JFI-GDT-OFF @ + DUP _EXT4-JFD-RAW-DESC !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + _EXT4-DESC-SIZE
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JFI-GDT-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-GDT-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-GDT !
    _EXT4-JFI-GDT-OFF @ + _EXT4-JFD-STAGED-DESC !
    _EXT4-JFD-GDT-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-DESC-UNCHANGED? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _EXT4-JFD-BITMAP-CHECKSUM @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-DESC-FREE@
    _EXT4-JFD-EXPECTED-GROUP-FREE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-DIRECTORY @ IF
        _EXT4-JFD-STAGED-DESC @ _EXT4-DESC-USED-DIRS@ 1+
        _EXT4-JFD-RAW-DESC @ _EXT4-DESC-USED-DIRS@ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JFD-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-SUPER-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-JFC-SUPER ! DROP
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JFD-RAW-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-JFD-RAW-SUPER !
    _EXT4-JFD-CTX @ _EXT4-C.SB + 1024 _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-SUPER-HOME-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-SUPER @
    DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP 0 _EXT4-JFD-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JFD-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-SB.FREE-INODES + L@
    _EXT4-JFD-EXPECTED-SUPER-FREE @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-BLOCKS-LO + L@ <>
    OVER _EXT4-SB.FREE-BLOCKS-HI + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-BLOCKS-HI + L@ <> OR IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <>
    SWAP _EXT4-SB.RO-COMPAT + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-REQUIRE-ZERO-TARGET ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-EA-REFDEC ?DUP IF EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFC-INODE-BITMAP-HOME !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFC-INODE-GDT-HOME !
    _EXT4-JFI-GDT-OFF @ _EXT4-JFC-INODE-GDT-OFF !
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        5
    ELSE
        4
    THEN
    _EXT4-JFI-EA-REFDEC? IF 1+ THEN
    DUP _EXT4-JFD-WRITER @ _EXT4-JWR.META-CREDIT + @ <>
    OVER _EXT4-JFD-WRITER @ _EXT4-JWR.META-USED + @ <> OR
    SWAP _EXT4-JFD-WRITER @ _EXT4-JWR.META-ACTIVE + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JDD-EXPECTED
VARIABLE _EXT4-JDD-HOME
VARIABLE _EXT4-JDD-IOR
VARIABLE _EXT4-JDD-DATA-BITMAP-HOME
VARIABLE _EXT4-JDD-DATA-BITMAP-CRC
VARIABLE _EXT4-JDD-INODE-BITMAP-CRC
VARIABLE _EXT4-JDD-DATA-GDT-HOME
VARIABLE _EXT4-JDD-DATA-GDT-OFF
VARIABLE _EXT4-JDD-PAGE-GDT-HOME
VARIABLE _EXT4-JDD-PAGE-ACTIVE
VARIABLE _EXT4-JDD-INODE-GDT-DONE
VARIABLE _EXT4-JDD-DESC
VARIABLE _EXT4-JDD-FREE
VARIABLE _EXT4-JDD-CHANGED
VARIABLE _EXT4-JDD-GDT-CRC
VARIABLE _EXT4-JDD-SUPER-HOME
VARIABLE _EXT4-JDD-SUPER
VARIABLE _EXT4-JDD-EXPECTED-CREDIT
VARIABLE _EXT4-JDD-GROUP
VARIABLE _EXT4-JDD-GROUP-FIRST
VARIABLE _EXT4-JDD-GROUP-END
VARIABLE _EXT4-JDD-RANGE-INDEX
VARIABLE _EXT4-JDD-RANGE-FIRST
VARIABLE _EXT4-JDD-RANGE-COUNT
VARIABLE _EXT4-JDD-RANGE-END
VARIABLE _EXT4-JDD-CHUNK-FIRST
VARIABLE _EXT4-JDD-GROUP-RELEASED
VARIABLE _EXT4-JDD-RELEASED-TOTAL
VARIABLE _EXT4-JDD-GROUP-TOUCHED

: _EXT4-JDD-REQUIRE-EXPECTED  ( expected home -- crc ior )
    _EXT4-JDD-HOME ! _EXT4-JDD-EXPECTED !
    _EXT4-JDD-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-EXPECTED @ _EXT4-JFC-IMAGE @
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ 0 ;

: _EXT4-JDD-ADD-CREDIT  ( -- ior )
    _EXT4-JDD-EXPECTED-CREDIT @ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-EXPECTED-CREDIT !
    0 ;

: _EXT4-JDD-SET-GROUP-RANGE  ( -- ior )
    _EXT4-JDD-GROUP @ _EXT4-JFB-GROUP !
    _EXT4-JDD-GROUP @ _EXT4-JFD-CTX @ _EXT4-GROUP-BLOCK-RANGE
    _EXT4-JDD-IOR ! _EXT4-JFB-GROUP-BLOCKS !
    _EXT4-JDD-GROUP-FIRST !
    _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
    _EXT4-JDD-GROUP-FIRST @ _EXT4-JFB-GROUP-BLOCKS @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-GROUP-END !
    0 ;

\ Intersect one retained physical range with the current group.  Publish the
\ group-local bitmap index and exact overlap count only when nonempty.
: _EXT4-JDD-SELECT-RANGE-CHUNK  ( range-index -- flag ior )
    _EXT4-JFI-RELEASE-RANGE DUP @ _EXT4-JDD-RANGE-FIRST !
    CELL+ @ DUP _EXT4-JDD-RANGE-COUNT !
    _EXT4-JDD-RANGE-FIRST @ SWAP _EXT4-UADD?
    DUP IF NIP FALSE SWAP EXIT THEN DROP _EXT4-JDD-RANGE-END !
    _EXT4-JDD-RANGE-FIRST @ _EXT4-JDD-GROUP-FIRST @ MAX
    _EXT4-JDD-CHUNK-FIRST !
    _EXT4-JDD-RANGE-END @ _EXT4-JDD-GROUP-END @ MIN
    DUP _EXT4-JDD-CHUNK-FIRST @ U<
    OVER _EXT4-JDD-CHUNK-FIRST @ = OR IF
        DROP FALSE 0 EXIT
    THEN
    _EXT4-JDD-CHUNK-FIRST @ - _EXT4-JFB-CHUNK !
    _EXT4-JDD-CHUNK-FIRST @ _EXT4-JDD-GROUP-FIRST @ -
    _EXT4-JFB-INDEX !
    TRUE 0 ;

: _EXT4-JDD-GROUP-TOUCHED?  ( -- flag ior )
    _EXT4-JDD-SET-GROUP-RANGE ?DUP IF FALSE SWAP EXIT THEN
    0 _EXT4-JDD-RANGE-INDEX !
    BEGIN
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JFI-RELEASE-RANGE-COUNT U<
    WHILE
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JDD-SELECT-RANGE-CHUNK
        _EXT4-JDD-IOR ! _EXT4-JDD-GROUP-TOUCHED !
        _EXT4-JDD-IOR @ ?DUP IF FALSE SWAP EXIT THEN
        _EXT4-JDD-GROUP-TOUCHED @ IF TRUE 0 EXIT THEN
        1 _EXT4-JDD-RANGE-INDEX +!
    REPEAT
    FALSE 0 ;

\ Reconstruct one complete block-bitmap after-image for a touched group.  All
\ discontiguous target overlaps are applied to one raw copy before comparison,
\ so shared bitmap and descriptor homes are authenticated exactly once.
: _EXT4-JDD-AUTH-DATA-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JDD-IOR ! _EXT4-JDD-DATA-BITMAP-HOME !
    _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
    _EXT4-JDD-DATA-BITMAP-HOME @ _EXT4-JFB-GROUP @
    _EXT4-JFD-CTX @ _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JDD-IOR !
    _EXT4-JDD-IOR @ IF DROP _EXT4-JDD-IOR @ EXIT THEN
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @ _EXT4-JDD-DATA-GDT-HOME !
    _EXT4-GD-OFF @ _EXT4-JDD-DATA-GDT-OFF !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JDD-GROUP-RELEASED !
    0 _EXT4-JDD-RANGE-INDEX !
    BEGIN
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JFI-RELEASE-RANGE-COUNT U<
    WHILE
        _EXT4-JDD-RANGE-INDEX @ _EXT4-JDD-SELECT-RANGE-CHUNK
        _EXT4-JDD-IOR ! _EXT4-JDD-GROUP-TOUCHED !
        _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
        _EXT4-JDD-GROUP-TOUCHED @ IF
            _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JFB-GROUP-BLOCKS @
            _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-ALL-SET? 0= IF
                DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
            THEN
            0= IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
            _EXT4-JFB-GROUP-BLOCKS @
            _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @
            BITSET-RANGE-CLEAR? 0= IF
                EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JDD-GROUP-RELEASED @ _EXT4-JFB-CHUNK @ _EXT4-UADD?
            DUP IF NIP EXIT THEN DROP _EXT4-JDD-GROUP-RELEASED !
        THEN
        1 _EXT4-JDD-RANGE-INDEX +!
    REPEAT
    _EXT4-JDD-GROUP-RELEASED @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-RELEASED-TOTAL @ _EXT4-JDD-GROUP-RELEASED @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-RELEASED-TOTAL !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-BLOCK-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JDD-DATA-BITMAP-CRC !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JDD-DATA-BITMAP-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN 2DROP
    _EXT4-JDD-ADD-CREDIT ;

: _EXT4-JDD-REQUIRE-INODE-BITMAP  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JDD-IOR !
    _EXT4-JDD-IOR @ IF DROP _EXT4-JDD-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @ BITSET-TEST? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-GROUP-INODES @ _EXT4-JFI-INDEX @
    BITSET-BIT-CLEAR? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JDD-INODE-BITMAP-CRC !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JFC-INODE-BITMAP-CRC !
    0 ;

: _EXT4-JDD-MUTATE-DATA-DESC  ( descriptor -- ior )
    _EXT4-JDD-DESC !
    _EXT4-JDD-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-JFB-DESC-FREE@
    _EXT4-JDD-GROUP-RELEASED @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JDD-FREE !
    _EXT4-JFB-GROUP-BLOCKS @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-FREE @ _EXT4-JDD-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JDD-DATA-BITMAP-CRC @ _EXT4-JDD-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JDD-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFD-CTX @
    _EXT4-RESTAMP-GROUP-DESC ;

: _EXT4-JDD-MUTATE-INODE-DESC  ( descriptor -- ior )
    _EXT4-JDD-DESC !
    _EXT4-JDD-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-JFI-DESC-FREE@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JDD-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-FREE @ _EXT4-JDD-DESC @ _EXT4-JFI-DESC-FREE!
    _EXT4-JDD-INODE-BITMAP-CRC @ _EXT4-JDD-DESC @
    _EXT4-JFI-DESC-BITMAP-CRC!
    _EXT4-JFI-DIRECTORY @ IF
        _EXT4-JDD-DESC @ _EXT4-DESC-USED-DIRS@ DUP 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        1- _EXT4-JDD-DESC @ _EXT4-DESC-USED-DIRS!
    THEN
    _EXT4-JDD-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-RESTAMP-GROUP-DESC ;

\ Hold one raw primary-GDT page in DIR-BLOCK while every data-group
\ descriptor on that page is reconstructed.  This preserves exact whole-home
\ comparison when a multi-block extent crosses groups whose descriptors
\ coalesce into one journal after-image.
: _EXT4-JDD-BEGIN-GDT-PAGE  ( home -- ior )
    _EXT4-JDD-PAGE-ACTIVE @ IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JDD-PAGE-GDT-HOME !
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JDD-CHANGED !
    -1 _EXT4-JDD-PAGE-ACTIVE !
    _EXT4-JDD-PAGE-GDT-HOME @ _EXT4-JFI-GDT-HOME @ <> IF
        _EXT4-JDD-ADD-CREDIT EXIT
    THEN
    0 ;

: _EXT4-JDD-FINISH-GDT-PAGE  ( -- ior )
    _EXT4-JDD-PAGE-ACTIVE @ 0= IF 0 EXIT THEN
    _EXT4-JDD-PAGE-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = IF
        _EXT4-JDD-INODE-GDT-DONE @ IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JFI-GDT-OFF @ + _EXT4-JDD-MUTATE-INODE-DESC
        ?DUP IF EXIT THEN
        -1 _EXT4-JDD-CHANGED !
        -1 _EXT4-JDD-INODE-GDT-DONE !
    THEN
    _EXT4-JDD-CHANGED @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-PAGE-GDT-HOME @
    _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-GDT-CRC !
    _EXT4-JDD-PAGE-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = IF
        _EXT4-JDD-GDT-CRC @ _EXT4-JFC-INODE-GDT-CRC !
    THEN
    0 _EXT4-JDD-PAGE-ACTIVE !
    0 ;

: _EXT4-JDD-REQUIRE-DATA-GDT  ( -- ior )
    _EXT4-JDD-PAGE-ACTIVE @ 0= IF
        _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JDD-BEGIN-GDT-PAGE
        ?DUP IF EXIT THEN
    ELSE
        _EXT4-JDD-DATA-GDT-HOME @
        _EXT4-JDD-PAGE-GDT-HOME @ <> IF
            _EXT4-JDD-DATA-GDT-HOME @
            _EXT4-JDD-PAGE-GDT-HOME @ U< IF
                EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JDD-FINISH-GDT-PAGE ?DUP IF EXIT THEN
            _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JDD-BEGIN-GDT-PAGE
            ?DUP IF EXIT THEN
        THEN
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-DATA-GDT-OFF @ + _EXT4-JDD-MUTATE-DATA-DESC
    ?DUP IF EXIT THEN
    -1 _EXT4-JDD-CHANGED !
    0 ;

: _EXT4-JDD-REQUIRE-DATA-PAGES  ( -- ior )
    0 _EXT4-JDD-PAGE-ACTIVE !
    0 _EXT4-JDD-INODE-GDT-DONE !
    0 _EXT4-JDD-RELEASED-TOTAL !
    0 _EXT4-JDD-GROUP !
    BEGIN
        _EXT4-JDD-GROUP @ _EXT4-JFD-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JDD-GROUP-TOUCHED?
        _EXT4-JDD-IOR ! _EXT4-JDD-GROUP-TOUCHED !
        _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
        _EXT4-JDD-GROUP-TOUCHED @ IF
            _EXT4-JDD-AUTH-DATA-GROUP ?DUP IF EXIT THEN
            _EXT4-JDD-REQUIRE-DATA-GDT ?DUP IF EXIT THEN
        THEN
        1 _EXT4-JDD-GROUP +!
    REPEAT
    _EXT4-JDD-RELEASED-TOTAL @ _EXT4-JFI-RELEASE-BLOCKS <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-FINISH-GDT-PAGE ?DUP IF EXIT THEN
    _EXT4-JDD-INODE-GDT-DONE @ 0= IF
        _EXT4-JFI-GDT-HOME @ _EXT4-JDD-BEGIN-GDT-PAGE
        ?DUP IF EXIT THEN
        _EXT4-JDD-FINISH-GDT-PAGE ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JDD-REQUIRE-SUPER  ( -- ior )
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP
    _EXT4-JDD-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    _EXT4-JFD-CTX @ _EXT4-C.SB + 1024 _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF + _EXT4-JDD-SUPER !
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFI-RELEASE-BLOCKS
    _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-INODES + L@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-CTX @ _EXT4-C.INODES + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        _EXT4-JDD-SUPER @ _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JFD-RECORD @ _EXT4-OE.INO + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFD-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-JDD-SUPER @ _EXT4-SB.LAST-ORPHAN + L!
    THEN
    _EXT4-JDD-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JDD-SUPER @ _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ 0 _EXT4-JFD-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-SUPER @ _EXT4-JFD-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-SUPER-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JFC-INODE-SUPER-CRC !
    0 ;


: _EXT4-JDD-VERIFY-STAGED  ( -- ior )
    _EXT4-JFI-RANGE-COUNT _EXT4-JFI-RANGE-CAP U>
    _EXT4-JFI-RELEASE-RANGE-COUNT 0= OR
    _EXT4-JFI-RELEASE-BLOCKS 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        5
    ELSE
        4
    THEN _EXT4-JDD-EXPECTED-CREDIT !
    _EXT4-JDD-REQUIRE-INODE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JDD-REQUIRE-DATA-PAGES ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-EA-REFDEC ?DUP IF EXIT THEN
    _EXT4-JFI-EA-REFDEC? IF
        _EXT4-JDD-ADD-CREDIT ?DUP IF EXIT THEN
    THEN
    _EXT4-JDD-REQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-ZERO-TARGET ?DUP IF EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFC-INODE-BITMAP-HOME !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFC-INODE-GDT-HOME !
    _EXT4-JFI-GDT-OFF @ _EXT4-JFC-INODE-GDT-OFF !
    \ A deletion folded into a release pass holds exactly these homes in a
    \ transaction of the pass's capacity, with a cancelled entry for each
    \ tree node the pass edited and then freed.
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JDD-EXPECTED-CREDIT @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-DATA-MAP-KIND @ _EXT4-JDM-RELEASED = IF
        _EXT4-JFD-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JFD-WRITER @ _EXT4-JWR.META-CREDIT + @ U>
    ELSE
        _EXT4-JFD-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JDD-EXPECTED-CREDIT @ <>
        _EXT4-JFD-WRITER @ _EXT4-JWR.META-CREDIT + @
        _EXT4-JDD-EXPECTED-CREDIT @ <> OR
    THEN IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ A deletion folded into a release pass carries the runs it freed in its
\ certificate, from which checkpoint verification rebuilds the vector in
\ the mutation range workspace.
: _EXT4-JFI-USE-CP-RUNS  ( writer -- ior )
    DUP _EXT4-JWR.CTX + @ _EXT4-JFI-CTX !
    FALSE _EXT4-JFI-RELEASED !
    DUP _EXT4-JWR.CP-DATA-MAP-KIND + @ _EXT4-JDM-RELEASED <> IF
        DROP 0 EXIT
    THEN
    DUP _EXT4-JWR.CP-DELETE-RANGE-COUNT + @
    DUP _EXT4-JFI-RANGE-CAP U> IF 2DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-RELEASED-RUNS !
    DUP _EXT4-JWR.CP-DELETE-BLOCKS + @ _EXT4-JFI-RELEASED-BLOCKS !
    _EXT4-JFI-RELEASED-RUNS @ 0 ?DO
        I OVER _EXT4-JWR-CP-DELETE-RANGE DUP @ SWAP CELL+ @
        I _EXT4-JFI-RANGE CELL+ ! I _EXT4-JFI-RANGE !
    LOOP
    DROP TRUE _EXT4-JFI-RELEASED ! 0 ;

: _EXT4-JFD-VERIFY-STAGED  ( plan-record writer -- ior )
    _EXT4-JFD-WRITER ! _EXT4-JFD-RECORD !
    _EXT4-JFD-WRITER @ _EXT4-JFC-WRITER !
    _EXT4-JFD-WRITER @ _EXT4-JWR.CTX + @ DUP
    _EXT4-JFD-CTX ! _EXT4-JFI-CTX !
    _EXT4-JFD-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-RELEASE-RANGE-COUNT IF _EXT4-JDD-VERIFY-STAGED EXIT THEN
    _EXT4-JFD-RECORD @ _EXT4-JFD-WRITER @
    _EXT4-JFD-VERIFY-EMPTY-STAGED ;

: _EXT4-JFC-FAIL  ( ior -- ior )
    _EXT4-JFC-IOR ! FALSE _EXT4-JFI-RELEASED !
    _EXT4-JFC-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = IF
        DROP _EXT4-JFC-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JFC-ABORT-IOR ! IF
            _EXT4-JFC-ABORT-IOR @ _EXT4-JFC-WRITER @
            _EXT4-JWR-LATCH-FAULT DROP
        THEN
    ELSE
        DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
            _EXT4-JFC-IOR @ _EXT4-JFC-WRITER @
            _EXT4-JWR-LATCH-FAULT DROP
        THEN
    THEN
    _EXT4-JFC-IOR @ ;

VARIABLE _EXT4-SMO-RECORD
VARIABLE _EXT4-SMO-CTX
VARIABLE _EXT4-SMO-KIND

\ Require the exact record selected by the recovery order before dereferencing
\ any of its fields.  A legacy mutation may remove only the current raw list
\ head.  Modern records are selected only after that chain is empty; their
\ locator order is imposed by the selector below rather than hash placement.
: _EXT4-REQUIRE-SELECTED-ORPHAN
  ( plan-record ctx -- ior )
    _EXT4-SMO-CTX ! _EXT4-SMO-RECORD !
    _EXT4-SMO-RECORD @ 0= _EXT4-SMO-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-SMO-CTX @ _EXT4-C.O.ACTIVE + @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SMO-RECORD @ _EXT4-SMO-CTX @
    _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SMO-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-SMO-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-SMO-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ 0=
        _EXT4-SMO-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0<> OR IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.SB + DUP
        _EXT4-SB.LAST-ORPHAN + L@ IF
            DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SB.RO-COMPAT + L@ _EXT4-RO-ORPHAN-PRESENT AND 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
            I _EXT4-SMO-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
                DUP _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
                    DUP _EXT4-OE.LOCATOR-A + @
                    _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-A + @ U<
                    OVER _EXT4-OE.LOCATOR-A + @
                    _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-A + @ =
                    2 PICK _EXT4-OE.LOCATOR-B + @
                    _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-B + @ U< AND OR IF
                        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                        UNLOOP EXIT
                    THEN
                THEN
            THEN
            DROP
        LOOP
    ELSE
        _EXT4-SMO-KIND @ _EXT4-OK-LEGACY <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-B + @ IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-SMO-RECORD @ _EXT4-OE.INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-SMO-RECORD @ _EXT4-SMO-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ;

: _EXT4-JFC-REQUIRE-SELECTED  ( -- ior )
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ;

VARIABLE _EXT4-JLH-RECORD
VARIABLE _EXT4-JLH-WRITER
VARIABLE _EXT4-JLH-CTX
VARIABLE _EXT4-JLH-INO
VARIABLE _EXT4-JLH-NEXT
VARIABLE _EXT4-JLH-IMAGE
VARIABLE _EXT4-JLH-SUPER
VARIABLE _EXT4-JLH-HOME

\ Advance the current legacy-list head to its authenticated retained successor
\ in the transaction-aware primary-super after-image.  Block-free accounting
\ may have edited this same super image first; acquire composes with and
\ reauthenticates that edit.
: _EXT4-JTX-ADVANCE-LEGACY-HEAD
  ( plan-record transaction -- ior )
    _EXT4-JLH-WRITER ! _EXT4-JLH-RECORD !
    _EXT4-JLH-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JLH-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JLH-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JLH-CTX !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JLH-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JLH-RECORD @ _EXT4-JLH-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JLH-RECORD @ _EXT4-OE.INO + @ _EXT4-JLH-INO !
    _EXT4-JLH-RECORD @ _EXT4-OE.LOCATOR-A + @ _EXT4-JLH-NEXT !
    _EXT4-JLH-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-JLH-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JLH-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JLH-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JLH-IMAGE !
    _EXT4-JLH-HOME @ _EXT4-JLH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JLH-INO @ <> IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JLH-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JLH-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JLH-NEXT @ _EXT4-JLH-SUPER @ _EXT4-SB.LAST-ORPHAN + L!
    _EXT4-JLH-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JLH-IMAGE @ _EXT4-JLH-HOME @ _EXT4-JLH-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JCM-RECORD
VARIABLE _EXT4-JCM-CTX
VARIABLE _EXT4-JCM-ORPHAN-HOME
VARIABLE _EXT4-JCM-INODE-HOME
VARIABLE _EXT4-JCM-SUPER-HOME
VARIABLE _EXT4-JCM-GROUP
VARIABLE _EXT4-JCM-GROUP-FIRST
VARIABLE _EXT4-JCM-GROUP-COUNT
VARIABLE _EXT4-JCM-RANGE-INDEX
VARIABLE _EXT4-JCM-TOUCHED
VARIABLE _EXT4-JCM-BITMAP-HOME
VARIABLE _EXT4-JCM-GDT-HOME
VARIABLE _EXT4-JCM-PREV-GDT
VARIABLE _EXT4-JCM-HAVE-GDT
VARIABLE _EXT4-JCM-HAVE-GROUP
VARIABLE _EXT4-JCM-CREDIT
VARIABLE _EXT4-JCM-IOR
VARIABLE _EXT4-JCM-KIND
VARIABLE _EXT4-JCM-DELETE

: _EXT4-JCM-RANGE-COUNT  ( -- count )  _EXT4-JFI-RELEASE-RANGE-COUNT ;

: _EXT4-JCM-RANGE  ( index -- pair-address )  _EXT4-JFI-RELEASE-RANGE ;

: _EXT4-JCM-GROUP-TOUCHED?  ( group -- flag ior )
    DUP _EXT4-JCM-GROUP ! _EXT4-JCM-CTX @ _EXT4-GROUP-BLOCK-RANGE
    _EXT4-JCM-IOR ! _EXT4-JCM-GROUP-COUNT !
    _EXT4-JCM-GROUP-FIRST !
    _EXT4-JCM-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    0 _EXT4-JCM-RANGE-INDEX !
    BEGIN
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JCM-RANGE-COUNT U<
    WHILE
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JCM-RANGE DUP @
        SWAP CELL+ @
        _EXT4-JCM-GROUP-FIRST @ _EXT4-JCM-GROUP-COUNT @
        URANGE-OVERLAP? 0= IF
            DROP FALSE EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        IF TRUE 0 EXIT THEN
        1 _EXT4-JCM-RANGE-INDEX +!
    REPEAT
    FALSE 0 ;

: _EXT4-JCM-ADD-CREDIT  ( -- ior )
    _EXT4-JCM-CREDIT @ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JCM-CREDIT !
    0 ;

: _EXT4-JCM-GROUP-HOMES-DISJOINT?  ( -- flag )
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-GDT-HOME @ =
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-INODE-HOME @ = OR
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-INODE-HOME @ = OR
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-SUPER-HOME @ = OR IF FALSE EXIT THEN
    _EXT4-JCM-DELETE @ IF
        _EXT4-JCM-BITMAP-HOME @ _EXT4-JFI-BITMAP-HOME @ =
        _EXT4-JCM-BITMAP-HOME @ _EXT4-JFI-GDT-HOME @ = OR
        _EXT4-JCM-GDT-HOME @ _EXT4-JFI-BITMAP-HOME @ = OR IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-ORPHAN-HOME @ =
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-ORPHAN-HOME @ = OR 0= ;

: _EXT4-JCM-DELETE-HOMES-DISJOINT?  ( -- flag )
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-GDT-HOME @ =
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JFI-GDT-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JFI-GDT-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JCM-SUPER-HOME @ _EXT4-JFI-INODE-HOME @ = OR IF
        FALSE EXIT
    THEN
    _EXT4-JFI-EA @ ?DUP IF
        DUP _EXT4-JFI-BITMAP-HOME @ =
        OVER _EXT4-JFI-GDT-HOME @ = OR
        OVER _EXT4-JCM-SUPER-HOME @ = OR
        SWAP _EXT4-JFI-INODE-HOME @ = OR IF FALSE EXIT THEN
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-BITMAP-HOME @ =
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-GDT-HOME @ = OR
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JFI-EA @ IF
        _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-EA @ = OR
    THEN 0= ;

: _EXT4-JCM-VALIDATE-RANGES  ( -- ior )
    _EXT4-JFI-RANGE-COUNT IF
        _EXT4-JFI-RANGES _EXT4-JFI-RANGE-COUNT
        _EXT4-JFI-RANGE-CAP
        _EXT4-JCM-CTX @ _EXT4-VALIDATE-MUTATION-RANGES-TARGETS
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-EA @ 1 _EXT4-JCM-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JCM-COUNT-GROUP-HOMES  ( -- ior )
    0 _EXT4-JCM-GROUP !
    0 _EXT4-JCM-HAVE-GDT !
    0 _EXT4-JCM-HAVE-GROUP !
    BEGIN
        _EXT4-JCM-GROUP @ _EXT4-JCM-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JCM-GROUP @ _EXT4-JCM-GROUP-TOUCHED?
        _EXT4-JCM-IOR ! _EXT4-JCM-TOUCHED !
        _EXT4-JCM-IOR @ ?DUP IF EXIT THEN
        _EXT4-JCM-TOUCHED @ IF
            -1 _EXT4-JCM-HAVE-GROUP !
            _EXT4-JCM-GROUP @ _EXT4-JCM-CTX @
            _EXT4-LOAD-BLOCK-BITMAP
            _EXT4-JCM-IOR ! _EXT4-JCM-BITMAP-HOME !
            _EXT4-JCM-IOR @ ?DUP IF EXIT THEN
            _EXT4-GD-BLOCK @ _EXT4-JCM-GDT-HOME !
            _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-GROUP @
            _EXT4-JCM-CTX @ _EXT4-VALIDATE-BLOCK-BITMAP-HOME
            ?DUP IF EXIT THEN
            _EXT4-JCM-GROUP-HOMES-DISJOINT? 0= IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
            _EXT4-JCM-DELETE @
            _EXT4-JCM-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = AND 0= IF
                _EXT4-JCM-HAVE-GDT @ IF
                    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT @ U< IF
                        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
                    THEN
                    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT @ <> IF
                        _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
                    THEN
                ELSE
                    _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
                    -1 _EXT4-JCM-HAVE-GDT !
                THEN
                _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT !
            THEN
        THEN
        1 _EXT4-JCM-GROUP +!
    REPEAT
    _EXT4-JCM-HAVE-GROUP @ 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Derive the exact coalesced metadata-home credit for one authenticated orphan
\ cleanup.  Every delete includes the zeroed inode-table block,
\ inode bitmap, primary GDT, primary superblock, and (for modern authority)
\ orphan-file block.  Any released data or external-xattr allocation adds one
\ uniquely owned block bitmap per touched group and one primary GDT block per
\ distinct descriptor page.
\ The group scan is constant-space and imposes no policy capacity beyond the
\ authenticated filesystem geometry.

: _EXT4-JCM-MEASURE-DELETE-AUTHENTICATED  ( -- meta-credit ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JCM-INODE-HOME !
    _EXT4-JCM-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCM-SUPER-HOME !
    _EXT4-JCM-DELETE-HOMES-DISJOINT? 0= IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF 5 ELSE 4 THEN
    _EXT4-JCM-CREDIT !
    _EXT4-JFI-EA-REFDEC? IF
        _EXT4-JCM-ADD-CREDIT ?DUP IF 0 SWAP EXIT THEN
    THEN
    _EXT4-JFI-RELEASE-RANGE-COUNT 0= IF
        _EXT4-JCM-CREDIT @ 0 EXIT
    THEN
    _EXT4-JCM-VALIDATE-RANGES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-COUNT-GROUP-HOMES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-CREDIT @ 0 ;

: _EXT4-JCM-MEASURE-DELETE  ( -- meta-credit ior )
    FALSE _EXT4-JFI-RELEASED !
    _EXT4-JCM-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JCM-CTX @ _EXT4-JFI-CTX !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-MEASURE-DELETE-AUTHENTICATED ;

VARIABLE _EXT4-JPU-ORPHAN-HOME
VARIABLE _EXT4-JPU-INO
VARIABLE _EXT4-JPU-GEN
VARIABLE _EXT4-JPU-CTX

: _EXT4-MEASURE-PROSPECTIVE-UNLINK-CLEANUP
  ( orphan-home inode-number expected-generation ctx -- meta-credit revoke-credit ior )
    _EXT4-JPU-CTX ! _EXT4-JPU-GEN ! _EXT4-JPU-INO !
    _EXT4-JPU-ORPHAN-HOME !
    _EXT4-JPU-CTX @ 0= IF 0 0 VFS-E-INVALID EXIT THEN
    _EXT4-JPU-ORPHAN-HOME @ 1 _EXT4-JPU-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS
    ?DUP IF 0 0 ROT EXIT THEN
    _EXT4-JPU-INO @ _EXT4-JPU-GEN @ _EXT4-JPU-CTX @
    _EXT4-JFI-AUTH-PROSPECTIVE ?DUP IF 0 0 ROT EXIT THEN
    _EXT4-JPU-CTX @ _EXT4-JCM-CTX !
    _EXT4-OK-MODERN _EXT4-JCM-KIND !
    -1 _EXT4-JCM-DELETE !
    _EXT4-JPU-ORPHAN-HOME @ _EXT4-JCM-ORPHAN-HOME !
    _EXT4-JCM-MEASURE-DELETE-AUTHENTICATED
    DUP IF NIP 0 0 ROT EXIT THEN
    DROP _EXT4-JFI-REVOKE-COUNT 0 ;

: _EXT4-JCM-MEASURE-ORPHAN-META
  ( plan-record ctx -- meta-credit ior )
    _EXT4-JCM-CTX ! _EXT4-JCM-RECORD !
    _EXT4-JCM-RECORD @ 0= _EXT4-JCM-CTX @ 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JCM-RECORD @ _EXT4-JCM-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-RECORD @ _EXT4-OE.KIND + @ _EXT4-JCM-KIND !
    _EXT4-JCM-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0=
    _EXT4-JCM-DELETE !
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JCM-RECORD @ _EXT4-JOS-RECORD !
        _EXT4-JCM-CTX @ _EXT4-JOS-CTX !
        _EXT4-JOS-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
        _EXT4-JOS-HOME @ _EXT4-JCM-ORPHAN-HOME !
    ELSE
        0 _EXT4-JCM-ORPHAN-HOME !
        _EXT4-JCM-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
        ?DUP IF 0 SWAP EXIT THEN
    THEN
    _EXT4-JCM-DELETE @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JCM-MEASURE-DELETE ;

\ Release passes free a record's blocks from the end of its extent tree, at
\ any depth, with the general write's tree code, which is defined later: a
\ linked record's blocks past EOF, and every block of an unlinked record
\ before its inode is deleted.  The step stages either one sealed release
\ pass, answering TRUE, or the target's part of a linked record's final
\ cleanup, answering FALSE.  The measure answers the credits of the
\ record's next transaction.
VARIABLE _EXT4-ORPHAN-STEP-XT     \ ( plan-record transaction -- release? ior )
VARIABLE _EXT4-ORPHAN-MEASURE-XT  \ ( plan-record ctx -- meta revoke ior )

\ True when the loaded inode is an unlinked regular file or directory
\ whose map still maps blocks, which release passes free before the inode
\ itself is deleted.
: _EXT4-UNLINKED-RELEASE?  ( ctx -- flag )
    _EXT4-C.INODE + DUP _EXT4-I.LINKS + W@ IF DROP FALSE EXIT THEN
    DUP _EXT4-I.MODE + W@ 0xF000 AND
    DUP 0x8000 <> SWAP 0x4000 <> AND IF DROP FALSE EXIT THEN
    _EXT4-MAP-MAPS? ;

: _EXT4-MEASURE-ORPHAN-CLEANUP
  ( plan-record ctx -- meta-credit revoke-credit ior )
    2DUP _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF NIP NIP 0 0 ROT EXIT THEN
    DUP _EXT4-C.INODE + _EXT4-I.LINKS + W@
    OVER _EXT4-UNLINKED-RELEASE? OR IF
        0 _EXT4-JCM-DELETE !
        _EXT4-ORPHAN-MEASURE-XT @ EXECUTE EXIT
    THEN
    _EXT4-JCM-MEASURE-ORPHAN-META
    DUP IF NIP 0 0 ROT EXIT THEN
    DROP _EXT4-JFI-REVOKE-COUNT 0 ;

: _EXT4-JFC-SEAL-MODERN-PROTOCOL  ( -- ior )
    _EXT4-JFC-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFC-LOGICAL @ _EXT4-JFC-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JFC-O-HOME !
    _EXT4-OV-GEN @ _EXT4-JFC-O-GEN !
    _EXT4-JFC-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-SLOT @ 4 * + L@
    _EXT4-JFC-INO @ <> IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-SLOT @ 4 * + L@ IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-O-HOME @
    _EXT4-JFC-CTX @ _EXT4-C.ORPHAN-INO + @ _EXT4-JFC-O-GEN @
    _EXT4-JFC-CTX @ _EXT4-ORPHAN-BLOCK-CHECKSUM?
    ?DUP IF NIP EXIT THEN 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-ORPHAN-CRC !
    _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
        _EXT4-JCPM-ORPHAN-MODERN-FINAL
    ELSE
        _EXT4-JCPM-ORPHAN-MODERN-MORE
    THEN _EXT4-JFC-MODE !
    0 ;

: _EXT4-JFC-SEAL-LEGACY-PROTOCOL  ( -- ior )
    0 _EXT4-JFC-SLOT !
    _EXT4-JFC-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFC-O-HOME !
    _EXT4-JPS-RAW-CRC @ _EXT4-JFC-O-GEN !
    _EXT4-JPS-RAW @ _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-INO @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JPS-SUPER @ DUP _EXT4-JFC-SUPER !
    _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-LOGICAL @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JFC-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JFC-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-LOGICAL @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-ORPHAN-CRC !
    _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
        _EXT4-JCPM-ORPHAN-LEGACY-FINAL
    ELSE
        _EXT4-JCPM-ORPHAN-LEGACY-MORE
    THEN _EXT4-JFC-MODE !
    0 ;

VARIABLE _EXT4-JIE-PRE
VARIABLE _EXT4-JIE-AFTER
VARIABLE _EXT4-JIE-ISIZE

\ The checksum of one ISIZE-byte inode record, as a pre-image certificate.
: _EXT4-RECORD-CRC  ( record ctx -- crc ior )
    _EXT4-C.ISIZE + @ 0xFFFFFFFF _EXT4-CRC-START _EXT4-CRC-ADD
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-CRC@ 0 ;

\ True when the records at _EXT4-JIE-PRE and _EXT4-JIE-AFTER agree in the
\ bytes from FROM up to TO, clipped to the record size.
: _EXT4-JIE=?  ( from to -- flag )
    _EXT4-JIE-ISIZE @ MIN OVER - DUP 0> 0= IF 2DROP TRUE EXIT THEN
    >R DUP _EXT4-JIE-PRE @ + SWAP _EXT4-JIE-AFTER @ + R> _EXT4-BYTES=? ;

\ A release pass changes only the target's block count, its extent root and
\ the record checksum.
: _EXT4-JIE-RELEASE?  ( -- flag )
    0 _EXT4-I.BLOCKS-LO _EXT4-JIE=?
    _EXT4-I.FLAGS _EXT4-I.BLOCK _EXT4-JIE=? AND
    _EXT4-I.GENERATION _EXT4-I.BLOCKS-HI _EXT4-JIE=? AND
    _EXT4-I.FILE-ACL-HI _EXT4-I.CSUM-LO _EXT4-JIE=? AND
    _EXT4-I.CSUM-LO 2 + _EXT4-I.CSUM-HI _EXT4-JIE=? AND
    _EXT4-I.CSUM-HI 2 + _EXT4-NONNEG-MAX _EXT4-JIE=? AND ;

\ A linked record's final cleanup changes its target's block count and
\ extent root when it also ends the release, and clears a legacy record's
\ successor link, which it keeps in i_dtime.
: _EXT4-JIE-FINAL?  ( successor? -- flag )
    IF
        _EXT4-JIE-AFTER @ _EXT4-I.DTIME + L@ IF FALSE EXIT THEN
        0 _EXT4-I.DTIME _EXT4-JIE=?
        _EXT4-I.DTIME 4 + _EXT4-I.BLOCKS-LO _EXT4-JIE=? AND
    ELSE
        0 _EXT4-I.BLOCKS-LO _EXT4-JIE=?
    THEN
    _EXT4-I.FLAGS _EXT4-I.BLOCK _EXT4-JIE=? AND
    _EXT4-I.GENERATION _EXT4-I.BLOCKS-HI _EXT4-JIE=? AND
    _EXT4-I.FILE-ACL-HI _EXT4-I.CSUM-LO _EXT4-JIE=? AND
    _EXT4-I.CSUM-LO 2 + _EXT4-I.CSUM-HI _EXT4-JIE=? AND
    _EXT4-I.CSUM-HI 2 + _EXT4-NONNEG-MAX _EXT4-JIE=? AND ;

VARIABLE _EXT4-JFT-HOME
VARIABLE _EXT4-JFT-AT
VARIABLE _EXT4-JFT-WRITER
VARIABLE _EXT4-JFT-CTX

\ The staged image of HOME, the block that holds EOF at SIZE, keeps the
\ bytes before EOF and zeroes the rest.  Those bytes lie past the committed
\ size, so no reader sees them before or after the transaction.
: _EXT4-JFC-TAIL-STAGED?  ( home size writer -- ior )
    DUP _EXT4-JFT-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JFT-CTX !
    _EXT4-JFT-CTX @ _EXT4-C.BSIZE + @ MOD DUP _EXT4-JFT-AT !
    0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JFT-HOME ! _EXT4-JFT-WRITER @ _EXT4-JFC-FIND-META
    ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFT-HOME @ _EXT4-JFT-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFT-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-IMAGE @
    _EXT4-JFT-AT @ _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFT-AT @ +
    _EXT4-JFT-CTX @ _EXT4-C.BSIZE + @ _EXT4-JFT-AT @ -
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JFC-TAIL-HOME
VARIABLE _EXT4-JFC-PRE-CRC
VARIABLE _EXT4-JFC-SIZE

\ A linked record's final cleanup runs once nothing past its target's EOF
\ is mapped.  It stages the target when it also ends the release or clears
\ a legacy record's successor link, and the stager may have zeroed the
\ bytes past EOF in _EXT4-JFC-TAIL-HOME.  Seal the target's pre-image
\ checksum, read from its inode-table home, and both images.
: _EXT4-JFC-SUCCESSOR?  ( -- flag )
    _EXT4-JFC-KIND @ _EXT4-OK-LEGACY = _EXT4-JFC-LOGICAL @ 0<> AND ;

: _EXT4-JFC-LINKED-SEAL  ( -- ior )
    _EXT4-JFC-FOUND @ IF
        _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-TARGET-CRC !
        _EXT4-JFC-IMAGE @ _EXT4-JFC-TARGET-OFF @ + _EXT4-JIE-AFTER !
    ELSE
        _EXT4-JFC-SUCCESSOR? IF VFS-E-CORRUPT EXIT THEN
        0 _EXT4-JFC-TARGET-CRC !
        0 _EXT4-JIE-AFTER !
    THEN
    _EXT4-JFC-TARGET-HOME @ _EXT4-JFC-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFC-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-TARGET-OFF @ +
    DUP _EXT4-JIE-PRE !
    DUP _EXT4-I.SIZE-LO + L@ OVER _EXT4-I.SIZE-HI + L@ 32 LSHIFT OR
    _EXT4-JFC-SIZE !
    _EXT4-JFC-CTX @ _EXT4-RECORD-CRC ?DUP IF NIP EXIT THEN
    _EXT4-JFC-PRE-CRC !
    _EXT4-JFC-CTX @ _EXT4-C.ISIZE + @ _EXT4-JIE-ISIZE !
    _EXT4-JIE-AFTER @ IF
        _EXT4-JFC-SUCCESSOR? _EXT4-JIE-FINAL? 0= IF VFS-E-CORRUPT EXIT THEN
    THEN
    _EXT4-JFC-TAIL-HOME @ ?DUP IF
        _EXT4-JFC-SIZE @ _EXT4-JFC-WRITER @ _EXT4-JFC-TAIL-STAGED?
        ?DUP IF EXIT THEN
    THEN
    0 ;

: _EXT4-JFC-SEAL  ( -- ior )
    0 _EXT4-JFC-INODE-BITMAP-HOME !
    0 _EXT4-JFC-INODE-BITMAP-CRC !
    0 _EXT4-JFC-INODE-GDT-HOME !
    0 _EXT4-JFC-INODE-GDT-OFF !
    0 _EXT4-JFC-INODE-GDT-CRC !
    0 _EXT4-JFC-INODE-SUPER-CRC !
    0 _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EA-ACTION + !
    0 _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + !
    0 _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EA-CRC + !
    _EXT4-JFC-WRITER @ _EXT4-JWR-ZERO-CP-DELETE-RANGES
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT +
    _EXT4-JWR.CP-PRE-ACTIVE _EXT4-JWR.CP-DELETE-RANGE-COUNT - 0 FILL
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-OE.KIND + @ _EXT4-JFC-KIND !
    _EXT4-JFC-CTX @ _EXT4-C.INODE +
    _EXT4-I.LINKS + W@ 0= _EXT4-JFC-DELETE !
    _EXT4-JFC-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.GENERATION + L@ _EXT4-JFC-TARGET-GEN !
    _EXT4-JFC-DELETE @ IF
        DROP 0 _EXT4-JFC-TARGET-ENTRIES !
    ELSE
        _EXT4-ROOT-ENTRIES _EXT4-JFC-TARGET-ENTRIES !
    THEN
    _EXT4-IR-BLOCK @ _EXT4-JFC-TARGET-HOME !
    _EXT4-IR-OFF @ _EXT4-JFC-TARGET-OFF !
    _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JFC-SEAL-MODERN-PROTOCOL ?DUP IF EXIT THEN
    ELSE
        _EXT4-JFC-KIND @ _EXT4-OK-LEGACY <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-SEAL-LEGACY-PROTOCOL ?DUP IF EXIT THEN
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
        _EXT4-JFD-VERIFY-STAGED ?DUP IF EXIT THEN
        _EXT4-JFI-INODE-HOME @ _EXT4-JFC-TARGET-HOME @ <>
        _EXT4-JFI-INODE-OFF @ _EXT4-JFC-TARGET-OFF @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@
        _EXT4-JFC-TARGET-GEN @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFI-DATA-ENTRIES @ _EXT4-JFC-TARGET-ENTRIES !
        _EXT4-JFC-WRITER @ _EXT4-JFI-STORE-CP-RANGES
    THEN
    _EXT4-JFC-TARGET-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JFC-TARGET-CRC @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JFC-TARGET-OFF @ +
        _EXT4-JFC-CTX @ _EXT4-C.ISIZE + @
        _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-JFC-LINKED-SEAL ?DUP IF EXIT THEN
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFI-RANGE-COUNT IF
            _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-MORE
                THEN
            ELSE
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-MORE
                THEN
            THEN
        ELSE
            _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-MODERN-DELETE-MORE
                THEN
            ELSE
                _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @ 1 = IF
                    _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL
                ELSE
                    _EXT4-JCPM-ORPHAN-LEGACY-DELETE-MORE
                THEN
            THEN
        THEN _EXT4-JFC-MODE !
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.EPOCH + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EPOCH + !
    _EXT4-JFC-INO @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-INO + !
    _EXT4-JFC-LOGICAL @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-LOGICAL + !
    _EXT4-JFC-SLOT @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-SLOT + !
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-HOME + !
    _EXT4-JFC-O-GEN @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-GEN + !
    _EXT4-JFC-TARGET-GEN @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-GEN + !
    _EXT4-JFC-TARGET-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-HOME + !
    _EXT4-JFC-TARGET-OFF @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-OFF + !
    _EXT4-JFC-TARGET-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-CRC + !
    _EXT4-JFC-ORPHAN-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + !
    _EXT4-JFC-TARGET-ENTRIES @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + !
    _EXT4-JFC-INODE-BITMAP-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + !
    _EXT4-JFC-INODE-BITMAP-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + !
    _EXT4-JFC-INODE-GDT-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + !
    _EXT4-JFC-INODE-GDT-OFF @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + !
    _EXT4-JFC-INODE-GDT-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + !
    _EXT4-JFC-INODE-SUPER-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + !
    _EXT4-JFC-DELETE @ 0= IF
        _EXT4-JFC-TAIL-HOME @
        _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TAIL-HOME + !
        _EXT4-JFC-PRE-CRC @
        _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-PRE-CRC + !
    THEN
    _EXT4-JFC-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + !
    _EXT4-JFC-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-PRE-MODERN + !
    _EXT4-JFC-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + !
    _EXT4-JFC-MODE @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-MODE + !
    _EXT4-JFC-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF
        _EXT4-JFC-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ A deletion frees the target's map and, when no other inode names it, its
\ xattr block.
: _EXT4-JFI-MAP-CHECK  ( -- ior )
    _EXT4-JFI-CTX @ _EXT4-JFI-WRITER @ _EXT4-NMC-BEGIN ?DUP IF EXIT THEN
    _EXT4-JFI-INO @ _EXT4-JFI-INODE-HOME @ _EXT4-JFI-INODE-OFF @
    _EXT4-NMC-FREED _EXT4-NMC-OLD
    _EXT4-JFI-EA @ IF
        _EXT4-JFI-EA-RELEASE? IF _EXT4-JFI-EA @ _EXT4-NMC-CLAIM-BLOCK THEN
    THEN
    _EXT4-NMC-BITMAPS
    _EXT4-NMC-END ;

\ Own one initially empty transaction, compose one selected orphan cleanup
\ and protocol-removal afterimage, then freeze it behind an exact pre-union
\ certificate.  Emit and abort remain legal; every later mutation is rejected
\ by _EXT4-JTX-MUTABLE?.
: _EXT4-JTX-STAGE-ORPHAN-CLEANUP
  ( plan-record transaction -- ior )
    _EXT4-JFC-WRITER ! _EXT4-JFC-RECORD !
    _EXT4-JFC-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-CREDIT + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFC-CTX !
    _EXT4-JFC-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFC-REQUIRE-SELECTED ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-OE.INO + @ _EXT4-JFC-INO !
    _EXT4-JFC-RECORD @ _EXT4-OE.LOCATOR-A + @ _EXT4-JFC-LOGICAL !
    _EXT4-JFC-RECORD @ _EXT4-OE.LOCATOR-B + @ _EXT4-JFC-SLOT !
    \ The staging below reloads other inodes, so keep the target's kind.
    _EXT4-JFC-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0= _EXT4-JFC-DELETE !
    FALSE _EXT4-JFI-RELEASED !
    _EXT4-JFC-DELETE @ _EXT4-JFC-CTX @ _EXT4-UNLINKED-RELEASE? 0= AND IF
        _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
        _EXT4-JTX-STAGE-FREE-ORPHAN-INODE ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    ELSE
        _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
        _EXT4-ORPHAN-STEP-XT @ EXECUTE
        ?DUP IF NIP _EXT4-JFC-FAIL EXIT THEN
        IF 0 EXIT THEN
        \ An unlinked record's pass that freed the rest of the map with room
        \ to spare deletes the inode in the same transaction.
        _EXT4-JFC-DELETE @ IF
            _EXT4-JFI-RELEASED @ 0= IF VFS-E-CORRUPT _EXT4-JFC-FAIL EXIT THEN
            _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
            _EXT4-JTX-STAGE-FREE-ORPHAN-INODE
            ?DUP IF _EXT4-JFC-FAIL EXIT THEN
        THEN
    THEN
    _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
    _EXT4-JFC-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        _EXT4-JTX-CLEAR-MODERN-ORPHAN-SLOT
    ELSE
        _EXT4-JTX-ADVANCE-LEGACY-HEAD
    THEN
    ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    \ A deletion's homes equal its exact measured credit.  A linked final
    \ cleanup or a deletion that ends a release pass uses at most the pass's
    \ capacity, and a tree node that pass edited and then freed leaves a
    \ cancelled entry.
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> IF
        VFS-E-CORRUPT _EXT4-JFC-FAIL EXIT
    THEN
    _EXT4-JFC-DELETE @ _EXT4-JFI-RELEASED @ 0= AND IF
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @ <>
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ <> OR
        _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
        _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ <> OR
    ELSE
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @ U>
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ U> OR
        _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
        _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U> OR
    THEN IF
        VFS-E-CORRUPT _EXT4-JFC-FAIL EXIT
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFI-MAP-CHECK ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    THEN
    _EXT4-JFC-SEAL ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    FALSE _EXT4-JFI-RELEASED !
    0 ;

\ True only after the unified legacy/modern pass has authenticated an empty
\ active union and proved that its derived clear-pending state agrees with the
\ raw ORPHAN_PRESENT bit.  This does not require that bit to be set: a legacy
\ singleton may finish with no modern transient feature to clear.
: _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION?  ( ctx -- flag )
    DUP _EXT4-C.O.ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.O.MODERN-ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.O.LEGACY-ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-C.O.CLEAR-PENDING + @ 0<>
    SWAP _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-ORPHAN-PRESENT AND 0<> = ;

\ The empty-modern landing additionally requires the authenticated transient
\ bit whose final-super transition it is about to clear.
: _EXT4-EMPTY-ORPHAN-RECOVERY?  ( ctx -- flag )
    DUP _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF DROP FALSE EXIT THEN
    _EXT4-C.O.CLEAR-PENDING + @ 0<> ;

VARIABLE _EXT4-JOC-WRITER
VARIABLE _EXT4-JOC-CTX

\ Retire the transient modern-orphan bit only after cleanup has produced an
\ authenticated empty union.  RECOVER remains set, so the mounted writer can
\ stay active and accept later operations; an ordinary CP-NONE checkpoint
\ proves the post-home union is empty with no clear-pending state.
: _EXT4-JTX-STAGE-CLEAR-MODERN-ORPHAN-PRESENT
  ( transaction -- ior )
    DUP _EXT4-JOC-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOC-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOC-CTX !
    _EXT4-JOC-WRITER @ _EXT4-JWR.META-CREDIT + @ 1 <>
    _EXT4-JOC-WRITER @ _EXT4-JWR.DATA-CREDIT + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.META-USED + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JOC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOC-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JOC-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JOC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-INCOMPAT-RECOVER AND 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.RO-COMPAT + DUP L@
    _EXT4-RO-ORPHAN-PRESENT AND 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP L@ _EXT4-RO-ORPHAN-PRESENT INVERT AND SWAP L!
    _EXT4-JPS-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JPS-IMAGE @ _EXT4-JPS-HOME @ _EXT4-JOC-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    _EXT4-JOC-WRITER @ _EXT4-JWR.META-USED + @ 1 <>
    _EXT4-JOC-WRITER @ _EXT4-JWR.META-ACTIVE + @ 1 <> OR
    _EXT4-JOC-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-RS-CTX
VARIABLE _EXT4-RS-V

\ Complete every persistent validation/allocation before a mount creates its
\ transient recovery tail.  Checkpoint reloads reuse the same preplan.
: _EXT4-AUTHENTICATE-REST-STEPS  ( ctx -- ior )
    DUP _EXT4-C.J.STRICT + -1 SWAP !
    DUP _EXT4-VALIDATE-GROUPS ?DUP IF NIP EXIT THEN
    DUP _EXT4-VALIDATE-BACKUPS ?DUP IF NIP EXIT THEN
    DUP _EXT4-AUTHENTICATE-ORPHAN-COUNTS ?DUP IF NIP EXIT THEN
    _EXT4-VALIDATE-JOURNAL ;

\ One authentication reads each block from media once: every group check
\ reloads the shared descriptor page, and backup and journal checks revisit
\ the same witness blocks.  A write inside it still discards every copy.
: _EXT4-AUTHENTICATE-REST-PREPLAN  ( ctx -- ior )
    DUP _EXT4-PROOF-SCOPE-OPEN
    _EXT4-AUTHENTICATE-REST-STEPS _EXT4-PROOF-SCOPE-CLOSE ;

: _EXT4-AUTHENTICATE-REST  ( ctx -- ior )
    DUP _EXT4-PROOF-SCOPE-OPEN
    DUP _EXT4-AUTHENTICATE-REST-STEPS ?DUP IF
        NIP _EXT4-PROOF-SCOPE-CLOSE EXIT
    THEN
    _EXT4-BUILD-AUTHENTICATED-ORPHAN-PLAN _EXT4-PROOF-SCOPE-CLOSE ;

\ A complete reload validates the superblock, groups, backups and orphan
\ union from blocks outside the journal and builds the context's state from
\ them.  Every write starts a new map epoch except a journal write on a mount
\ whose ownership proof stands, which no such block can receive
\ (vfs-ext4-admission.f, vfs-ext4-jbd2-map.f).  While the epoch a complete
\ reload of a context finished in still holds, those blocks therefore read
\ as that reload read them and the state it built stands, so authenticating
\ the context again reads only the journal.
VARIABLE _EXT4-AUTH-CTX
VARIABLE _EXT4-AUTH-EPOCH
0 _EXT4-AUTH-CTX !

: _EXT4-AUTH-KEEP  ( ctx -- )
    DUP _EXT4-C.OWNERSHIP + @ -1 = IF
        _EXT4-AUTH-CTX ! _EXT4-MAP-EPOCH @ _EXT4-AUTH-EPOCH ! EXIT
    THEN
    DROP 0 _EXT4-AUTH-CTX ! ;

: _EXT4-AUTH-STANDS?  ( ctx -- flag )
    DUP 0= IF EXIT THEN
    DUP _EXT4-AUTH-CTX @ =
    SWAP _EXT4-C.OWNERSHIP + @ -1 = AND
    _EXT4-MAP-EPOCH @ _EXT4-AUTH-EPOCH @ = AND ;

: _EXT4-REAUTHENTICATE-JOURNAL  ( ctx -- ior )
    DUP _EXT4-C.J.STRICT + -1 SWAP !
    DUP _EXT4-PROOF-SCOPE-OPEN
    _EXT4-VALIDATE-JOURNAL _EXT4-PROOF-SCOPE-CLOSE ;

: _EXT4-RELOAD-AUTHENTICATED  ( ctx vfs -- ior )
    _EXT4-RS-V ! _EXT4-RS-CTX !
    0 _EXT4-AUTH-CTX !
    _EXT4-RS-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-RS-V @ _EXT4-VALIDATE-SUPER ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-AUTHENTICATE-REST ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-AUTH-KEEP 0 ;

: _EXT4-RELOAD-STRICT  ( ctx vfs -- ior )
    _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-C.O.ACTIVE + @ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

\ The strict reload, reading only the journal again while the context's
\ last complete reload stands.
: _EXT4-REAUTHENTICATE-STRICT  ( ctx vfs -- ior )
    OVER _EXT4-AUTH-STANDS? 0= IF _EXT4-RELOAD-STRICT EXIT THEN
    DROP DUP _EXT4-REAUTHENTICATE-JOURNAL ?DUP IF NIP EXIT THEN
    _EXT4-C.O.ACTIVE + @ IF EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT THEN
    0 ;

\ ---------------------------------------------------------------------
\  Orphan release passes
\ ---------------------------------------------------------------------
\
\ A truncate whose release does not fit one transaction first publishes its
\ new size together with a linked orphan record, and the unlink of a
\ file's last link publishes an unlinked one.  Release passes then free the
\ blocks past EOF, or every block of the unlinked file, while the record
\ keeps the inode recoverable.  Mount recovery runs the same passes for any
\ record whose inode still maps blocks it must free, and the record's final
\ cleanup, or the unlinked inode's deletion, removes it once none remain.
\ A pass stages the target's edited tree nodes, the accounting of the runs
\ it frees and the target's inode, keeping its size and times.  Its
\ certificate binds the record, the target's pre-image, the staged target
\ and, for a legacy record, the staged superblock that keeps the record at
\ the head of the list.

VARIABLE _EXT4-JRL-RECORD
VARIABLE _EXT4-JRL-WRITER
VARIABLE _EXT4-JRL-CTX
VARIABLE _EXT4-JRL-KIND
VARIABLE _EXT4-JRL-HOME
VARIABLE _EXT4-JRL-OFF
VARIABLE _EXT4-JRL-GEN
VARIABLE _EXT4-JRL-ENTRIES
VARIABLE _EXT4-JRL-PRE-CRC
VARIABLE _EXT4-JRL-TARGET-CRC
VARIABLE _EXT4-JRL-O-HOME
VARIABLE _EXT4-JRL-O-GEN
VARIABLE _EXT4-JRL-O-CRC
VARIABLE _EXT4-JRL-COUNT

\ A superblock a pass stages for its free counts keeps the orphan protocol:
\ the legacy list head and both feature words.
: _EXT4-JRL-SUPER-KEPT?  ( super -- flag )
    DUP _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JRL-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ =
    OVER _EXT4-SB.INCOMPAT + L@
    _EXT4-JRL-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ = AND
    SWAP _EXT4-SB.RO-COMPAT + L@
    _EXT4-JRL-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ = AND ;

: _EXT4-JRL-SUPER?  ( -- ior )
    _EXT4-JRL-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _EXT4-JRL-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JRL-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JRL-SUPER-KEPT? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ The staged target block, found by the last _EXT4-JFC-FIND-META, keeps
\ every byte outside the target's record, and the record changes only as a
\ release pass may.  The pre-image is the target block read from media.
: _EXT4-JRL-TARGET?  ( -- ior )
    _EXT4-JFC-IMAGE @ _EXT4-JRL-OFF @ + _EXT4-JIE-AFTER !
    _EXT4-JRL-HOME @ _EXT4-JRL-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JRL-CTX @ _EXT4-C.BLOCK + _EXT4-JRL-OFF @ + _EXT4-JIE-PRE !
    _EXT4-JRL-CTX @ _EXT4-C.ISIZE + @ _EXT4-JIE-ISIZE !
    _EXT4-JRL-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-IMAGE @ _EXT4-JRL-OFF @
    _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JRL-OFF @ _EXT4-JIE-ISIZE @ + DUP
    _EXT4-JRL-CTX @ _EXT4-C.BLOCK + + SWAP DUP _EXT4-JFC-IMAGE @ + SWAP
    _EXT4-JRL-CTX @ _EXT4-C.BSIZE + @ SWAP - _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JIE-RELEASE? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ Seal one staged release pass for the selected RECORD, linked or unlinked.
: _EXT4-JRL-SEAL  ( plan-record transaction -- ior )
    _EXT4-JRL-WRITER ! _EXT4-JRL-RECORD !
    _EXT4-JRL-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JRL-CTX !
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-NONE <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JRL-RECORD @ _EXT4-JRL-CTX @ _EXT4-REQUIRE-SELECTED-ORPHAN
    ?DUP IF EXIT THEN
    _EXT4-JRL-RECORD @ _EXT4-OE.KIND + @ _EXT4-JRL-KIND !
    _EXT4-JRL-CTX @ _EXT4-C.INODE +
    DUP _EXT4-I.GENERATION + L@ _EXT4-JRL-GEN !
    DUP _EXT4-ROOT-ENTRIES _EXT4-JRL-ENTRIES !
    _EXT4-JRL-CTX @ _EXT4-RECORD-CRC ?DUP IF NIP EXIT THEN
    _EXT4-JRL-PRE-CRC !
    _EXT4-IR-BLOCK @ _EXT4-JRL-HOME !
    _EXT4-IR-OFF @ _EXT4-JRL-OFF !
    _EXT4-JRL-HOME @ _EXT4-JRL-WRITER @ _EXT4-JFC-FIND-META
    ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JRL-TARGET-CRC !
    _EXT4-JRL-TARGET? ?DUP IF EXIT THEN
    _EXT4-JRL-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JRL-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-JRL-RECORD @ _EXT4-OE.LOCATOR-A + @ _EXT4-JRL-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @ _EXT4-JRL-O-HOME !
        _EXT4-OV-GEN @ _EXT4-JRL-O-GEN !
        _EXT4-JRL-CTX @ _EXT4-C.BLOCK +
        _EXT4-JRL-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-JRL-RECORD @ _EXT4-OE.INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JRL-O-HOME @ _EXT4-JRL-WRITER @ _EXT4-JFC-FIND-META
        ?DUP IF EXIT THEN
        _EXT4-JFC-FOUND @ IF VFS-E-CORRUPT EXIT THEN
        0 _EXT4-JRL-O-CRC !
    ELSE
        _EXT4-JRL-KIND @ _EXT4-OK-LEGACY <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JRL-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _EXT4-JRL-O-HOME !
        _EXT4-JRL-CTX @ _EXT4-C.SB + _EXT4-SB.CHECKSUM + L@
        _EXT4-JRL-O-GEN !
        _EXT4-JRL-O-HOME @ _EXT4-JRL-WRITER @ _EXT4-JFC-FIND-META
        ?DUP IF EXIT THEN
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JRL-O-CRC !
    THEN
    _EXT4-JRL-SUPER? ?DUP IF EXIT THEN
    _EXT4-JRL-WRITER @ _EXT4-JWR.EPOCH + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-EPOCH + !
    _EXT4-JRL-RECORD @ _EXT4-OE.INO + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-INO + !
    _EXT4-JRL-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-LOGICAL + !
    _EXT4-JRL-RECORD @ _EXT4-OE.LOCATOR-B + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-SLOT + !
    _EXT4-JRL-O-HOME @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-HOME + !
    _EXT4-JRL-O-GEN @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-GEN + !
    _EXT4-JRL-GEN @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-GEN + !
    _EXT4-JRL-HOME @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-HOME + !
    _EXT4-JRL-OFF @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-OFF + !
    _EXT4-JRL-TARGET-CRC @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-CRC + !
    _EXT4-JRL-O-CRC @ _EXT4-JRL-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + !
    _EXT4-JRL-ENTRIES @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + !
    _EXT4-JRL-PRE-CRC @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-PRE-CRC + !
    _EXT4-JRL-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + !
    _EXT4-JRL-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-PRE-MODERN + !
    _EXT4-JRL-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + !
    _EXT4-JRL-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JCPM-ORPHAN-MODERN-RELEASE
    ELSE
        _EXT4-JCPM-ORPHAN-LEGACY-RELEASE
    THEN _EXT4-JRL-WRITER @ _EXT4-JWR.CP-MODE + !
    _EXT4-JRL-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF
        _EXT4-JRL-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Before its first home write, a sealed pass still holds exactly the
\ target image and protocol state its certificate binds.
: _EXT4-JRL-STAGED?  ( writer -- ior )
    DUP _EXT4-JRL-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JRL-CTX !
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ _EXT4-JRL-HOME !
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ _EXT4-JRL-OFF !
    _EXT4-JRL-HOME @ _EXT4-JRL-WRITER @ _EXT4-JFC-FIND-META
    ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JRL-TARGET? ?DUP IF EXIT THEN
    _EXT4-JIE-PRE @ _EXT4-JRL-CTX @ _EXT4-RECORD-CRC ?DUP IF NIP EXIT THEN
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-TARGET-PRE-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-HOME + @ _EXT4-JRL-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JRL-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JFC-FOUND @ IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JRL-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @ _EXT4-JRL-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JRL-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JRL-SUPER? ;

VARIABLE _EXT4-JPF-WRITER
VARIABLE _EXT4-JPF-CTX
VARIABLE _EXT4-JPF-V
VARIABLE _EXT4-JPF-RECORD
VARIABLE _EXT4-JPF-COUNT
VARIABLE _EXT4-JPF-MODE
VARIABLE _EXT4-JPF-KIND
VARIABLE _EXT4-JPF-TARGET
VARIABLE _EXT4-JPF-OFF
VARIABLE _EXT4-JPF-AFTER

: _EXT4-JWR-ORPHAN-PREPLAN  ( writer ctx -- ior )
    _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JPF-MODE !
    _EXT4-JCPM-ORPHAN? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ <>
    _EXT4-JPF-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ <> OR
    _EXT4-JPF-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-JPF-RECORD ! 0 _EXT4-JPF-COUNT !
    _EXT4-JPF-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JPF-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            1 _EXT4-JPF-COUNT +!
            DUP _EXT4-OE.INO + @
            _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ = IF
                _EXT4-JPF-RECORD @ IF
                    DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
                THEN
                _EXT4-JPF-RECORD !
            ELSE
                DROP
            THEN
        ELSE
            DROP
        THEN
    LOOP
    _EXT4-JPF-COUNT @ _EXT4-JPF-CTX @ _EXT4-C.O.ACTIVE + @ <>
    _EXT4-JPF-RECORD @ 0= OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.INO + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-JPF-KIND !
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-OK-MODERN <>
    ELSE
        _EXT4-OK-LEGACY <>
    THEN IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.LOCATOR-B + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-JPF-CTX @
    _EXT4-REQUIRE-SELECTED-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-C.INODE + DUP _EXT4-JPF-TARGET !
    _EXT4-I.LINKS + W@ 0=
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? <>
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-RELEASE? 0= AND IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-TARGET @ _EXT4-I.GENERATION + L@
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    \ A release pass or a linked record's final cleanup was sealed against
    \ this exact pre-image, whose tree nothing else can have changed since.
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? 0= IF
        _EXT4-JPF-TARGET @ _EXT4-JPF-CTX @ _EXT4-RECORD-CRC
        ?DUP IF NIP EXIT THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-PRE-CRC + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JPF-RECORD @ _EXT4-JFI-RECORD !
        _EXT4-JPF-WRITER @ _EXT4-JFI-USE-CP-RUNS ?DUP IF EXIT THEN
        _EXT4-JPF-CTX @ _EXT4-JFI-CTX !
        _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
        _EXT4-JFI-DATA-ENTRIES @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JFI-CP-RANGES-MATCH? 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE?
        _EXT4-JFI-RANGE-COUNT 0<> <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JPF-TARGET @ _EXT4-ROOT-ENTRIES
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-IR-BLOCK @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <>
    _EXT4-IR-OFF @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JPF-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-OV-GEN @ _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-RECORD @ _EXT4-JPF-CTX @
        _EXT4-ORPHAN-RECORD? 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ _EXT4-JPF-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-CTX @ _EXT4-C.SB + DUP
        _EXT4-SB.CHECKSUM + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
            DROP EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _EXT4-JPF-HOME-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JPF-AFTER ! _EXT4-JPF-OFF !
    _EXT4-JPF-CTX @ _EXT4-C.BLOCK + _EXT4-JPF-OFF @ +
    _EXT4-JFC-IMAGE @ _EXT4-JPF-OFF @ +
    _EXT4-JPF-AFTER @ _EXT4-BYTES=? ;

: _EXT4-JPF-LEGACY-SUPER-EXACT?  ( -- flag )
    0 _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x0C +
    _EXT4-JPF-HOME-RANGE-UNCHANGED?
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? 0= IF
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x10 + 4
        _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ 0= IF
            _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x0C + 4
            _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
            _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x158 + 4
            _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
        THEN
    THEN
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x14 +
    0xE8 0x14 - _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0xEC +
    0x158 0xEC - _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x15C +
    0x3FC 0x15C - _EXT4-JPF-HOME-RANGE-UNCHANGED? AND
    _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x400 + DUP
    _EXT4-JPF-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JPF-HOME-RANGE-UNCHANGED? AND ;

\ A linked record's final cleanup stages its target when it also ends the
\ release or clears a legacy successor link, against the pre-image in the
\ target block read just before, and stages a sealed tail block with
\ exactly the bytes past the target's EOF zeroed.
: _EXT4-JPF-LINKED-STAGED?  ( -- ior )
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-ORPHAN-LEGACY?
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0<> AND
    _EXT4-JFC-FOUND @ IF
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ + _EXT4-JIE-AFTER !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ + _EXT4-JIE-PRE !
        _EXT4-JPF-CTX @ _EXT4-C.ISIZE + @ _EXT4-JIE-ISIZE !
        _EXT4-JIE-FINAL? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        IF VFS-E-CORRUPT EXIT THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TAIL-HOME + @ 0= IF 0 EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JPF-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
    DUP _EXT4-I.SIZE-LO + L@ SWAP _EXT4-I.SIZE-HI + L@ 32 LSHIFT OR
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TAIL-HOME + @ SWAP
    _EXT4-JPF-WRITER @ _EXT4-JFC-TAIL-STAGED? ;

: _EXT4-JWR-ORPHAN-STAGED?  ( writer -- ior )
    DUP _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-ORPHAN-RELEASE? IF
        _EXT4-JRL-STAGED? EXIT
    THEN
    DUP _EXT4-JPF-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JPF-CTX !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ _EXT4-JPF-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JPF-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
        _EXT4-JPF-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <>
        _EXT4-OV-GEN @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 *
        DUP _EXT4-JPF-OFF !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JFC-IMAGE @ ROT _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-OFF @ 4 + DUP _EXT4-JPF-AFTER !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK + OVER +
        _EXT4-JFC-IMAGE @ ROT +
        _EXT4-JPF-CTX @ _EXT4-C.BSIZE + @ 4 -
        _EXT4-JPF-AFTER @ - _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@ IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @ _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @
        _EXT4-JPF-CTX @ _EXT4-C.ORPHAN-INO + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ _EXT4-JPF-CTX @
        _EXT4-ORPHAN-BLOCK-CHECKSUM?
        ?DUP IF NIP EXIT THEN 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
        _EXT4-JCPM-ORPHAN-LEGACY? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
        _EXT4-JPF-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-JPF-LEGACY-SUPER-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        DUP _EXT4-JFC-SUPER !
        DUP _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP EXIT THEN 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-SUPER-SEED? ?DUP IF NIP NIP EXIT THEN 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP 0 _EXT4-JPF-CTX @ _EXT4-C.SB +
        _EXT4-SUPER-INVARIANTS? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JPF-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
        ?DUP IF NIP EXIT THEN
        DUP _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-SB.INCOMPAT + L@
        _EXT4-JPF-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-SB.RO-COMPAT + L@
        _EXT4-JPF-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JPF-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ IF
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
        _EXT4-JPF-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ DUP
        _EXT4-JPF-OFF !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JFC-IMAGE @ ROT _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-OFF @ _EXT4-JPF-CTX @ _EXT4-C.ISIZE + @ + DUP
        _EXT4-JPF-AFTER !
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK + OVER +
        _EXT4-JFC-IMAGE @ ROT +
        _EXT4-JPF-CTX @ _EXT4-C.BSIZE + @
        _EXT4-JPF-AFTER @ - _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
        _EXT4-JPF-CTX @ _EXT4-C.ISIZE + @
        _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-JPF-LINKED-STAGED? ?DUP IF EXIT THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JPF-WRITER @ _EXT4-JFI-USE-CP-RUNS ?DUP IF EXIT THEN
        _EXT4-JPF-RECORD @ _EXT4-JPF-WRITER @
        _EXT4-JFD-VERIFY-STAGED ?DUP IF EXIT THEN
        _EXT4-JFC-INODE-BITMAP-HOME @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ <>
        _EXT4-JFC-INODE-BITMAP-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @ <> OR
        _EXT4-JFC-INODE-GDT-HOME @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ <> OR
        _EXT4-JFC-INODE-GDT-OFF @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ <> OR
        _EXT4-JFC-INODE-GDT-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ <> OR
        _EXT4-JFC-INODE-SUPER-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JFI-CP-RANGES-MATCH? 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Reload admission binds an ADD certificate to the freshly authenticated
\ pre-union and proves that its candidate is still absent.  The later staged
\ proof, still before the first home write, rederives the deterministic empty
\ slot.
: _EXT4-JWR-ORPHAN-ADD-RELOAD-ADMISSION  ( writer ctx -- ior )
    _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JPF-CTX @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-ADD? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ <>
    _EXT4-JPF-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ <> OR
    _EXT4-JPF-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ _EXT4-JPF-CTX @
    _EXT4-ORPHAN-PLAN-FIND
    DUP IF NIP EXIT THEN DROP IF VFS-E-CONFLICT EXIT THEN
    0 ;

\ A typed orphan reload admitted by checkpoint is bound to one sealed writer,
\ its exact checkpoint phase, and the fully authenticated pre-union.  It skips
\ only the public policy refusal.  Cleanup retains its complete preplan here;
\ insertion uses bounded admission and performs its complete staged proof
\ later in this same checkpoint preflight.  While the context's last complete
\ reload stands, the certificate binds to the plan it built and only the
\ journal is read again.
VARIABLE _EXT4-JPF-STOOD

: _EXT4-RELOAD-STRICT-ORPHAN-PREPLAN  ( writer ctx vfs -- ior )
    _EXT4-JPF-V ! _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCPM-ORPHAN?
    SWAP _EXT4-JCPM-ORPHAN-ADD? OR 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-CHECKPOINTING <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.PHASE + @
    _EXT4-JWP-CHECKPOINT-PREFLIGHT <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JPF-CTX @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-V @ _EXT4-CTX _EXT4-JPF-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JPF-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0=
    _EXT4-JPF-CTX @ _EXT4-C.RECOVERY + @ 0= OR
    _EXT4-JPF-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-AUTH-STANDS? DUP _EXT4-JPF-STOOD ! 0= IF
        0 _EXT4-AUTH-CTX !
        _EXT4-JPF-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
        ?DUP IF EXIT THEN
        _EXT4-JPF-CTX @ _EXT4-JPF-V @ _EXT4-VALIDATE-SUPER
        ?DUP IF EXIT THEN
        -1 _EXT4-JPF-CTX @ _EXT4-C.J.STRICT + !
        _EXT4-JPF-CTX @ _EXT4-VALIDATE-GROUPS ?DUP IF EXIT THEN
        _EXT4-JPF-CTX @ _EXT4-VALIDATE-BACKUPS ?DUP IF EXIT THEN
        _EXT4-JPF-CTX @ _EXT4-AUTHENTICATE-ORPHAN-PLAN ?DUP IF EXIT THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-ADD? IF
        _EXT4-JPF-WRITER @ _EXT4-JPF-CTX @
        _EXT4-JWR-ORPHAN-ADD-RELOAD-ADMISSION ?DUP IF EXIT THEN
    ELSE
        _EXT4-JPF-WRITER @ _EXT4-JPF-CTX @
        _EXT4-JWR-ORPHAN-PREPLAN ?DUP IF EXIT THEN
    THEN
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JPF-STOOD @ 0= IF _EXT4-JPF-CTX @ _EXT4-AUTH-KEEP THEN
    0 ;

: _EXT4-VALIDATE-ROOT  ( ctx -- ior )
    DUP _EXT4-RJ-CTX ! 2 SWAP _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-STAGE-ROOT ;

VARIABLE _EXT4-JCP-WRITER
VARIABLE _EXT4-JCP-CTX
VARIABLE _EXT4-JCP-V
VARIABLE _EXT4-JCP-INDEX
VARIABLE _EXT4-JCP-ENTRY
VARIABLE _EXT4-JCP-WROTE
VARIABLE _EXT4-JCP-ENTRY-READY

: _EXT4-JCP-FAULT  ( ior -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR-LATCH-FAULT ;

: _EXT4-JCP-RELOAD-PREFLIGHT  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @ DUP
    _EXT4-JCPM-NONE = IF
        DROP _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-REAUTHENTICATE-STRICT EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-ADD? IF
        DROP
        _EXT4-JCP-WRITER @ _EXT4-JCP-CTX @ _EXT4-JCP-V @
        _EXT4-RELOAD-STRICT-ORPHAN-PREPLAN EXIT
    THEN
    _EXT4-JCPM-ORPHAN? IF
        _EXT4-JCP-WRITER @ _EXT4-JCP-CTX @ _EXT4-JCP-V @
        _EXT4-RELOAD-STRICT-ORPHAN-PREPLAN EXIT
    THEN
    VFS-E-CORRUPT ;

VARIABLE _EXT4-JCE-GROUP
VARIABLE _EXT4-JCE-INDEX
VARIABLE _EXT4-JCE-HOME
VARIABLE _EXT4-JCE-IOR
VARIABLE _EXT4-JCE-META-INDEX
VARIABLE _EXT4-JCE-META-ENTRY
VARIABLE _EXT4-JCE-META-IMAGE
VARIABLE _EXT4-JCE-DATA-BITMAP-HOME
VARIABLE _EXT4-JCE-DATA-GDT-HOME
VARIABLE _EXT4-JCE-DATA-RANGE-INDEX
VARIABLE _EXT4-JCE-DATA-BLOCKS
VARIABLE _EXT4-JCE-GROUP-INODES

\ The staged home of the current entry reached the medium exactly.
: _EXT4-JCE-REQUIRE-RETAINED  ( -- ior )
    _EXT4-JCE-META-ENTRY @ @ DUP 0< IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-JCP-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCE-META-INDEX @ _EXT4-JCP-WRITER @
    _EXT4-JWR-META-IMAGE DUP _EXT4-JCE-META-IMAGE !
    _EXT4-JCP-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCE-META-ENTRY @ 2 CELLS + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCE-META-IMAGE @
    _EXT4-JCP-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Every staged home reached the medium exactly.  A cancelled entry is a
\ block the transaction edited and then freed, whose revoke took its
\ after-image out of the transaction and left no home write: an ordinary
\ transaction or a release pass, a deletion folded into one included, may
\ hold one, and the other orphan modes never do.
: _EXT4-JCP-REQUIRE-RETAINED-META-HOMES  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JCE-META-INDEX !
    BEGIN
        _EXT4-JCE-META-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JCE-META-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-META-ENTRY DUP _EXT4-JCE-META-ENTRY !
        CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP _EXT4-JCE-REQUIRE-RETAINED ?DUP IF EXIT THEN
        ELSE
            _EXT4-JE-CANCELLED =
            _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @ DUP _EXT4-JCPM-ORPHAN?
            OVER _EXT4-JCPM-ORPHAN-DELETE? 0=
            _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DATA-MAP-KIND + @
            _EXT4-JDM-RELEASED = OR AND
            SWAP _EXT4-JCPM-NONE = OR AND 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        THEN
        1 _EXT4-JCE-META-INDEX +!
    REPEAT
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-RANGE  ( first count -- ior )
    _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    _EXT4-JCE-DATA-BLOCKS @ _EXT4-JFB-COUNT @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JCE-DATA-BLOCKS !
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-GROUP @ _EXT4-JCP-CTX @ _EXT4-LOAD-BLOCK-BITMAP
        _EXT4-JCE-IOR ! _EXT4-JCE-DATA-BITMAP-HOME !
        _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
        _EXT4-JFB-GROUP-BLOCKS @
        _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ BITSET-ALL-CLEAR? 0= IF
            DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-GD-BLOCK @ _EXT4-JCE-DATA-GDT-HOME !
        _EXT4-JCE-DATA-BITMAP-HOME @ _EXT4-JCP-WRITER @
        _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JCE-DATA-GDT-HOME @ _EXT4-JCP-WRITER @
        _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    0 ;

: _EXT4-JCP-REQUIRE-REFDEC-EA  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-ACTION + @
    _EXT4-JEA-REFDEC <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JCP-CTX @ _EXT4-BLOCK-ALLOCATED?
    ?DUP IF NIP EXIT THEN
    0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JCP-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JCP-WRITER @ _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @
    _EXT4-JCP-CTX @ _EXT4-LOAD-XATTR-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + 4 + L@
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-REFCOUNT + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-IMAGE @
    _EXT4-JCP-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-DATA  ( -- ior )
    _EXT4-JCP-CTX @ _EXT4-JFB-CTX !
    0 _EXT4-JCE-DATA-BLOCKS !
    0 _EXT4-JCE-DATA-RANGE-INDEX !
    BEGIN
        _EXT4-JCE-DATA-RANGE-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DELETE-RANGE-COUNT + @ U<
    WHILE
        _EXT4-JCE-DATA-RANGE-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-CP-DELETE-RANGE DUP @ SWAP CELL+ @
        _EXT4-JCP-REQUIRE-DELETE-RANGE ?DUP IF EXIT THEN
        1 _EXT4-JCE-DATA-RANGE-INDEX +!
    REPEAT
    _EXT4-JCE-DATA-BLOCKS @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DELETE-BLOCKS + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-HOME + @ ?DUP IF
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-EA-ACTION + @
        _EXT4-JEA-RELEASE = IF
            1 _EXT4-JCP-REQUIRE-DELETE-RANGE ?DUP IF EXIT THEN
        ELSE
            DROP _EXT4-JCP-REQUIRE-REFDEC-EA ?DUP IF EXIT THEN
        THEN
    THEN
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-HOMES  ( -- ior )
    _EXT4-JCP-REQUIRE-RETAINED-META-HOMES ?DUP IF EXIT THEN
    _EXT4-JCP-REQUIRE-DELETE-DATA ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ 1-
    _EXT4-JCP-CTX @ _EXT4-C.IPG + @ /MOD
    _EXT4-JCE-GROUP ! _EXT4-JCE-INDEX !
    _EXT4-JCE-GROUP @ _EXT4-JCP-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JCE-IOR ! _EXT4-JCE-HOME !
    _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
    _EXT4-JCE-HOME @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ <>
    _EXT4-GD-OFF @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCE-GROUP @ _EXT4-JCP-CTX @ _EXT4-GROUP-INODE-COUNT
    _EXT4-JCE-IOR ! _EXT4-JCE-GROUP-INODES !
    _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCE-GROUP-INODES @ _EXT4-JCE-INDEX @ BITSET-TEST? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    ?DUP IF NIP EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCP-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
    _EXT4-JCP-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JCP-POST-ACTIVE
VARIABLE _EXT4-JCP-POST-MODERN
VARIABLE _EXT4-JCP-POST-COUNT
VARIABLE _EXT4-JCP-ADD-RECORD
VARIABLE _EXT4-JCP-ADD-IOR
VARIABLE _EXT4-JCP-ADD-INODE
VARIABLE _EXT4-JCP-ADD-HOME
VARIABLE _EXT4-JCP-ADD-OFF

: _EXT4-JCP-REQUIRE-ADD-POSTSTATE  ( -- ior )
    _EXT4-JCP-REQUIRE-RETAINED-META-HOMES ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ 1 _EXT4-UADD?
    DUP IF 2DROP VFS-E-CORRUPT EXIT THEN DROP
    DUP _EXT4-JCP-POST-ACTIVE !
    _EXT4-JCP-CTX @ _EXT4-C.O.ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ 1 _EXT4-UADD?
    DUP IF 2DROP VFS-E-CORRUPT EXIT THEN DROP
    DUP _EXT4-JCP-POST-MODERN !
    _EXT4-JCP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @
    _EXT4-JCP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ <>
    _EXT4-JCP-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-ORPHAN-PRESENT AND 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ _EXT4-JCP-CTX @
    _EXT4-REAUTH-MODERN-ORPHAN-BY-INODE
    _EXT4-JCP-ADD-IOR ! _EXT4-JCP-ADD-RECORD !
    _EXT4-JCP-ADD-IOR @ ?DUP IF EXIT THEN
    _EXT4-JCP-ADD-RECORD @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-ADD-RECORD @ DUP _EXT4-OE.KIND + @
    _EXT4-OK-MODERN <>
    OVER _EXT4-OE.LOCATOR-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> OR
    SWAP _EXT4-OE.LOCATOR-B + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.INODE + _EXT4-JCP-ADD-INODE !
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-UNLINK-ADD? IF
        _EXT4-JCP-ADD-INODE @ _EXT4-I.LINKS + W@ IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JCP-ADD-INODE @ _EXT4-I.LINKS + W@ 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JCP-ADD-INODE @ _EXT4-I.GENERATION + L@
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-ADD-INODE @ _EXT4-I.SIZE-LO + L@
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-LO + @ <>
    _EXT4-JCP-ADD-INODE @ _EXT4-I.SIZE-HI + L@
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-ADD-TARGET-SIZE-HI + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-UNLINK-ADD? IF
        _EXT4-JCP-ADD-RECORD @ _EXT4-JFI-RECORD !
        _EXT4-JCP-CTX @ _EXT4-JFI-CTX !
        0 _EXT4-JFI-PROSPECTIVE ! FALSE _EXT4-JFI-RELEASED !
        _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
        _EXT4-JCP-WRITER @ _EXT4-JFI-CP-RANGES-MATCH? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFI-DATA-ENTRIES @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-IR-BLOCK @ DUP _EXT4-JCP-ADD-HOME !
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <>
    _EXT4-IR-OFF @ DUP _EXT4-JCP-ADD-OFF !
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-OV-GEN @ _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
    _EXT4-JCP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-HOME + @ <>
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ A checkpointed release pass leaves the union it found, with its record
\ still recoverable at the same locators.
: _EXT4-JCP-REQUIRE-RELEASE-POSTSTATE  ( -- ior )
    _EXT4-JCP-REQUIRE-RETAINED-META-HOMES ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ <>
    _EXT4-JCP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ <> OR
    _EXT4-JCP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ <> OR
    _EXT4-JCP-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JRL-COUNT !
    _EXT4-JCP-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JCP-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            DUP _EXT4-OE.INO + @
            _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ = IF
                1 _EXT4-JRL-COUNT +!
                DUP _EXT4-OE.LOCATOR-A + @
                _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <>
                OVER _EXT4-OE.LOCATOR-B + @
                _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> OR IF
                    DROP VFS-E-CORRUPT UNLOOP EXIT
                THEN
            THEN
        THEN
        DROP
    LOOP
    _EXT4-JRL-COUNT @ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCP-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
        _EXT4-JCP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @ _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-HOME + @ <>
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JCP-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _EXT4-JCP-REQUIRE-POSTSTATE  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCPM-NONE = IF
        DROP
        _EXT4-JCP-REQUIRE-RETAINED-META-HOMES ?DUP IF EXIT THEN
        _EXT4-JCP-CTX @
        _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        0 EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-ADD? IF
        DROP _EXT4-JCP-REQUIRE-ADD-POSTSTATE EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-RELEASE? IF
        DROP _EXT4-JCP-REQUIRE-RELEASE-POSTSTATE EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-ACTIVE + @ 1-
    DUP _EXT4-JCP-POST-ACTIVE !
    _EXT4-JCP-CTX @ _EXT4-C.O.ACTIVE + @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @ 1-
        _EXT4-JCP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ <>
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @
        _EXT4-JCP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ <> OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    ELSE
        DUP _EXT4-JCPM-ORPHAN-LEGACY? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-LEGACY + @ 1-
        _EXT4-JCP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ <>
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-PRE-MODERN + @
        _EXT4-JCP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ <> OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 _EXT4-JCP-POST-COUNT !
    _EXT4-JCP-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JCP-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            1 _EXT4-JCP-POST-COUNT +!
            _EXT4-OE.INO + @
            _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ = IF
                DROP VFS-E-CORRUPT UNLOOP EXIT
            THEN
        ELSE
            DROP
        THEN
    LOOP
    _EXT4-JCP-POST-COUNT @ _EXT4-JCP-POST-ACTIVE @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-FINAL? IF
        _EXT4-JCP-POST-ACTIVE @ IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-JCP-CTX @
        _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JCPM-ORPHAN-MODERN? IF
            _EXT4-JCP-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= IF
                DROP VFS-E-CORRUPT EXIT
            THEN
        THEN
    ELSE
        DUP _EXT4-JCPM-ORPHAN-MORE? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-POST-ACTIVE @ 0= IF DROP VFS-E-CORRUPT EXIT THEN
    THEN
    DUP _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCP-CTX @ _EXT4-PREPARE-ORPHAN-FILE
        ?DUP IF NIP EXIT THEN
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
        _EXT4-JCP-CTX @ _EXT4-READ-ORPHAN-BLOCK
        ?DUP IF NIP EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-HOME + @ <>
        _EXT4-OV-GEN @
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@ IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JCP-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN
    DUP _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCP-REQUIRE-DELETE-HOMES ?DUP IF NIP EXIT THEN
    THEN
    DROP
    0 ;

\ Reauthenticate both the persisted transaction and its retained checkpoint
\ source before the first home write.  JSCAN proves the exact committed disk
\ prefix; the bounded writer tables prove the home identities and images that
\ will be consumed without allocating recovery-only revoke workspace.
: _EXT4-JTX-CHECKPOINT-PREFLIGHT  ( -- ior )
    _EXT4-JCP-RELOAD-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 1-
    _EXT4-JCP-CTX @ _EXT4-JOURNAL-ADVANCE
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    \ Root staging may use TREE-BLOCK.  Freeze inode 8 again before JSCAN and
    \ retained-image authority checks consume the retry-preservation proof.
    8 _EXT4-JCP-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.INODE +
    _EXT4-JCP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JCP-CTX @ _EXT4-C.ISIZE + @ CMOVE
    \ First prove an ordinary complete committed prefix, then repeat the same
    \ bounded scan in lockstep with retained metadata and revoke order.  The
    \ second pass cannot grant home-write authority merely because two valid
    \ but different transaction descriptions happen to have the same shape.
    _EXT4-JSCAN-PREFLIGHT _EXT4-JCP-CTX @ _EXT4-JSCAN ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JSCAN-BIND-BEGIN
    _EXT4-JSCAN-BINDING _EXT4-JCP-CTX @ _EXT4-JSCAN
    _EXT4-JSCAN-BIND-FINISH ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-CURSOR + @
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.COMMITTED + @ 1 <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.CURSOR + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
    0xFFFFFFFF AND <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-COUNT + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JTX-PREFLIGHT-IMAGES ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @ DUP
    _EXT4-JCPM-ORPHAN-ADD? IF
        _EXT4-JCPM-ORPHAN-UNLINK-ADD? IF
            _EXT4-JCP-WRITER @ _EXT4-JUA-STAGED? ?DUP IF EXIT THEN
        ELSE
            _EXT4-JCP-WRITER @ _EXT4-JTA-STAGED? ?DUP IF EXIT THEN
        THEN
    ELSE _EXT4-JCPM-ORPHAN? IF
        _EXT4-JCP-WRITER @ _EXT4-JWR-ORPHAN-STAGED?
        ?DUP IF EXIT THEN
    THEN THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JTX-CHECKPOINT-HOMES  ( -- ior )
    _EXT4-JWP-CHECKPOINT-HOME
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    0 _EXT4-JCP-INDEX ! 0 _EXT4-JCP-WROTE !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.HOME-WRITES + !
    BEGIN
        _EXT4-JCP-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JCP-INDEX @ _EXT4-JCP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JCP-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JCP-INDEX @ _EXT4-JCP-WRITER @ _EXT4-JWR-META-IMAGE
            _EXT4-JCP-ENTRY @ @ _EXT4-JCP-CTX @ _EXT4-WRITE-BLOCK
            ?DUP IF EXIT THEN
            1 _EXT4-JCP-WROTE +!
            1 _EXT4-JCP-CTX @ _EXT4-C.J.HOME-WRITES + +!
        THEN
        1 _EXT4-JCP-INDEX +!
    REPEAT
    _EXT4-JCP-WROTE @
    _EXT4-JCP-WRITER @ _EXT4-JWR.META-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWP-CHECKPOINT-HOME-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ;

\ Checkpoint one durable transaction, release its complete log reservation,
\ and keep the mounted filesystem at a standard empty RECOVER-set journal.
\ Any failure after publication enters CHECKPOINTING is quarantined for
\ remount; same-session retry never guesses which prefix reached the medium.
: _EXT4-JTX-CHECKPOINT  ( transaction -- ior )
    DUP _EXT4-JCP-WRITER ! _EXT4-JWR-VALID? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-COMMITTED <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JCP-CTX !
    DUP _EXT4-C.J.PROTOCOL-OWNERS + @ -1 <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-C.J.WRITER-CURRENT + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.READY + @ DUP _EXT4-JCP-ENTRY-READY !
    DUP 0= SWAP -1 = OR 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-JCP-V ! _EXT4-CTX _EXT4-JCP-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JCP-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-JWP-CHECKPOINT-PREFLIGHT
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-CHECKPOINTING
    _EXT4-JCP-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JTX-CHECKPOINT-PREFLIGHT ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JTX-CHECKPOINT-HOMES ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-PROOF
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-AUTHENTICATED
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-REQUIRE-POSTSTATE ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JWP-CHECKPOINT-RESET
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-RESET-JOURNAL
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-RESET-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-WITNESS-CLEAR
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-WITNESS-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-GUARD-RETIRE
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-GUARD-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-FINAL-PROOF
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-C.RECOVERY + @ 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.SB + DUP
    _EXT4-SUPER-CHECKSUM? ?DUP IF NIP NIP _EXT4-JCP-FAULT EXIT THEN 0= IF
        DROP VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    \ Context and writer publication are withdrawn before authenticated reload
    \ turns the in-memory active-log view into the empty write-active endpoint.
    \ The journal release writes only journal blocks, so once the post-home
    \ reload stands the poststate it proved stands too, and only the journal
    \ is authenticated again.
    0 _EXT4-JCP-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JCP-CTX @ _EXT4-C.READY + !
    _EXT4-JCP-CTX @ _EXT4-AUTH-STANDS? IF
        _EXT4-JCP-CTX @ _EXT4-REAUTHENTICATE-JOURNAL
        ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    ELSE
        _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-AUTHENTICATED
        ?DUP IF _EXT4-JCP-FAULT EXIT THEN
        _EXT4-JCP-REQUIRE-POSTSTATE ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-V @ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-JCP-FAULT EXIT
    THEN
    0 _EXT4-JCP-CTX @ _EXT4-C.J.COMMITTED + !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-HITS + !
    _EXT4-JCP-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JCP-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JCP-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JCP-CTX @ _EXT4-C.J.FIRST + @
    THEN _EXT4-JCP-CTX @ _EXT4-C.J.CURSOR + !
    _EXT4-JCP-CTX @ _EXT4-JWR-REBASE-WRITE-ACTIVE
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    -1 _EXT4-JCP-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    _EXT4-JCP-ENTRY-READY @ _EXT4-JCP-CTX @ _EXT4-C.READY + !
    0 ;

VARIABLE _EXT4-MOW-V
VARIABLE _EXT4-MOW-CTX
VARIABLE _EXT4-MOW-ACTIVE
VARIABLE _EXT4-MOW-ALLOW-ORPHAN-UNION
VARIABLE _EXT4-MOW-O-ACTIVE
VARIABLE _EXT4-MOW-O-MODERN
VARIABLE _EXT4-MOW-O-LEGACY
VARIABLE _EXT4-MOW-O-PRESENT
\ Classify the complete retained orphan state before admitting any mounted
\ mutation.  Ordinary writers remain strict.  A caller that explicitly owns
\ modern-orphan composition may retain only an authenticated modern-only
\ union; legacy authority and the clear-pending endpoint remain recovery work.
: _EXT4-MOW-REQUIRE-ORPHAN-STATE  ( -- ior )
    _EXT4-MOW-CTX @ _EXT4-C.O.ACTIVE + @ DUP
    _EXT4-MOW-O-ACTIVE ! 0< IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ DUP
    _EXT4-MOW-O-MODERN ! 0< IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ DUP
    _EXT4-MOW-O-LEGACY ! 0< IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MOW-O-MODERN @ _EXT4-MOW-O-LEGACY @ _EXT4-UADD?
    DUP IF 2DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    DROP _EXT4-MOW-O-ACTIVE @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.O.CLEAR-PENDING + @ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-ORPHAN-PRESENT AND 0<> _EXT4-MOW-O-PRESENT !
    _EXT4-MOW-O-LEGACY @
    _EXT4-MOW-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-MOW-O-ACTIVE @ 0= IF
        _EXT4-MOW-O-MODERN @ _EXT4-MOW-O-PRESENT @ OR IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        0 EXIT
    THEN
    _EXT4-MOW-O-MODERN @ _EXT4-MOW-O-ACTIVE @ <>
    _EXT4-MOW-O-PRESENT @ 0= OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MOW-ALLOW-ORPHAN-UNION @ 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-MOW-V @
    _EXT4-REQUIRE-RUNTIME-ORPHAN-BINDING ?DUP IF EXIT THEN
    _EXT4-MOW-O-ACTIVE @
    _EXT4-MOW-CTX @ _EXT4-C.O.RUNTIME-CAPACITY + @ U> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-MOW-ENTRY  ( allow-modern-orphan-union? -- ior )
    _EXT4-MOW-ALLOW-ORPHAN-UNION !
    _EXT4-MOW-V @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MOW-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-V @ V.VOLUME @ DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN _EXT4-IO-VOL !
    _EXT4-MOW-V @ _EXT4-IO-VFS !
    _EXT4-MOW-V @ V.BCTX @ DUP _EXT4-MOW-CTX ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOW-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.START + @
    _EXT4-MOW-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-MOW-REQUIRE-ORPHAN-STATE ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-C.RECOVERY + @ 0<> DUP
    _EXT4-MOW-ACTIVE !
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0<> = 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-MOW-ACTIVE @ IF
        _EXT4-MOW-V @ V.FLAGS @ VFS-F-DIRTY AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-MOW-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
            DUP _EXT4-JWR.FAULT + @ ?DUP IF NIP EXIT THEN
            DROP VFS-E-BUSY EXIT
        THEN
        DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-MOW-V @ V.FLAGS @ VFS-F-DIRTY AND IF
            VFS-E-BUSY EXIT
        THEN
    THEN
    _EXT4-MOW-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-PROVE-OWNERSHIP ;

\ =====================================================================
\  Private VFS-shaped write boundary and trusted clock injection
\ =====================================================================
\
\ The binding ABI does not carry a timestamp.  Keep the time authority on
\ the ext4 instance instead of consulting EPOCH@ or another ambient clock.
\ The provider returns one nonnegative Unix-epoch millisecond scalar:
\
\     now-ms-xt  ( clock-context -- epoch-ms ior )
\
\ Binding is allowed once, at the authenticated clean mounted endpoint and
\ before the first mutation.  Clock and workspace-profile binding may occur
\ in either order while a dedicated writer remains untouched, idle, and
\ clean.  The XT is stored last so it is the publication word for the
\ accompanying opaque context.

VARIABLE _EXT4-BWC-XT
VARIABLE _EXT4-BWC-CLOCK-CTX
VARIABLE _EXT4-BWC-V
VARIABLE _EXT4-BWC-CTX

: EXT4-BIND-WRITE-CLOCK?  ( now-ms-xt clock-context vfs -- ior )
    _EXT4-BWC-V ! _EXT4-BWC-CLOCK-CTX ! _EXT4-BWC-XT !
    _EXT4-BWC-XT @ 0= _EXT4-BWC-V @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-BWC-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-BWC-V @ V.BCTX @ DUP _EXT4-BWC-CTX ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-BWC-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-BWC-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-BWC-V @ V.FLAGS @ VFS-F-DIRTY AND IF VFS-E-BUSY EXIT THEN
    _EXT4-BWC-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-BWC-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-BWC-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-BWC-CTX @ _EXT4-C.J.WRITER + @ ?DUP IF
        _EXT4-BWC-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
        _EXT4-JWR-STORE-DEDICATED <> IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
            DROP VFS-E-BUSY EXIT
        THEN
        DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-BUSY EXIT THEN
        _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    THEN
    _EXT4-BWC-CTX @ _EXT4-C.WCLOCK-XT + @ IF VFS-E-CONFLICT EXIT THEN
    _EXT4-BWC-CLOCK-CTX @ _EXT4-BWC-CTX @ _EXT4-C.WCLOCK-CTX + !
    _EXT4-BWC-XT @ _EXT4-BWC-CTX @ _EXT4-C.WCLOCK-XT + !
    0 ;

