VARIABLE _XC-HP-ORDINAL
VARIABLE _XC-HP-COUNT
VARIABLE _XC-HP-STAGED-I
VARIABLE _XC-HP-STAGED-COUNT
VARIABLE _XC-HP-WRITER
VARIABLE _XC-HP-ENTRIES
VARIABLE _XC-HP-STRIDE
VARIABLE _XC-HP-TX-HOME
VARIABLE _XC-HP-MAPS
CREATE _XC-HP-SWAP _XC-HP-ENTRY-CELLS CELLS ALLOT

: _XC-HP-ENTRY  ( plan index -- entry )
    _XC-HP-ENTRY-CELLS * CELLS
    SWAP _XC-P.HOME-ENTRIES + + ;

: _XC-HP-ROLE?  ( role -- flag )
    DUP 0> SWAP _XC-HR-LIMIT U< AND ;

: _XC-HP-KIND?  ( kind -- flag )
    DUP 0< 0= SWAP 3 U< AND ;

: _XC-HP-COUNT?  ( plan -- plan flag )
    DUP _XC-P.HOME-COUNT + @ _XC-HP-CAPACITY U> 0= ;

\ A family role may bind several homes, each once; every other role binds
\ one.
: _XC-HP-FAMILY-ROLE?  ( role -- flag )
    DUP _XC-HR-DIRECTORY-GROWTH =
    OVER _XC-HR-DIRECTORY-MAP = OR
    SWAP _XC-HR-ALLOCATION = OR ;

\ Insert one semantic role without mutating the record on any refusal.  A
\ role binds one home, and a family role each of its homes once, so the
\ vector is bounded by the roles and the format bounds of the families.
\ Same-kind home aliases remain provisional until the complete pairwise
\ policy audit at seal.
: _XC-HP-ADD  ( plan role kind home -- plan ior )
    _XC-HP-HOME ! _XC-HP-KIND ! _XC-HP-ROLE !
    DUP _XC-P.STATE + @ _XC-PS-BUILDING-SHAPE-SET <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-HP-ROLE @ _XC-HP-ROLE? 0= IF VFS-E-INVALID EXIT THEN
    _XC-HP-KIND @ _XC-HP-KIND? 0= IF VFS-E-INVALID EXIT THEN
    DUP _XC-P.OWNER-CTX + @ DUP 0= IF DROP VFS-E-CORRUPT EXIT THEN
    _XC-HP-HOME @ OVER _EXT4-C.BLOCKS + @ U< 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-HP-HOME @ SWAP _EXT4-JOURNAL-DATA? IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _XC-HP-COUNT? 0= IF VFS-E-CORRUPT EXIT THEN
    0 _XC-HP-I !
    BEGIN
        _XC-HP-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-I @ _XC-HP-ENTRY
        DUP @ _XC-HP-ROLE @ = IF
            _XC-HP-ROLE @ _XC-HP-FAMILY-ROLE? 0=
            OVER 2 CELLS + @ _XC-HP-HOME @ = OR IF
                DROP VFS-E-CONFLICT EXIT
            THEN
        THEN
        DUP 2 CELLS + @ _XC-HP-HOME @ = IF
            CELL+ @ _XC-HP-KIND @ <> IF VFS-E-CONFLICT EXIT THEN
        ELSE
            DROP
        THEN
        1 _XC-HP-I +!
    REPEAT
    DUP _XC-P.HOME-COUNT + @
    DUP _XC-HP-CAPACITY U< 0= IF DROP VFS-E-CORRUPT EXIT THEN
    2DUP _XC-HP-ENTRY
    _XC-HP-ROLE @ OVER !
    _XC-HP-KIND @ OVER CELL+ !
    _XC-HP-HOME @ OVER 2 CELLS + !
    DROP 1+ OVER _XC-P.HOME-COUNT + !
    0 ;

: _XC-HP-FIND-ROLE  ( plan role -- plan entry ior )
    _XC-HP-ROLE !
    _XC-HP-ROLE @ _XC-HP-ROLE? 0= IF 0 VFS-E-INVALID EXIT THEN
    _XC-HP-COUNT? 0= IF 0 VFS-E-CORRUPT EXIT THEN
    0 _XC-HP-FIND-I !
    BEGIN
        _XC-HP-FIND-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-FIND-I @ _XC-HP-ENTRY
        DUP @ _XC-HP-ROLE @ = IF 0 EXIT THEN
        DROP 1 _XC-HP-FIND-I +!
    REPEAT
    0 VFS-E-CONFLICT ;

: _XC-HP-ROLE@  ( plan role -- plan kind home ior )
    _XC-HP-ROLE !
    DUP _XC-P.STATE + @ _XC-PS-SEALED <> IF
        0 0 VFS-E-CORRUPT EXIT
    THEN
    _XC-HP-ROLE @ _XC-HP-FIND-ROLE
    DUP IF >R DROP 0 0 R> EXIT THEN DROP
    DUP CELL+ @ SWAP 2 CELLS + @ 0 ;

\ Inspect two semantic roles without exposing an entry index or a second home
\ array.  This is used by the seal-time alias policy, not only by tests.
: _XC-HP-ROLES-ALIAS?  ( plan role-a role-b -- plan aliased? ior )
    _XC-HP-ALIAS-B ! _XC-HP-ALIAS-A !
    _XC-HP-ALIAS-A @ _XC-HP-ALIAS-B @ = IF FALSE 0 EXIT THEN
    _XC-HP-ALIAS-A @ _XC-HP-FIND-ROLE
    DUP IF >R DROP FALSE R> EXIT THEN DROP
    DUP CELL+ @ _XC-HP-KIND !
    2 CELLS + @ _XC-HP-HOME !
    _XC-HP-ALIAS-B @ _XC-HP-FIND-ROLE
    DUP IF >R DROP FALSE R> EXIT THEN DROP
    DUP CELL+ @ _XC-HP-KIND @ =
    SWAP 2 CELLS + @ _XC-HP-HOME @ = AND 0 ;

: _XC-HP-INODE-TABLE-ROLE?  ( role -- flag )
    DUP _XC-HR-INODE =
    OVER _XC-HR-PARENT-INODE = OR
    OVER _XC-HR-RENAME-OLD-PARENT-INODE = OR
    SWAP _XC-HR-RENAME-VICTIM-INODE = OR ;

\ Two roles share a home only as inode records in one inode-table block.
: _XC-HP-ALIAS-ALLOWED?  ( role-a role-b -- flag )
    _XC-HP-INODE-TABLE-ROLE? SWAP _XC-HP-INODE-TABLE-ROLE? AND ;

: _XC-HP-TABLE?  ( plan -- plan flag )
    DUP _XC-P.HOME-COUNT + @
    DUP 0= SWAP _XC-HP-CAPACITY U> OR IF FALSE EXIT THEN
    0 _XC-HP-I !
    BEGIN
        _XC-HP-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-I @ _XC-HP-ENTRY
        DUP @ _XC-HP-OUTER-ROLE !
        DUP CELL+ @ _XC-HP-KIND !
        2 CELLS + @ _XC-HP-HOME !
        _XC-HP-OUTER-ROLE @ _XC-HP-ROLE? 0= IF FALSE EXIT THEN
        _XC-HP-KIND @ _XC-HP-KIND? 0= IF FALSE EXIT THEN
        DUP _XC-P.OWNER-CTX + @ DUP 0= IF DROP FALSE EXIT THEN
        _XC-HP-HOME @ OVER _EXT4-C.BLOCKS + @ U< 0= IF
            DROP FALSE EXIT
        THEN
        _XC-HP-HOME @ SWAP _EXT4-JOURNAL-DATA? IF FALSE EXIT THEN
        0 _XC-HP-J !
        BEGIN _XC-HP-J @ _XC-HP-I @ U< WHILE
            DUP _XC-HP-J @ _XC-HP-ENTRY
            DUP @ _XC-HP-OUTER-ROLE @ = IF
                _XC-HP-OUTER-ROLE @ _XC-HP-FAMILY-ROLE? 0=
                OVER 2 CELLS + @ _XC-HP-HOME @ = OR IF DROP FALSE EXIT THEN
            THEN
            DUP 2 CELLS + @ _XC-HP-HOME @ = IF
                CELL+ @ _XC-HP-KIND @ <> IF FALSE EXIT THEN
            ELSE
                DROP
            THEN
            1 _XC-HP-J +!
        REPEAT
        1 _XC-HP-I +!
    REPEAT
    TRUE ;

: _XC-HP-ALIASES?  ( plan -- plan flag )
    0 _XC-HP-I !
    BEGIN
        _XC-HP-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-I @ _XC-HP-ENTRY
        DUP @ _XC-HP-OUTER-ROLE !
        2 CELLS + @ _XC-HP-HOME !
        _XC-HP-I @ 1+ _XC-HP-J !
        BEGIN
            _XC-HP-J @ OVER _XC-P.HOME-COUNT + @ U<
        WHILE
            DUP _XC-HP-J @ _XC-HP-ENTRY
            DUP 2 CELLS + @ _XC-HP-HOME @ = IF
                @ _XC-HP-ALIAS-B !
                _XC-HP-OUTER-ROLE @ _XC-HP-ALIAS-B @
                _XC-HP-ROLES-ALIAS?
                DUP IF 2DROP FALSE EXIT THEN DROP
                0= IF FALSE EXIT THEN
                _XC-HP-OUTER-ROLE @ _XC-HP-ALIAS-B @
                _XC-HP-ALIAS-ALLOWED? 0= IF FALSE EXIT THEN
            ELSE
                DROP
            THEN
            1 _XC-HP-J +!
        REPEAT
        1 _XC-HP-I +!
    REPEAT
    TRUE ;

: _XC-P-SEAL  ( plan -- plan ior )
    DUP _XC-P.STATE + @ _XC-PS-BUILDING-SHAPE-SET <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-P-SHAPE? 0= IF VFS-E-CORRUPT EXIT THEN
    _XC-HP-TABLE? 0= IF VFS-E-CORRUPT EXIT THEN
    _XC-HP-ALIASES? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-PS-SEALED OVER _XC-P.STATE + !
    0 ;

: _XC-P-REQUIRE-SEALED  ( plan ctx op -- plan ior )
    DUP _XC-P-OP? 0= IF 2DROP VFS-E-INVALID EXIT THEN
    OVER 0= IF 2DROP VFS-E-INVALID EXIT THEN
    2 PICK _XC-P.STATE + @ _XC-PS-SEALED <> IF
        2DROP VFS-E-CORRUPT EXIT
    THEN
    2 PICK _XC-P-SHAPE? NIP 0= IF 2DROP VFS-E-CORRUPT EXIT THEN
    2 PICK _XC-P.OWNER-CTX + @ 2 PICK <>
    3 PICK _XC-P.OP + @ 2 PICK <> OR IF
        2DROP VFS-E-CONFLICT EXIT
    THEN
    \ Seal already performed the full bounds, journal-exclusion, table, and
    \ alias audit.  Every staged pass immediately rebinds the exact expected
    \ role/kind/home vector and count before it may publish an image, then the
    \ final boundary reconciles first-seen order against the writer tables.
    2DROP 0 ;

: _XC-HP-FIRST?  ( plan index -- plan flag )
    _XC-HP-AT !
    _XC-HP-AT @ OVER _XC-P.HOME-COUNT + @ U< 0= IF FALSE EXIT THEN
    DUP _XC-HP-AT @ _XC-HP-ENTRY 2 CELLS + @ _XC-HP-HOME !
    0 _XC-HP-SCAN !
    BEGIN _XC-HP-SCAN @ _XC-HP-AT @ U< WHILE
        DUP _XC-HP-SCAN @ _XC-HP-ENTRY 2 CELLS + @
        _XC-HP-HOME @ = IF FALSE EXIT THEN
        1 _XC-HP-SCAN +!
    REPEAT
    TRUE ;

: _XC-HP-CREDITS@  ( plan -- plan meta data revoke ior )
    DUP _XC-P.STATE + @ _XC-PS-SEALED <> IF
        0 0 0 VFS-E-CORRUPT EXIT
    THEN
    _XC-HP-COUNT? 0= IF 0 0 0 VFS-E-CORRUPT EXIT THEN
    0 _XC-HP-META-CREDIT !
    0 _XC-HP-DATA-CREDIT !
    0 _XC-HP-REVOKE-CREDIT !
    0 _XC-HP-I !
    BEGIN
        _XC-HP-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        _XC-HP-I @ _XC-HP-FIRST? IF
            DUP _XC-HP-I @ _XC-HP-ENTRY CELL+ @
            DUP _XC-HK-META = IF
                DROP 1 _XC-HP-META-CREDIT +!
            ELSE DUP _XC-HK-DATA = IF
                DROP 1 _XC-HP-DATA-CREDIT +!
            ELSE _XC-HK-REVOKE = IF
                1 _XC-HP-REVOKE-CREDIT +!
            ELSE
                0 0 0 VFS-E-CORRUPT EXIT
            THEN THEN THEN
        THEN
        1 _XC-HP-I +!
    REPEAT
    _XC-HP-META-CREDIT @ _XC-HP-DATA-CREDIT @
    _XC-HP-REVOKE-CREDIT @ 0 ;

: _XC-HP-HOME@  ( plan kind ordinal -- plan home ior )
    _XC-HP-ORDINAL ! _XC-HP-KIND !
    DUP _XC-P.STATE + @ _XC-PS-SEALED <> IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _XC-HP-KIND @ _XC-HP-KIND? 0= IF 0 VFS-E-INVALID EXIT THEN
    _XC-HP-ORDINAL @ 0< IF 0 VFS-E-INVALID EXIT THEN
    _XC-HP-COUNT? 0= IF 0 VFS-E-CORRUPT EXIT THEN
    0 _XC-HP-COUNT ! 0 _XC-HP-I !
    BEGIN
        _XC-HP-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-I @ _XC-HP-ENTRY CELL+ @ _XC-HP-KIND @ = IF
            _XC-HP-I @ _XC-HP-FIRST? IF
                _XC-HP-COUNT @ _XC-HP-ORDINAL @ = IF
                    DUP _XC-HP-I @ _XC-HP-ENTRY 2 CELLS + @ 0 EXIT
                THEN
                1 _XC-HP-COUNT +!
            THEN
        THEN
        1 _XC-HP-I +!
    REPEAT
    0 VFS-E-CONFLICT ;

: _XC-HP-REQUIRE-KIND
  ( plan kind entries entry-cells count -- plan ior )
    _XC-HP-STAGED-COUNT !
    _XC-HP-STRIDE ! _XC-HP-ENTRIES ! _XC-HP-KIND !
    0 _XC-HP-STAGED-I !
    BEGIN _XC-HP-STAGED-I @ _XC-HP-STAGED-COUNT @ U< WHILE
        _XC-HP-KIND @ _XC-HP-STAGED-I @ _XC-HP-HOME@
        DUP IF >R DROP R> EXIT THEN DROP
        _XC-HP-HOME !
        _XC-HP-STAGED-I @ _XC-HP-STRIDE @ * CELLS
        _XC-HP-ENTRIES @ +
        DUP @ _XC-HP-HOME @ <>
        SWAP CELL+ @ _EXT4-JE-ACTIVE <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        1 _XC-HP-STAGED-I +!
    REPEAT
    0 ;

: _XC-HP-REQUIRE-CREDITS  ( plan writer -- plan ior )
    _XC-HP-WRITER !
    _XC-HP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _XC-HP-CREDITS@
    DUP IF >R 2DROP DROP R> EXIT THEN DROP
    _XC-HP-REVOKE-CREDIT !
    _XC-HP-DATA-CREDIT !
    _XC-HP-META-CREDIT !
    _XC-HP-WRITER @ _EXT4-JWR.META-CREDIT + @
        _XC-HP-META-CREDIT @ <>
    _XC-HP-WRITER @ _EXT4-JWR.DATA-CREDIT + @
        _XC-HP-DATA-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
        _XC-HP-REVOKE-CREDIT @ <> OR IF
        VFS-E-INVALID EXIT
    THEN
    0 ;

: _XC-HP-REQUIRE-STAGED  ( plan writer -- plan ior )
    _XC-HP-WRITER !
    _XC-HP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _XC-HP-CREDITS@
    DUP IF >R 2DROP DROP R> EXIT THEN DROP
    _XC-HP-REVOKE-CREDIT !
    _XC-HP-DATA-CREDIT !
    _XC-HP-META-CREDIT !
    _XC-HP-WRITER @ _EXT4-JWR.META-CREDIT + @
        _XC-HP-META-CREDIT @ <>
    _XC-HP-WRITER @ _EXT4-JWR.DATA-CREDIT + @
        _XC-HP-DATA-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
        _XC-HP-REVOKE-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.META-USED + @
        _XC-HP-META-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.DATA-USED + @
        _XC-HP-DATA-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.REVOKE-USED + @
        _XC-HP-REVOKE-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.META-ACTIVE + @
        _XC-HP-META-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
        _XC-HP-DATA-CREDIT @ <> OR
    _XC-HP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
        _XC-HP-REVOKE-CREDIT @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-HP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-HK-META
    _XC-HP-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS _XC-HP-META-CREDIT @
    _XC-HP-REQUIRE-KIND ?DUP IF EXIT THEN
    _XC-HK-DATA
    _XC-HP-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS _XC-HP-DATA-CREDIT @
    _XC-HP-REQUIRE-KIND ?DUP IF EXIT THEN
    _XC-HK-REVOKE
    _XC-HP-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS _XC-HP-REVOKE-CREDIT @
    _XC-HP-REQUIRE-KIND ;

\ The sealed plan binds family role ROLE to KIND and HOME.
: _XC-HP-PAIR?  ( plan -- plan ior )
    0 _XC-HP-FIND-I !
    BEGIN
        _XC-HP-FIND-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-FIND-I @ _XC-HP-ENTRY
        DUP @ _XC-HP-ROLE @ =
        OVER CELL+ @ _XC-HP-KIND @ = AND
        SWAP 2 CELLS + @ _XC-HP-HOME @ = AND IF 0 EXIT THEN
        1 _XC-HP-FIND-I +!
    REPEAT
    VFS-E-CONFLICT ;

\ Before seal this inserts.  A sealed plan instead requires the role, or for
\ a family role one of its entries, to bind exactly this kind and home.
: _XC-HP-BIND  ( plan role kind home -- plan ior )
    _XC-HP-HOME ! _XC-HP-KIND ! _XC-HP-ROLE !
    DUP _XC-P.STATE + @ _XC-PS-SEALED = IF
        _XC-HP-ROLE @ _XC-HP-FAMILY-ROLE? IF _XC-HP-PAIR? EXIT THEN
        _XC-HP-ROLE @ _XC-HP-ROLE@
        DUP IF >R 2DROP R> EXIT THEN DROP
        _XC-HP-HOME @ <>
        SWAP _XC-HP-KIND @ <> OR IF VFS-E-CONFLICT EXIT THEN
        0 EXIT
    THEN
    _XC-HP-ROLE @ _XC-HP-KIND @ _XC-HP-HOME @ _XC-HP-ADD ;

: _XC-HP-BIND-META  ( plan role home -- plan ior )
    _XC-HK-META SWAP _XC-HP-BIND ;

: _XC-HP-PREFLIGHT  ( plan -- plan ior )
    _XC-HP-CREDITS@
    DUP IF >R 2DROP DROP R> EXIT THEN DROP
    3 PICK _XC-P.OWNER-CTX + @ _EXT4-JTX-PREFLIGHT-CAPACITY ;

: _XC-HP-ENSURE  ( plan -- plan writer ior )
    _XC-HP-CREDITS@
    DUP IF >R 2DROP DROP 0 R> EXIT THEN DROP
    3 PICK _XC-P.OWNER-CTX + @ _EXT4-JWR-ENSURE ;

: _XC-HP-BEGIN-TX  ( plan writer -- plan transaction ior )
    _XC-HP-WRITER !
    _XC-HP-CREDITS@
    DUP IF >R 2DROP DROP 0 R> EXIT THEN DROP
    _XC-HP-WRITER @ _EXT4-JTX-BEGIN ;

\ Whether an entry from index AT on binds HOME; FIND-I holds the first one.
: _XC-HP-HOME-FROM?  ( plan at home -- plan flag )
    _XC-HP-HOME ! _XC-HP-FIND-I !
    BEGIN
        _XC-HP-FIND-I @ OVER _XC-P.HOME-COUNT + @ U<
    WHILE
        DUP _XC-HP-FIND-I @ _XC-HP-ENTRY 2 CELLS + @
        _XC-HP-HOME @ = IF TRUE EXIT THEN
        1 _XC-HP-FIND-I +!
    REPEAT
    FALSE ;

\ The role of a home an insert's staging did not name itself: the primary
\ superblock, a block bitmap or descriptor page that block allocation
\ staged, which are static metadata, or else a node of the parent's extent
\ tree.
: _XC-HP-CLASSIFY  ( home -- role ior )
    DUP _XC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = IF
        DROP _XC-HR-PRIMARY-SUPER 0 EXIT
    THEN
    _XC-CTX @ _EXT4-SR-CURRENT ?DUP IF NIP 0 SWAP EXIT THEN
    1 _EXT4-SR-ALIAS? IF _XC-HR-ALLOCATION ELSE _XC-HR-DIRECTORY-MAP THEN
    0 ;

\ Move entry FROM back to AT, keeping the order of the entries between.
: _XC-HP-RAISE  ( plan from at -- plan )
    _XC-HP-AT ! _XC-HP-SCAN !
    DUP _XC-HP-SCAN @ _XC-HP-ENTRY _XC-HP-SWAP
    _XC-HP-ENTRY-CELLS CELLS MOVE
    DUP _XC-HP-AT @ _XC-HP-ENTRY OVER _XC-HP-AT @ 1+ _XC-HP-ENTRY
    _XC-HP-SCAN @ _XC-HP-AT @ - _XC-HP-ENTRY-CELLS * CELLS MOVE
    _XC-HP-SWAP OVER _XC-HP-AT @ _XC-HP-ENTRY
    _XC-HP-ENTRY-CELLS CELLS MOVE ;

\ Put the entries in the order in which the transaction first stages their
\ homes; every entry must bind one of them.
: _XC-HP-ORDER  ( plan -- plan ior )
    0 _XC-HP-J ! 0 _XC-HP-STAGED-I !
    BEGIN
        _XC-HP-STAGED-I @ _XC-HP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _XC-HP-STAGED-I @ _XC-HP-WRITER @ _EXT4-JWR-META-ENTRY @
        _XC-HP-TX-HOME !
        _XC-HP-J @ _XC-HP-I !
        BEGIN
            _XC-HP-I @ OVER _XC-P.HOME-COUNT + @ U<
        WHILE
            DUP _XC-HP-I @ _XC-HP-ENTRY 2 CELLS + @
            _XC-HP-TX-HOME @ = IF
                _XC-HP-I @ _XC-HP-J @ _XC-HP-RAISE
                1 _XC-HP-J +!
            THEN
            1 _XC-HP-I +!
        REPEAT
        1 _XC-HP-STAGED-I +!
    REPEAT
    DUP _XC-P.HOME-COUNT + @ _XC-HP-J @ <> IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ Complete a measured insert's certificate from its staged transaction.
\ Staging bound each home it names itself; every other metadata home is
\ bound here under the role it plays, and the extent-tree nodes among them
\ must be exactly the ones the tree edit allocated or first edited.  An
\ insert stages no ordered data and no revoke.
: _XC-HP-BIND-TRANSACTION  ( plan writer -- plan ior )
    _XC-HP-WRITER !
    _XC-HP-WRITER @ _EXT4-JWR.DATA-USED + @
    _XC-HP-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR IF VFS-E-CORRUPT EXIT THEN
    0 _XC-HP-MAPS ! 0 _XC-HP-STAGED-I !
    BEGIN
        _XC-HP-STAGED-I @ _XC-HP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _XC-HP-STAGED-I @ _XC-HP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP CELL+ @ _EXT4-JE-ACTIVE <> IF DROP VFS-E-CORRUPT EXIT THEN
        @ _XC-HP-TX-HOME !
        0 _XC-HP-TX-HOME @ _XC-HP-HOME-FROM? 0= IF
            _XC-HP-TX-HOME @ _XC-HP-CLASSIFY ?DUP IF NIP EXIT THEN
            DUP _XC-HR-DIRECTORY-MAP = IF 1 _XC-HP-MAPS +! THEN
            _XC-HK-META _XC-HP-TX-HOME @ _XC-HP-ADD ?DUP IF EXIT THEN
        THEN
        1 _XC-HP-STAGED-I +!
    REPEAT
    _XC-HP-MAPS @ _XN-NEW-NODES @ _XN-EXISTING @ + <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _XC-HP-ORDER ;

: _XC-DIRENT-NAME=?  ( dirent -- flag )
    _XC-NAME-SNAPSHOT _XC-NLEN @ _EXT4-DIRENT-HOLDS? ;

\ A named inode's record has its type: two for a directory, zero or one for
\ a regular file.
: _XC-RECORD-TYPE?  ( dirent dir? -- flag )
    SWAP 7 + C@ SWAP IF 2 = ELSE 1 U> 0= THEN ;

\ In a removal's or a rename's scan, note the live record at DIR-OFF: count
\ it when it names the target's inode, and when it holds the find name, the
\ removed name or the rename's old one, take its place, its length and its
\ predecessor in the block, the record before it, live or unused, or none.
\ The name holds the target's inode and its type.
: _XC-FIND-RECORD  ( -- ior )
    _XC-DIR-INODE @ _XC-INODE @ = IF 1 _XC-REFS +! THEN
    _XC-DIR-DE @ _XC-FIND-NAME @ _XC-FIND-NLEN @ _EXT4-DIRENT-HOLDS? 0= IF
        0 EXIT
    THEN
    _XC-FOUND @ IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    _XC-DIR-INODE @ _XC-INODE @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-DIR-DE @ _XC-DIRECTORY @ _XC-RECORD-TYPE? 0= IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    -1 _XC-FOUND !
    _XC-DIR-OFF @ _XC-RM-OFF ! _XC-DIR-REC @ _XC-RM-REC !
    _XC-PREV-OFF @ _XC-RM-PREV-OFF ! _XC-PREV-REC @ _XC-RM-PREV-REC !
    0 ;

\ In a rename's scan of its new parent, note the live record at DIR-OFF
\ against the victim: count it when it names the victim's inode, and when
\ it holds the new name take its place and length.  The name holds the
\ victim's inode and its type.
: _XC-FIND-VICTIM  ( -- ior )
    _XC-DIR-INODE @ _XC-VICTIM-INO @ = IF 1 _XC-VICTIM-REFS +! THEN
    _XC-DIR-DE @ _XC-DIRENT-NAME=? 0= IF 0 EXIT THEN
    _XC-VICTIM-FOUND @ IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    _XC-DIR-INODE @ _XC-VICTIM-INO @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-DIR-DE @ _XC-VICTIM-DIR @ _XC-RECORD-TYPE? 0= IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    -1 _XC-VICTIM-FOUND !
    _XC-DIR-OFF @ _XC-VICTIM-DE-OFF ! _XC-DIR-REC @ _XC-VICTIM-DE-REC !
    0 ;

\ Note the live record at DIR-OFF in the walk's modes: the find name's
\ record, the victim's, or, while the new name must be absent, the new name
\ itself, which answers EXISTS.
: _XC-NOTE-LIVE  ( -- exists? ior )
    _XC-WALK-SOURCE @ IF
        _XC-FIND-RECORD ?DUP IF FALSE SWAP EXIT THEN
    THEN
    _XC-WALK-VICTIM @ IF
        _XC-FIND-VICTIM ?DUP IF FALSE SWAP EXIT THEN
    THEN
    _XC-WALK-INSERT @ IF _XC-DIR-DE @ _XC-DIRENT-NAME=? 0 EXIT THEN
    FALSE 0 ;

\ Note the first record of the block with room for the new name: a live
\ record's slack past its used length, USED bytes at DIR-USED, or an unused
\ record.
: _XC-NOTE-SLOT  ( live? -- )
    _XC-INSERT-OFF @ -1 <> IF DROP EXIT THEN
    IF
        _XC-DIR-REC @ _XC-DIR-USED @ - _XC-NEEDED @ U< IF EXIT THEN
        1 _XC-INSERT-KIND !
        _XC-DIR-OFF @ _XC-INSERT-PREV-OFF !
        _XC-DIR-USED @ _XC-INSERT-PREV-USED !
        _XC-DIR-OFF @ _XC-DIR-USED @ + _XC-INSERT-OFF !
        _XC-DIR-REC @ _XC-DIR-USED @ - _XC-INSERT-REC !
    ELSE
        _XC-DIR-REC @ _XC-NEEDED @ U< IF EXIT THEN
        2 _XC-INSERT-KIND !
        _XC-DIR-OFF @ _XC-INSERT-OFF !
        _XC-DIR-REC @ _XC-INSERT-REC !
    THEN ;

: _XC-DIR-SCAN  ( -- ior )
    0 _XC-DIR-DOT ! 0 _XC-DIR-DOTDOT !
    -1 _XC-INSERT-OFF ! 0 _XC-INSERT-KIND !
    -1 _XC-PREV-OFF ! 0 _XC-PREV-REC !
    0 _XC-DIR-OFF !
    _XC-CTX @ _EXT4-C.BSIZE + @ 12 - _XC-DIR-LIMIT !
    BEGIN _XC-DIR-OFF @ _XC-DIR-LIMIT @ < WHILE
        _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-DIR-OFF @ +
        DUP _XC-DIR-DE !
        4 + W@ DUP _XC-DIR-REC !
        DUP 12 U< SWAP 3 AND 0<> OR IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-OFF @ _XC-DIR-REC @ + _XC-DIR-LIMIT @ > IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-DE @ 6 + C@ DUP _XC-DIR-NAME-LEN !
        _XC-DIR-REC @ 8 - U> IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-DE @ L@ DUP _XC-DIR-INODE ! IF
            _XC-DIR-INODE @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-NAME-LEN @ 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 8 + _XC-DIR-NAME-LEN @
            _EXT4-DIRENT-NAME-VALID? 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 7 + C@ _EXT4-DIRENT>TYPE 0= IF
                DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN DROP
            _XC-DIR-NAME-LEN @ 1 =
            _XC-DIR-DE @ 8 + C@ [CHAR] . = AND IF
                _XC-DIR-INODE @ _XC-PARENT-INO @ <>
                _XC-DIR-DOT @ OR IF
                    EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                THEN
                -1 _XC-DIR-DOT !
            ELSE
                _XC-DIR-NAME-LEN @ 2 =
                _XC-DIR-DE @ 8 + C@ [CHAR] . = AND
                _XC-DIR-DE @ 9 + C@ [CHAR] . = AND IF
                    _XC-DIR-INODE @ _XC-PARENT-PARENT-INO @ <>
                    _XC-DIR-DOTDOT @ OR IF
                        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
                    THEN
                    -1 _XC-DIR-DOTDOT !
                ELSE
                    _XC-NOTE-LIVE ?DUP IF NIP EXIT THEN
                    IF VFS-E-EXISTS EXIT THEN
                THEN
            THEN
            _XC-DIR-NAME-LEN @ 8 + 3 + -4 AND
            DUP _XC-DIR-USED !
            _XC-DIR-REC @ U> IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-WALK-INSERT @ IF TRUE _XC-NOTE-SLOT THEN
        ELSE
            _XC-DIR-NAME-LEN @
            _XC-DIR-DE @ 7 + C@ OR IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-WALK-INSERT @ IF FALSE _XC-NOTE-SLOT THEN
        THEN
        _XC-DIR-OFF @ _XC-PREV-OFF ! _XC-DIR-REC @ _XC-PREV-REC !
        _XC-DIR-REC @ _XC-DIR-OFF +!
    REPEAT
    _XC-DIR-OFF @ _XC-DIR-LIMIT @ <>
    _XC-DIR-DOT @ 0= OR _XC-DIR-DOTDOT @ 0= OR IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _XC-HASH-SUPER

\ Recheck the live primary fields that select the HTree hash function and
\ seed.  Generic read mounts may tolerate historically stale backup s_flags;
\ mutation instead binds the checksummed live primary to the mounted cache.
: _XC-REQUIRE-HASH-AUTHORITY  ( -- ior )
    _XC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK +
    _XC-CTX @ _EXT4-PRIMARY-SUPER-OFF + DUP _XC-HASH-SUPER !
    _EXT4-SUPER-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-HASH-SUPER @ _EXT4-SUPER-SEED? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-HASH-SUPER @ _EXT4-SB.HASH-SEED +
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.HASH-SEED + 16
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-HASH-SUPER @ _EXT4-SB.DEFAULT-HASH + C@
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.DEFAULT-HASH + C@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-HASH-SUPER @ _EXT4-SB.FLAGS + L@
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.FLAGS + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 ;

\ ---------------------------------------------------------------------
\  Splitting a full block
\ ---------------------------------------------------------------------
\
\ A full block splits as the kernel's do_split does.  Each live record of
\ the block is one cell of the record map, its name's hash above its offset
\ in the block, so that sorting the cells orders the records by hash.
\ Records move to the new block from the highest hash down while the moved
\ bytes, with half the next record's, stay within half the block; a
\ record's bytes are its rec_len, and the last record of a converted linear
\ block also spans the bytes `.` and `..` leave to it.  A block whose sizes
\ defeat that rule splits its records in half by count.  The first moved
\ hash, with the continuation bit when the record before it has the same
\ hash, separates the two blocks.  The kept records stay in block order and
\ the moved ones follow in hash order, each packed to its used length, and
\ the new name joins the side its hash falls on.

: _XC-RECORD-USED  ( record -- bytes )  6 + C@ 8 + 3 + -4 AND ;

\ The bytes the record at OFFSET of the split source spans.
: _XC-RECORD-SPAN  ( offset -- bytes )
    DUP _XC-SPLIT-SOURCE @ + 4 + W@
    TUCK + _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - = IF
        _XC-SPLIT-BASE @ +
    THEN ;

\ The record map's cell at INDEX of the hash-sorted copy.
: _XC-SORTED@  ( plan index -- plan cell )
    CELLS OVER _XC-P.SORTED + + @ ;

\ Sort the record map, choose where the block splits and its separator, and
\ find the side the new name joins, which must have room for it.  A block
\ with fewer than two live records cannot split.
: _XC-CHOOSE-SPLIT  ( plan -- plan ior )
    _XC-SPLIT-COUNT @ 2 U< IF VFS-E-NOSPC EXIT THEN
    DUP _XC-P.DIR-SNAPSHOT + _XC-SPLIT-SOURCE !
    DUP _XC-P.RECORDS + OVER _XC-P.SORTED +
    _XC-SPLIT-COUNT @ CELLS MOVE
    DUP _XC-P.SORTED + _XC-SPLIT-COUNT @ _EXT4-SORT-CELLS
    0 _XC-SPLIT-SIZE ! 0 _XC-SPLIT-MOVE !
    _XC-SPLIT-COUNT @ 1- _XC-SPLIT-I !
    BEGIN
        _XC-SPLIT-I @ 0< IF
            FALSE
        ELSE
            _XC-SPLIT-I @ _XC-SORTED@ 0xFFFF AND _XC-RECORD-SPAN 2/
            _XC-SPLIT-SIZE @ +
            _XC-CTX @ _EXT4-C.BSIZE + @ 2/ U> 0=
        THEN
    WHILE
        _XC-SPLIT-I @ _XC-SORTED@ 0xFFFF AND _XC-RECORD-SPAN
        _XC-SPLIT-SIZE +!
        1 _XC-SPLIT-MOVE +!
        -1 _XC-SPLIT-I +!
    REPEAT
    _XC-SPLIT-I @ 0> IF
        _XC-SPLIT-COUNT @ _XC-SPLIT-MOVE @ -
    ELSE
        _XC-SPLIT-COUNT @ 2/
    THEN _XC-SPLIT-AT !
    _XC-SPLIT-AT @ _XC-SORTED@ DUP _XC-SPLIT-KEY !
    16 RSHIFT DUP _XC-SPLIT-SEPARATOR !
    _XC-INDEX-HASH @ SWAP U< 0= _XC-SPLIT-HIGH !
    _XC-SPLIT-AT @ 1- _XC-SORTED@ 16 RSHIFT
    _XC-SPLIT-SEPARATOR @ = IF 1 _XC-SPLIT-SEPARATOR +! THEN
    0 _XC-SPLIT-LOW-USED ! 0 _XC-SPLIT-HIGH-USED !
    _XC-SPLIT-COUNT @ 0 ?DO
        I _XC-SORTED@ 0xFFFF AND _XC-SPLIT-SOURCE @ + _XC-RECORD-USED
        I _XC-SPLIT-AT @ < IF
            _XC-SPLIT-LOW-USED
        ELSE
            _XC-SPLIT-HIGH-USED
        THEN +!
    LOOP
    _XC-SPLIT-HIGH @ IF _XC-SPLIT-HIGH-USED ELSE _XC-SPLIT-LOW-USED THEN @
    _XC-NEEDED @ +
    _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - U> IF VFS-E-NOSPC EXIT THEN
    0 ;

\ The record map of a full linear block: every live record after `.` at
\ offset 0 and `..` at offset 12, where the root keeps them.  The last
\ record also spans the bytes they leave to it.
: _XC-CONVERT-RECORDS  ( plan -- plan ior )
    DUP _XC-P.DIR-SNAPSHOT + _XC-SPLIT-SOURCE !
    DUP _XC-P.RECORDS + _XC-SPLIT-RECORDS !
    _XC-SPLIT-SOURCE @
    DUP 4 + W@ 12 <>
    OVER 6 + C@ 1 <> OR
    OVER 8 + C@ [CHAR] . <> OR
    OVER 18 + C@ 2 <> OR
    SWAP 20 + W@ 0x2E2E <> OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-SPLIT-SOURCE @ 16 + W@ 12 + DUP _XC-SPLIT-BASE ! _XC-DIR-OFF !
    0 _XC-SPLIT-COUNT !
    BEGIN
        _XC-DIR-OFF @ _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - U<
    WHILE
        _XC-SPLIT-SOURCE @ _XC-DIR-OFF @ + DUP _XC-DIR-DE !
        L@ IF
            _XC-SPLIT-COUNT @ _XC-RECORD-MAX U< 0= IF
                VFS-E-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 8 + _XC-DIR-DE @ 6 + C@
            _XC-HASH-VERSION @ _XC-CTX @ _EXT4-HALF-MD4-DIRHASH?
            _XC-IOR ! DROP
            _XC-IOR @ ?DUP IF NIP EXIT THEN
            16 LSHIFT _XC-DIR-OFF @ OR
            _XC-SPLIT-RECORDS @ _XC-SPLIT-COUNT @ CELLS + !
            1 _XC-SPLIT-COUNT +!
        THEN
        _XC-DIR-DE @ 4 + W@ _XC-DIR-OFF +!
    REPEAT
    0 ;

\ An HTree leaf contains no dot records.  Authenticate every live entry's
\ name, type, inode bound, and hash interval, and note the names the walk
\ looks for.  The selected leaf's scan also finds the first record with room
\ for the new name and records the leaf's record map for a split.
: _XC-INDEXED-LEAF-SCAN  ( plan selected? -- plan ior )
    _XC-INDEX-SELECTED !
    DUP _XC-P.RECORDS + _XC-SPLIT-RECORDS !
    _XC-INDEX-SELECTED @ IF
        0 _XC-SPLIT-COUNT !
        -1 _XC-INSERT-OFF ! 0 _XC-INSERT-KIND !
    THEN
    -1 _XC-PREV-OFF ! 0 _XC-PREV-REC !
    0 _XC-DIR-OFF !
    _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - _XC-DIR-LIMIT !
    BEGIN _XC-DIR-OFF @ _XC-DIR-LIMIT @ < WHILE
        _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-DIR-OFF @ +
        DUP _XC-DIR-DE !
        4 + W@ DUP _XC-DIR-REC !
        DUP 12 U< SWAP 3 AND 0<> OR IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-OFF @ _XC-DIR-REC @ + _XC-DIR-LIMIT @ > IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-DE @ 6 + C@ DUP _XC-DIR-NAME-LEN !
        _XC-DIR-REC @ 8 - U> IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-DIR-DE @ L@ DUP _XC-DIR-INODE ! IF
            _XC-DIR-INODE @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-NAME-LEN @ 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 8 + _XC-DIR-NAME-LEN @
            _EXT4-DIRENT-NAME-VALID? 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-DIR-DE @ 7 + C@ _EXT4-DIRENT>TYPE 0= IF
                DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN DROP
            _XC-DIR-NAME-LEN @ 1 =
            _XC-DIR-DE @ 8 + C@ [CHAR] . = AND
            _XC-DIR-NAME-LEN @ 2 =
            _XC-DIR-DE @ 8 + C@ [CHAR] . = AND
            _XC-DIR-DE @ 9 + C@ [CHAR] . = AND OR IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-NOTE-LIVE ?DUP IF NIP EXIT THEN
            IF -1 _XC-INDEX-DUPLICATE ! THEN
            _XC-DIR-DE @ 8 + _XC-DIR-NAME-LEN @
            _XC-DIRECTORY-DESC _EXT4-DD.DX-VERSION + @ _XC-CTX @
            _EXT4-HALF-MD4-DIRHASH?
            _XC-IOR ! DROP _XC-INDEX-SCAN-HASH !
            _XC-IOR @ ?DUP IF EXIT THEN
            _XC-INDEX-SCAN-HASH @ _XC-DIRECTORY-DESC
            _EXT4-DD-HASH-IN-INTERVAL? 0= IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-INDEX-SELECTED @ IF
                _XC-SPLIT-COUNT @ _XC-RECORD-MAX U< 0= IF
                    VFS-E-CORRUPT EXIT
                THEN
                _XC-INDEX-SCAN-HASH @ 16 LSHIFT _XC-DIR-OFF @ OR
                _XC-SPLIT-RECORDS @ _XC-SPLIT-COUNT @ CELLS + !
                1 _XC-SPLIT-COUNT +!
            THEN
            _XC-DIR-NAME-LEN @ 8 + 3 + -4 AND
            DUP _XC-DIR-USED !
            _XC-DIR-REC @ U> IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-INDEX-SELECTED @ IF TRUE _XC-NOTE-SLOT THEN
        ELSE
            _XC-DIR-NAME-LEN @
            _XC-DIR-DE @ 7 + C@ OR IF
                EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
            THEN
            _XC-INDEX-SELECTED @ IF FALSE _XC-NOTE-SLOT THEN
        THEN
        _XC-DIR-OFF @ _XC-PREV-OFF ! _XC-DIR-REC @ _XC-PREV-REC !
        _XC-DIR-REC @ _XC-DIR-OFF +!
    REPEAT
    _XC-DIR-OFF @ _XC-DIR-LIMIT @ <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ The operation must refer to the live VFS parent, not merely to an inode
\ number that still parses on disk.  CREATE and MKDIR create in the
\ working directory, as the generic VFS-MKFILE? and VFS-MKDIR do.  The
\ entry's dentry is the parent's child, except in a rename's new parent.
: _XC-REQUIRE-PARENT-RUNTIME  ( -- ior )
    _XC-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF VFS-E-STALE EXIT THEN
    _XC-V @ V.BCTX @ _XC-CTX @ <> IF VFS-E-STALE EXIT THEN
    _XC-V @ _EXT4-ATTACHED? 0= _XC-V @ _EXT4-READY? 0= OR IF
        VFS-E-STALE EXIT
    THEN
    _XC-RENAMING @ 0= _XC-WALK-SOURCE @ OR IF
        _XC-D @ IN.PARENT @ _XC-PARENT @ <> IF VFS-E-CONFLICT EXIT THEN
    THEN
    _XC-PARENT @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ D.VNODE @ _XC-PARENT-VN @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-PARENT-VN @ VN.TYPE @ VFS-T-DIR <> IF VFS-E-NOTDIR EXIT THEN
    _XC-PARENT-VN @ VN.BID @ _XC-PARENT-INO @ <> IF VFS-E-STALE EXIT THEN
    _XC-PARENT-VN @ VN.GEN @ _XC-PARENT-GEN @ <> IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ IN.PARENT @ ?DUP IF
        IN.BID @
    ELSE
        _XC-PARENT-INO @
    THEN _XC-PARENT-PARENT-INO @ <> IF VFS-E-STALE EXIT THEN
    _XC-CREATING? _XC-PARENT @ _XC-V @ V.CWD @ <> AND IF
        VFS-E-CONFLICT EXIT
    THEN
    0 ;

\ ---------------------------------------------------------------------
\  Parent authentication
\ ---------------------------------------------------------------------
\
\ An operation authenticates each parent once, before any staging.  A
\ linear parent's block is validated and scanned.  An HTree parent's root
\ is validated, and then every block it names: each index node, checksum
\ and entry vector, and each leaf, checksum and dirent chain, with every
\ live name hashed and checked against the hash interval its routing gives
\ it.  The names are looked for in every leaf.  Every block but the root
\ must be named exactly once, so a level-one walk marks each block it
\ reaches and the root, its nodes and their entries must account for the
\ whole directory.  An insert's walk selects the leaf the new name's hash
\ routes to, as the kernel's dx_probe does, and that leaf's scan gives the
\ record with room for the name and the record map a split sorts.  A
\ removal's walk takes the leaf that holds the name, wherever a run of
\ equal hashes put it.  A rename walks its old parent for the source's
\ record and its new parent for the new name, as an insert does, or for the
\ victim's record; within one parent one walk does both.

\ The name a removal or a rename finds must be in its parent, and a
\ victim's record in the new parent.  A last link's inode is named there
\ once; a remaining link's must be named there again, which keeps the link
\ the operation leaves.
: _XC-REQUIRE-NAMED  ( found? final? refs -- ior )
    ROT 0= IF 2DROP VFS-E-CONFLICT EXIT THEN
    SWAP IF
        1 <> IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    ELSE
        2 U< IF EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT THEN
    THEN
    0 ;

: _XC-REQUIRE-FOUND  ( -- ior )
    _XC-FOUND @ _XC-FINAL @ _XC-REFS @ _XC-REQUIRE-NAMED ?DUP IF EXIT THEN
    _XC-EK-REMOVE _XC-EDIT ! 0 _XC-GROWTH !
    0 ;

\ A rename's source keeps its links, so its record need only be found.
: _XC-REQUIRE-SOURCE  ( -- ior )
    _XC-FOUND @ 0= IF VFS-E-CONFLICT EXIT THEN 0 ;

\ Over a victim the victim's record takes the source, and nothing grows.
: _XC-REQUIRE-VICTIM  ( -- ior )
    _XC-VICTIM-FOUND @ _XC-VICTIM-FINAL @ _XC-VICTIM-REFS @
    _XC-REQUIRE-NAMED ?DUP IF EXIT THEN
    _XC-EK-REPLACE _XC-EDIT ! 0 _XC-GROWTH !
    0 ;

\ A walk looking for room for the new name chooses the leaf it routes to;
\ one finding records finds their leaves.
: _XC-CHOOSES?  ( -- flag )  _XC-WALK-INSERT @ ;

\ The block holding a rename's source record becomes the plan's source
\ snapshot as media holds it.
: _XC-CAPTURE-SOURCE  ( plan home -- plan )
    _XC-SOURCE-HOME !
    _XC-CTX @ _EXT4-C.DIR-BLOCK + OVER _XC-P.SOURCE-SNAPSHOT +
    _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE ;

\ Mark the block at LOGICAL as named in a level-one tree.
: _XC-MARK-SEEN  ( plan logical -- plan ior )
    _XC-WALK-LOGICAL !
    DUP _XC-P.SEEN + _XC-OLD-BLOCKS @ _XC-WALK-LOGICAL @
    BITSET-TEST? 0= IF DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    DUP _XC-P.SEEN + _XC-OLD-BLOCKS @ _XC-WALK-LOGICAL @
    BITSET-BIT-SET? 0= IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    0 ;

\ Validate the leaf at LOGICAL against the interval the descriptor holds.
\ The selected leaf is the one the new name routes to, a removal's is the
\ one its scan finds the name in, and a rename's victim's the one holding
\ the victim's record; that block becomes the plan's directory snapshot.
\ The leaf holding a rename's source record becomes its source snapshot.
: _XC-AUTH-LEAF  ( plan logical selected? -- plan ior )
    _XC-INDEX-SELECTED ! DUP _XC-WALK-LOGICAL !
    _XC-FOUND @ _XC-LEAF-FOUND ! _XC-VICTIM-FOUND @ _XC-LEAF-VICTIM !
    _XC-DIRECTORY-DESC _EXT4-DD-LOAD-LOGICAL
    _XC-IOR ! _XC-INDEX-PHYS !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    _XC-INDEX-SELECTED @ _XC-INDEXED-LEAF-SCAN ?DUP IF EXIT THEN
    _XC-INDEX-SELECTED @
    _XC-VICTIM-FOUND @ _XC-LEAF-VICTIM @ <> OR
    _XC-FOUND @ _XC-LEAF-FOUND @ <> _XC-RENAMING @ 0= AND OR IF
        _XC-INDEX-PHYS @ _XC-DIR-HOME !
        _XC-WALK-LOGICAL @ _XC-INDEX-LEAF-LOGICAL !
        _XC-CTX @ _EXT4-C.DIR-BLOCK + OVER _XC-P.DIR-SNAPSHOT +
        _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
    THEN
    _XC-FOUND @ _XC-LEAF-FOUND @ <> _XC-RENAMING @ AND IF
        _XC-INDEX-PHYS @ _XC-CAPTURE-SOURCE
    THEN
    0 ;

\ A level-zero root names every other block of the directory as a leaf.
: _XC-AUTH-DEPTH0  ( plan -- plan ior )
    _XC-DIRECTORY-DESC _EXT4-DD-REQUIRE-DEPTH0 ?DUP IF EXIT THEN
    _XC-INDEX-ROUTE @ _XC-INDEX-LEAF-ENTRY !
    0 _XC-INDEX-ENTRY !
    BEGIN
        _XC-INDEX-ENTRY @ _XC-INDEX-ROOT-COUNT @ U<
    WHILE
        _XC-INDEX-ENTRY @ _XC-DIRECTORY-DESC _EXT4-DD-SET-INTERVAL
        ?DUP IF EXIT THEN
        _XC-DIRECTORY-DESC _EXT4-DD.LEAF-LOGICAL + @
        _XC-INDEX-ENTRY @ _XC-INDEX-ROUTE @ = _XC-CHOOSES? AND
        _XC-AUTH-LEAF ?DUP IF EXIT THEN
        1 _XC-INDEX-ENTRY +!
    REPEAT
    0 ;

\ The interval of entry J of the level-one node under root entry I, as
\ lookup routes a hash: from the entry's own hash, or for the node's first
\ entry the root entry's, up to the next entry's in the node, or after the
\ node's last entry the next root entry's.  An upper bound carrying the
\ continuation bit also admits its own hash.
: _XC-NODE-INTERVAL  ( -- )
    _XC-WALK-J @ IF
        _XC-WALK-TABLE @ _XC-WALK-J @ 8 * + L@
    ELSE _XC-INDEX-ENTRY @ IF
        _XC-DIRECTORY-DESC _EXT4-DD.ACTIVE-ENTRIES + @
        _XC-INDEX-ENTRY @ 8 * + L@
    ELSE
        0
    THEN THEN
    0xFFFFFFFE AND _XC-DIRECTORY-DESC _EXT4-DD.INTERVAL-LOWER + !
    _XC-WALK-J @ 1+ _XC-WALK-COUNT @ U< IF
        _XC-WALK-TABLE @ _XC-WALK-J @ 1+ 8 * + L@ TRUE
    ELSE _XC-INDEX-ENTRY @ 1+ _XC-INDEX-ROOT-COUNT @ U< IF
        _XC-DIRECTORY-DESC _EXT4-DD.ACTIVE-ENTRIES + @
        _XC-INDEX-ENTRY @ 1+ 8 * + L@ TRUE
    ELSE
        0 FALSE
    THEN THEN
    _XC-DIRECTORY-DESC _EXT4-DD.INTERVAL-HAS-UPPER + !
    DUP 1 AND _XC-DIRECTORY-DESC _EXT4-DD.INTERVAL-UPPER-INCLUSIVE + !
    0xFFFFFFFE AND _XC-DIRECTORY-DESC _EXT4-DD.INTERVAL-UPPER + ! ;

\ The entry of the walked node the new name's hash routes to: the last whose
\ hash is at most the name's, or the first.
: _XC-NODE-ROUTE  ( -- )
    0 _XC-INDEX-LEAF-ENTRY !
    _XC-WALK-COUNT @ 1 ?DO
        _XC-WALK-TABLE @ I 8 * + L@ _XC-INDEX-HASH @ U> 0= IF
            I _XC-INDEX-LEAF-ENTRY !
        THEN
    LOOP ;

\ A level-one root names the index nodes, and they the leaves.  The routed
\ node is kept as the plan's node snapshot.  Each walk starts with no block
\ marked, since a rename walks two parents.
: _XC-AUTH-DEPTH1  ( plan -- plan ior )
    _XC-OLD-BLOCKS @ _XC-SEEN-BITS U> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    DUP _XC-P.SEEN + _XC-SEEN-BITS 63 + 64 / CELLS 0 FILL
    0 _XC-MARK-SEEN ?DUP IF EXIT THEN
    1 _XC-WALK-TOTAL !
    0 _XC-INDEX-ENTRY !
    BEGIN
        _XC-INDEX-ENTRY @ _XC-INDEX-ROOT-COUNT @ U<
    WHILE
        _XC-DIRECTORY-DESC _EXT4-DD.ACTIVE-ENTRIES + @
        _XC-INDEX-ENTRY @ 8 * + 4 + L@ 0x0FFFFFFF AND
        _XC-MARK-SEEN ?DUP IF EXIT THEN
        _XC-WALK-LOGICAL @ _XC-DIRECTORY-DESC _EXT4-DD-LOAD-LOGICAL
        _XC-IOR ! _XC-INDEX-PHYS !
        _XC-IOR @ ?DUP IF EXIT THEN
        _XC-CTX @ _EXT4-DX-NODE? 0= IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-PARENT-INO @ _EXT4-DX-DIRINO !
        _XC-PARENT-GEN @ _EXT4-DX-GEN !
        _XC-CTX @ _XC-OLD-BLOCKS @ _EXT4-VALIDATE-DX-NODE ?DUP IF EXIT THEN
        _XC-CTX @ _EXT4-C.DIR-BLOCK + OVER _XC-P.NODE-WORK +
        _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
        DUP _XC-P.NODE-WORK + _XC-DX-NODE-ENTRIES + _XC-WALK-TABLE !
        _EXT4-DX-COUNT @ DUP _XC-WALK-COUNT ! 1+ _XC-WALK-TOTAL +!
        _XC-INDEX-ENTRY @ _XC-INDEX-ROUTE @ = IF
            _XC-INDEX-PHYS @ _XC-INDEX-NODE-HOME !
            _XC-WALK-COUNT @ _XC-INDEX-NODE-COUNT !
            _EXT4-DX-LIMIT @ _XC-INDEX-NODE-LIMIT !
            DUP _XC-P.NODE-WORK + OVER _XC-P.NODE-SNAPSHOT +
            _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
            _XC-NODE-ROUTE
        THEN
        0 _XC-WALK-J !
        BEGIN _XC-WALK-J @ _XC-WALK-COUNT @ U< WHILE
            _XC-WALK-TABLE @ _XC-WALK-J @ 8 * + 4 + L@ 0x0FFFFFFF AND
            _XC-MARK-SEEN ?DUP IF EXIT THEN
            _XC-NODE-INTERVAL
            _XC-WALK-LOGICAL @
            _XC-INDEX-ENTRY @ _XC-INDEX-ROUTE @ =
            _XC-WALK-J @ _XC-INDEX-LEAF-ENTRY @ = AND _XC-CHOOSES? AND
            _XC-AUTH-LEAF ?DUP IF EXIT THEN
            1 _XC-WALK-J +!
        REPEAT
        1 _XC-INDEX-ENTRY +!
    REPEAT
    _XC-WALK-TOTAL @ _XC-OLD-BLOCKS @ <> IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Choose an HTree parent's edit as ext4_dx_add_entry does: slack in the
\ routed leaf, or else its split, after growing a full level-zero root or
\ splitting a full level-one node under a root with room.  A full root over
\ a full node at level one would need a third level.
: _XC-PLAN-INDEXED-EDIT  ( plan -- plan ior )
    _XC-INSERT-OFF @ -1 <> IF
        _XC-EK-SLACK _XC-EDIT ! 0 _XC-GROWTH ! 0 EXIT
    THEN
    _XC-INDEX-DEPTH @ IF
        _XC-INDEX-NODE-COUNT @ _XC-INDEX-NODE-LIMIT @ U< IF
            _XC-EK-SPLIT
        ELSE _XC-INDEX-ROOT-COUNT @ _XC-INDEX-ROOT-LIMIT @ U< IF
            _XC-EK-NODE-SPLIT
        ELSE
            VFS-E-NOSPC EXIT
        THEN THEN
    ELSE
        _XC-INDEX-ROOT-COUNT @ _XC-INDEX-ROOT-LIMIT @ U< IF
            _XC-EK-SPLIT
        ELSE
            _XC-EK-GROW
        THEN
    THEN
    DUP _XC-EDIT ! _XC-EK-SPLIT = IF 1 ELSE 2 THEN _XC-GROWTH !
    _XC-EDIT @ _XC-EK-NODE-SPLIT = IF
        _XC-INDEX-NODE-COUNT @ 2/ _XC-NODE-LOW !
        DUP _XC-P.NODE-SNAPSHOT + _XC-DX-NODE-ENTRIES +
        _XC-NODE-LOW @ 8 * + L@ _XC-NODE-HASH !
    THEN
    0 _XC-SPLIT-BASE !
    _XC-CHOOSE-SPLIT ;

\ Authenticate an HTree parent and select the leaf the new name routes to,
\ or find the records a removal or a rename looks for.  The plan records
\ the authenticated route and the leaf the edit rewrites in the parent that
\ takes the new name; a rename's walk of its old parent records nothing.
: _XC-AUTH-INDEXED-PARENT  ( plan -- plan ior )
    _XC-DIRECTORY-DESC _EXT4-DD-AUTH-HTREE-ROOT ?DUP IF EXIT THEN
    _XC-REQUIRE-HASH-AUTHORITY ?DUP IF EXIT THEN
    _XC-DIRECTORY-DESC _EXT4-DD.DX-LEVEL + @ _XC-INDEX-DEPTH !
    _XC-DIRECTORY-DESC _EXT4-DD.DX-COUNT + @ _XC-INDEX-ROOT-COUNT !
    _XC-DIRECTORY-DESC _EXT4-DD.DX-LIMIT + @ _XC-INDEX-ROOT-LIMIT !
    _XC-DIRECTORY-DESC _EXT4-DD.ROOT-HOME + @ _XC-INDEX-ROOT-HOME !
    _XC-DIRECTORY-DESC _EXT4-DD.DX-VERSION + @ _XC-HASH-VERSION !
    _XC-NAME-SNAPSHOT _XC-NLEN @ _XC-HASH-VERSION @ _XC-CTX @
    _EXT4-HALF-MD4-DIRHASH?
    _XC-IOR ! _XC-INDEX-MINOR ! _XC-INDEX-HASH !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-INDEX-HASH @ _XC-DIRECTORY-DESC
    _EXT4-DD-SELECT-ROUTE ?DUP IF EXIT THEN
    _XC-DIRECTORY-DESC _EXT4-DD.ROUTE-ENTRY + @ _XC-INDEX-ROUTE !
    0 _XC-INDEX-DUPLICATE !
    -1 _XC-INSERT-OFF ! 0 _XC-INSERT-KIND !
    0 _XC-INDEX-NODE-HOME ! 0 _XC-DIR-HOME !
    0 _XC-FOUND ! 0 _XC-REFS ! 0 _XC-VICTIM-FOUND ! 0 _XC-VICTIM-REFS !
    _XC-INDEX-DEPTH @ IF _XC-AUTH-DEPTH1 ELSE _XC-AUTH-DEPTH0 THEN
    ?DUP IF EXIT THEN
    _XC-INDEX-DUPLICATE @ IF VFS-E-EXISTS EXIT THEN
    _XC-OLD-WALK @ IF 0 EXIT THEN
    -1 OVER _XC-P.INDEX-BASELINE + !
    _XC-INDEX-ROOT-HOME @ OVER _XC-P.INDEX-BASE-ROOT-HOME + !
    _XC-INDEX-DEPTH @ OVER _XC-P.INDEX-BASE-DEPTH + !
    _XC-INDEX-NODE-HOME @ OVER _XC-P.INDEX-BASE-ROUTE-NODE-HOME + !
    _XC-INDEX-ROUTE @ OVER _XC-P.INDEX-BASE-ROUTE + !
    DUP _XC-P.ROOT-SNAPSHOT + _XC-DX-ROOT-ENTRIES +
    _XC-INDEX-ROUTE @ 8 * + 4 + L@ 0x0FFFFFFF AND
    OVER _XC-P.INDEX-BASE-ROUTE-LOGICAL + !
    _XC-INDEX-LEAF-ENTRY @ OVER _XC-P.INDEX-BASE-ENTRY + !
    _XC-INDEX-LEAF-LOGICAL @ OVER _XC-P.INDEX-BASE-LOGICAL + !
    _XC-DIR-HOME @ OVER _XC-P.INDEX-BASE-HOME + !
    _XC-INDEX-HASH @ OVER _XC-P.INDEX-BASE-HASH + !
    _XC-INDEX-MINOR @ OVER _XC-P.INDEX-BASE-MINOR + !
    _XC-PARENT-GROUP @ OVER _XC-P.INDEX-BASE-PARENT-GROUP + !
    _XC-PARENT-HOME @ OVER _XC-P.INDEX-BASE-PARENT-HOME + !
    _XC-PARENT-OFF @ OVER _XC-P.INDEX-BASE-PARENT-OFF + !
    0 ;

\ Authenticate a one-block linear parent and scan its block, which has no
\ index blocks.
: _XC-AUTH-LINEAR-PARENT  ( plan -- plan ior )
    0 _XC-INDEX-DEPTH ! 0 _XC-INDEX-NODE-HOME ! 0 _XC-INDEX-ROOT-HOME !
    0 _XC-CTX @ _EXT4-MAP-BLOCK
    _XC-IOR ! SWAP _XC-DIR-HOME !
    _XC-IOR @ ?DUP IF NIP EXIT THEN
    0= IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    _XC-DIR-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-CTX @ _EXT4-C.DIR-BLOCK +
    _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.DIR-BLOCK + OVER _XC-P.DIR-SNAPSHOT +
    _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 _XC-FOUND ! 0 _XC-REFS ! 0 _XC-VICTIM-FOUND ! 0 _XC-VICTIM-REFS !
    _XC-DIR-SCAN ?DUP IF EXIT THEN
    _XC-RENAMING @ _XC-FOUND @ AND IF _XC-DIR-HOME @ _XC-CAPTURE-SOURCE THEN
    0 ;

\ Choose an insert's edit once its parent is walked.  A one-block linear
\ parent takes the name in its slack, or a full block converts to a
\ depth-zero HTree as make_indexed_dir builds one, under the superblock's
\ default hash.  An HTree parent's edit is chosen as ext4_dx_add_entry
\ chooses it.
: _XC-PLAN-INSERT-EDIT  ( plan -- plan ior )
    _XC-LOAD-INDEXED @ IF _XC-PLAN-INDEXED-EDIT EXIT THEN
    _XC-INSERT-OFF @ -1 <> IF
        _XC-EK-SLACK _XC-EDIT ! 0 _XC-GROWTH ! 0 EXIT
    THEN
    _XC-REQUIRE-HASH-AUTHORITY ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.DEFAULT-HASH + C@ _XC-HASH-VERSION !
    _XC-NAME-SNAPSHOT _XC-NLEN @ _XC-HASH-VERSION @ _XC-CTX @
    _EXT4-HALF-MD4-DIRHASH?
    _XC-IOR ! _XC-INDEX-MINOR ! _XC-INDEX-HASH !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-CONVERT-RECORDS ?DUP IF EXIT THEN
    _XC-EK-CONVERT _XC-EDIT ! 2 _XC-GROWTH !
    _XC-CHOOSE-SPLIT ;

\ Find again, in the plan's directory snapshot, the first record with room
\ for the new name, as the walk's scans find it.
: _XC-SCAN-SLOT  ( plan -- plan )
    -1 _XC-INSERT-OFF ! 0 _XC-INSERT-KIND !
    0 _XC-DIR-OFF !
    BEGIN
        _XC-DIR-OFF @ _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - U<
    WHILE
        DUP _XC-P.DIR-SNAPSHOT + _XC-DIR-OFF @ + DUP _XC-DIR-DE !
        4 + W@ _XC-DIR-REC !
        _XC-DIR-DE @ _XC-RECORD-USED _XC-DIR-USED !
        _XC-DIR-DE @ L@ 0<> _XC-NOTE-SLOT
        _XC-DIR-REC @ _XC-DIR-OFF +!
    REPEAT ;

\ Take the record at OFFSET out of the selected leaf's record map.
: _XC-DROP-RECORD  ( plan offset -- plan ior )
    _XC-DIR-OFF ! 0 _XC-SPLIT-I !
    BEGIN _XC-SPLIT-I @ _XC-SPLIT-COUNT @ U< WHILE
        DUP _XC-P.RECORDS + _XC-SPLIT-I @ CELLS +
        DUP @ 0xFFFF AND _XC-DIR-OFF @ = IF
            DUP CELL+ SWAP
            _XC-SPLIT-COUNT @ _XC-SPLIT-I @ - 1- CELLS MOVE
            -1 _XC-SPLIT-COUNT +!
            0 EXIT
        THEN
        DROP 1 _XC-SPLIT-I +!
    REPEAT
    VFS-E-CORRUPT ;

\ Take the target's record out of IMAGE as ext4_generic_delete_entry
\ does.  The record before it in the block, live or unused, absorbs its
\ length and the record's bytes are cleared; the first record of a block
\ keeps its length and becomes unused, its inode and every byte from its
\ name length to its end cleared.  IMAGE is the authenticated block, which
\ its stager stamps once every edit is in.
: _XC-DIR-REMOVE  ( image -- ior )
    DUP _XC-DIR-IMAGE ! 0= IF VFS-E-INVALID EXIT THEN
    _XC-DIR-IMAGE @ _XC-RM-OFF @ + _XC-DIR-DE !
    _XC-RM-PREV-OFF @ 0< IF
        0 _XC-DIR-DE @ L!
        _XC-DIR-DE @ 6 + _XC-RM-REC @ 6 - 0 FILL
    ELSE
        _XC-RM-PREV-REC @ _XC-RM-REC @ +
        _XC-DIR-IMAGE @ _XC-RM-PREV-OFF @ + 4 + W!
        _XC-DIR-DE @ _XC-RM-REC @ 0 FILL
    THEN
    0 ;

\ Within one parent the source's record leaves first, and the insert plans
\ against the directory that removal leaves.  When the new name routes to
\ the block that held the source, the plan's directory snapshot takes the
\ removal, is scanned again for the first record with room, and loses the
\ source's record from its record map, so a name that fits where the source
\ was needs no growth.  The kernel's ext4_rename instead adds the new name
\ first, then deletes the old one, finding it again after a split.  Both
\ orders leave a valid directory; this one never splits a block that the
\ removal leaves room in.
: _XC-PLAN-AFTER-REMOVAL  ( plan -- plan ior )
    _XC-CROSS @ _XC-SOURCE-HOME @ _XC-DIR-HOME @ <> OR IF 0 EXIT THEN
    DUP _XC-P.DIR-SNAPSHOT + _XC-DIR-REMOVE ?DUP IF EXIT THEN
    _XC-SCAN-SLOT
    _XC-LOAD-INDEXED @ IF _XC-RM-OFF @ _XC-DROP-RECORD EXIT THEN
    0 ;

VARIABLE _XC-FI-GROUP
VARIABLE _XC-FI-VISITED
VARIABLE _XC-FI-SAW-UNINIT
VARIABLE _XC-GROUP-INODES
VARIABLE _XC-GROUP-BASE
VARIABLE _XC-GROUP-FREE
VARIABLE _XC-GROUP-NEW-FREE
VARIABLE _XC-GROUP-UNUSED
VARIABLE _XC-GROUP-NEW-UNUSED
VARIABLE _XC-GROUP-HIGH-WATER
VARIABLE _XC-BITMAP-HOME
VARIABLE _XC-BITMAP-CRC
VARIABLE _XC-BITMAP-NEW-CRC
VARIABLE _XC-GDT-HOME
VARIABLE _XC-GDT-OFF
VARIABLE _XC-INODE-TABLE
VARIABLE _XC-INODE-HOME
VARIABLE _XC-INODE-OFF
VARIABLE _XC-NEW-GEN
VARIABLE _XC-FIRST-CLEAR
VARIABLE _XC-SUPER-HOME
VARIABLE _XC-SUPER-NEW-FREE
VARIABLE _XC-DATA-BLOCK
VARIABLE _XC-GROUP-USED-DIRS
VARIABLE _XC-GROUP-NEW-USED-DIRS
VARIABLE _XC-DESC
VARIABLE _XC-IMAGE
VARIABLE _XC-NEW-DIR-IMAGE

\ Exchange the victim's bank with the removal target's cells and record, so
\ that the removal's words authenticate, stage and audit the victim.
: _XC-SWAP-TARGET  ( -- )
    _XC-D _XC-VICTIM-D _XC-EXCHANGE
    _XC-VN _XC-VICTIM-VN _XC-EXCHANGE
    _XC-INODE _XC-VICTIM-INO _XC-EXCHANGE
    _XC-NEW-GEN _XC-VICTIM-GEN _XC-EXCHANGE
    _XC-NLINK _XC-VICTIM-NLINK _XC-EXCHANGE
    _XC-FINAL _XC-VICTIM-FINAL _XC-EXCHANGE
    _XC-ORPHAN _XC-VICTIM-ORPHAN _XC-EXCHANGE
    _XC-FI-GROUP _XC-VICTIM-GROUP _XC-EXCHANGE
    _XC-TARGET-INDEX _XC-VICTIM-INDEX _XC-EXCHANGE
    _XC-INODE-HOME _XC-VICTIM-INODE-HOME _XC-EXCHANGE
    _XC-INODE-OFF _XC-VICTIM-INODE-OFF _XC-EXCHANGE
    _XC-INODE-ROLE _XC-VICTIM-ROLE _XC-EXCHANGE
    _XC-OLD-INODE _XC-VICTIM-INODE _XC-EXCHANGE-RECORDS ;

: _XC-DESC-ITABLE-UNUSED@  ( descriptor -- inodes )
    DUP _EXT4-GD.ITABLE-UNUSED-LO + W@
    SWAP _EXT4-GD.ITABLE-UNUSED-HI + W@ 16 LSHIFT OR ;

: _XC-DESC-ITABLE-UNUSED!  ( inodes descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.ITABLE-UNUSED-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.ITABLE-UNUSED-HI + W! ;

: _XC-FI-ADVANCE  ( -- )
    1 _XC-FI-GROUP +!
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-C.GROUPS + @ = IF
        0 _XC-FI-GROUP !
    THEN
    1 _XC-FI-VISITED +! ;

: _XC-FI-CAPTURE-RECORD  ( -- ior )
    _XC-INODE @ _XC-CTX @ _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XC-FI-GROUP @ <>
    _EXT4-IR-INDEX @ _XC-FIRST-CLEAR @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-FIRST-CLEAR @ _XC-CTX @ _EXT4-C.ISIZE + @ _EXT4-UMUL?
    _XC-IOR ! DUP
    _XC-CTX @ _EXT4-C.BSIZE + @ / _XC-INODE-TABLE @ +
    _XC-INODE-HOME !
    _XC-IOR @ ?DUP IF NIP EXIT THEN
    _XC-CTX @ _EXT4-C.BSIZE + @ MOD _XC-INODE-OFF !
    _XC-INODE-OFF @ _XC-CTX @ _EXT4-C.ISIZE + @ +
    _XC-CTX @ _EXT4-C.BSIZE + @ U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-INODE-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XC-INODE-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-INODE-OFF @ +
    DUP _XC-OLD-INODE _XC-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-I.GENERATION + L@
    1+ 0xFFFFFFFF AND DUP 0= IF DROP 1 THEN _XC-NEW-GEN !
    0 ;

: _XC-FIRST-ELIGIBLE-INDEX  ( -- index )
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@
    _XC-GROUP-BASE @ 1+ 2DUP U> IF - ELSE 2DROP 0 THEN
    _XC-GROUP-INODES @ MIN ;

: _XC-FI-SCAN-GROUP  ( -- found? ior )
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-GROUP-INODE-COUNT
    _XC-IOR ! _XC-GROUP-INODES !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-DESC ?DUP IF
        FALSE SWAP EXIT
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF
        -1 _XC-FI-SAW-UNINIT ! FALSE 0 EXIT
    THEN
    _XC-CTX @ _EXT4-C.DESC + DUP
    _EXT4-JFI-DESC-FREE@ DUP _XC-GROUP-FREE !
    _XC-GROUP-INODES @ U> IF
        DROP FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _XC-DESC-ITABLE-UNUSED@ DUP _XC-GROUP-UNUSED !
    _XC-GROUP-INODES @ U> IF
        DROP FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-DESC-USED-DIRS@ DUP _XC-GROUP-USED-DIRS !
    _XC-GROUP-INODES @ U> IF
        DROP FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-GROUP-USED-DIRS @
    _XC-GROUP-INODES @ _XC-GROUP-FREE @ - U> IF
        DROP FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DROP
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    _XC-IOR ! _XC-GROUP-BASE !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR ! _XC-BITMAP-HOME !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _EXT4-GD-BLOCK @ _XC-GDT-HOME !
    _EXT4-GD-OFF @ _XC-GDT-OFF !
    _XC-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _XC-INODE-TABLE !
    _XC-CTX @ _EXT4-C.BLOCK + _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    _XC-IOR ! _XC-BITMAP-CRC !
    _XC-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK +
    _XC-GROUP-INODES @ BITSET-COUNT-SET? 0= IF
        DROP FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-GROUP-INODES @ SWAP -
    _XC-GROUP-FREE @ <> IF
        FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    -1 _XC-FIRST-CLEAR !
    _XC-CTX @ _EXT4-C.BLOCK + _XC-GROUP-INODES @
    _XC-FIRST-ELIGIBLE-INDEX BITSET-FIND-CLEAR? 0= IF
        2DROP FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF DROP FALSE 0 EXIT THEN
    _XC-FIRST-CLEAR !
    _XC-BITMAP-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-BITMAP-HOME ?DUP IF FALSE SWAP EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR !
    _XC-IOR @ IF DROP FALSE _XC-IOR @ EXIT THEN
    _XC-BITMAP-HOME @ <>
    _EXT4-GD-BLOCK @ _XC-GDT-HOME @ <> OR
    _EXT4-GD-OFF @ _XC-GDT-OFF @ <> OR
    _XC-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _XC-INODE-TABLE @ <> OR IF
        FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK +
    _XC-GROUP-INODES @ _XC-FIRST-CLEAR @ BITSET-TEST? 0= IF
        DROP FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    IF FALSE VFS-E-CONFLICT EXIT THEN
    _XC-GROUP-FREE @ 0= IF
        FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-GROUP-FREE @ 1- _XC-GROUP-NEW-FREE !
    _XC-GROUP-INODES @ _XC-GROUP-UNUSED @ -
    _XC-GROUP-HIGH-WATER !
    _XC-FIRST-CLEAR @ _XC-GROUP-HIGH-WATER @ U< IF
        _XC-GROUP-UNUSED @
    ELSE
        _XC-GROUP-INODES @ _XC-FIRST-CLEAR @ 1+ -
    THEN _XC-GROUP-NEW-UNUSED !
    _XC-DIRECTORY @ IF
        _XC-GROUP-USED-DIRS @ _XC-GROUP-INODES @ U< 0= IF
            FALSE EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
        THEN
        _XC-GROUP-USED-DIRS @ 1+ _XC-GROUP-NEW-USED-DIRS !
    ELSE
        _XC-GROUP-USED-DIRS @ _XC-GROUP-NEW-USED-DIRS !
    THEN
    _XC-GROUP-BASE @ _XC-FIRST-CLEAR @ + 1+ DUP _XC-INODE !
    _XC-CTX @ _EXT4-C.INODES + @ U> IF
        FALSE EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-FI-CAPTURE-RECORD ?DUP IF FALSE SWAP EXIT THEN
    TRUE 0 ;

: _XC-FIND-FREE-INODE  ( -- ior )
    _XC-CTX @ _EXT4-C.FREE-INODES + @ 0= IF VFS-E-NOSPC EXIT THEN
    _XC-PARENT-GROUP @ _XC-FI-GROUP !
    0 _XC-FI-VISITED ! 0 _XC-FI-SAW-UNINIT !
    BEGIN
        _XC-FI-VISITED @ _XC-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _XC-FI-SCAN-GROUP _XC-IOR ! IF
            _XC-IOR @ EXIT
        THEN
        _XC-IOR @ ?DUP IF EXIT THEN
        _XC-FI-ADVANCE
    REPEAT
    _XC-FI-SAW-UNINIT @ IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    EXT4-D-GEOMETRY _EXT4-CORRUPT ;

: _XC-LINK-TARGET-CACHE-MATCH?  ( -- flag )
    _XC-CTX @ _EXT4-C.R.GEN + @ _XC-VN @ VN.GEN @ =
    _XC-CTX @ _EXT4-C.R.SIZE + @ _XC-VN @ VN.SIZE-LO @ = AND
    _XC-VN @ VN.SIZE-HI @ 0= AND
    _XC-CTX @ _EXT4-C.R.MODE + @ _XC-VN @ VN.MODE @ = AND
    _XC-CTX @ _EXT4-C.R.UID + @ _XC-VN @ VN.UID @ = AND
    _XC-CTX @ _EXT4-C.R.GID + @ _XC-VN @ VN.GID @ = AND
    _XC-CTX @ _EXT4-C.R.NLINK + @ _XC-LINK-OLD-NLINK @ = AND
    _XC-LINK-NEW-NLINK @ _XC-VN @ VN.NLINK @ = AND
    _XC-CTX @ _EXT4-C.R.BLOCKS + @ _XC-VN @ VN.BLOCKS @ = AND
    _XC-CTX @ _EXT4-C.R.ATIME + @ _XC-VN @ VN.ATIME @ = AND
    _XC-CTX @ _EXT4-C.R.ATIME-NS + @ _XC-VN @ VN.ATIME-NS @ = AND
    _XC-CTX @ _EXT4-C.R.MTIME + @ _XC-VN @ VN.MTIME @ = AND
    _XC-CTX @ _EXT4-C.R.MTIME-NS + @ _XC-VN @ VN.MTIME-NS @ = AND
    _XC-CTX @ _EXT4-C.R.CTIME + @ _XC-VN @ VN.CTIME @ = AND
    _XC-CTX @ _EXT4-C.R.CTIME-NS + @ _XC-VN @ VN.CTIME-NS @ = AND ;

: _XC-STAGE-CURRENT-LINK-TARGET  ( -- ior )
    _XC-CTX @ _EXT4-STAGE-CURRENT-INODE
    _XC-IOR ! DUP VFS-T-FILE <> IF
        DROP _XC-IOR @ ?DUP IF EXIT THEN
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN DROP
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-LINK-TARGET-CACHE-MATCH? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.R.NLINK + @ DUP _XC-LINK-OLD-NLINK @ <>
    OVER 1 U< OR
    OVER _EXT4-LINK-MAX U< 0= OR IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    1+ _XC-LINK-NEW-NLINK @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.R.UID + @
    _XC-CTX @ _EXT4-C.R.GID + @ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FLAGS + L@ 0x30 AND IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-I.DTIME + L@ IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

: _XC-REQUIRE-LINK-TARGET  ( -- ior )
    _XC-INODE @ _XC-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XC-FI-GROUP @ <>
    _EXT4-IR-BLOCK @ _XC-INODE-HOME @ <> OR
    _EXT4-IR-OFF @ _XC-INODE-OFF @ <> OR IF VFS-E-STALE EXIT THEN
    _XC-CTX @ _EXT4-C.INODE + _XC-OLD-INODE
    _XC-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-STAGE-CURRENT-LINK-TARGET ;

: _XC-AUTH-LINK-TARGET  ( -- ior )
    _XC-INODE @
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-INODE @ 8 =
    _XC-INODE @ _XC-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-INODE @ _XC-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XC-FI-GROUP !
    _EXT4-IR-BLOCK @ _XC-INODE-HOME !
    _EXT4-IR-OFF @ _XC-INODE-OFF !
    _XC-STAGE-CURRENT-LINK-TARGET ?DUP IF EXIT THEN
    _XC-INODE-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.INODE + _XC-OLD-INODE
    _XC-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    _XC-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF EXIT THEN
    _XC-REQUIRE-LINK-TARGET ;

VARIABLE _EXT4-VCM-CTX

\ Whether VNODE caches the inode CTX just staged: its generation, size,
\ mode, owners, links, blocks and every timestamp.
: _EXT4-VN-CACHE-MATCH?  ( vnode ctx -- flag )
    _EXT4-VCM-CTX ! >R
    _EXT4-VCM-CTX @ _EXT4-C.R.GEN + @ R@ VN.GEN @ =
    _EXT4-VCM-CTX @ _EXT4-C.R.SIZE + @ R@ VN.SIZE-LO @ = AND
    R@ VN.SIZE-HI @ 0= AND
    _EXT4-VCM-CTX @ _EXT4-C.R.MODE + @ R@ VN.MODE @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.UID + @ R@ VN.UID @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.GID + @ R@ VN.GID @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.NLINK + @ R@ VN.NLINK @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.BLOCKS + @ R@ VN.BLOCKS @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.ATIME + @ R@ VN.ATIME @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.ATIME-NS + @ R@ VN.ATIME-NS @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.MTIME + @ R@ VN.MTIME @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.MTIME-NS + @ R@ VN.MTIME-NS @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.CTIME + @ R@ VN.CTIME @ = AND
    _EXT4-VCM-CTX @ _EXT4-C.R.CTIME-NS + @ R> VN.CTIME-NS @ = AND ;

: _XC-PARENT-CACHE-MATCH?  ( -- flag )
    _XC-CTX @ _EXT4-C.R.GEN + @ _XC-PARENT-VN @ VN.GEN @ =
    _XC-CTX @ _EXT4-C.R.SIZE + @ _XC-PARENT-VN @ VN.SIZE-LO @ = AND
    _XC-PARENT-VN @ VN.SIZE-HI @ 0= AND
    _XC-CTX @ _EXT4-C.R.MODE + @ _XC-PARENT-VN @ VN.MODE @ = AND
    _XC-CTX @ _EXT4-C.R.UID + @ _XC-PARENT-VN @ VN.UID @ = AND
    _XC-CTX @ _EXT4-C.R.GID + @ _XC-PARENT-VN @ VN.GID @ = AND
    _XC-CTX @ _EXT4-C.R.NLINK + @ _XC-PARENT-VN @ VN.NLINK @ = AND
    _XC-CTX @ _EXT4-C.R.BLOCKS + @ _XC-PARENT-VN @ VN.BLOCKS @ = AND
    _XC-CTX @ _EXT4-C.R.MTIME + @ _XC-PARENT-VN @ VN.MTIME @ = AND
    _XC-CTX @ _EXT4-C.R.MTIME-NS + @
        _XC-PARENT-VN @ VN.MTIME-NS @ = AND
    _XC-CTX @ _EXT4-C.R.CTIME + @ _XC-PARENT-VN @ VN.CTIME @ = AND
    _XC-CTX @ _EXT4-C.R.CTIME-NS + @
        _XC-PARENT-VN @ VN.CTIME-NS @ = AND ;

\ Authenticate a parent once for the whole operation: its VFS identity, the
\ inode policy every namespace write admits, and then every block of the
\ directory.  Its link count changes by PARENT-LINKS: MKDIR and a directory
\ arriving from another parent raise it, which needs a count below the
\ limit, and RMDIR, a directory victim and a directory leaving for another
\ parent lower it, which needs a subdirectory's link.  A depth-zero map's
\ sector count must be exactly its blocks'; a deeper map's is checked
\ against its walk in the map proof.  A rename's walk of its old parent
\ leaves the plan's shape to the new parent.
: _XC-AUTH-PARENT  ( plan -- plan ior )
    _XC-REQUIRE-PARENT-RUNTIME ?DUP IF EXIT THEN
    DUP _XC-P.ROOT-SNAPSHOT + _XC-DIRECTORY-DESC _EXT4-DD-INIT
    _XC-PARENT @ _XC-V @ _XC-CTX @ _XC-DIRECTORY-DESC
    _EXT4-DD-AUTH-INODE ?DUP IF EXIT THEN
    _XC-DIRECTORY-DESC _EXT4-DD.CTX + @ _XC-CTX @ <>
    _XC-DIRECTORY-DESC _EXT4-DD.PARENT + @ _XC-PARENT @ <> OR
    _XC-DIRECTORY-DESC _EXT4-DD.VFS + @ _XC-V @ <> OR
    _XC-DIRECTORY-DESC _EXT4-DD.INO + @ _XC-PARENT-INO @ <> OR
    _XC-DIRECTORY-DESC _EXT4-DD.PARINO + @
        _XC-PARENT-PARENT-INO @ <> OR
    _XC-DIRECTORY-DESC _EXT4-DD.GEN + @ _XC-PARENT-GEN @ <> OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-DIRECTORY-DESC _EXT4-DD.GROUP + @ _XC-PARENT-GROUP !
    _XC-DIRECTORY-DESC _EXT4-DD.INODE-HOME + @ _XC-PARENT-HOME !
    _XC-DIRECTORY-DESC _EXT4-DD.INODE-OFF + @ _XC-PARENT-OFF !
    _XC-PARENT-CACHE-MATCH? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.R.NLINK + @
    _XC-PARENT-LINKS @ 0< IF
        DUP 3 U< OVER _EXT4-LINK-MAX U> OR IF
            DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        1-
    THEN
    _XC-PARENT-LINKS @ 0> IF
        DUP 2 U< OVER _EXT4-LINK-MAX U< 0= OR IF
            DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        1+
    THEN
    _XC-PARENT-NEW-NLINK !
    _XC-CTX @ _EXT4-C.R.UID + @
    _XC-CTX @ _EXT4-C.R.GID + @ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.R.MODE + @ _EXT4-S-ISGID AND IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.INODE + _XC-PARENT-IN !
    _XC-PARENT-IN @ _EXT4-I.FLAGS + L@ DUP _XC-PARENT-FLAGS !
    _EXT4-INDEX-FL AND 0<> _XC-LOAD-INDEXED !
    _XC-LOAD-INDEXED @ IF
        _XC-PARENT-FLAGS @
        _EXT4-EXTENTS-FL _EXT4-INDEX-FL OR <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
    ELSE
        _XC-PARENT-FLAGS @ _EXT4-EXTENTS-FL <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
    THEN
    _XC-OLD-WALK @ 0= IF
        _XC-LOAD-INDEXED @ _XC-P-BIND-SHAPE ?DUP IF EXIT THEN
    THEN
    _XC-DIRECTORY-DESC _EXT4-DD.INDEXED + @ 0<>
    _XC-LOAD-INDEXED @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-DIRECTORY-DESC _EXT4-DD.LOGICAL-BLOCKS + @ _XC-OLD-BLOCKS !
    _XC-DIRECTORY-DESC _EXT4-DD.SECTORS + @ _XC-OLD-SECTORS !
    _XC-LOAD-INDEXED @ 0= _XC-OLD-BLOCKS @ 1 <> AND IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-PARENT-IN @ _EXT4-I.BLOCK + 6 + W@ 0= IF
        _XC-OLD-BLOCKS @ _XC-CTX @ _EXT4-C.SPB + @ *
        _XC-OLD-SECTORS @ <> IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    THEN
    _XC-PARENT-IN @ _EXT4-I.FILE-ACL-LO + L@
    _XC-PARENT-IN @ _EXT4-I.FILE-ACL-HI + W@ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-PARENT-IN @ _EXT4-I.EXTRA-SIZE + W@ 32 <> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-PARENT-IN @ _EXT4-I.PROJECT-ID + L@ IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-PARENT-IN @ 160 + _XC-CTX @ _EXT4-C.ISIZE + @ 160 -
    _EXT4-BYTES-ZERO? 0= IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-PARENT-HOME @ _XC-PARENT-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XC-PARENT-IN @ OVER _XC-PARENT-SNAP @ +
    _XC-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _XC-LOAD-INDEXED @ IF
        _XC-AUTH-INDEXED-PARENT
    ELSE
        _XC-AUTH-LINEAR-PARENT
    THEN ;

\ The directory's size once the edit appends its blocks.  A directory
\ without the largedir feature stays below 2 GiB.
: _XC-PLAN-GROWTH  ( plan -- plan ior )
    _XC-EDIT @ OVER _XC-P.INSERT-EDIT + !
    _XC-OLD-BLOCKS @ _XC-GROWTH @ +
    _XC-CTX @ _EXT4-C.BSIZE + @ _EXT4-UMUL? ?DUP IF NIP EXIT THEN
    DUP 0x7FFFFFFF U> IF DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT THEN
    _XC-NEW-SIZE !
    0 ;

\ ---------------------------------------------------------------------
\  A removal's target
\ ---------------------------------------------------------------------

VARIABLE _XC-TARGET-IN
VARIABLE _XC-EMPTY-DOTS

\ No xattr block, project zero and no deletion time.
: _XC-REQUIRE-PLAIN-TARGET  ( -- ior )
    _XC-TARGET-IN @ DUP _EXT4-I.FILE-ACL-LO + L@
    SWAP _EXT4-I.FILE-ACL-HI + W@ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-TARGET-IN @ _EXT4-I.PROJECT-ID + L@ IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-TARGET-IN @ _EXT4-I.DTIME + L@ IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ The target's record as the cache names it, under the policy a removal
\ admits: root owners and neither the immutable nor the append-only flag.
\ A closed last link of an empty file is freed in the namespace
\ transaction, so its map is empty and the record is plain.  A directory
\ holds the extents flag, alone or with the index flag, a 32-byte extra
\ size and a zero tail, and is plain; its blocks are proved empty apart.
: _XC-STAGE-REMOVAL-TARGET  ( -- ior )
    _XC-CTX @ _EXT4-STAGE-CURRENT-INODE
    _XC-IOR ! DUP
    _XC-DIRECTORY @ IF VFS-T-DIR ELSE VFS-T-FILE THEN <> IF
        DROP _XC-IOR @ ?DUP IF EXIT THEN VFS-E-INVALID EXIT
    THEN DROP
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-VN @ _XC-CTX @ _EXT4-VN-CACHE-MATCH? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.R.UID + @
    _XC-CTX @ _EXT4-C.R.GID + @ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-CTX @ _EXT4-C.INODE + DUP _XC-TARGET-IN !
    _EXT4-I.FLAGS + L@ DUP 0x30 AND IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-DIRECTORY @ IF
        DUP _EXT4-EXTENTS-FL <>
        SWAP _EXT4-EXTENTS-FL _EXT4-INDEX-FL OR <> AND IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XC-TARGET-IN @ _EXT4-I.EXTRA-SIZE + W@ 32 <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XC-TARGET-IN @ 160 + _XC-CTX @ _EXT4-C.ISIZE + @ 160 -
        _EXT4-BYTES-ZERO? 0= IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XC-REQUIRE-PLAIN-TARGET EXIT
    THEN
    DROP
    _XC-FINAL @ 0= _XC-ORPHAN @ OR IF 0 EXIT THEN
    _XC-CTX @ _EXT4-C.R.SIZE + @
    _XC-CTX @ _EXT4-C.R.BLOCKS + @ OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-REQUIRE-PLAIN-TARGET ?DUP IF EXIT THEN
    _XC-TARGET-IN @ _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0<>
    _XC-TARGET-IN @ _EXT4-EMPTY-MAP? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Authenticate the target: an ordinary inode, neither the journal's nor
\ the orphan file's, at its table home, with valid xattrs.  Its record is
\ the snapshot the live pass requires.
: _XC-AUTH-REMOVAL-TARGET  ( -- ior )
    _XC-INODE @
    _XC-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-INODE @ 8 =
    _XC-INODE @ _XC-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-INODE @ _XC-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XC-FI-GROUP !
    _EXT4-IR-INDEX @ _XC-TARGET-INDEX !
    _EXT4-IR-BLOCK @ _XC-INODE-HOME !
    _EXT4-IR-OFF @ _XC-INODE-OFF !
    _XC-STAGE-REMOVAL-TARGET ?DUP IF EXIT THEN
    _XC-INODE-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.INODE + _XC-OLD-INODE
    _XC-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    _XC-CTX @ _EXT4-XA-SCAN-BOTH ;

\ Validate the child's block at LOGICAL: a DX node of an indexed child, or
\ a checksummed leaf whose records are all unused but, with DOTS, `.`
\ naming the child and then `..` naming the parent at its start.
: _XC-AUTH-EMPTY-BLOCK  ( logical dots? -- ior )
    _XC-EMPTY-DOTS !
    _XC-CHILD-DESC _EXT4-DD-LOAD-LOGICAL NIP ?DUP IF EXIT THEN
    _XC-CHILD-DESC _EXT4-DD.INDEXED + @ IF
        _XC-CTX @ _EXT4-DX-NODE? IF
            _XC-INODE @ _EXT4-DX-DIRINO ! _XC-NEW-GEN @ _EXT4-DX-GEN !
            _XC-CTX @ _XC-CHILD-DESC _EXT4-DD.LOGICAL-BLOCKS + @
            _EXT4-VALIDATE-DX-NODE EXIT
        THEN
    THEN
    _XC-INODE @ _XC-NEW-GEN @ _XC-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    0 _XC-DIR-OFF !
    _XC-EMPTY-DOTS @ IF
        _XC-CTX @ _EXT4-C.DIR-BLOCK + DUP L@ _XC-INODE @ <>
        OVER 6 + C@ 1 <> OR SWAP 8 + C@ [CHAR] . <> OR IF
            EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        _XC-CTX @ _EXT4-C.DIR-BLOCK + 4 + W@ _XC-DIR-OFF !
        _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-DIR-OFF @ +
        DUP L@ _XC-PARENT-INO @ <> OVER 6 + C@ 2 <> OR
        OVER 8 + W@ 0x2E2E <> OR IF
            DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
        THEN
        4 + W@ _XC-DIR-OFF +!
    THEN
    BEGIN
        _XC-DIR-OFF @ _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - U<
    WHILE
        _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-DIR-OFF @ +
        DUP L@ IF DROP VFS-E-NOTEMPTY EXIT THEN
        4 + W@ _XC-DIR-OFF +!
    REPEAT
    0 ;

\ An empty directory, as ext4_empty_dir finds one: block 0 holds `.` and
\ then `..`, in a linear block whose later records are unused or as a valid
\ DX root, and every other block is a valid DX node of an indexed child or
\ a checksummed leaf whose records are all unused.  Each block is read
\ through the child's map, which must map every one; the map proof counts
\ that map against the child's sector count.  The DX root's copy lies in
\ the plan's node workspace, which the parent's walk no longer needs.
: _XC-AUTH-EMPTY-DIRECTORY  ( plan -- plan ior )
    DUP _XC-P.NODE-WORK + _XC-CHILD-DESC _EXT4-DD-INIT
    _XC-D @ _XC-V @ _XC-CTX @ _XC-CHILD-DESC _EXT4-DD-AUTH-INODE
    ?DUP IF EXIT THEN
    _XC-CHILD-DESC _EXT4-DD.INO + @ _XC-INODE @ <>
    _XC-CHILD-DESC _EXT4-DD.PARINO + @ _XC-PARENT-INO @ <> OR
    _XC-CHILD-DESC _EXT4-DD.GEN + @ _XC-NEW-GEN @ <> OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-CHILD-DESC _EXT4-DD.INDEXED + @ IF
        _XC-CHILD-DESC _EXT4-DD-AUTH-HTREE-ROOT ?DUP IF EXIT THEN
    ELSE
        0 TRUE _XC-AUTH-EMPTY-BLOCK ?DUP IF EXIT THEN
    THEN
    1 _XC-WALK-LOGICAL !
    BEGIN
        _XC-WALK-LOGICAL @
        _XC-CHILD-DESC _EXT4-DD.LOGICAL-BLOCKS + @ U<
    WHILE
        _XC-WALK-LOGICAL @ FALSE _XC-AUTH-EMPTY-BLOCK ?DUP IF EXIT THEN
        1 _XC-WALK-LOGICAL +!
    REPEAT
    0 ;

\ A closed last link of an empty file is freed with its group's
\ accounting: the inode bitmap holding its bit, the group's descriptor,
\ whose counts must agree with the group, and the superblock.
: _XC-AUTH-FINAL-RELEASE  ( -- ior )
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-GROUP-INODE-COUNT
    _XC-IOR ! _XC-GROUP-INODES !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR ! _XC-BITMAP-HOME !
    _XC-IOR @ ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _XC-GDT-HOME !
    _EXT4-GD-OFF @ _XC-GDT-OFF !
    _XC-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.INODE-BITMAP-HI + L@
    OVER _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JFI-DESC-FREE@ DUP _XC-GROUP-FREE !
    _XC-GROUP-INODES @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-DESC-USED-DIRS@
    _XC-GROUP-INODES @ _XC-GROUP-FREE @ - U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-GD.INODE-BITMAP-LO + L@
    _XC-BITMAP-HOME @ <> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD.INODE-TABLE-LO + L@ _XC-INODE-TABLE !
    _XC-TARGET-INDEX @ _XC-CTX @ _EXT4-C.ISIZE + @ _EXT4-UMUL?
    _XC-IOR !
    _XC-CTX @ _EXT4-C.BSIZE + @ / _XC-INODE-TABLE @ +
    _XC-INODE-HOME @ <>
    _XC-IOR @ OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-BITMAP-HOME @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-VALIDATE-INODE-BITMAP-HOME ?DUP IF EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR !
    _XC-IOR @ IF DROP _XC-IOR @ EXIT THEN
    _XC-BITMAP-HOME @ <>
    _EXT4-GD-BLOCK @ _XC-GDT-HOME @ <> OR
    _EXT4-GD-OFF @ _XC-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK +
    _XC-GROUP-INODES @ _XC-TARGET-INDEX @ BITSET-TEST? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _XC-SUPER-HOME !
    _XC-CTX @ _EXT4-C.FREE-INODES + @
    _XC-CTX @ _EXT4-C.INODES + @ U< 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ A last link that enters the orphan file needs an empty orphan file with
\ a free slot, the deletion its drain will stage qualified now, and
\ mounted free counts equal to the bitmaps, so that every release fits as
\ it lands.  The deletion's credits then size the writer.
: _XC-AUTH-ORPHAN-RELEASE  ( -- ior )
    _XC-INODE @ _XC-NEW-GEN @ _XC-CTX @ _XC-V @
    _EXT4-JUA-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JUA-O-HOME @ _XC-INODE @ _XC-NEW-GEN @ _XC-CTX @
    _EXT4-MEASURE-PROSPECTIVE-UNLINK-CLEANUP
    _XC-IOR ! _XC-CLEANUP-REVOKE ! _XC-CLEANUP-CREDIT !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-CLEANUP-CREDIT @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-EA @ ?DUP IF
        DUP _XC-PARENT-HOME @ = SWAP _XC-DIR-HOME @ = OR IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    _XC-CTX @ _EXT4-REQUIRE-EXACT-BLOCK-ACCOUNTING ;

\ A removal's cold plan: the target, the parent with the target's record,
\ an empty directory's blocks, and the release the removal leads to.
: _XC-PLAN-REMOVAL  ( plan -- plan ior )
    _XC-AUTH-REMOVAL-TARGET ?DUP IF EXIT THEN
    _XC-AUTH-PARENT ?DUP IF EXIT THEN
    _XC-REQUIRE-FOUND ?DUP IF EXIT THEN
    _XC-DIRECTORY @ IF _XC-AUTH-EMPTY-DIRECTORY ?DUP IF EXIT THEN THEN
    _XC-ORPHAN @ IF _XC-AUTH-ORPHAN-RELEASE EXIT THEN
    _XC-FINAL @ IF _XC-AUTH-FINAL-RELEASE EXIT THEN
    0 ;

\ A directory that changes parent names the new parent in its `..`.  The
\ cold plan reads its block 0 through its own map and validates it: a DX
\ root whose `.` names the directory and whose `..` names the old parent,
\ or a checksummed leaf whose first two records are those.  No other block
\ of the directory is read.
: _XC-AUTH-MOVED-DIRECTORY  ( plan -- plan ior )
    DUP _XC-P.CHILD-SNAPSHOT + _XC-MOVED-DESC _EXT4-DD-INIT
    _XC-D @ _XC-V @ _XC-CTX @ _XC-MOVED-DESC _EXT4-DD-AUTH-INODE
    ?DUP IF EXIT THEN
    _XC-MOVED-DESC _EXT4-DD.INO + @ _XC-INODE @ <>
    _XC-MOVED-DESC _EXT4-DD.PARINO + @ _XC-OLD-PARENT-INO @ <> OR
    _XC-MOVED-DESC _EXT4-DD.GEN + @ _XC-NEW-GEN @ <> OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-MOVED-DESC _EXT4-DD.INDEXED + @ IF
        _XC-MOVED-DESC _EXT4-DD-AUTH-HTREE-ROOT ?DUP IF EXIT THEN
        _XC-MOVED-DESC _EXT4-DD.ROOT-HOME + @ _XC-CHILD-HOME !
        12 _XC-CHILD-DOTDOT !
        0 EXIT
    THEN
    0 _XC-MOVED-DESC _EXT4-DD-LOAD-LOGICAL
    _XC-IOR ! _XC-CHILD-HOME !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-INODE @ _XC-NEW-GEN @ _XC-CTX @
    _EXT4-VALIDATE-DIR-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.DIR-BLOCK + _XC-INODE @ _XC-OLD-PARENT-INO @
    _EXT4-DIR-DOTDOT DUP _XC-CHILD-DOTDOT ! 0= IF
        EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.DIR-BLOCK + OVER _XC-P.CHILD-SNAPSHOT +
    _XC-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 ;

\ A final victim's xattr block, which its drain frees, is none of the
\ rename's own homes: the source's record, the old parent's, the block the
\ source's record leaves and a moved directory's block 0.  The orphan
\ release's own proof keeps it from the new parent's record and block.
: _XC-REQUIRE-EA-APART  ( -- ior )
    _EXT4-JFI-EA @ DUP 0= IF EXIT THEN
    DUP _XC-INODE-HOME @ = OVER _XC-SOURCE-HOME @ = OR
    _XC-CROSS @ IF OVER _XC-OLD-PARENT-HOME @ = OR THEN
    _XC-MOVING @ IF OVER _XC-CHILD-HOME @ = OR THEN
    NIP IF EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    0 ;

\ A rename's cold plan: the source, and a victim, under the removal
\ target's policy; each parent walked once, the old parent for the source's
\ record and the new one for the new name's room or the victim's record,
\ in one walk within one parent; the new name's edit after the source's
\ removal; a victim directory's blocks; a moved directory's block 0; and a
\ final victim's release.
: _XC-PLAN-RENAME  ( plan -- plan ior )
    _XC-AUTH-REMOVAL-TARGET ?DUP IF EXIT THEN
    _XC-VICTIM @ IF
        _XC-SWAP-TARGET _XC-AUTH-REMOVAL-TARGET _XC-SWAP-TARGET
        ?DUP IF EXIT THEN
    THEN
    _XC-CROSS @ IF
        _XC-SWAP-PARENT -1 _XC-OLD-WALK !
        TRUE FALSE FALSE _XC-WALK-MODE
        _XC-AUTH-PARENT
        _XC-EK-REMOVE _XC-EDIT ! 0 _XC-GROWTH !
        0 _XC-OLD-WALK ! _XC-SWAP-PARENT
        ?DUP IF EXIT THEN
        _XC-REQUIRE-SOURCE ?DUP IF EXIT THEN
        FALSE
    ELSE
        TRUE
    THEN
    _XC-VICTIM @ DUP 0= _XC-WALK-MODE
    _XC-AUTH-PARENT ?DUP IF EXIT THEN
    _XC-CROSS @ 0= IF _XC-REQUIRE-SOURCE ?DUP IF EXIT THEN THEN
    _XC-VICTIM @ IF
        _XC-REQUIRE-VICTIM ?DUP IF EXIT THEN
        _XC-VICTIM-DIR @ IF
            _XC-SWAP-TARGET _XC-AUTH-EMPTY-DIRECTORY _XC-SWAP-TARGET
            ?DUP IF EXIT THEN
        THEN
    ELSE
        _XC-PLAN-AFTER-REMOVAL ?DUP IF EXIT THEN
        _XC-PLAN-INSERT-EDIT ?DUP IF EXIT THEN
    THEN
    _XC-MOVING @ IF _XC-AUTH-MOVED-DIRECTORY ?DUP IF EXIT THEN THEN
    _XC-PLAN-GROWTH ?DUP IF EXIT THEN
    _XC-VICTIM-FINAL @ 0= IF 0 EXIT THEN
    _XC-SWAP-TARGET _XC-AUTH-ORPHAN-RELEASE _XC-SWAP-TARGET
    ?DUP IF EXIT THEN
    _XC-REQUIRE-EA-APART ;

\ The cold plan: authenticate the link target, find the new inode, or
\ authenticate the removal's or the rename's inodes, then authenticate the
\ parents and choose the edits, all before the writer is touched.  The
\ epoch it ends in vouches for every block it read.
: _XC-PLAN  ( plan -- plan ior )
    _XC-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    \ A map walk left in flight refuses the operation before it reads or
    \ stages anything.
    _EXT4-MUTATION-MAP-TARGET @ _EXT4-MUTATION-MAP-ACTIVE @ OR
    _EXT4-MUTATION-MAP-HITS @ OR
    _EXT4-MUTATION-MAP-VECTOR-COUNT @ OR IF VFS-E-BUSY EXIT THEN
    _XC-RENAMING @ IF
        _XC-PLAN-RENAME ?DUP IF EXIT THEN
    ELSE _XC-REMOVING @ IF
        TRUE FALSE FALSE _XC-WALK-MODE
        _XC-PLAN-REMOVAL ?DUP IF EXIT THEN
    ELSE _XC-LINKING @ IF
        FALSE FALSE TRUE _XC-WALK-MODE
        _XC-AUTH-LINK-TARGET ?DUP IF EXIT THEN
        _XC-AUTH-PARENT ?DUP IF EXIT THEN
        _XC-PLAN-INSERT-EDIT ?DUP IF EXIT THEN
        _XC-REQUIRE-LINK-TARGET ?DUP IF EXIT THEN
        _XC-PLAN-GROWTH ?DUP IF EXIT THEN
    ELSE
        FALSE FALSE TRUE _XC-WALK-MODE
        _XC-CTX @ _EXT4-C.SB + DUP _EXT4-SB.MIN-EXTRA + W@ 32 <>
        SWAP _EXT4-SB.WANT-EXTRA + W@ 32 <> OR IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
        _XC-AUTH-PARENT ?DUP IF EXIT THEN
        _XC-PLAN-INSERT-EDIT ?DUP IF EXIT THEN
        _XC-FIND-FREE-INODE ?DUP IF EXIT THEN
        _XC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _XC-SUPER-HOME !
        _XC-PLAN-GROWTH ?DUP IF EXIT THEN
    THEN THEN THEN
    _XC-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES ?DUP IF EXIT THEN
    _EXT4-MAP-EPOCH @ _XC-AUTH-EPOCH !
    0 ;

VARIABLE _XC-NEW-INODE-PTR
VARIABLE _XC-NEW-ROOT

: _XC-SET-NEW-INODE-TIMES  ( inode -- ior )
    DUP _XC-NEW-INODE-PTR !
    _XC-SECONDS @ _XC-NSEC @ ROT _XC-CTX @
    _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _EXT4-I.CTIME + L@
    DUP _XC-NEW-INODE-PTR @ _EXT4-I.ATIME + L!
    _XC-NEW-INODE-PTR @ _EXT4-I.CRTIME + L!
    _XC-NEW-INODE-PTR @ _EXT4-I.CTIME-EXTRA + L@
    DUP _XC-NEW-INODE-PTR @ _EXT4-I.ATIME-EXTRA + L!
    _XC-NEW-INODE-PTR @ _EXT4-I.CRTIME-EXTRA + L!
    0 ;

: _XC-BUILD-NEW-INODE  ( inode -- ior )
    DUP _XC-NEW-INODE-PTR !
    _XC-CTX @ _EXT4-C.ISIZE + @ 0 FILL
    _XC-DIRECTORY @ IF
        0x41ED _XC-NEW-INODE-PTR @ _EXT4-I.MODE + W!
        _XC-CTX @ _EXT4-C.BSIZE + @
        _XC-NEW-INODE-PTR @ _EXT4-I.SIZE-LO + L!
        2 _XC-NEW-INODE-PTR @ _EXT4-I.LINKS + W!
    ELSE
        0x81B6 _XC-NEW-INODE-PTR @ _EXT4-I.MODE + W!
        1 _XC-NEW-INODE-PTR @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-EXTENTS-FL _XC-NEW-INODE-PTR @ _EXT4-I.FLAGS + L!
    _XC-NEW-GEN @ _XC-NEW-INODE-PTR @ _EXT4-I.GENERATION + L!
    32 _XC-NEW-INODE-PTR @ _EXT4-I.EXTRA-SIZE + W!
    _XC-NEW-INODE-PTR @ _EXT4-I.BLOCK + DUP _XC-NEW-ROOT !
    _EXT4-EXTENT-MAGIC OVER W!
    0 OVER 2 + W!
    4 OVER 4 + W!
    0 OVER 6 + W!
    0 SWAP 8 + L!
    _XC-DIRECTORY @ IF
        1 _XC-NEW-ROOT @ 2 + W!
        0 _XC-NEW-ROOT @ 12 + L!
        1 _XC-NEW-ROOT @ 16 + W!
        _XC-DATA-BLOCK @ 32 RSHIFT 0xFFFF AND
        _XC-NEW-ROOT @ 18 + W!
        _XC-DATA-BLOCK @ 0xFFFFFFFF AND
        _XC-NEW-ROOT @ 20 + L!
        _XC-CTX @ _EXT4-C.SPB + @ _XC-NEW-INODE-PTR @ _XC-CTX @
        _EXT4-ENCODE-I-BLOCKS ?DUP IF EXIT THEN
    THEN
    _XC-NEW-INODE-PTR @ _XC-SET-NEW-INODE-TIMES ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-INODE @ _XC-CTX @ _EXT4-RESTAMP-INODE ;

\ Acquire the after-image of the entry inode's table block, whose record
\ the cold plan authenticated into OLD-INODE: the free slot CREATE and
\ MKDIR fill, LINK's target, a removal's, or a rename's source or, through
\ the victim's bank, its victim.  NEW-INODE-PTR points at the record in the
\ image.
: _XC-ACQUIRE-INODE  ( plan -- plan ior )
    _XC-INODE-ROLE @ _XC-INODE-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _XC-INODE-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-INODE-OFF @ +
    _XC-OLD-INODE _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-INODE-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    _XC-INODE-OFF @ + DUP _XC-NEW-INODE-PTR !
    _XC-OLD-INODE _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    0 ;

: _XC-REPLACE-INODE  ( plan -- plan ior )
    _XC-IMAGE @ _XC-INODE-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

: _XC-STAGE-NEW-INODE  ( plan -- plan ior )
    _XC-ACQUIRE-INODE ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-BUILD-NEW-INODE ?DUP IF EXIT THEN
    _XC-REPLACE-INODE ;

: _XC-STAGE-LINK-TARGET  ( plan -- plan ior )
    _XC-ACQUIRE-INODE ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _EXT4-I.LINKS + W@
    _XC-LINK-OLD-NLINK @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-LINK-NEW-NLINK @
    _XC-NEW-INODE-PTR @ _EXT4-I.LINKS + W!
    _XC-SECONDS @ _XC-NSEC @ _XC-NEW-INODE-PTR @ _XC-CTX @
    _EXT4-SET-INODE-CTIME ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-INODE @ _XC-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XC-REPLACE-INODE ;

\ A rename's source keeps its links and takes a new change time.
: _XC-STAGE-SOURCE-INODE  ( plan -- plan ior )
    _XC-ACQUIRE-INODE ?DUP IF EXIT THEN
    _XC-SECONDS @ _XC-NSEC @ _XC-NEW-INODE-PTR @ _XC-CTX @
    _EXT4-SET-INODE-CTIME ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-INODE @ _XC-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XC-REPLACE-INODE ;

\ A removal's target loses the link: one fewer and a new change time, or
\ for its last link no links at all while the orphan file holds it, or
\ else a cleared record, which frees it.  A rename's victim loses its link
\ the same way.
: _XC-STAGE-REMOVAL-INODE  ( plan -- plan ior )
    _XC-ACQUIRE-INODE ?DUP IF EXIT THEN
    _XC-FINAL @ _XC-ORPHAN @ 0= AND IF
        _XC-NEW-INODE-PTR @ _XC-CTX @ _EXT4-C.ISIZE + @ 0 FILL
        _XC-REPLACE-INODE EXIT
    THEN
    _XC-FINAL @ IF 0 ELSE _XC-NLINK @ 1- THEN
    _XC-NEW-INODE-PTR @ _EXT4-I.LINKS + W!
    _XC-SECONDS @ _XC-NSEC @ _XC-NEW-INODE-PTR @ _XC-CTX @
    _EXT4-SET-INODE-CTIME ?DUP IF EXIT THEN
    _XC-NEW-INODE-PTR @ _XC-INODE @ _XC-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XC-REPLACE-INODE ;

\ ---------------------------------------------------------------------
\  Directory block images
\ ---------------------------------------------------------------------

VARIABLE _XC-NAME-REC
VARIABLE _XC-LEAF-IMAGE
VARIABLE _XC-LEAF-HIGH
VARIABLE _XC-LEAF-OFF
VARIABLE _XC-LEAF-LAST
VARIABLE _XC-LEAF-USED
VARIABLE _XC-LEAF-RECORD
VARIABLE _XC-DX-TABLE
VARIABLE _XC-DX-AT
VARIABLE _XC-DX-HASH
VARIABLE _XC-DX-BLOCK

\ Write the new name's record of REC-LEN bytes at RECORD.
: _XC-PUT-NAME-RECORD  ( record rec-len -- )
    _XC-NAME-REC ! DUP _XC-NAME-REC @ 0 FILL
    _XC-INODE @ OVER L!
    _XC-NAME-REC @ OVER 4 + W!
    _XC-NLEN @ OVER 6 + C!
    _XC-DIRECTORY @ IF 2 ELSE 1 THEN OVER 7 + C!
    _XC-NAME-SNAPSHOT SWAP 8 + _XC-NLEN @ CMOVE ;

\ The checksum record that ends every leaf, at the end of IMAGE.
: _XC-PUT-DIRENT-TAIL  ( image -- )
    _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - +
    DUP _XC-DIRENT-TAIL 0 FILL
    _XC-DIRENT-TAIL OVER 4 + W!
    0xDE SWAP 7 + C! ;

\ Write the new name's record into IMAGE where the scan found room: in the
\ slack after a live record, which keeps its used length, or in an unused
\ record, which keeps the rest as an unused record when that rest holds a
\ header.  Its stager stamps the block.
: _XC-DIR-APPLY  ( image -- ior )
    DUP _XC-DIR-IMAGE ! 0= IF VFS-E-INVALID EXIT THEN
    _XC-INSERT-KIND @ 1 = IF
        _XC-INSERT-PREV-USED @
        _XC-DIR-IMAGE @ _XC-INSERT-PREV-OFF @ + 4 + W!
        _XC-INSERT-REC @ _XC-INSERT-ALLOC-REC !
    ELSE
        _XC-INSERT-KIND @ 2 <> IF VFS-E-CORRUPT EXIT THEN
        _XC-INSERT-REC @ _XC-NEEDED @ - DUP _XC-INSERT-REMAIN !
        _XC-DIRENT-MIN U< IF
            _XC-INSERT-REC @ _XC-INSERT-ALLOC-REC !
        ELSE
            _XC-NEEDED @ _XC-INSERT-ALLOC-REC !
            _XC-DIR-IMAGE @ _XC-INSERT-OFF @ + _XC-NEEDED @ +
            DUP _XC-INSERT-REMAIN @ 0 FILL
            _XC-INSERT-REMAIN @ SWAP 4 + W!
        THEN
    THEN
    _XC-DIR-IMAGE @ _XC-INSERT-OFF @ + _XC-INSERT-ALLOC-REC @
    _XC-PUT-NAME-RECORD
    0 ;

\ Append the record at OFFSET of the split source to the leaf being built,
\ packed to its used length.
: _XC-LEAF-APPEND  ( offset -- )
    _XC-SPLIT-SOURCE @ + DUP _XC-LEAF-RECORD !
    _XC-RECORD-USED _XC-LEAF-USED !
    _XC-LEAF-RECORD @ _XC-LEAF-IMAGE @ _XC-LEAF-OFF @ +
    _XC-LEAF-USED @ MOVE
    _XC-LEAF-USED @ _XC-LEAF-IMAGE @ _XC-LEAF-OFF @ + 4 + W!
    _XC-LEAF-OFF @ _XC-LEAF-LAST !
    _XC-LEAF-USED @ _XC-LEAF-OFF +! ;

\ Build in IMAGE the kept half of a split, or with HIGH the moved half; the
\ new name joins the side its hash falls on, and the last record reaches the
\ checksum tail.
: _XC-BUILD-LEAF  ( plan image high? -- plan ior )
    _XC-LEAF-HIGH ! _XC-LEAF-IMAGE !
    DUP _XC-P.DIR-SNAPSHOT + _XC-SPLIT-SOURCE !
    _XC-LEAF-IMAGE @ _XC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    0 _XC-LEAF-OFF ! -1 _XC-LEAF-LAST !
    _XC-LEAF-HIGH @ IF
        _XC-SPLIT-COUNT @ _XC-SPLIT-AT @ ?DO
            I _XC-SORTED@ 0xFFFF AND _XC-LEAF-APPEND
        LOOP
    ELSE
        _XC-SPLIT-COUNT @ 0 ?DO
            DUP _XC-P.RECORDS + I CELLS + @
            DUP _XC-SPLIT-KEY @ U< IF
                0xFFFF AND _XC-LEAF-APPEND
            ELSE
                DROP
            THEN
        LOOP
    THEN
    _XC-LEAF-HIGH @ _XC-SPLIT-HIGH @ = IF
        _XC-LEAF-IMAGE @ _XC-LEAF-OFF @ +
        _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - _XC-LEAF-OFF @ -
        _XC-PUT-NAME-RECORD
    ELSE
        _XC-LEAF-LAST @ 0< IF VFS-E-CORRUPT EXIT THEN
        _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIRENT-TAIL - _XC-LEAF-LAST @ -
        _XC-LEAF-IMAGE @ _XC-LEAF-LAST @ + 4 + W!
    THEN
    _XC-LEAF-IMAGE @ _XC-PUT-DIRENT-TAIL
    _XC-LEAF-IMAGE @ _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-RESTAMP-DIR-BLOCK ;

\ Insert the entry HASH and BLOCK after entry AT of the DX entry table at
\ TABLE, as the kernel's dx_insert_block does.  A table's first entry holds
\ its limit and count in place of a hash.
: _XC-DX-INSERT  ( table at hash block -- )
    _XC-DX-BLOCK ! _XC-DX-HASH ! 1+ _XC-DX-AT ! _XC-DX-TABLE !
    _XC-DX-TABLE @ _XC-DX-AT @ 8 * + DUP 8 +
    _XC-DX-TABLE @ 2 + W@ _XC-DX-AT @ - 8 * MOVE
    _XC-DX-HASH @ _XC-DX-TABLE @ _XC-DX-AT @ 8 * + L!
    _XC-DX-BLOCK @ _XC-DX-TABLE @ _XC-DX-AT @ 8 * + 4 + L!
    _XC-DX-TABLE @ 2 + W@ 1+ _XC-DX-TABLE @ 2 + W! ;

: _XC-ROOT-LIMIT  ( -- entries )
    _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DX-ROOT-ENTRIES - _XC-DX-TAIL - 8 / ;

: _XC-NODE-LIMIT  ( -- entries )
    _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DX-NODE-ENTRIES - _XC-DX-TAIL - 8 / ;

\ The directory's block count after the edit, and the logical block of the
\ new leaf a split adds, which is always the last one appended.
: _XC-NEW-BLOCKS  ( -- blocks )  _XC-OLD-BLOCKS @ _XC-GROWTH @ + ;
: _XC-NEW-LEAF  ( -- logical )  _XC-NEW-BLOCKS 1- ;

: _XC-RESTAMP-ROOT  ( image -- ior )
    _XC-PARENT-INO @ _XC-PARENT-PARENT-INO @ _XC-PARENT-GEN @
    _XC-NEW-BLOCKS _XC-CTX @ _EXT4-RESTAMP-DX-ROOT ;

: _XC-RESTAMP-NODE  ( image -- ior )
    _XC-PARENT-INO @ _XC-PARENT-GEN @
    _XC-NEW-BLOCKS _XC-CTX @ _EXT4-RESTAMP-DX-NODE ;

\ The root a converted linear block becomes, as make_indexed_dir builds it:
\ `.`, then `..` spanning the rest of the block, the root information, and
\ two entries naming the kept leaf and the moved leaf.
: _XC-BUILD-CONVERTED-ROOT  ( image -- ior )
    DUP _XC-DIR-IMAGE ! _XC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _XC-PARENT-INO @ _XC-DIR-IMAGE @ L!
    12 _XC-DIR-IMAGE @ 4 + W!
    1 _XC-DIR-IMAGE @ 6 + C!
    2 _XC-DIR-IMAGE @ 7 + C!
    [CHAR] . _XC-DIR-IMAGE @ 8 + C!
    _XC-PARENT-PARENT-INO @ _XC-DIR-IMAGE @ 12 + L!
    _XC-CTX @ _EXT4-C.BSIZE + @ 12 - _XC-DIR-IMAGE @ 16 + W!
    2 _XC-DIR-IMAGE @ 18 + C!
    2 _XC-DIR-IMAGE @ 19 + C!
    [CHAR] . _XC-DIR-IMAGE @ 20 + C!
    [CHAR] . _XC-DIR-IMAGE @ 21 + C!
    _XC-HASH-VERSION @ _XC-DIR-IMAGE @ 28 + C!
    8 _XC-DIR-IMAGE @ 29 + C!
    _XC-ROOT-LIMIT _XC-DIR-IMAGE @ _XC-DX-ROOT-ENTRIES + W!
    1 _XC-DIR-IMAGE @ _XC-DX-ROOT-ENTRIES + 2 + W!
    _XC-OLD-BLOCKS @ _XC-DIR-IMAGE @ _XC-DX-ROOT-ENTRIES + 4 + L!
    _XC-DIR-IMAGE @ _XC-DX-ROOT-ENTRIES + 0
    _XC-SPLIT-SEPARATOR @ _XC-NEW-LEAF _XC-DX-INSERT
    _XC-DIR-IMAGE @ _XC-RESTAMP-ROOT ;

\ A full level-zero root grows as ext4_dx_add_entry grows it: its entries
\ move to the new index node, and it keeps one entry naming that node at
\ indirect level one.
: _XC-BUILD-GROWN-ROOT  ( image -- ior )
    DUP _XC-DIR-IMAGE !
    1 OVER 30 + C!
    1 OVER _XC-DX-ROOT-ENTRIES + 2 + W!
    _XC-OLD-BLOCKS @ OVER _XC-DX-ROOT-ENTRIES + 4 + L!
    _XC-DX-ROOT-ENTRIES + 8 + _XC-ROOT-LIMIT 1- 8 * 0 FILL
    _XC-DIR-IMAGE @ _XC-RESTAMP-ROOT ;

\ Insert the entry naming a new block after the root's routing entry.
: _XC-BUILD-ROOT-ENTRY  ( image hash block -- ior )
    ROT DUP _XC-DIR-IMAGE ! _XC-DX-ROOT-ENTRIES + _XC-INDEX-ROUTE @
    2SWAP _XC-DX-INSERT
    _XC-DIR-IMAGE @ _XC-RESTAMP-ROOT ;

\ Begin a new index node in IMAGE: an empty record spanning the block, then
\ the entry table.
: _XC-START-NODE  ( image -- )
    DUP _XC-DIR-IMAGE ! _XC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _XC-CTX @ _EXT4-C.BSIZE + @ _XC-DIR-IMAGE @ 4 + W! ;

\ Set the limit and COUNT of the index node being built.
: _XC-NODE-COUNT!  ( count -- )
    _XC-NODE-LIMIT _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES + W!
    _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES + 2 + W! ;

\ The index node a grown root's entries move to, with the new leaf's entry
\ after the full leaf's.
: _XC-BUILD-GROWN-NODE  ( plan image -- plan ior )
    _XC-START-NODE
    DUP _XC-P.ROOT-SNAPSHOT + _XC-DX-ROOT-ENTRIES +
    _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES +
    _XC-INDEX-ROOT-COUNT @ 8 * MOVE
    _XC-INDEX-ROOT-COUNT @ _XC-NODE-COUNT!
    _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES + _XC-INDEX-LEAF-ENTRY @
    _XC-SPLIT-SEPARATOR @ _XC-NEW-LEAF _XC-DX-INSERT
    _XC-DIR-IMAGE @ _XC-RESTAMP-NODE ;

\ The routed level-one node gains the new leaf's entry after the full
\ leaf's.
: _XC-BUILD-NODE-ENTRY  ( image -- ior )
    DUP _XC-DIR-IMAGE ! _XC-DX-NODE-ENTRIES + _XC-INDEX-LEAF-ENTRY @
    _XC-SPLIT-SEPARATOR @ _XC-NEW-LEAF _XC-DX-INSERT
    _XC-DIR-IMAGE @ _XC-RESTAMP-NODE ;

\ A full level-one node splits as ext4_dx_add_entry splits it: it keeps its
\ first half, the new node takes the rest, and whichever holds the full
\ leaf's entry gains the new leaf's.
: _XC-BUILD-LOW-NODE  ( image -- ior )
    DUP _XC-DIR-IMAGE !
    _XC-DX-NODE-ENTRIES + DUP _XC-NODE-LOW @ 8 * +
    _XC-NODE-LIMIT _XC-NODE-LOW @ - 8 * 0 FILL
    _XC-NODE-LOW @ SWAP 2 + W!
    _XC-INDEX-LEAF-ENTRY @ _XC-NODE-LOW @ U< IF
        _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES + _XC-INDEX-LEAF-ENTRY @
        _XC-SPLIT-SEPARATOR @ _XC-NEW-LEAF _XC-DX-INSERT
    THEN
    _XC-DIR-IMAGE @ _XC-RESTAMP-NODE ;

: _XC-BUILD-HIGH-NODE  ( plan image -- plan ior )
    _XC-START-NODE
    DUP _XC-P.NODE-SNAPSHOT + _XC-DX-NODE-ENTRIES + _XC-NODE-LOW @ 8 * +
    _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES +
    _XC-INDEX-NODE-COUNT @ _XC-NODE-LOW @ - 8 * MOVE
    _XC-INDEX-NODE-COUNT @ _XC-NODE-LOW @ - _XC-NODE-COUNT!
    _XC-INDEX-LEAF-ENTRY @ _XC-NODE-LOW @ U< 0= IF
        _XC-DIR-IMAGE @ _XC-DX-NODE-ENTRIES +
        _XC-INDEX-LEAF-ENTRY @ _XC-NODE-LOW @ -
        _XC-SPLIT-SEPARATOR @ _XC-NEW-LEAF _XC-DX-INSERT
    THEN
    _XC-DIR-IMAGE @ _XC-RESTAMP-NODE ;

\ The new directory's one block: `.` and `..`, the latter spanning to the
\ checksum tail.
: _XC-BUILD-NEW-DIRECTORY-BLOCK  ( image -- ior )
    DUP _XC-NEW-DIR-IMAGE !
    _XC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _XC-INODE @ _XC-NEW-DIR-IMAGE @ L!
    12 _XC-NEW-DIR-IMAGE @ 4 + W!
    1 _XC-NEW-DIR-IMAGE @ 6 + C!
    2 _XC-NEW-DIR-IMAGE @ 7 + C!
    [CHAR] . _XC-NEW-DIR-IMAGE @ 8 + C!
    _XC-PARENT-INO @ _XC-NEW-DIR-IMAGE @ 12 + L!
    _XC-CTX @ _EXT4-C.BSIZE + @ 12 - _XC-DIRENT-TAIL -
    _XC-NEW-DIR-IMAGE @ 16 + W!
    2 _XC-NEW-DIR-IMAGE @ 18 + C!
    2 _XC-NEW-DIR-IMAGE @ 19 + C!
    [CHAR] . _XC-NEW-DIR-IMAGE @ 20 + C!
    [CHAR] . _XC-NEW-DIR-IMAGE @ 21 + C!
    _XC-NEW-DIR-IMAGE @ _XC-PUT-DIRENT-TAIL
    _XC-NEW-DIR-IMAGE @ _XC-INODE @ _XC-NEW-GEN @ _XC-CTX @
    _EXT4-RESTAMP-DIR-BLOCK ;

\ ---------------------------------------------------------------------
\  Staging one pass
\ ---------------------------------------------------------------------

VARIABLE _XC-ACQ-SNAPSHOT
VARIABLE _XC-ACQ-HOME

\ Acquire the after-image of the existing directory block HOME, which the
\ cold plan authenticated into SNAPSHOT.  While no write has started a new
\ map epoch since then, the block still holds those bytes; after one, it is
\ read and must still hold them.
: _XC-ACQUIRE-SNAPSHOT  ( snapshot home -- image ior )
    _XC-ACQ-HOME ! _XC-ACQ-SNAPSHOT !
    _EXT4-MAP-EPOCH @ _XC-AUTH-EPOCH @ <> IF
        _XC-ACQ-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF 0 SWAP EXIT THEN
        _XC-CTX @ _EXT4-C.BLOCK + _XC-ACQ-SNAPSHOT @
        _XC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
            0 VFS-E-CONFLICT EXIT
        THEN
    THEN
    _XC-ACQ-SNAPSHOT @ _XC-ACQ-HOME @ _XC-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF EXIT THEN DROP
    DUP _XC-ACQ-SNAPSHOT @ _XC-CTX @ _EXT4-C.BSIZE + @
    _EXT4-BYTES=? 0= IF DROP 0 VFS-E-CONFLICT EXIT THEN
    0 ;

\ Within one parent a rename's source record and its new name share a
\ block, or lie apart.
: _XC-SAME-BLOCK?  ( -- flag )
    _XC-RENAMING @ _XC-CROSS @ 0= AND
    _XC-SOURCE-HOME @ _XC-DIR-HOME @ = AND ;

: _XC-SOURCE-APART?  ( -- flag )
    _XC-RENAMING @ _XC-CROSS @ 0= AND
    _XC-SOURCE-HOME @ _XC-DIR-HOME @ <> AND ;

\ The edits that change records in place: slack, removal and replacement.
: _XC-RECORD-EDIT?  ( -- flag )
    _XC-EDIT @ DUP _XC-EK-SLACK = OVER _XC-EK-REMOVE = OR
    SWAP _XC-EK-REPLACE = OR ;

\ Edit the records of IMAGE in place and stamp it once.  A block that also
\ holds a rename's source record loses that record first; then the new
\ name fills its room, the removal's record leaves, or the victim's record
\ takes the source's inode.
: _XC-STAGE-RECORDS  ( -- ior )
    _XC-SAME-BLOCK? IF _XC-IMAGE @ _XC-DIR-REMOVE ?DUP IF EXIT THEN THEN
    _XC-EDIT @ DUP _XC-EK-SLACK = IF
        DROP _XC-IMAGE @ _XC-DIR-APPLY
    ELSE _XC-EK-REMOVE = IF
        _XC-IMAGE @ _XC-DIR-REMOVE
    ELSE
        _XC-INODE @ _XC-IMAGE @ _XC-VICTIM-DE-OFF @ + L! 0
    THEN THEN ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-RESTAMP-DIR-BLOCK ;

\ The block that holds, splits or loses the name: the linear block, which
\ a conversion turns into the root, or the routed or found leaf.  A block
\ that also holds a rename's source record is acquired as media holds it,
\ the source snapshot, since the plan's directory snapshot took the
\ source's removal; a conversion or a split rebuilds the block from that
\ directory snapshot and stamps it as it builds it.
: _XC-STAGE-TARGET  ( plan -- plan ior )
    _XC-HR-PARENT-DIRECTORY _XC-DIR-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    DUP _XC-SAME-BLOCK? IF _XC-P.SOURCE-SNAPSHOT ELSE _XC-P.DIR-SNAPSHOT THEN
    + _XC-DIR-HOME @ _XC-ACQUIRE-SNAPSHOT
    ?DUP IF NIP EXIT THEN _XC-IMAGE !
    _XC-EDIT @ _XC-EK-CONVERT = IF
        _XC-IMAGE @ _XC-BUILD-CONVERTED-ROOT
    ELSE _XC-RECORD-EDIT? IF
        _XC-STAGE-RECORDS
    ELSE
        _XC-IMAGE @ FALSE _XC-BUILD-LEAF
    THEN THEN ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-DIR-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

\ The block a rename's source record leaves, apart from the block the new
\ name edits: the old parent's block, or another leaf of the same parent.
: _XC-STAGE-SOURCE-BLOCK  ( plan -- plan ior )
    _XC-HR-RENAME-SOURCE-DIRECTORY _XC-SOURCE-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    DUP _XC-P.SOURCE-SNAPSHOT + _XC-SOURCE-HOME @ _XC-ACQUIRE-SNAPSHOT
    ?DUP IF NIP EXIT THEN _XC-IMAGE !
    _XC-IMAGE @ _XC-DIR-REMOVE ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-PARENT-INO @ _XC-PARENT-GEN @ _XC-CTX @
    _EXT4-RESTAMP-DIR-BLOCK ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-SOURCE-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

\ A directory that changes parent names the new parent in the `..` of its
\ block 0, which is stamped as the leaf or the DX root it is.
: _XC-STAGE-CHILD-BLOCK  ( plan -- plan ior )
    _XC-HR-RENAME-CHILD-DIRECTORY _XC-CHILD-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    DUP _XC-P.CHILD-SNAPSHOT + _XC-CHILD-HOME @ _XC-ACQUIRE-SNAPSHOT
    ?DUP IF NIP EXIT THEN _XC-IMAGE !
    _XC-PARENT-INO @ _XC-IMAGE @ _XC-CHILD-DOTDOT @ + L!
    _XC-IMAGE @ _XC-INODE @
    _XC-MOVED-DESC _EXT4-DD.INDEXED + @ IF
        _XC-PARENT-INO @ _XC-NEW-GEN @
        _XC-MOVED-DESC _EXT4-DD.LOGICAL-BLOCKS + @ _XC-CTX @
        _EXT4-RESTAMP-DX-ROOT
    ELSE
        _XC-NEW-GEN @ _XC-CTX @ _EXT4-RESTAMP-DIR-BLOCK
    THEN ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-CHILD-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

\ The routed level-one node, which gains the new leaf's entry or splits.
: _XC-STAGE-NODE  ( plan -- plan ior )
    _XC-HR-DIRECTORY-NODE _XC-INDEX-NODE-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    DUP _XC-P.NODE-SNAPSHOT + _XC-INDEX-NODE-HOME @ _XC-ACQUIRE-SNAPSHOT
    ?DUP IF NIP EXIT THEN _XC-IMAGE !
    _XC-EDIT @ _XC-EK-NODE-SPLIT = IF
        _XC-IMAGE @ _XC-BUILD-LOW-NODE
    ELSE
        _XC-IMAGE @ _XC-BUILD-NODE-ENTRY
    THEN ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-INDEX-NODE-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

\ The root, which grows, gains the new leaf's entry, or gains the new
\ node's.
: _XC-STAGE-ROOT  ( plan -- plan ior )
    _XC-HR-DIRECTORY-ROOT _XC-INDEX-ROOT-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    DUP _XC-P.ROOT-SNAPSHOT + _XC-INDEX-ROOT-HOME @ _XC-ACQUIRE-SNAPSHOT
    ?DUP IF NIP EXIT THEN _XC-IMAGE !
    _XC-EDIT @ DUP _XC-EK-GROW = IF
        DROP _XC-IMAGE @ _XC-BUILD-GROWN-ROOT
    ELSE _XC-EK-NODE-SPLIT = IF
        _XC-IMAGE @ _XC-NODE-HASH @ _XC-OLD-BLOCKS @ _XC-BUILD-ROOT-ENTRY
    ELSE
        _XC-IMAGE @ _XC-SPLIT-SEPARATOR @ _XC-NEW-LEAF _XC-BUILD-ROOT-ENTRY
    THEN THEN ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-INDEX-ROOT-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

\ The first block of a group-relative goal: the start of GROUP.
: _XC-GROUP-GOAL  ( group -- physical )
    _XC-CTX @ _EXT4-C.BPG + @ * _XC-CTX @ _EXT4-C.FIRST + @ + ;

\ Choose the new directory's block near its inode, as the general writer
\ places a file's first block.  Its allocation is staged with its image
\ once the parent's edits are staged.
: _XC-FIND-CHILD-BLOCK  ( -- ior )
    _XC-FI-GROUP @ _XC-GROUP-GOAL 1 _XC-WRITER @ _EXT4-JTX-FIND-FREE-RUN
    ?DUP IF NIP NIP EXIT THEN
    0= IF DROP VFS-E-NOSPC EXIT THEN
    _XC-DATA-BLOCK ! 0 ;

: _XC-STAGE-NEW-DIRECTORY-BLOCK  ( plan -- plan ior )
    _XC-HR-MKDIR-DIRECTORY _XC-DATA-BLOCK @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    DUP _XC-BUILD-NEW-DIRECTORY-BLOCK ?DUP IF NIP EXIT THEN
    _XC-DATA-BLOCK @ _XC-WRITER @ _EXT4-JTX-META-PUT ?DUP IF EXIT THEN
    _XC-DATA-BLOCK @ 1 _XC-WRITER @ _EXT4-JTX-STAGE-ALLOCATE-RANGE
    ?DUP IF EXIT THEN
    _EXT4-JAB-NEW-SUPER-FREE @ _XC-NEW-FREE !
    0 ;

\ Append directory block INDEX of the growth at the directory's end: take a
\ free block where the directory's last extent would continue, or else at
\ the start of the parent's group, stage its image, and map it into the
\ parent's tree, which may split or deepen there.
: _XC-STAGE-GROWTH-BLOCK  ( plan index -- plan ior )
    DUP _XC-GROWTH-I ! _XC-OLD-BLOCKS @ + DUP _XC-GROWTH-LOGICAL !
    _XN-LOOKUP ?DUP IF >R 2DROP DROP R> EXIT THEN
    _XN-HOLE <> IF 2DROP EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN 2DROP
    _XN-HINT @ ?DUP 0= IF _XC-PARENT-GROUP @ _XC-GROUP-GOAL THEN
    1 _XC-WRITER @ _EXT4-JTX-FIND-FREE-RUN ?DUP IF NIP NIP EXIT THEN
    0= IF DROP VFS-E-NOSPC EXIT THEN
    DUP _XC-GROWTH-HOME !
    1 _XC-WRITER @ _EXT4-JTX-STAGE-ALLOCATE-RANGE ?DUP IF EXIT THEN
    _XC-HR-DIRECTORY-GROWTH _XC-GROWTH-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.SCRATCH-A + @ _XC-IMAGE !
    _XC-EDIT @ _XC-EK-CONVERT = IF
        _XC-IMAGE @ _XC-GROWTH-I @ 0<> _XC-BUILD-LEAF
    ELSE _XC-GROWTH-I @ 1+ _XC-GROWTH @ = IF
        _XC-IMAGE @ TRUE _XC-BUILD-LEAF
    ELSE _XC-EDIT @ _XC-EK-GROW = IF
        _XC-IMAGE @ _XC-BUILD-GROWN-NODE
    ELSE
        _XC-IMAGE @ _XC-BUILD-HIGH-NODE
    THEN THEN THEN ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-GROWTH-HOME @ _XC-WRITER @ _EXT4-JTX-META-PUT
    ?DUP IF EXIT THEN
    _XC-GROWTH-HOME @ 1+ _XN-GOAL !
    _XC-GROWTH-LOGICAL @ 1 _XC-GROWTH-HOME @ _XN-INSERT ?DUP IF EXIT THEN
    _EXT4-JAB-NEW-SUPER-FREE @ _XC-NEW-FREE !
    0 ;

\ The parent's record: its link count and times, and after growth its size,
\ sector count and the map the tree edit left in the private record.  A
\ conversion also makes it an HTree.
: _XC-STAGE-PARENT-INODE  ( plan -- plan ior )
    _XC-PARENT-ROLE @ _XC-PARENT-HOME @ _XC-HP-BIND-META
    ?DUP IF EXIT THEN
    _XC-PARENT-HOME @ _XC-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-PARENT-OFF @ +
    OVER _XC-PARENT-SNAP @ + _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-PARENT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _XC-IMAGE !
    _XC-IMAGE @ _XC-PARENT-OFF @ +
    OVER _XC-PARENT-SNAP @ + _XC-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XC-PARENT-NEW-NLINK @ _XW-INODE _EXT4-I.LINKS + W!
    _XC-EDIT @ _XC-EK-CONVERT = IF
        _EXT4-EXTENTS-FL _EXT4-INDEX-FL OR _XW-INODE _EXT4-I.FLAGS + L!
    THEN
    _XC-GROWTH @ IF
        _XC-NEW-SIZE @ _XW-INODE _EXT4-I.SIZE-LO + L!
        0 _XW-INODE _EXT4-I.SIZE-HI + L!
        _XC-GROWTH @ _XN-NEW-NODES @ + _XC-CTX @ _EXT4-C.SPB + @ *
        _XC-OLD-SECTORS @ + DUP _XC-NEW-SECTORS !
        _XW-INODE _XC-CTX @ _EXT4-ENCODE-I-BLOCKS ?DUP IF EXIT THEN
    THEN
    _XC-SECONDS @ _XC-NSEC @ _XW-INODE _XC-CTX @
    _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _XW-INODE _XC-PARENT-INO @ _XC-CTX @ _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XW-INODE _XC-IMAGE @ _XC-PARENT-OFF @ +
    _XC-CTX @ _EXT4-C.ISIZE + @ MOVE
    _XC-IMAGE @ _XC-PARENT-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

\ Point the general tree editor and the home-set proof at the parent, whose
\ private record starts from its authenticated snapshot.
: _XC-PREPARE-PARENT-TREE  ( plan -- plan )
    DUP _XC-PARENT-SNAP @ + _XW-INODE _XC-CTX @ _EXT4-C.ISIZE + @ MOVE
    _XC-CTX @ _XW-CTX ! _XC-WRITER @ _XW-TX !
    _XC-CTX @ _EXT4-C.BSIZE + @ _XW-BSIZE !
    _XC-PARENT-INO @ _XW-INO ! _XC-PARENT-GEN @ _XW-EXPECTED-GEN !
    0 _XW-EA ! FALSE _XW-ORPHAN ! FALSE _XW-DELETION !
    _XW-TREE
    0 _XN-NEW-NODES ! 0 _XN-EXISTING !
    _XC-PARENT-GROUP @ _XC-GROUP-GOAL _XN-GOAL ! ;

: _XC-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _XC-DESC @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? ?DUP IF NIP EXIT THEN 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-INODE-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _XC-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _XC-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _XC-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _XC-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-DESC @ _EXT4-JFI-DESC-FREE@ _XC-GROUP-FREE @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-DESC @ _XC-DESC-ITABLE-UNUSED@
    _XC-GROUP-UNUSED @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-DESC @ _EXT4-DESC-USED-DIRS@
    _XC-GROUP-USED-DIRS @ <> IF VFS-E-CONFLICT EXIT THEN
    0 ;

: _XC-STAGE-INODE-ALLOCATION  ( plan -- plan ior )
    _XC-HR-INODE-GDT _XC-GDT-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _XC-HR-INODE-BITMAP _XC-BITMAP-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-INODE-BITMAP
    _XC-IOR !
    _XC-IOR @ IF DROP _XC-IOR @ EXIT THEN
    _XC-BITMAP-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK +
    _XC-GROUP-INODES @ _XC-FIRST-CLEAR @ BITSET-TEST? 0= IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    IF VFS-E-CONFLICT EXIT THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP EXIT THEN
    _XC-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-BITMAP-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    DUP _XC-GROUP-INODES @ _XC-FIRST-CLEAR @ BITSET-TEST? 0= IF
        2DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    IF DROP VFS-E-CONFLICT EXIT THEN
    DUP _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    ?DUP IF NIP NIP EXIT THEN
    _XC-BITMAP-CRC @ <> IF DROP VFS-E-CONFLICT EXIT THEN
    DROP
    _XC-IMAGE @ _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-GROUP-INODES @ _XC-FIRST-CLEAR @ BITSET-BIT-SET? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-CTX @ _EXT4-INODE-BITMAP-CRC
    _XC-IOR ! _XC-BITMAP-NEW-CRC !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-FI-GROUP @ _XC-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _XC-GDT-HOME @ <>
    _EXT4-GD-OFF @ _XC-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _XC-CTX @ _EXT4-C.BLOCK + _XC-GDT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XC-IMAGE !
    _XC-GDT-OFF @ + DUP _XC-DESC ! DROP
    _XC-VALIDATE-EFFECTIVE-DESC ?DUP IF EXIT THEN
    _XC-GROUP-NEW-FREE @ _XC-DESC @ _EXT4-JFI-DESC-FREE!
    _XC-GROUP-NEW-UNUSED @ _XC-DESC @ _XC-DESC-ITABLE-UNUSED!
    _XC-GROUP-NEW-USED-DIRS @ _XC-DESC @ _EXT4-DESC-USED-DIRS!
    _XC-BITMAP-NEW-CRC @ _XC-DESC @ _EXT4-JFI-DESC-BITMAP-CRC!
    _XC-DESC @ _XC-FI-GROUP @ _XC-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _XC-IMAGE @ _XC-GDT-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _XC-BITMAP-HOME @ _XC-WRITER @ _EXT4-JTX-META-REPLACE ;

: _XC-STAGE-SUPER  ( plan -- plan ior )
    _XC-HR-PRIMARY-SUPER _XC-SUPER-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _XC-SUPER-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.FREE-INODES + L@
    DUP _XC-CTX @ _EXT4-C.FREE-INODES + @ <> IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    DUP 0= IF DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT THEN
    1- DUP _XC-SUPER-NEW-FREE !
    _EXT4-JPS-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JPS-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM ?DUP IF EXIT THEN
    _EXT4-JPS-IMAGE @ _XC-SUPER-HOME @ _XC-WRITER @
    _EXT4-JTX-META-REPLACE ;

\ Stage the orphan record the payload cells describe: the target's record
\ in the first orphan block and ORPHAN_PRESENT in the primary superblock.
\ The live pass also seals the payload the checkpoint verifies.  The
\ measuring transaction's credits are the writer's capacity, not the exact
\ credits a seal binds, so it seals nothing.
: _XC-STAGE-ORPHAN-RECORD  ( plan -- plan ior )
    _XC-WRITER @ _EXT4-JWR.META-CREDIT + @ _EXT4-JUA-META !
    _XC-HR-ORPHAN _EXT4-JUA-O-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _EXT4-JUA-STAGE-ORPHAN ?DUP IF EXIT THEN
    _XC-HR-PRIMARY-SUPER _XC-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _XC-HP-BIND-META ?DUP IF EXIT THEN
    _EXT4-JUA-STAGE-SUPER ?DUP IF EXIT THEN
    DUP _XC-P.STATE + @ _XC-PS-SEALED = IF _EXT4-JUA-SEAL EXIT THEN
    0 ;

\ A last link that keeps storage or an open descriptor, and every removed
\ directory, enters the orphan file in the removal's transaction.  A
\ block's first record leaves no predecessor, which the payload names as a
\ predecessor of no length at the record's own offset.
: _XC-STAGE-ORPHAN-ADD  ( plan -- plan ior )
    _XC-V @ _EXT4-JUA-V ! _XC-WRITER @ _EXT4-JUA-WRITER !
    _XC-CTX @ _EXT4-JUA-CTX ! _XC-INODE @ _EXT4-JUA-INO !
    _XC-NEW-GEN @ _EXT4-JUA-GEN ! _XC-SECONDS @ _EXT4-JUA-SECONDS !
    _XC-NSEC @ _EXT4-JUA-NSEC ! _XC-PARENT-INO @ _EXT4-JUA-PARENT-INO !
    _XC-PARENT-GEN @ _EXT4-JUA-PARENT-GEN !
    _XC-PARENT-HOME @ _EXT4-JUA-PARENT-HOME !
    _XC-PARENT-OFF @ _EXT4-JUA-PARENT-OFF !
    _XC-DIR-HOME @ _EXT4-JUA-DIR-HOME !
    _XC-RM-OFF @ _EXT4-JUA-TARGET-OFF !
    _XC-RM-REC @ _EXT4-JUA-TARGET-REC !
    _XC-RM-PREV-OFF @ 0< IF
        _XC-RM-OFF @ _EXT4-JUA-PREV-OFF ! 0 _EXT4-JUA-PREV-REC !
    ELSE
        _XC-RM-PREV-OFF @ _EXT4-JUA-PREV-OFF !
        _XC-RM-PREV-REC @ _EXT4-JUA-PREV-REC !
    THEN
    _EXT4-JUA-CLEAR-RENAME
    _XC-STAGE-ORPHAN-RECORD ;

\ A rename's final victim enters the orphan file under the rename form of
\ the payload: the victim's record in the new parent names the source, and
\ the source's record leaves its block, joined to its predecessor or, as
\ its block's first record, left unused, which the payload names as a
\ predecessor of no length at offset zero.  A directory that changes parent
\ adds its block 0.
: _XC-STAGE-RENAME-ORPHAN  ( plan -- plan ior )
    _XC-V @ _EXT4-JUA-V ! _XC-WRITER @ _EXT4-JUA-WRITER !
    _XC-CTX @ _EXT4-JUA-CTX ! _XC-VICTIM-INO @ _EXT4-JUA-INO !
    _XC-VICTIM-GEN @ _EXT4-JUA-GEN ! _XC-SECONDS @ _EXT4-JUA-SECONDS !
    _XC-NSEC @ _EXT4-JUA-NSEC ! _XC-PARENT-INO @ _EXT4-JUA-PARENT-INO !
    _XC-PARENT-GEN @ _EXT4-JUA-PARENT-GEN !
    _XC-PARENT-HOME @ _EXT4-JUA-PARENT-HOME !
    _XC-PARENT-OFF @ _EXT4-JUA-PARENT-OFF !
    _XC-DIR-HOME @ _EXT4-JUA-DIR-HOME !
    _XC-VICTIM-DE-OFF @ _EXT4-JUA-TARGET-OFF !
    _XC-VICTIM-DE-REC @ _EXT4-JUA-TARGET-REC !
    0 _EXT4-JUA-PREV-OFF ! 0 _EXT4-JUA-PREV-REC !
    _XC-INODE @ _EXT4-JUA-SOURCE-INO !
    _XC-NEW-GEN @ _EXT4-JUA-SOURCE-GEN !
    _XC-INODE-HOME @ _EXT4-JUA-SOURCE-HOME !
    _XC-INODE-OFF @ _EXT4-JUA-SOURCE-OFF !
    _XC-CROSS @ IF
        _XC-OLD-PARENT-INO @ _EXT4-JUA-OLD-PARENT-INO !
        _XC-OLD-PARENT-GEN @ _EXT4-JUA-OLD-PARENT-GEN !
        _XC-OLD-PARENT-HOME @ _EXT4-JUA-OLD-PARENT-HOME !
        _XC-OLD-PARENT-OFF @ _EXT4-JUA-OLD-PARENT-OFF !
    ELSE
        0 _EXT4-JUA-OLD-PARENT-INO ! 0 _EXT4-JUA-OLD-PARENT-GEN !
        0 _EXT4-JUA-OLD-PARENT-HOME ! 0 _EXT4-JUA-OLD-PARENT-OFF !
    THEN
    _XC-SOURCE-HOME @ _EXT4-JUA-OLD-DIR-HOME !
    _XC-RM-OFF @ _EXT4-JUA-OLD-SOURCE-OFF !
    _XC-RM-REC @ _EXT4-JUA-OLD-SOURCE-REC !
    _XC-RM-PREV-OFF @ 0< IF
        0 _EXT4-JUA-OLD-PREV-OFF ! 0 _EXT4-JUA-OLD-PREV-REC !
    ELSE
        _XC-RM-PREV-OFF @ _EXT4-JUA-OLD-PREV-OFF !
        _XC-RM-PREV-REC @ _EXT4-JUA-OLD-PREV-REC !
    THEN
    _XC-MOVING @ IF _XC-CHILD-HOME @ ELSE 0 THEN _EXT4-JUA-CHILD-HOME !
    _XC-STAGE-ORPHAN-RECORD ;

\ A closed last link of an empty file is freed in the removal's
\ transaction: its inode bitmap bit, its group's descriptor and the
\ superblock's free count, after its cleared record.
: _XC-STAGE-FINAL-RELEASE  ( plan -- plan ior )
    _XC-WRITER @ _EXT4-JFI-WRITER !
    _XC-CTX @ _EXT4-JFI-CTX !
    _XC-INODE @ _EXT4-JFI-INO !
    _XC-FI-GROUP @ _EXT4-JFI-GROUP !
    _XC-TARGET-INDEX @ _EXT4-JFI-INDEX !
    _XC-GROUP-INODES @ _EXT4-JFI-GROUP-INODES !
    _XC-INODE-TABLE @ _EXT4-JFI-INODE-TABLE !
    _XC-INODE-HOME @ _EXT4-JFI-INODE-HOME !
    _XC-INODE-OFF @ _EXT4-JFI-INODE-OFF !
    _XC-BITMAP-HOME @ _EXT4-JFI-BITMAP-HOME !
    _XC-GDT-HOME @ _EXT4-JFI-GDT-HOME !
    _XC-GDT-OFF @ _EXT4-JFI-GDT-OFF !
    0 _EXT4-JFI-PUBLISHED ! 0 _EXT4-JFI-DIRECTORY !
    _XC-HR-INODE-GDT _XC-GDT-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _XC-HR-INODE-BITMAP _XC-BITMAP-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _EXT4-JFI-STAGE-GROUP ?DUP IF EXIT THEN
    _XC-HR-PRIMARY-SUPER _XC-SUPER-HOME @ _XC-HP-BIND-META ?DUP IF EXIT THEN
    _EXT4-JFI-STAGE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-SUPER-FREE @ _XC-SUPER-NEW-FREE !
    0 ;

\ The parent is kept.  The entry's inode is created, kept by LINK, a
\ rename and a removal that leaves it links or the orphan file, and freed
\ with a closed last link of an empty file.
: _XC-INODE-KIND  ( -- kind )
    _XC-CREATING? IF _EXT4-NMC-CREATED EXIT THEN
    _XC-FINAL @ _XC-ORPHAN @ 0= AND IF _EXT4-NMC-FREED EXIT THEN
    _EXT4-NMC-RETAINED ;

\ The existing directory blocks the parent's edit rewrites: the target, an
\ HTree's routed node and root when the edit changes them, and a rename's
\ source block when it lies apart from the target.
: _XC-REWRITTEN  ( -- blocks )
    _XC-RECORD-EDIT? _XC-EDIT @ _XC-EK-CONVERT = OR IF
        1
    ELSE
        _XC-EDIT @ _XC-EK-NODE-SPLIT = IF 3 ELSE 2 THEN
    THEN
    _XC-SOURCE-APART? IF 1+ THEN ;

VARIABLE _XC-MAP-LIMIT
VARIABLE _XC-MAP-CLAIM

\ One validation walk of the parent's map as it stood before the
\ transaction proves that every existing directory block and tree node the
\ transaction rewrites is mapped exactly once, and no home it allocates or
\ any accounting home at all.  The walk runs inside the map check and
\ claims the parent's old map when the transaction changes it or the map
\ has external nodes; the claims count the old map's blocks and nodes,
\ which a deeper map's sector count must equal.  A map the transaction
\ keeps then gives its claims back, walking the staged record, which maps
\ the same blocks.
: _XC-MAP-AUDIT  ( -- ior )
    0 _XP-BASE !
    _XC-REWRITTEN _XN-EXISTING @ + _XP-EXPECT !
    _XP-COLLECT ?DUP IF EXIT THEN
    _XC-GROWTH @ 0<> _XW-INODE _EXT4-I.BLOCK + 6 + W@ 0<> OR
    _XC-MAP-CLAIM !
    _EXT4-MAP-VALIDATION-LIMIT @ _XC-MAP-LIMIT !
    _XC-OLD-BLOCKS @ _EXT4-MAP-VALIDATION-LIMIT !
    _XC-MAP-CLAIM @ IF 1 ELSE 0 THEN _EXT4-OWN-MODE !
    _XP-MAP-AUDIT
    0 _EXT4-OWN-MODE !
    _XC-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    ?DUP IF EXIT THEN
    _XC-MAP-CLAIM @ 0= IF 0 EXIT THEN
    _XC-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK + 6 + W@ IF
        _EXT4-OWN-COUNT @ _XC-CTX @ _EXT4-C.SPB + @ *
        _XC-OLD-SECTORS @ <> IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    THEN
    _XC-GROWTH @ IF 0 EXIT THEN
    _XC-PARENT-INO @ _XC-PARENT-HOME @ _XC-PARENT-OFF @ _EXT4-NMC-RELEASE ;

VARIABLE _XC-CHILD-CLAIMS

\ A removed directory keeps its map until the drain frees it.  One claim
\ walk of that map, bounded by the child's size, counts its blocks and
\ tree nodes, which its sector count must equal, so the release passes
\ and the deletion account exactly; a block the parent's map also holds
\ refuses.  The walk of the record the transaction stages, with the same
\ map, gives the claims back.
: _XC-CHILD-MAP-AUDIT  ( -- ior )
    _XC-INODE @ _EXT4-NMC-INO ! _XC-INODE-HOME @ _EXT4-NMC-HOME !
    _XC-INODE-OFF @ _EXT4-NMC-OFF !
    _EXT4-NMC-MEDIA-RECORD ?DUP IF EXIT THEN
    _EXT4-OWN-COUNT @ _XC-CHILD-CLAIMS !
    _EXT4-MAP-VALIDATION-LIMIT @ _XC-MAP-LIMIT !
    _XC-CHILD-DESC _EXT4-DD.LOGICAL-BLOCKS + @
    _EXT4-MAP-VALIDATION-LIMIT !
    1 _EXT4-OWN-MODE ! _EXT4-NMC-WALK
    0 _EXT4-OWN-MODE !
    _XC-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    ?DUP IF EXIT THEN
    _EXT4-OWN-COUNT @ _XC-CHILD-CLAIMS @ - _XC-CTX @ _EXT4-C.SPB + @ *
    _XC-CTX @ _EXT4-C.INODE + _XC-CTX @ _EXT4-DECODE-I-BLOCKS
    ?DUP IF NIP NIP EXIT THEN
    <> IF EXT4-D-DIRECTORY _EXT4-CORRUPT EXIT THEN
    _XC-INODE @ _XC-INODE-HOME @ _XC-INODE-OFF @ _EXT4-NMC-RELEASE ;

\ A directory that changes parent keeps its map, which names the block 0
\ the transaction rewrites exactly once and no other home it stages.
: _XC-MOVED-MAP-AUDIT  ( -- ior )
    _XC-INODE @ _XW-INO ! FALSE _XW-ORPHAN ! 0 _XW-EA !
    0 _XP-BASE ! 1 _XP-EXPECT !
    _XP-COLLECT ?DUP IF EXIT THEN
    _EXT4-MAP-VALIDATION-LIMIT @ _XC-MAP-LIMIT !
    _XC-MOVED-DESC _EXT4-DD.LOGICAL-BLOCKS + @
    _EXT4-MAP-VALIDATION-LIMIT !
    _XP-MAP-AUDIT
    _XC-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT ! ;

\ A rename keeps every inode it names: the source, both parents and a
\ victim, whose map its drain frees.  The new parent's map changes by
\ exactly the blocks its growth allocates.  The old parent's map, a moved
\ directory's and a victim directory's stay as they are, the last counted
\ against its sector count.  The new parent's audit comes first, while the
\ tree editor's registers still describe its staging.
: _XC-RENAME-MAP-CHECK  ( plan -- plan ior )
    _XC-CTX @ _XC-WRITER @ _EXT4-NMC-BEGIN ?DUP IF EXIT THEN
    _XC-MAP-AUDIT _EXT4-NMC-IOR !
    _XC-CROSS @ _EXT4-NMC-IOR @ 0= AND IF
        _XC-SWAP-PARENT _XC-PREPARE-PARENT-TREE
        _XC-MAP-AUDIT _EXT4-NMC-IOR !
        _XC-SWAP-PARENT
    THEN
    _XC-MOVING @ _EXT4-NMC-IOR @ 0= AND IF
        _XC-MOVED-MAP-AUDIT _EXT4-NMC-IOR !
    THEN
    _XC-VICTIM-DIR @ _EXT4-NMC-IOR @ 0= AND IF
        _XC-SWAP-TARGET _XC-CHILD-MAP-AUDIT _XC-SWAP-TARGET
        _EXT4-NMC-IOR !
    THEN
    _XC-INODE @ _XC-INODE-HOME @ _XC-INODE-OFF @
    _EXT4-NMC-RETAINED _EXT4-NMC-OLD
    _XC-VICTIM @ IF
        _XC-VICTIM-INO @ _XC-VICTIM-INODE-HOME @ _XC-VICTIM-INODE-OFF @
        _EXT4-NMC-RETAINED _EXT4-NMC-OLD
    THEN
    _EXT4-NMC-BITMAPS
    _XC-PARENT-INO @ _XC-PARENT-HOME @ _XC-PARENT-OFF @
    _EXT4-NMC-RETAINED _EXT4-NMC-NEW
    _XC-CROSS @ IF
        _XC-OLD-PARENT-INO @ _XC-OLD-PARENT-HOME @ _XC-OLD-PARENT-OFF @
        _EXT4-NMC-RETAINED _EXT4-NMC-NEW
    THEN
    _XC-INODE @ _XC-INODE-HOME @ _XC-INODE-OFF @
    _EXT4-NMC-RETAINED _EXT4-NMC-NEW
    _XC-VICTIM @ IF
        _XC-VICTIM-INO @ _XC-VICTIM-INODE-HOME @ _XC-VICTIM-INODE-OFF @
        _EXT4-NMC-RETAINED _EXT4-NMC-NEW
    THEN
    _EXT4-NMC-END ;

\ Prove the transaction's map change: the parent's map, and a new
\ directory's, change by exactly the blocks the transaction allocates,
\ and a removed directory keeps its exact map.
: _XC-MAP-CHECK  ( plan -- plan ior )
    _XC-RENAMING @ IF _XC-RENAME-MAP-CHECK EXIT THEN
    _XC-CTX @ _XC-WRITER @ _EXT4-NMC-BEGIN ?DUP IF EXIT THEN
    _XC-MAP-AUDIT _EXT4-NMC-IOR !
    _XC-REMOVING @ _XC-DIRECTORY @ AND _EXT4-NMC-IOR @ 0= AND IF
        _XC-CHILD-MAP-AUDIT _EXT4-NMC-IOR !
    THEN
    _XC-INODE @ _XC-INODE-HOME @ _XC-INODE-OFF @ _XC-INODE-KIND _EXT4-NMC-OLD
    _EXT4-NMC-BITMAPS
    _XC-PARENT-INO @ _XC-PARENT-HOME @ _XC-PARENT-OFF @
    _EXT4-NMC-RETAINED _EXT4-NMC-NEW
    _XC-INODE @ _XC-INODE-HOME @ _XC-INODE-OFF @ _XC-INODE-KIND _EXT4-NMC-NEW
    _EXT4-NMC-END ;

\ Stage the complete removal: the target's record, the parent's record and
\ the block the record leaves, then the orphan file's record or a freed
\ inode's accounting.
: _XC-STAGE-REMOVAL  ( plan -- plan ior )
    _XC-STAGE-REMOVAL-INODE ?DUP IF EXIT THEN
    _XC-STAGE-PARENT-INODE ?DUP IF EXIT THEN
    _XC-STAGE-TARGET ?DUP IF EXIT THEN
    _XC-ORPHAN @ IF _XC-STAGE-ORPHAN-ADD EXIT THEN
    _XC-FINAL @ IF _XC-STAGE-FINAL-RELEASE EXIT THEN
    0 ;

\ Stage the parent's edit: its record when its map stays, its existing
\ directory blocks, MKDIR's new block or a moved directory's block 0, each
\ appended block with its allocation and map edits, and its record when its
\ map grows.
: _XC-STAGE-EDIT  ( plan -- plan ior )
    _XC-GROWTH @ 0= IF _XC-STAGE-PARENT-INODE ?DUP IF EXIT THEN THEN
    _XC-STAGE-TARGET ?DUP IF EXIT THEN
    _XC-EDIT @ _XC-EK-SPLIT = _XC-INDEX-DEPTH @ AND
    _XC-EDIT @ _XC-EK-NODE-SPLIT = OR IF
        _XC-STAGE-NODE ?DUP IF EXIT THEN
    THEN
    _XC-EDIT @ _XC-EK-SPLIT = _XC-INDEX-DEPTH @ 0= AND
    _XC-EDIT @ _XC-EK-GROW = OR
    _XC-EDIT @ _XC-EK-NODE-SPLIT = OR IF
        _XC-STAGE-ROOT ?DUP IF EXIT THEN
    THEN
    _XC-RENAMING @ IF
        _XC-MOVING @ IF _XC-STAGE-CHILD-BLOCK ?DUP IF EXIT THEN THEN
    ELSE
        _XC-DIRECTORY @ IF
            _XC-STAGE-NEW-DIRECTORY-BLOCK ?DUP IF EXIT THEN
        THEN
    THEN
    _XC-GROWTH @ IF
        \ The tree's external nodes are checksummed against the parent, which
        \ must be the context's current inode while the tree is edited.
        _XC-DIRECTORY-DESC _EXT4-DD-REQUIRE-INODE ?DUP IF EXIT THEN
        0 _XC-GROWTH-I !
        BEGIN _XC-GROWTH-I @ _XC-GROWTH @ U< WHILE
            _XC-GROWTH-I @ _XC-STAGE-GROWTH-BLOCK ?DUP IF EXIT THEN
            1 _XC-GROWTH-I +!
        REPEAT
        _XC-STAGE-PARENT-INODE ?DUP IF EXIT THEN
    THEN
    0 ;

\ Stage the complete rename: the source's record, a victim's, the old
\ parent's record and the block the source's record leaves, apart from the
\ new name's block, then the new parent's edit and a final victim's orphan
\ record.  The old parent's staging runs in its own bank, after which the
\ tree editor is pointed at the new parent again.
: _XC-STAGE-RENAME  ( plan -- plan ior )
    _XC-STAGE-SOURCE-INODE ?DUP IF EXIT THEN
    _XC-VICTIM @ IF
        _XC-SWAP-TARGET _XC-STAGE-REMOVAL-INODE _XC-SWAP-TARGET
        ?DUP IF EXIT THEN
    THEN
    _XC-CROSS @ IF
        _XC-SWAP-PARENT _XC-PREPARE-PARENT-TREE
        _XC-STAGE-PARENT-INODE
        DUP 0= IF DROP _XC-STAGE-SOURCE-BLOCK THEN
        _XC-SWAP-PARENT ?DUP IF EXIT THEN
        _XC-PREPARE-PARENT-TREE
    ELSE _XC-SOURCE-APART? IF
        _XC-STAGE-SOURCE-BLOCK ?DUP IF EXIT THEN
    THEN THEN
    _XC-STAGE-EDIT ?DUP IF EXIT THEN
    _XC-VICTIM-FINAL @ IF _XC-STAGE-RENAME-ORPHAN EXIT THEN
    0 ;

\ Stage the complete operation into _XC-WRITER's open transaction.  The
\ order of first staged homes is the certificate's order: the entry's
\ inode, then the parent's edit, and a new inode's allocation.
: _XC-STAGE  ( plan -- plan ior )
    _XC-PREPARE-PARENT-TREE
    _XC-REMOVING @ IF _XC-STAGE-REMOVAL EXIT THEN
    _XC-CTX @ _EXT4-C.FREE-BLOCKS + @ _XC-NEW-FREE !
    _XC-RENAMING @ IF _XC-STAGE-RENAME EXIT THEN
    _XC-DIRECTORY @ IF _XC-FIND-CHILD-BLOCK ?DUP IF EXIT THEN THEN
    _XC-LINKING @ IF
        _XC-STAGE-LINK-TARGET
    ELSE
        _XC-STAGE-NEW-INODE
    THEN ?DUP IF EXIT THEN
    _XC-STAGE-EDIT ?DUP IF EXIT THEN
    _XC-LINKING @ 0= IF
        _XC-STAGE-INODE-ALLOCATION ?DUP IF EXIT THEN
        _XC-STAGE-SUPER ?DUP IF EXIT THEN
    THEN
    0 ;

: _XC-OP  ( -- op )
    _XC-RENAMING @ IF _XC-PO-RENAME EXIT THEN
    _XC-REMOVING @ 0= IF _XC-PO-INSERT EXIT THEN
    _XC-DIRECTORY @ IF _XC-PO-RMDIR ELSE _XC-PO-UNLINK THEN ;

\ The live pass: stage under exactly the sealed credits, reproduce the
\ sealed homes in order, and prove the map change.
: _EXT4-JTX-STAGE-NAMESPACE  ( plan transaction -- plan ior )
    DUP _XC-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.CTX + @ _XC-CTX @ <> IF VFS-E-INVALID EXIT THEN
    _XC-CTX @ _XC-OP _XC-P-REQUIRE-SEALED ?DUP IF EXIT THEN
    _XC-WRITER @ _XC-HP-REQUIRE-CREDITS ?DUP IF EXIT THEN
    _XC-STAGE ?DUP IF EXIT THEN
    _XC-WRITER @ _XC-HP-REQUIRE-STAGED ?DUP IF EXIT THEN
    _XC-MAP-CHECK ;

\ An operation leaves an orphan to drain when a removal's last link or a
\ rename's final victim enters the orphan file.
: _XC-DRAINS?  ( -- flag )
    _XC-RENAMING @ IF _XC-VICTIM-FINAL @ EXIT THEN
    _XC-REMOVING @ _XC-ORPHAN @ AND ;

\ The record of the inode the drain frees, as the cold plan authenticated it.
: _XC-DRAIN-RECORD  ( -- record )
    _XC-RENAMING @ IF _XC-VICTIM-INODE ELSE _XC-OLD-INODE THEN ;

\ The writer an operation needs: room for its own transaction, which the
\ measuring pass proves, and for an orphan's drain the credits its
\ deletion takes.
: _XC-WRITER-NEED  ( -- meta-cap data-cap revoke-cap )
    _XC-DRAINS? IF _XC-CLEANUP-CREDIT @ 0 _XC-CLEANUP-REVOKE @ EXIT THEN
    1 0 0 ;

\ An orphan that leaves mapped blocks to release passes requires that a
\ pass under the bound profile can take a removal step from its tree,
\ whose depth the authenticated record gives.
: _XC-REQUIRE-PASS-ROOM  ( -- ior )
    _XC-DRAINS? 0= IF 0 EXIT THEN
    _XC-DRAIN-RECORD _EXT4-MAP-MAPS? 0= IF 0 EXIT THEN
    _XC-DRAIN-RECORD _EXT4-RELEASE-DEPTH _XC-WRITER @ _XW-PASS-ROOM? 0= IF
        VFS-E-NOSPC EXIT
    THEN
    0 ;

\ The measuring pass: stage the operation into a transaction the writer's
\ capacity bounds, complete the certificate from it, and abort it.  On a
\ clean mount it also proves the map change, so a refusal leaves the medium
\ untouched before the journal is activated.
: _XC-MEASURE  ( plan -- plan ior )
    _XC-WRITER-NEED _XC-CTX @ _EXT4-JWR-ENSURE ?DUP IF NIP EXIT THEN
    _XC-WRITER !
    _XC-REQUIRE-PASS-ROOM ?DUP IF EXIT THEN
    _XC-WRITER @ _EXT4-JWR.META-CAP + @ 0 0 _XC-WRITER @ _EXT4-JTX-BEGIN
    ?DUP IF NIP EXIT THEN _XC-TX !
    _XC-STAGE ?DUP IF EXIT THEN
    _XC-WRITER @ _XC-HP-BIND-TRANSACTION ?DUP IF EXIT THEN
    _XC-ACTIVE @ 0= IF _XC-MAP-CHECK ?DUP IF EXIT THEN THEN
    _XC-WRITER @ _EXT4-JTX-ABORT ;

\ Clear a rename's cells and both of its banks.
: _XC-SCRUB-RENAME  ( -- )
    0 _XC-RENAMING ! 0 _XC-FLAGS ! 0 _XC-CROSS ! 0 _XC-MOVING !
    0 _XC-VICTIM ! 0 _XC-OLD-WALK ! 0 _XC-OLD-NLEN !
    0 _XC-SOURCE-HOME ! 0 _XC-CHILD-HOME ! 0 _XC-CHILD-DOTDOT !
    0 _XC-VICTIM-D ! 0 _XC-VICTIM-VN ! 0 _XC-VICTIM-INO !
    0 _XC-VICTIM-GEN ! 0 _XC-VICTIM-NLINK ! 0 _XC-VICTIM-FINAL !
    0 _XC-VICTIM-ORPHAN ! 0 _XC-VICTIM-GROUP ! 0 _XC-VICTIM-INDEX !
    0 _XC-VICTIM-INODE-HOME ! 0 _XC-VICTIM-INODE-OFF !
    0 _XC-VICTIM-ROLE ! 0 _XC-VICTIM-DIR !
    0 _XC-VICTIM-FOUND ! 0 _XC-VICTIM-REFS !
    0 _XC-VICTIM-DE-OFF ! 0 _XC-VICTIM-DE-REC !
    0 _XC-OLD-PARENT ! 0 _XC-OLD-PARENT-VN ! 0 _XC-OLD-PARENT-INO !
    0 _XC-OLD-PARENT-PARENT-INO ! 0 _XC-OLD-PARENT-GEN !
    0 _XC-OLD-PARENT-NEW-NLINK ! 0 _XC-OLD-PARENT-GROUP !
    0 _XC-OLD-PARENT-HOME ! 0 _XC-OLD-PARENT-OFF !
    0 _XC-OLD-PARENT-BLOCKS ! 0 _XC-OLD-PARENT-SECTORS !
    0 _XC-OLD-PARENT-LINKS ! 0 _XC-OLD-PARENT-ROLE !
    0 _XC-OLD-PARENT-SNAP ! 0 _XC-OLD-PARENT-EDIT !
    0 _XC-OLD-PARENT-GROWTH !
    _XC-OLD-NAME-SNAPSHOT 256 0 FILL
    _XC-MOVED-DESC _EXT4-DD-SIZE 0 FILL
    _XC-VICTIM-INODE _EXT4-STAGED-WRITE-INODE-SIZE 0 FILL
    _XC-SWAP-RECORD _EXT4-STAGED-WRITE-INODE-SIZE 0 FILL ;

: _XC-SCRUB-PRIVATE  ( -- )
    0 _XC-WRITER ! 0 _XC-TX !
    _XC-NAME-SNAPSHOT 256 0 FILL
    _XC-DIRECTORY-DESC _EXT4-DD-SIZE 0 FILL
    _XC-OLD-INODE _EXT4-STAGED-WRITE-INODE-SIZE 0 FILL
    0 _XC-EDIT ! 0 _XC-GROWTH ! 0 _XC-AUTH-EPOCH !
    0 _XC-OLD-BLOCKS ! 0 _XC-OLD-SECTORS !
    0 _XC-NEW-SIZE ! 0 _XC-NEW-SECTORS ! 0 _XC-NEW-FREE !
    0 _XC-HASH-VERSION ! 0 _XC-GROWTH-HOME !
    0 _XC-INDEX-DEPTH ! 0 _XC-INDEX-ROUTE ! 0 _XC-INDEX-ROOT-HOME !
    0 _XC-INDEX-ROOT-COUNT ! 0 _XC-INDEX-ROOT-LIMIT !
    0 _XC-INDEX-LEAF-LOGICAL ! 0 _XC-INDEX-LEAF-ENTRY !
    0 _XC-INDEX-NODE-HOME !
    0 _XC-INDEX-NODE-COUNT ! 0 _XC-INDEX-NODE-LIMIT !
    0 _XC-SPLIT-COUNT ! 0 _XC-SPLIT-AT ! 0 _XC-SPLIT-KEY !
    0 _XC-SPLIT-SEPARATOR ! 0 _XC-SPLIT-HIGH ! 0 _XC-SPLIT-BASE !
    0 _XC-NODE-LOW ! 0 _XC-NODE-HASH !
    _XC-CHILD-DESC _EXT4-DD-SIZE 0 FILL
    _XC-SCRUB-RENAME ;

: _XC-SCRUB  ( plan -- )
    _XC-P-SCRUB
    _XC-SCRUB-PRIVATE ;

\ LINK names an existing regular file through a second dentry, whose vnode
\ the VFS already counts.
: _XC-ENTRY-LINK  ( -- ior )
    _XC-TARGET @ 0= _XC-TARGET @ _XC-D @ = OR IF
        VFS-E-INVALID EXIT
    THEN
    _XC-TARGET @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF
        VFS-E-STALE EXIT
    THEN
    _XC-TARGET @ D.FLAGS @ VFS-DF-UNLINKED AND IF
        VFS-E-STALE EXIT
    THEN
    _XC-TARGET @ D.VNODE @ _XC-VN @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-VN @ VN.TYPE @ VFS-T-FILE <> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-VN @ VN.DREFS @ 2 U< IF VFS-E-CONFLICT EXIT THEN
    _XC-VN @ VN.BID @ DUP _XC-INODE ! 0= IF VFS-E-STALE EXIT THEN
    _XC-INODE @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-VN @ VN.GEN @ DUP _XC-NEW-GEN ! 0xFFFFFFFF U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-VN @ VN.NLINK @ DUP 2 U< OVER _EXT4-LINK-MAX U> OR IF
        DROP EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _XC-LINK-NEW-NLINK ! 1- _XC-LINK-OLD-NLINK !
    0 ;

\ CREATE and MKDIR fill a fresh vnode, which a MKDIR's dentry gives no
\ children.
: _XC-ENTRY-NEW  ( -- ior )
    _XC-DIRECTORY @ IF
        _XC-VN @ VN.TYPE @ VFS-T-DIR <> IF VFS-E-INVALID EXIT THEN
        _XC-D @ IN.CHILD @ IF VFS-E-CONFLICT EXIT THEN
        _XC-VN @ VN.FLAGS @ VFS-IF-CHILDREN AND 0= IF
            VFS-E-CONFLICT EXIT
        THEN
    ELSE
        _XC-VN @ VN.TYPE @ VFS-T-FILE <> IF VFS-E-INVALID EXIT THEN
    THEN
    _XC-VN @ VN.BID @ _XC-VN @ VN.GEN @ OR
    _XC-VN @ VN.BLOCKS @ OR
    _XC-VN @ VN.SIZE-LO @ OR _XC-VN @ VN.SIZE-HI @ OR IF
        VFS-E-CONFLICT EXIT
    THEN
    _XC-VN @ VN.NLINK @ 1 <> IF VFS-E-CONFLICT EXIT THEN
    0 ;

\ UNLINK removes a regular file's name and RMDIR an empty directory's.  The
\ directory is held by its one dentry outside the working directory, with
\ no child cached; the plan proves it empty on media.  Its last link is
\ always final, and a regular file's last link is final; a final link
\ whose file still holds data or is open, and every directory, goes
\ through the orphan file.
: _XC-ENTRY-REMOVAL  ( -- ior )
    _XC-VN @ VN.TYPE @
    _XC-DIRECTORY @ IF VFS-T-DIR ELSE VFS-T-FILE THEN <> IF
        VFS-E-INVALID EXIT
    THEN
    _XC-DIRECTORY @ IF
        _XC-VN @ VN.DREFS @ 1 <> IF VFS-E-BUSY EXIT THEN
        _XC-D @ _XC-V @ V.CWD @ = IF VFS-E-BUSY EXIT THEN
        _XC-D @ IN.CHILD @ IF VFS-E-NOTEMPTY EXIT THEN
    THEN
    _XC-VN @ VN.BID @ DUP _XC-INODE ! 0= IF VFS-E-STALE EXIT THEN
    _XC-INODE @ _XC-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-STALE EXIT THEN
    _XC-VN @ VN.GEN @ DUP _XC-NEW-GEN ! 0xFFFFFFFF U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-VN @ VN.NLINK @ DUP _XC-NLINK !
    _XC-DIRECTORY @ IF
        2 <> IF VFS-E-CONFLICT EXIT THEN
        -1 _XC-FINAL ! -1 _XC-ORPHAN !
        0 EXIT
    THEN
    DUP 1 U< IF DROP VFS-E-STALE EXIT THEN
    1 = DUP _XC-FINAL !
    _XC-VN @ VN.SIZE-LO @ _XC-VN @ VN.SIZE-HI @ OR
    _XC-VN @ VN.BLOCKS @ OR _XC-VN @ VN.OPEN-REFS @ OR 0<> AND
    _XC-ORPHAN !
    0 ;

: _XC-ENTRY-PARENT  ( -- ior )
    _XC-PARENT @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XC-CREATING? IF
        _XC-PARENT @ _XC-V @ V.CWD @ <> IF VFS-E-CONFLICT EXIT THEN
    THEN
    _XC-PARENT @ D.VNODE @ DUP _XC-PARENT-VN ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _XC-PARENT-VN @ VN.TYPE @ VFS-T-DIR <> IF VFS-E-NOTDIR EXIT THEN
    _XC-PARENT-VN @ VN.BID @ DUP _XC-PARENT-INO ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _XC-CREATING? 0= _XC-PARENT-INO @ _XC-INODE @ = AND IF
        VFS-E-CORRUPT EXIT
    THEN
    _XC-PARENT-INO @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-PARENT-VN @ VN.GEN @ DUP _XC-PARENT-GEN !
    0xFFFFFFFF U> IF VFS-E-STALE EXIT THEN
    _XC-PARENT @ IN.PARENT @ ?DUP IF
        IN.BID @
    ELSE
        _XC-PARENT-INO @
    THEN DUP _XC-PARENT-PARENT-INO ! 0= IF VFS-E-STALE EXIT THEN
    0 ;

\ The new name, which a record of NEEDED bytes holds.
: _XC-ENTRY-NAME  ( -- ior )
    _XC-NAME @ _XC-NLEN @ _VFS-VALID-NAME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _XC-NLEN @ 8 + 3 + -4 AND DUP _XC-NEEDED !
    _XC-CTX @ _EXT4-C.BSIZE + @ 12 - U> IF
        VFS-E-NAMETOOLONG EXIT
    THEN
    _XC-NAME @ _XC-NAME-SNAPSHOT _XC-NLEN @ CMOVE
    0 ;

\ The trusted clock and the mount's dedicated writer.
: _XC-ENTRY-WRITER  ( -- ior )
    _XC-CTX @ _EXT4-C.WCLOCK-XT + @ 0= IF VFS-E-UNSUPPORTED EXIT THEN
    _XC-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF VFS-E-NOSPC EXIT THEN
    _XC-CTX @ _EXT4-C.J.WRITER-ARENA + @ 0=
    _XC-CTX @ _EXT4-C.J.WRITER + @ 0= OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

\ A rename's victim is the new parent's child of the new name, apart from
\ the source and both parents and of the source's type: a regular file, or
\ an empty directory held by its one dentry outside the working directory,
\ with no child cached, which the plan proves empty on media.  It loses
\ the name as a removal's target loses its link, and a last link goes to
\ the orphan file.
: _XC-ENTRY-VICTIM  ( -- ior )
    _XC-VICTIM-D @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XC-VICTIM-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XC-VICTIM-D @ IN.PARENT @ _XC-PARENT @ <> IF VFS-E-STALE EXIT THEN
    _XC-VICTIM-D @ D.VNODE @ DUP _XC-VICTIM-VN ! 0= IF VFS-E-STALE EXIT THEN
    _XC-VICTIM-VN @ _XC-VN @ = IF VFS-E-INVALID EXIT THEN
    _XC-VICTIM-VN @ VN.TYPE @ DUP VFS-T-DIR = _XC-VICTIM-DIR !
    DUP VFS-T-FILE <> SWAP VFS-T-DIR <> AND IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-VICTIM-DIR @ _XC-DIRECTORY @ <> IF VFS-E-CONFLICT EXIT THEN
    _XC-VICTIM-DIR @ IF
        _XC-VICTIM-VN @ VN.DREFS @ 1 <> IF VFS-E-BUSY EXIT THEN
        _XC-VICTIM-D @ _XC-V @ V.CWD @ = IF VFS-E-BUSY EXIT THEN
        _XC-VICTIM-D @ IN.CHILD @ IF VFS-E-NOTEMPTY EXIT THEN
    THEN
    _XC-VICTIM-VN @ VN.BID @ DUP _XC-VICTIM-INO ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _XC-VICTIM-INO @ _XC-CTX @ _EXT4-C.INODES + @ U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-VICTIM-INO @ _XC-INODE @ =
    _XC-VICTIM-INO @ _XC-PARENT-INO @ = OR
    _XC-VICTIM-INO @ _XC-OLD-PARENT-INO @ = OR IF VFS-E-CORRUPT EXIT THEN
    _XC-VICTIM-VN @ VN.GEN @ DUP _XC-VICTIM-GEN !
    0xFFFFFFFF U> IF VFS-E-STALE EXIT THEN
    _XC-VICTIM-VN @ VN.NLINK @ DUP _XC-VICTIM-NLINK !
    _XC-VICTIM-DIR @ IF
        2 <> IF VFS-E-CONFLICT EXIT THEN
        TRUE
    ELSE
        DUP 1 U< SWAP _EXT4-LINK-MAX U> OR IF VFS-E-STALE EXIT THEN
        _XC-VICTIM-NLINK @ 1 =
    THEN DUP _XC-VICTIM-FINAL ! _XC-VICTIM-ORPHAN !
    _XC-HR-RENAME-VICTIM-INODE _XC-VICTIM-ROLE !
    -1 _XC-VICTIM !
    0 ;

\ RENAME names its source, a regular file or a directory held by its one
\ dentry, the new parent and the new name, and over an existing name its
\ victim.  Both parents are directories.  The old parent takes the parent
\ cells first and moves to its own bank when the parents differ; it loses
\ a link when a directory leaves it.  The new parent gains one when a
\ directory arrives from another parent and loses one with a directory
\ victim.
: _XC-ENTRY-RENAME  ( -- ior )
    _XC-FLAGS @ VFS-RN-NOREPLACE INVERT AND IF VFS-E-INVALID EXIT THEN
    _XC-VN @ VN.TYPE @ DUP VFS-T-DIR = _XC-DIRECTORY !
    DUP VFS-T-FILE <> SWAP VFS-T-DIR <> AND IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XC-VN @ VN.DREFS @ _XC-DIRECTORY @ IF
        1 <> IF VFS-E-CONFLICT EXIT THEN
    ELSE
        1 U< IF VFS-E-STALE EXIT THEN
    THEN
    _XC-VN @ VN.BID @ DUP _XC-INODE ! 0= IF VFS-E-STALE EXIT THEN
    _XC-INODE @ _XC-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-STALE EXIT THEN
    _XC-VN @ VN.GEN @ DUP _XC-NEW-GEN ! 0xFFFFFFFF U> IF
        VFS-E-STALE EXIT
    THEN
    _XC-VN @ VN.NLINK @ DUP _XC-NLINK !
    DUP 1 U< SWAP _EXT4-LINK-MAX U> OR IF VFS-E-STALE EXIT THEN
    _XC-D @ IN.PARENT @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _XC-PARENT @ <> DUP _XC-CROSS ! IF
        _XC-PARENT @ _XC-OLD-PARENT ! _XC-PARENT !
        _XC-DIRECTORY @ IF -1 ELSE 0 THEN _XC-PARENT-LINKS !
        _XC-HR-RENAME-OLD-PARENT-INODE _XC-PARENT-ROLE !
        _XC-P.OLD-PARENT-SNAPSHOT _XC-PARENT-SNAP !
        _XC-ENTRY-PARENT
        _XC-SWAP-PARENT
        ?DUP IF EXIT THEN
        _XC-DIRECTORY @ _XC-MOVING !
    ELSE
        DROP
    THEN
    _XC-HR-PARENT-INODE _XC-PARENT-ROLE !
    _XC-P.PARENT-SNAPSHOT _XC-PARENT-SNAP !
    _XC-ENTRY-PARENT ?DUP IF EXIT THEN
    _XC-CROSS @ IF
        _XC-PARENT-VN @ _XC-OLD-PARENT-VN @ =
        _XC-PARENT-INO @ _XC-OLD-PARENT-INO @ = OR IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _XC-VICTIM-D @ IF _XC-ENTRY-VICTIM ?DUP IF EXIT THEN THEN
    _XC-MOVING @ IF 1 ELSE 0 THEN
    _XC-VICTIM-DIR @ IF 1- THEN _XC-PARENT-LINKS !
    _XC-ENTRY-NAME ?DUP IF EXIT THEN
    _XC-D @ D.NAME @ _VFS-STR-GET
    2DUP _VFS-VALID-NAME? 0= IF 2DROP VFS-E-INVALID EXIT THEN
    DUP _XC-OLD-NLEN ! _XC-OLD-NAME-SNAPSHOT SWAP CMOVE
    _XC-CROSS @ 0= _XC-OLD-NLEN @ _XC-NLEN @ = AND IF
        _XC-OLD-NAME-SNAPSHOT _XC-NAME-SNAPSHOT _XC-NLEN @ _EXT4-BYTES=? IF
            VFS-E-INVALID EXIT
        THEN
    THEN
    _XC-OLD-NAME-SNAPSHOT _XC-FIND-NAME ! _XC-OLD-NLEN @ _XC-FIND-NLEN !
    _XC-ENTRY-WRITER ;

: _XC-ENTRY  ( -- ior )
    _XC-D @ 0= _XC-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _XC-LINKING @ 0<> _XC-DIRECTORY @ 0<> AND
    _XC-LINKING @ 0<> _XC-REMOVING @ 0<> AND OR
    _XC-RENAMING @ 0<> _XC-LINKING @ _XC-REMOVING @ OR 0<> AND OR IF
        VFS-E-INVALID EXIT
    THEN
    0 _XC-FINAL ! 0 _XC-ORPHAN !
    _XC-HR-INODE _XC-INODE-ROLE !
    _XC-HR-PARENT-INODE _XC-PARENT-ROLE !
    _XC-P.PARENT-SNAPSHOT _XC-PARENT-SNAP !
    _XC-DIRECTORY @ IF _XC-REMOVING @ IF -1 ELSE 1 THEN ELSE 0 THEN
    _XC-PARENT-LINKS !
    _XC-V @ _EXT4-MOW-V !
    0 _EXT4-MOW-ENTRY ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _XC-CTX !
    _EXT4-MOW-ACTIVE @ _XC-ACTIVE !
    _XC-D @ _XC-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XC-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XC-D @ D.VNODE @ DUP _XC-VN ! 0= IF VFS-E-STALE EXIT THEN
    _XC-RENAMING @ IF _XC-ENTRY-RENAME EXIT THEN
    _XC-REMOVING @ IF
        _XC-ENTRY-REMOVAL
    ELSE _XC-LINKING @ IF
        _XC-ENTRY-LINK
    ELSE
        _XC-ENTRY-NEW
    THEN THEN ?DUP IF EXIT THEN
    _XC-D @ IN.PARENT @ DUP _XC-PARENT ! 0= IF VFS-E-INVALID EXIT THEN
    _XC-ENTRY-PARENT ?DUP IF EXIT THEN
    _XC-D @ D.NAME @ _VFS-STR-GET _XC-NLEN ! _XC-NAME !
    _XC-ENTRY-NAME ?DUP IF EXIT THEN
    _XC-NAME-SNAPSHOT _XC-FIND-NAME ! _XC-NLEN @ _XC-FIND-NLEN !
    _XC-ENTRY-WRITER ;

: _XC-NOW  ( -- ior )
    _XC-CTX @ _EXT4-C.WCLOCK-CTX + @
    _XC-CTX @ _EXT4-C.WCLOCK-XT + @ EXECUTE
    _XC-IOR ! _XC-MS !
    _XC-IOR @ ?DUP IF EXIT THEN
    _XC-MS @ 0< IF VFS-E-INVALID EXIT THEN
    _XC-MS @ _EXT4-WRITE-EPOCH-MS-MAX U> IF VFS-E-OVERFLOW EXIT THEN
    _XC-MS @ 1000 /MOD
    _XC-SECONDS ! 1000000 * _XC-NSEC !
    0 ;

: _XC-REFUSE-ENTRY  ( ior -- ior )
    _XC-IOR !
    _XC-SCRUB-PRIVATE
    _EXT4-MOW-CTX @ ?DUP IF
        _XC-V @ _XC-P-CONTEXT?
        DUP IF
            2DROP
        ELSE
            DROP _XC-P-SCRUB
        THEN
    THEN
    _XC-V @ IF _XC-IOR @ _XC-V @ V.LAST-IOR ! THEN
    _XC-IOR @ ;

: _XC-REFUSE  ( plan ior -- ior )
    DUP _XC-V @ V.LAST-IOR !
    OVER _XC-SCRUB NIP ;

: _XC-FAIL-RETAIN  ( plan ior -- plan ior )
    _XC-IOR !
    _XC-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF
                _XC-WRITER @ _EXT4-JWR-LATCH-FAULT _XC-IOR !
            THEN
        ELSE
            DUP _EXT4-JWR.STATE + @ _EXT4-JWR-COMMITTED = IF
                DROP
                _EXT4-JWP-CHECKPOINT-PREFLIGHT
                _XC-WRITER @ _EXT4-JWR.PHASE + !
                _XC-IOR @ _XC-WRITER @ _EXT4-JWR-LATCH-FAULT
                _XC-IOR !
            ELSE
                DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
                    _EXT4-JWR.FAULT + @ ?DUP IF _XC-IOR ! THEN
                ELSE
                    DROP
                THEN
            THEN
        THEN
    THEN
    _XC-IOR @ _XC-V @ V.LAST-IOR !
    _XC-IOR @ ;

: _XC-FAIL  ( plan ior -- ior )
    _XC-FAIL-RETAIN
    OVER _XC-SCRUB NIP ;

\ Publish a committed parent into the cache: its times and link count, and
\ after growth its size and sectors.
: _XC-PUBLISH-PARENT  ( -- )
    _XC-SECONDS @ _XC-PARENT-VN @ VN.MTIME !
    _XC-NSEC @ _XC-PARENT-VN @ VN.MTIME-NS !
    _XC-SECONDS @ _XC-PARENT-VN @ VN.CTIME !
    _XC-NSEC @ _XC-PARENT-VN @ VN.CTIME-NS !
    _XC-PARENT-NEW-NLINK @ _XC-PARENT-VN @ VN.NLINK !
    _XC-GROWTH @ IF
        _XC-NEW-SIZE @ _XC-PARENT-VN @ VN.SIZE-LO !
        0 _XC-PARENT-VN @ VN.SIZE-HI !
        _XC-NEW-SECTORS @ _XC-PARENT-VN @ VN.BLOCKS !
    THEN ;

\ Publish a committed removal into the cache: the target's change time, or
\ for a closed last link of an empty file the mount's free inode count; a
\ removed directory's one link, which the VFS lowers to zero once the
\ callback returns; and the parent.
: _XC-PUBLISH-REMOVAL  ( -- )
    _XC-FINAL @ _XC-ORPHAN @ 0= AND IF
        _XC-SUPER-NEW-FREE @ _XC-CTX @ _EXT4-C.FREE-INODES + !
    ELSE
        _XC-SECONDS @ _XC-VN @ VN.CTIME !
        _XC-NSEC @ _XC-VN @ VN.CTIME-NS !
    THEN
    _XC-DIRECTORY @ IF 1 _XC-VN @ VN.NLINK ! THEN
    _XC-PUBLISH-PARENT
    VFS-IF-DIRTY _XC-VN @ VN.FLAGS DUP @ ROT OR SWAP !
    VFS-IF-DIRTY _XC-PARENT-VN @ VN.FLAGS DUP @ ROT OR SWAP !
    VFS-F-DIRTY _XC-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

\ Publish a committed rename into the cache: the source's change time; a
\ victim's, and a directory victim's one link, which the VFS lowers to zero
\ once the callback returns; both parents, the old one from its own bank;
\ and after growth the mount's free blocks.
: _XC-PUBLISH-RENAME  ( -- )
    _XC-SECONDS @ _XC-VN @ VN.CTIME !
    _XC-NSEC @ _XC-VN @ VN.CTIME-NS !
    VFS-IF-DIRTY _XC-VN @ VN.FLAGS DUP @ ROT OR SWAP !
    _XC-VICTIM @ IF
        _XC-SECONDS @ _XC-VICTIM-VN @ VN.CTIME !
        _XC-NSEC @ _XC-VICTIM-VN @ VN.CTIME-NS !
        _XC-VICTIM-DIR @ IF 1 _XC-VICTIM-VN @ VN.NLINK ! THEN
        VFS-IF-DIRTY _XC-VICTIM-VN @ VN.FLAGS DUP @ ROT OR SWAP !
    THEN
    _XC-PUBLISH-PARENT
    VFS-IF-DIRTY _XC-PARENT-VN @ VN.FLAGS DUP @ ROT OR SWAP !
    _XC-CROSS @ IF
        _XC-SWAP-PARENT
        _XC-PUBLISH-PARENT
        VFS-IF-DIRTY _XC-PARENT-VN @ VN.FLAGS DUP @ ROT OR SWAP !
        _XC-SWAP-PARENT
    THEN
    _XC-NEW-FREE @ _XC-CTX @ _EXT4-C.FREE-BLOCKS + !
    VFS-F-DIRTY _XC-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

\ Publish a committed operation into the cache: a rename's or a removal's
\ own publication, or an insert's entry inode, its parent and the mount's
\ free counts.
: _XC-PUBLISH-COMMITTED  ( -- )
    _XC-RENAMING @ IF _XC-PUBLISH-RENAME EXIT THEN
    _XC-REMOVING @ IF _XC-PUBLISH-REMOVAL EXIT THEN
    _XC-LINKING @ IF
        _XC-LINK-NEW-NLINK @ _XC-VN @ VN.NLINK !
        _XC-SECONDS @ _XC-VN @ VN.CTIME !
        _XC-NSEC @ _XC-VN @ VN.CTIME-NS !
        VFS-IF-DIRTY _XC-VN @ VN.FLAGS DUP @ ROT OR SWAP !
        VFS-IF-DIRTY _XC-PARENT-VN @ VN.FLAGS DUP @ ROT OR SWAP !
    ELSE
        _XC-DIRECTORY @ IF
            VFS-T-DIR _XC-VN @ VN.TYPE !
            0x41ED _XC-VN @ VN.MODE !
            _XC-CTX @ _EXT4-C.BSIZE + @ _XC-VN @ VN.SIZE-LO !
            2 _XC-VN @ VN.NLINK !
            _XC-CTX @ _EXT4-C.SPB + @ _XC-VN @ VN.BLOCKS !
        ELSE
            VFS-T-FILE _XC-VN @ VN.TYPE !
            0x81B6 _XC-VN @ VN.MODE !
            0 _XC-VN @ VN.SIZE-LO !
            1 _XC-VN @ VN.NLINK !
            0 _XC-VN @ VN.BLOCKS !
        THEN
        0 _XC-VN @ VN.SIZE-HI !
        0 _XC-VN @ VN.UID ! 0 _XC-VN @ VN.GID !
        _XC-INODE @ DUP _XC-VN @ VN.BID !
        _XC-VN @ VN.BDATA !
        0 _XC-VN @ VN.BDATA 8 + !
        _XC-NEW-GEN @ _XC-VN @ VN.GEN !
        _XC-SECONDS @ _XC-VN @ VN.ATIME !
        _XC-NSEC @ _XC-VN @ VN.ATIME-NS !
        _XC-SECONDS @ _XC-VN @ VN.MTIME !
        _XC-NSEC @ _XC-VN @ VN.MTIME-NS !
        _XC-SECONDS @ _XC-VN @ VN.CTIME !
        _XC-NSEC @ _XC-VN @ VN.CTIME-NS !
        _XC-SUPER-NEW-FREE @ _XC-CTX @ _EXT4-C.FREE-INODES + !
    THEN
    _XC-PUBLISH-PARENT
    _XC-NEW-FREE @ _XC-CTX @ _EXT4-C.FREE-BLOCKS + !
    VFS-F-DIRTY _XC-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

\ Checkpoint preflight reloads the on-disk superblock before writing any
\ home.  A home tear may therefore leave the cached free counts at the
\ pretransaction values even though the committed journal is now the
\ namespace authority.  Reapply the complete committed cache projection
\ after quarantine; recovery will converge the media on the next mount.
: _XC-POSTCOMMIT-FAIL  ( plan ior -- ior )
    _XC-FAIL-RETAIN DROP
    _XC-PUBLISH-COMMITTED
    _XC-SCRUB
    0 ;

\ A drain that fails after the operation's checkpoint leaves a durable
\ orphan that mount recovery finishes.  Report success, keep the diagnostic in
\ V.LAST-IOR, and turn the volume read-only until that remount.
: _XC-DURABLE-FAIL  ( plan ior -- ior )
    VFS-F-RO VFS-F-DIRTY OR _XC-V @ V.FLAGS DUP @ ROT OR SWAP !
    _XC-POSTCOMMIT-FAIL ;

\ A closed last link that entered the orphan file drains now, through the
\ release passes and the deletion; an open one drains on its last RELEASE.
\ A rename's final victim drains as a removal's target does.
: _XC-DRAIN  ( -- ior )
    _XC-DRAINS? 0= IF 0 EXIT THEN
    _XC-RENAMING @ IF
        _XC-VICTIM-VN @ _XC-VICTIM-INO @
    ELSE
        _XC-VN @ _XC-INODE @
    THEN
    SWAP VN.OPEN-REFS @ IF DROP 0 EXIT THEN
    _XC-WRITER @ _XC-CTX @ _EXT4-DRAIN-ORPHAN ;

\ Plan, measure and seal the operation, activate a clean journal, then
\ stage the live transaction, emit it, checkpoint it synchronously, and
\ drain the orphan a removal or a rename's victim leaves.
: _XC-RUN  ( -- ior )
    0 _XC-WRITER ! 0 _XC-TX !
    0 _XC-CTX ! 0 _EXT4-MOW-CTX !
    0 _XC-EDIT ! 0 _XC-GROWTH !
    _XC-ENTRY ?DUP IF _XC-REFUSE-ENTRY EXIT THEN
    _XC-CTX @ _XC-V @ _XC-P-CONTEXT?
    DUP IF NIP _XC-REFUSE-ENTRY EXIT THEN DROP
    _XC-CTX @ _XC-OP _XC-P-BEGIN ?DUP IF _XC-REFUSE EXIT THEN
    _XC-NOW ?DUP IF _XC-REFUSE EXIT THEN
    _XC-PLAN ?DUP IF _XC-REFUSE EXIT THEN
    _XC-MEASURE ?DUP IF _XC-FAIL EXIT THEN
    _XC-P-SEAL ?DUP IF _XC-FAIL EXIT THEN
    _XC-ACTIVE @ 0= IF
        _XC-WRITER @ _EXT4-JWR-ACTIVATE ?DUP IF _XC-FAIL EXIT THEN
    THEN
    _XC-WRITER @ _XC-HP-BEGIN-TX
    DUP IF NIP _XC-FAIL EXIT THEN
    DROP _XC-TX !
    _XC-TX @ _EXT4-JTX-STAGE-NAMESPACE
    ?DUP IF _XC-FAIL EXIT THEN
    _XC-TX @ _EXT4-JTX-EMIT ?DUP IF _XC-FAIL EXIT THEN
    _XC-PUBLISH-COMMITTED
    _XC-TX @ _EXT4-JTX-CHECKPOINT
    ?DUP IF _XC-POSTCOMMIT-FAIL EXIT THEN
    _XC-WRITER @ _EXT4-REQUIRE-IDLE-WRITER
    ?DUP IF _XC-POSTCOMMIT-FAIL EXIT THEN
    _XC-DRAIN ?DUP IF _XC-DURABLE-FAIL EXIT THEN
    0 _XC-V @ V.LAST-IOR !
    _XC-SCRUB
    0 ;

: _EXT4-CREATE  ( dentry vfs -- ior )
    _XC-V ! _XC-D !
    0 _XC-TARGET ! 0 _XC-LINKING ! 0 _XC-DIRECTORY ! 0 _XC-REMOVING !
    0 _XC-RENAMING !
    _XC-RUN ;

: _EXT4-MKDIR  ( dentry vfs -- ior )
    _XC-V ! _XC-D !
    0 _XC-TARGET ! 0 _XC-LINKING ! -1 _XC-DIRECTORY ! 0 _XC-REMOVING !
    0 _XC-RENAMING !
    _XC-RUN ;

: _EXT4-LINK  ( new-dentry target vfs -- ior )
    _XC-V ! _XC-TARGET ! _XC-D !
    -1 _XC-LINKING ! 0 _XC-DIRECTORY ! 0 _XC-REMOVING !
    0 _XC-RENAMING !
    _XC-RUN ;

: _EXT4-UNLINK  ( dentry vfs -- ior )
    _XC-V ! _XC-D !
    0 _XC-TARGET ! 0 _XC-LINKING ! 0 _XC-DIRECTORY ! -1 _XC-REMOVING !
    0 _XC-RENAMING !
    _XC-RUN ;

: _EXT4-RMDIR  ( dentry vfs -- ior )
    _XC-V ! _XC-D !
    0 _XC-TARGET ! 0 _XC-LINKING ! -1 _XC-DIRECTORY ! -1 _XC-REMOVING !
    0 _XC-RENAMING !
    _XC-RUN ;

: _EXT4-RENAME  ( new-a new-u source new-parent victim flags vfs -- ior )
    _XC-SCRUB-RENAME
    _XC-V ! _XC-FLAGS ! _XC-VICTIM-D ! _XC-PARENT ! _XC-D !
    _XC-NLEN ! _XC-NAME !
    0 _XC-TARGET ! 0 _XC-LINKING ! 0 _XC-DIRECTORY ! 0 _XC-REMOVING !
    -1 _XC-RENAMING !
    _XC-RUN ;

' _EXT4-CREATE EXT4-STAGED-WRITE-OPS VFS-OP-CREATE CELLS + !
' _EXT4-MKDIR EXT4-STAGED-WRITE-OPS VFS-OP-MKDIR CELLS + !
' _EXT4-LINK EXT4-STAGED-WRITE-OPS VFS-OP-LINK CELLS + !
' _EXT4-UNLINK EXT4-STAGED-WRITE-OPS VFS-OP-UNLINK CELLS + !
' _EXT4-RMDIR EXT4-STAGED-WRITE-OPS VFS-OP-RMDIR CELLS + !
' _EXT4-RENAME EXT4-STAGED-WRITE-OPS VFS-OP-RENAME CELLS + !

\ =====================================================================
\  General regular-file truncate
\ =====================================================================
\
\ The generic VFS has already published the requested size when this
\ callback runs and retains the old size in its guarded operation state.
\ One journal transaction sets the new size and trusted-clock times.  A
\ shrink also releases every block past the new EOF at any tree depth and
\ zeroes the bytes past EOF in the block that now holds it.  That block is
\ staged as a journaled after-image rather than ordered data, since an
\ ordered write before commit could zero bytes the old size still shows.
\ A growing truncate instead zeroes the old EOF block's bytes past the old
\ size as ordered data, which the old size hides until commit.  A release
\ that does not fit one transaction under the bound profile refuses with
\ VFS-E-NOSPC before any media I/O.

VARIABLE _XT-D
VARIABLE _XT-V
VARIABLE _XT-VN
VARIABLE _XT-NEW
VARIABLE _XT-OLD
VARIABLE _XT-MS
VARIABLE _XT-IOR
VARIABLE _XT-AT
VARIABLE _XT-JOURNALED
VARIABLE _XT-NEW-BLOCKS
VARIABLE _XT-NEW-FREE

: _XT-ENTRY  ( -- ior )
    _XT-D @ 0= _XT-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _XT-V @ _EXT4-MOW-V !
    0 _EXT4-MOW-ENTRY ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _XW-CTX !
    _XW-CTX @ _EXT4-C.BSIZE + @ _XW-BSIZE !
    _XT-D @ _XT-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XT-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XT-D @ D.VNODE @ DUP _XT-VN ! 0= IF VFS-E-STALE EXIT THEN
    _XT-VN @ VN.TYPE @ VFS-T-DIR = IF VFS-E-ISDIR EXIT THEN
    _XT-VN @ VN.TYPE @ VFS-T-FILE <> IF
        EXT4-D-FEATURE _EXT4-UNSUPPORTED EXIT
    THEN
    _XT-VN @ VN.BID @ DUP _XW-INO ! 0= IF VFS-E-STALE EXIT THEN
    _XW-INO @ _XW-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-STALE EXIT THEN
    _XT-VN @ VN.GEN @ DUP _XW-EXPECTED-GEN ! 0xFFFFFFFF U> IF
        VFS-E-STALE EXIT
    THEN
    _XT-VN @ VN.SIZE-HI @ IF VFS-E-OVERFLOW EXIT THEN
    _XT-VN @ VN.SIZE-LO @ DUP _XT-NEW ! 0< IF VFS-E-OVERFLOW EXIT THEN
    _VTR-SIZE @ _XT-NEW @ <> IF VFS-E-CONFLICT EXIT THEN
    _VTR-OLD-SIZE-HI @ IF VFS-E-OVERFLOW EXIT THEN
    _VTR-OLD-SIZE @ DUP _XT-OLD ! 0< IF VFS-E-OVERFLOW EXIT THEN
    _XT-VN @ VN.NLINK @ 0= IF VFS-E-STALE EXIT THEN
    0 ;

\ A size change needs the format to hold the new size, a writable
\ geometry, a trusted clock and a bound writer profile.
: _XT-QUALIFY  ( -- ior )
    _XT-NEW @ _XW-CTX @ _EXT4-MAX-FILE-SIZE U> IF VFS-E-OVERFLOW EXIT THEN
    _XW-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    _XW-CTX @ _EXT4-C.WCLOCK-XT + @ 0= IF VFS-E-UNSUPPORTED EXIT THEN
    _XW-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF VFS-E-NOSPC EXIT THEN
    _XW-CTX @ _EXT4-C.J.WRITER-ARENA + @ 0=
    _XW-CTX @ _EXT4-C.J.WRITER + @ 0= OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _XT-NOW  ( -- ior )
    _XW-CTX @ _EXT4-C.WCLOCK-CTX + @
    _XW-CTX @ _EXT4-C.WCLOCK-XT + @ EXECUTE
    _XT-IOR ! _XT-MS !
    _XT-IOR @ ?DUP IF EXIT THEN
    _XT-MS @ 0< IF VFS-E-INVALID EXIT THEN
    _XT-MS @ _EXT4-WRITE-EPOCH-MS-MAX U> IF VFS-E-OVERFLOW EXIT THEN
    _XT-MS @ 1000 /MOD
    _XW-SECONDS ! 1000000 * _XW-NSEC !
    0 ;

\ Zero the bytes past SIZE in the block that holds it, when that block is
\ mapped, initialized and left partial.  A shrink stages the block as a
\ journaled after-image, a growth as ordered data.
: _XT-ZERO-TAIL  ( size journaled? -- ior )
    _XT-JOURNALED !
    _XW-BSIZE @ /MOD SWAP DUP _XT-AT ! 0= IF DROP 0 EXIT THEN
    _XN-LOOKUP ?DUP IF >R 2DROP DROP R> EXIT THEN
    _XN-MAPPED <> IF 2DROP 0 EXIT THEN
    DROP
    DUP _XW-CTX @ _EXT4-READ-BLOCK ?DUP IF NIP EXIT THEN
    _XW-CTX @ _EXT4-C.BLOCK + _XW-DATA _XW-BSIZE @ MOVE
    _XW-DATA _XT-AT @ + _XW-BSIZE @ _XT-AT @ - 0 FILL
    1 _XW-OVERWRITES +!
    _XW-DATA SWAP _XW-TX @
    _XT-JOURNALED @ IF _EXT4-JTX-META-PUT ELSE _EXT4-JTX-DATA-PUT THEN ;

\ Stage one complete truncate into _XW-TX: the zeroed tail, the release of
\ every block past the new EOF, and the inode record as the last home.
: _XT-STAGE  ( -- ior )
    0 _XW-OVERWRITES ! 0 _XN-NEW-NODES ! 0 _XN-EXISTING !
    0 _XR-DATA ! 0 _XR-NODES ! 0 _XR-FREED !
    _XW-AUTH ?DUP IF EXIT THEN
    _XW-SIZE @ _XT-OLD @ <> IF VFS-E-STALE EXIT THEN
    _XW-TREE
    _XT-NEW @ _XT-OLD @ U< IF
        _XT-NEW @ TRUE _XT-ZERO-TAIL ?DUP IF EXIT THEN
        _XT-NEW @ _XW-BSIZE @ 1- + _XW-BSIZE @ / _XR-START !
        FALSE _XR-FIT !
        _XR-RELEASE ?DUP IF EXIT THEN
        _XR-DONE @ 0= IF VFS-E-NOSPC EXIT THEN
        \ The root's slots past its last entry carry no stale bytes, as
        \ every edited node's do.
        _XN-ROOT @ _XN-CLEAR-TAIL
    ELSE
        _XT-OLD @ FALSE _XT-ZERO-TAIL ?DUP IF EXIT THEN
    THEN
    _XR-DATA @ _XR-NODES @ + DUP
    _XW-CTX @ _EXT4-C.FREE-BLOCKS + @ + _XT-NEW-FREE !
    _XW-CTX @ _EXT4-C.SPB + @ * _XW-BLOCKS @ SWAP - _XT-NEW-BLOCKS !
    _XT-NEW @ _XT-NEW-BLOCKS @ _XW-PUT-INODE ;

\ The freed runs, the zeroed tail and every edited tree node must be mapped
\ exactly once by the target.
: _XT-PROVE  ( -- ior )
    _XR-FREED @ _XP-BASE !
    _XW-OVERWRITES @ _XN-EXISTING @ + _XR-DATA @ + _XR-NODES @ +
    _XP-EXPECT !
    _XP-COLLECT ?DUP IF EXIT THEN
    _XP-MAP-CHECK ;

\ ---------------------------------------------------------------------
\  Orphan release and a linked record's final cleanup
\ ---------------------------------------------------------------------
\
\ A linked orphan record holds an inode whose size a truncate has already
\ committed while blocks past its EOF may still be mapped, and an unlinked
\ one holds a file whose last link is gone, every block of which must be
\ freed before the inode is.  Release passes free them from the end of the
\ file, as many removal steps per pass as surely fit the transaction.  A
\ linked record's final cleanup then zeroes the bytes past EOF in the
\ block that holds it and removes the record; an unlinked record's inode
\ is then deleted with it.  A live truncate or unlink and mount recovery
\ run the same steps.  The kernel's orphan cleanup truncates or deletes
\ such an inode the same way, so a record either one leaves behind
\ completes on the other.

VARIABLE _XO-RECORD
VARIABLE _XO-CTX
VARIABLE _XO-AT
VARIABLE _XO-CAP
VARIABLE _XO-HOME
CREATE _XO-AFTER _EXT4-MAX-INODE ALLOT

\ Load the record's target into the general write's state, its whole map
\ validated, an extent tree or a legacy block map.  A linked target is
\ released from its EOF, and an unlinked one from its first block.
: _XO-LOAD  ( -- ior )
    TRUE _XW-ORPHAN !
    _XO-RECORD @ _XW-CTX @ _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF EXIT THEN
    _XW-CTX @ _EXT4-C.BSIZE + @ _XW-BSIZE !
    _XO-RECORD @ _EXT4-OE.INO + @ _XW-INO !
    _XW-CTX @ _EXT4-C.INODE +
    DUP _EXT4-I.LINKS + W@ 0= _XW-DELETION !
    _EXT4-I.GENERATION + L@ _XW-EXPECTED-GEN !
    _XW-AUTH ?DUP IF EXIT THEN
    _XW-TREE
    _XW-DELETION @ IF 0 ELSE
        _XW-SIZE @ _XW-BSIZE @ 1- + _XW-BSIZE @ /
    THEN _XR-START !
    0 ;

\ True when the target maps nothing at or past _XR-START.  Extents are
\ ordered and no external node is empty, so the last extent decides; a
\ legacy map is searched from its last branch down.
: _XO-COMPLETE?  ( -- flag ior )
    _XN-LEGACY @ IF
        _XI-FIND ?DUP IF FALSE SWAP EXIT THEN
        _XI-ITEM @ _XI-NONE = 0 EXIT
    THEN
    0xFFFFFFFF _XN-FIND ?DUP IF FALSE SWAP EXIT THEN
    _XN-LEAF DUP _XN-COUNT@ 0= IF DROP TRUE 0 EXIT THEN
    DUP _XN-COUNT@ 1- _XN-ENTRY DUP L@ SWAP _EXT4-EXTENT-LEN@ +
    _XR-START @ U> 0= 0 ;

\ The block that holds EOF when EOF falls inside it, the block is mapped and
\ initialized, and a byte past EOF in it is not zero; otherwise zero.  The
\ block is left in C.BLOCK.
: _XO-TAIL-HOME  ( -- home ior )
    _XW-SIZE @ _XW-BSIZE @ /MOD SWAP DUP _XO-AT ! 0= IF DROP 0 0 EXIT THEN
    _XN-LEGACY @ IF
        _XI-LOOKUP ?DUP IF NIP 0 SWAP EXIT THEN
        ?DUP 0= IF 0 0 EXIT THEN
    ELSE
        _XN-LOOKUP ?DUP IF >R 2DROP DROP 0 R> EXIT THEN
        _XN-MAPPED <> IF 2DROP 0 0 EXIT THEN
        DROP
    THEN
    DUP _XW-CTX @ _EXT4-READ-BLOCK ?DUP IF NIP 0 SWAP EXIT THEN
    _XW-CTX @ _EXT4-C.BLOCK + _XO-AT @ + _XW-BSIZE @ _XO-AT @ -
    _EXT4-BYTES-ZERO? IF DROP 0 THEN 0 ;

\ A legacy record keeps the next record's inode in i_dtime, which its final
\ cleanup clears when it has a successor.
: _XO-SUCCESSOR?  ( -- flag )
    _XO-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY =
    _XO-RECORD @ _EXT4-OE.LOCATOR-A + @ 0<> AND ;

\ Zero the bytes past EOF in HOME, the block that holds EOF, whose image
\ _XO-TAIL-HOME left in C.BLOCK.  The block is staged as a journaled
\ after-image of a data block the target rewrites.
: _XO-STAGE-TAIL  ( home -- ior )
    DUP _EXT4-JFC-TAIL-HOME !
    _XW-CTX @ _EXT4-C.BLOCK + _XW-DATA _XW-BSIZE @ MOVE
    _XW-DATA _XO-AT @ + _XW-BSIZE @ _XO-AT @ - 0 FILL
    1 _XW-OVERWRITES +!
    _XW-DATA SWAP _XW-TX @ _EXT4-JTX-META-PUT ;

\ Stage the target's part of the final cleanup of a record whose release
\ is already complete.  The tail is a data block the target alone maps,
\ exactly once.
: _XO-FINAL  ( -- ior )
    _XO-TAIL-HOME ?DUP IF NIP EXIT THEN
    ?DUP IF
        DUP _XO-STAGE-TAIL ?DUP IF NIP EXIT THEN
        _XW-CTX @ _EXT4-C.MUTATION-RANGES + @ DUP _XP-RANGES ! 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _XW-CTX @ _EXT4-C.MUTATION-RANGE-CAP + @ _XP-CAP !
        0 _XP-COUNT ! 1 _XP-EXPECT !
        _XP-ADD ?DUP IF EXIT THEN
        _XP-MAP-CHECK ?DUP IF EXIT THEN
    THEN
    _XO-SUCCESSOR? IF
        _XW-INODE _XO-AFTER _XW-CTX @ _EXT4-C.ISIZE + @ MOVE
        0 _XO-AFTER _EXT4-I.DTIME + L!
        _XO-AFTER _XO-RECORD @ _XW-TX @ _EXT4-JTX-STAGE-ORPHAN-INODE
        ?DUP IF EXIT THEN
    THEN
    0 ;

\ True when the pass's release finished and a linked record's final
\ cleanup's homes still fit: the inode, the tail when it needs zeroing, and
\ a modern record's orphan block.  A legacy record's head moves in the
\ superblock the freed runs' accounting already staged.  An unlinked
\ record's deletion folds through _XO-DELETE? instead.
: _XO-FOLD?  ( -- flag ior )
    _XR-DONE @ 0= _XW-DELETION @ OR IF FALSE 0 EXIT THEN
    _XO-TAIL-HOME ?DUP IF NIP FALSE SWAP EXIT THEN
    DUP _XO-HOME ! 0<> 1 AND 1+
    _XO-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = 1 AND +
    _XW-TX @ _EXT4-JWR.META-USED + @ +
    _XW-TX @ _EXT4-JWR.META-CREDIT + @ U> 0= 0 ;

\ Stage the target's inode with its new block count.  A pass that also ends
\ the record's cleanup clears a legacy record's successor link.
: _XO-PUT-TARGET  ( fold? -- ior )
    IF _XO-SUCCESSOR? IF 0 _XW-INODE _EXT4-I.DTIME + L! THEN THEN
    _XW-SIZE @
    _XR-DATA @ _XR-NODES @ + _XW-CTX @ _EXT4-C.SPB + @ * _XW-BLOCKS @ SWAP -
    _XW-PUT-RECORD ;

VARIABLE _XO-D-NEED
VARIABLE _XO-D-REVOKE

\ Count HOME toward the folded deletion unless the pass already stages it.
: _XO-D-HOME  ( home -- ior )
    _XW-TX @ _EXT4-JTX-META-IMAGE ?DUP IF NIP EXIT THEN
    0= IF 1 _XO-D-NEED +! THEN 0 ;

\ The primary descriptor block that holds GROUP's descriptor.
: _XO-D-PAGE  ( group -- home )
    _XR-PAGE-OF _XW-CTX @ _EXT4-GDT-BASE + ;

\ An external xattr block's part of the deletion.  A larger reference
\ count rewrites the block itself; the last reference frees it with a
\ revoke, in its group's bitmap and descriptor page.
: _XO-D-XATTR  ( block -- ior )
    DUP _XW-CTX @ _EXT4-LOAD-XATTR-BLOCK ?DUP IF NIP EXIT THEN
    _XW-CTX @ _EXT4-C.BLOCK + 4 + L@ 1 <> IF
        DROP 1 _XO-D-NEED +! 0 EXIT
    THEN
    1 _XO-D-REVOKE !
    _XR-GROUP-OF DUP _XW-CTX @ _EXT4-LOAD-DESC ?DUP IF NIP EXIT THEN
    _XW-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _XO-D-HOME ?DUP IF NIP EXIT THEN
    _XO-D-PAGE _XO-D-HOME ;

\ True when an unlinked record's pass freed the rest of the map and its
\ deletion still fits, counted against the homes the pass already stages:
\ the inode's record and the inode bitmap, the inode group's descriptor
\ page, the superblock, a modern record's orphan block, and an external
\ xattr block's part.  The pass's freed runs then become the deletion's
\ vector.
: _XO-DELETE?  ( -- flag ior )
    _XR-DONE @ 0= IF FALSE 0 EXIT THEN
    2 _XO-D-NEED ! 0 _XO-D-REVOKE !
    _XO-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        1 _XO-D-NEED +!
    THEN
    _XW-INO @ 1- _XW-CTX @ _EXT4-C.IPG + @ / _XO-D-PAGE _XO-D-HOME
    ?DUP IF FALSE SWAP EXIT THEN
    _XW-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _XO-D-HOME
    ?DUP IF FALSE SWAP EXIT THEN
    _XW-INODE _EXT4-I.FILE-ACL-LO + L@ ?DUP IF
        _XO-D-XATTR ?DUP IF FALSE SWAP EXIT THEN
    THEN
    _XW-TX @ _EXT4-JWR.META-USED + @ _XO-D-NEED @ +
    _XW-TX @ _EXT4-JWR.META-CREDIT + @ U> IF FALSE 0 EXIT THEN
    _XW-TX @ _EXT4-JWR.REVOKE-USED + @ _XO-D-REVOKE @ +
    _XW-TX @ _EXT4-JWR.REVOKE-CREDIT + @ U> IF FALSE 0 EXIT THEN
    _XR-FREED @ _EXT4-JFI-RELEASED-RUNS !
    _XR-DATA @ _XR-NODES @ + _EXT4-JFI-RELEASED-BLOCKS !
    TRUE _EXT4-JFI-RELEASED !
    TRUE 0 ;

\ Stage one release pass: the removal steps that surely fit, then the
\ target's inode with its unchanged size and times.  FOLD? is true when the
\ pass also stages the target's part of the final cleanup, or, for an
\ unlinked record, when its deletion follows in the same transaction and
\ stages the inode itself.
: _XO-PASS  ( -- fold? ior )
    0 _XW-OVERWRITES ! 0 _XN-NEW-NODES ! 0 _XN-EXISTING !
    0 _XR-DATA ! 0 _XR-NODES ! 0 _XR-FREED !
    TRUE _XR-FIT !
    _XR-RELEASE ?DUP IF FALSE SWAP EXIT THEN
    _XR-STEPS @ 0= IF FALSE VFS-E-NOSPC EXIT THEN
    _XN-LEGACY @ 0= IF _XN-ROOT @ _XN-CLEAR-TAIL THEN
    _XW-DELETION @ IF
        _XO-DELETE? ?DUP IF NIP FALSE SWAP EXIT THEN
        IF TRUE 0 EXIT THEN
    THEN
    _XO-FOLD? ?DUP IF NIP FALSE SWAP EXIT THEN
    DUP IF
        _XO-HOME @ ?DUP IF
            _XO-STAGE-TAIL ?DUP IF NIP FALSE SWAP EXIT THEN
        THEN
    THEN
    DUP _XO-PUT-TARGET ?DUP IF NIP FALSE SWAP EXIT THEN
    _XT-PROVE ;

\ The record step for mount recovery and a live drain.  A linked record's
\ pass that ends the release also stages the target's part of the final
\ cleanup, as one that finds the release complete does, and the caller then
\ removes the record in the same transaction.  An unlinked record is
\ stepped only while its tree maps blocks.
: _XO-STEP  ( plan-record transaction -- release? ior )
    _XW-TX ! _XO-RECORD !
    _XW-TX @ _EXT4-JWR.CTX + @ _XW-CTX !
    0 _EXT4-JFC-TAIL-HOME !
    _XO-LOAD ?DUP IF FALSE SWAP EXIT THEN
    _XO-COMPLETE? ?DUP IF NIP FALSE SWAP EXIT THEN
    IF
        _XW-DELETION @ IF FALSE VFS-E-CORRUPT EXIT THEN
        _XO-FINAL FALSE SWAP EXIT
    THEN
    _XO-PASS ?DUP IF NIP TRUE SWAP EXIT THEN
    IF FALSE 0 EXIT THEN
    _XO-RECORD @ _XW-TX @ _EXT4-JRL-SEAL TRUE SWAP ;

' _XO-STEP _EXT4-ORPHAN-STEP-XT !

\ A release pass's credits.  A bound writer profile is the pass's capacity.
\ Mount recovery sizes its own writer to free one full leaf of fragmented
\ extents per pass, two homes each, and halves it while the mount arena or
\ the journal cannot hold it, down to the room one removal step needs.
: _EXT4-RELEASE-PASS-CREDIT  ( ctx -- meta-credit revoke-credit ior )
    DUP _EXT4-C.J.WRITER + @ ?DUP IF
        NIP DUP _EXT4-JWR.META-CAP + @ SWAP _EXT4-JWR.REVOKE-CAP + @ 0 EXIT
    THEN
    _XO-CTX !
    _XO-CTX @ _EXT4-C.BSIZE + @ 12 - 12 / 2*
    _EXT4-MAX-EXTENT-DEPTH 3 * + 8 + _XO-CAP !
    BEGIN
        _XO-CAP @ 0 _XO-CAP @ _XO-CTX @ _EXT4-JTX-PREFLIGHT-CAPACITY
    WHILE
        _XO-CAP @ 2/ _XO-CAP !
        _XO-CAP @ _EXT4-MAX-EXTENT-DEPTH 3 * 5 + U< IF
            0 0 VFS-E-NOMEM EXIT
        THEN
    REPEAT
    _XO-CAP @ DUP 0 ;

\ The credits of the record's next transaction: a release pass while blocks
\ it must free remain, else a linked record's final cleanup's exact homes,
\ its orphan block or superblock, the tail and a legacy successor's inode.
: _XO-MEASURE  ( plan-record ctx -- meta-credit revoke-credit ior )
    _XW-CTX ! _XO-RECORD !
    0 _XW-TX !
    _XO-LOAD ?DUP IF 0 0 ROT EXIT THEN
    _XO-COMPLETE? ?DUP IF NIP 0 0 ROT EXIT THEN
    0= IF _XW-CTX @ _EXT4-RELEASE-PASS-CREDIT EXIT THEN
    _XW-DELETION @ IF 0 0 VFS-E-CORRUPT EXIT THEN
    _XO-TAIL-HOME ?DUP IF NIP 0 0 ROT EXIT THEN
    0<> 1 AND 1+ _XO-SUCCESSOR? 1 AND + 0 0 ;

' _XO-MEASURE _EXT4-ORPHAN-MEASURE-XT !

\ Begin a transaction with the whole bound profile, then stage and prove
\ the truncate.  On success the transaction stays staged.
: _XT-PASS  ( -- ior )
    _XW-WRITER @ _EXT4-JWR.META-CAP + @
    _XW-WRITER @ _EXT4-JWR.DATA-CAP + @
    _XW-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _XW-WRITER @ _EXT4-JTX-BEGIN ?DUP IF NIP EXIT THEN
    _XW-TX !
    _XT-STAGE DUP 0= IF DROP _XT-PROVE THEN
    DUP IF _XW-DISCARD ?DUP IF NIP THEN THEN ;

\ Settle a failure before commit.  A staged transaction is discarded, a
\ committed one whose checkpoint could not start is latched, and a latched
\ fault keeps its first diagnosis.
: _XT-FAIL  ( ior -- ior )
    _XT-IOR !
    _XW-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            DROP _XW-DISCARD ?DUP IF _XT-IOR ! THEN
        ELSE DUP _EXT4-JWR.STATE + @ _EXT4-JWR-COMMITTED = IF
            _EXT4-JWP-CHECKPOINT-PREFLIGHT OVER _EXT4-JWR.PHASE + !
            _XT-IOR @ SWAP _EXT4-JWR-LATCH-FAULT _XT-IOR !
        ELSE DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
            _EXT4-JWR.FAULT + @ ?DUP IF _XT-IOR ! THEN
        ELSE
            DROP
        THEN THEN THEN
    THEN
    _XT-IOR @ ;

\ Publish the committed size, block count, free count and times into the
\ shared vnode and the mount.
: _XT-PUBLISH  ( -- )
    _XT-NEW @ _XT-VN @ VN.SIZE-LO !
    0 _XT-VN @ VN.SIZE-HI !
    _XT-NEW-BLOCKS @ _XT-VN @ VN.BLOCKS !
    _XW-SECONDS @ _XT-VN @ VN.MTIME !
    _XW-NSEC @ _XT-VN @ VN.MTIME-NS !
    _XW-SECONDS @ _XT-VN @ VN.CTIME !
    _XW-NSEC @ _XT-VN @ VN.CTIME-NS !
    _XT-NEW-FREE @ _XW-CTX @ _EXT4-C.FREE-BLOCKS + !
    VFS-F-DIRTY _XT-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

\ A failure after commit cannot roll the truncate back: the committed
\ journal is authoritative and replays on the next mount.  Report success,
\ keep the diagnostic in V.LAST-IOR, and republish the committed state,
\ since checkpoint quarantine may have reloaded the old inode.
: _XT-POSTCOMMIT-FAIL  ( ior -- ior )
    _XT-FAIL _XT-V @ V.LAST-IOR !
    _XT-PUBLISH
    0 ;

\ The committed block count and free count, read back from the target.
: _XT-REFRESH  ( -- ior )
    _XW-AUTH ?DUP IF EXIT THEN
    _XW-SIZE @ _XT-NEW @ <> IF VFS-E-CORRUPT EXIT THEN
    _XW-BLOCKS @ _XT-NEW-BLOCKS !
    _XW-CTX @ _EXT4-C.FREE-BLOCKS + @ _XT-NEW-FREE !
    0 ;

\ A committed truncate whose remaining release failed is durable: its new
\ size stands, and its orphan record makes mount recovery finish the
\ release.  Report success, keep the diagnostic in V.LAST-IOR, and turn the
\ volume read-only until that remount.
: _XT-DURABLE-FAIL  ( ior -- ior )
    _XT-FAIL _XT-V @ V.LAST-IOR !
    VFS-F-RO VFS-F-DIRTY OR _XT-V @ V.FLAGS DUP @ ROT OR SWAP !
    _XT-REFRESH DROP
    _XT-PUBLISH
    0 ;

\ The target's own tree maps none of the insertion's homes.
: _XT-ADD-PROVE  ( -- ior )
    _XW-AUTH ?DUP IF EXIT THEN
    0 _XP-BASE ! 0 _XP-EXPECT !
    _XP-COLLECT ?DUP IF EXIT THEN
    _XP-MAP-CHECK ;

\ Stage and prove the orphan insertion that commits the new size.  On
\ success the transaction stays staged.
: _XT-ADD-PASS  ( -- ior )
    3 0 0 _XW-WRITER @ _EXT4-JTX-BEGIN ?DUP IF NIP EXIT THEN
    _XW-TX !
    _XT-NEW @ _XT-OLD @ _XW-INO @ _XW-EXPECTED-GEN @
    _XW-SECONDS @ _XW-NSEC @ _XW-TX @
    _EXT4-JTX-STAGE-MODERN-ORPHAN-TRUNCATE
    DUP 0= IF DROP _XT-ADD-PROVE THEN
    DUP IF _XW-DISCARD ?DUP IF NIP THEN THEN ;

\ A truncate whose release does not fit one transaction, as the kernel's
\ ext4 truncates: one transaction commits the new size behind a modern
\ orphan record, release passes free the blocks past EOF, and the record's
\ final cleanup zeroes the bytes past EOF and removes it.  Every refusal
\ comes before the insertion's commit; a crash after it leaves the record
\ that mount recovery completes.
: _XT-MULTI  ( -- ior )
    _XW-WRITER @ _EXT4-JWR.META-CAP + @ 3 U< IF VFS-E-NOSPC EXIT THEN
    _XW-CTX @ _XT-V @ _EXT4-MEASURE-MODERN-ORPHAN-ADD NIP ?DUP IF EXIT THEN
    _XW-CTX @ _EXT4-REQUIRE-PROTOCOL-HOME-OWNERS ?DUP IF EXIT THEN
    _XW-INO @ _XW-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _XW-CTX @ _EXT4-C.INODE + _EXT4-I.BLOCK + 6 + W@
    _XW-WRITER @ _XW-PASS-ROOM? 0= IF VFS-E-NOSPC EXIT THEN
    _XW-BLOCKS @ _XT-NEW-BLOCKS !
    _XW-CTX @ _EXT4-C.FREE-BLOCKS + @ _XT-NEW-FREE !
    _EXT4-MOW-ACTIVE @ 0= IF
        _XT-ADD-PASS ?DUP IF _XT-FAIL EXIT THEN
        _XW-DISCARD ?DUP IF _XT-FAIL EXIT THEN
        _XW-WRITER @ _EXT4-JWR-ACTIVATE ?DUP IF _XT-FAIL EXIT THEN
    THEN
    _XT-ADD-PASS ?DUP IF _XT-FAIL EXIT THEN
    _XW-TX @ _EXT4-JTX-EMIT ?DUP IF _XT-FAIL EXIT THEN
    _XW-TX @ _EXT4-JTX-CHECKPOINT ?DUP IF _XT-DURABLE-FAIL EXIT THEN
    _XW-WRITER @ _EXT4-REQUIRE-IDLE-WRITER ?DUP IF _XT-DURABLE-FAIL EXIT THEN
    _XW-INO @ _XW-WRITER @ _XW-CTX @ _EXT4-DRAIN-ORPHAN
    ?DUP IF _XT-DURABLE-FAIL EXIT THEN
    _XT-REFRESH ?DUP IF _XT-DURABLE-FAIL EXIT THEN
    _XT-PUBLISH
    0 _XT-V @ V.LAST-IOR !
    0 ;

\ Truncate in one transaction when it fits.  The first pass on a clean
\ mount is staged and proved before the journal is activated, so a refusal
\ leaves the volume untouched; the live pass then repeats it against the
\ activated volume, emits it, and checkpoints it synchronously.  A shrink
\ whose release does not fit continues across transactions.
: _XT-RUN  ( -- ior )
    1 0 0 _XW-CTX @ _EXT4-JWR-ENSURE ?DUP IF NIP EXIT THEN
    _XW-WRITER !
    _XT-PASS DUP VFS-E-NOSPC = _XT-NEW @ _XT-OLD @ U< AND IF
        DROP _XT-MULTI EXIT
    THEN
    ?DUP IF _XT-FAIL EXIT THEN
    _EXT4-MOW-ACTIVE @ 0= IF
        _XW-DISCARD ?DUP IF _XT-FAIL EXIT THEN
        _XW-WRITER @ _EXT4-JWR-ACTIVATE ?DUP IF _XT-FAIL EXIT THEN
        _XT-PASS ?DUP IF _XT-FAIL EXIT THEN
    THEN
    _XW-TX @ _EXT4-JTX-EMIT ?DUP IF _XT-FAIL EXIT THEN
    _XT-PUBLISH
    _XW-TX @ _EXT4-JTX-CHECKPOINT ?DUP IF _XT-POSTCOMMIT-FAIL EXIT THEN
    _XW-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _XW-WRITER @ _EXT4-JWR-LATCH-FAULT
        _XT-POSTCOMMIT-FAIL EXIT
    THEN
    _XW-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <>
    _XW-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= OR IF
        VFS-E-CORRUPT _XW-WRITER @ _EXT4-JWR-LATCH-FAULT
        _XT-POSTCOMMIT-FAIL EXIT
    THEN
    0 _XT-V @ V.LAST-IOR !
    0 ;

: _EXT4-TRUNCATE  ( dentry vfs -- ior )
    _XT-V ! _XT-D !
    0 _XW-WRITER ! 0 _XW-TX ! FALSE _XW-ORPHAN ! FALSE _XW-DELETION !
    _XT-ENTRY ?DUP IF EXIT THEN
    \ The generic VFS marks the volume dirty after any successful truncate,
    \ and a dirty volume with an inactive journal refuses later mutations,
    \ so a size that does not change refuses rather than succeed unwritten.
    _XT-NEW @ _XT-OLD @ = IF EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT THEN
    _XT-QUALIFY ?DUP IF EXIT THEN
    _XT-NOW ?DUP IF EXIT THEN
    _XT-RUN
    _XW-DATA _EXT4-MAX-BLOCK 0 FILL ;

' _EXT4-TRUNCATE EXT4-STAGED-WRITE-OPS VFS-OP-TRUNCATE CELLS + !

\ =====================================================================
\  The last RELEASE of an unlinked file or directory
\ =====================================================================
\
\ A file or directory whose last link went while a descriptor held it open
\ keeps its storage while the descriptor stays open, and its orphan record
\ drains through the release passes and the deletion on its last staged
\ RELEASE.

VARIABLE _EXT4-LR-D
VARIABLE _EXT4-LR-V
VARIABLE _EXT4-LR-CTX
VARIABLE _EXT4-LR-VN
VARIABLE _EXT4-LR-INO
VARIABLE _EXT4-LR-GEN
VARIABLE _EXT4-LR-COOKIE
VARIABLE _EXT4-LR-WRITER
VARIABLE _EXT4-LR-RECORD
VARIABLE _EXT4-LR-IOR

\ The unlinked inode's modern orphan record, reauthenticated by inode, and
\ its record with no links and no deletion time, under exact block
\ accounting, drain through the mount's writer.
: _EXT4-LR-BODY  ( -- ior )
    _EXT4-LR-V @ _EXT4-MOW-V !
    -1 _EXT4-MOW-ENTRY ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-LR-CTX ! _EXT4-MOW-ACTIVE @ 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-LR-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    _EXT4-LR-CTX @ _EXT4-C.O.ACTIVE + @ 1 <>
    _EXT4-LR-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ 1 <> OR
    _EXT4-LR-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-LR-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-LR-INO @ _EXT4-LR-CTX @ _EXT4-REAUTH-MODERN-ORPHAN-BY-INODE
    _EXT4-LR-IOR ! _EXT4-LR-RECORD !
    _EXT4-LR-IOR @ ?DUP IF EXIT THEN
    _EXT4-LR-RECORD @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-LR-CTX @ _EXT4-C.INODE + DUP _EXT4-I.GENERATION + L@
    _EXT4-LR-GEN @ <> OVER _EXT4-I.DTIME + L@ OR
    SWAP _EXT4-I.LINKS + W@ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-LR-CTX @ _EXT4-C.J.WRITER + @ DUP _EXT4-LR-WRITER ! 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-LR-CTX @ _EXT4-REQUIRE-EXACT-BLOCK-ACCOUNTING ?DUP IF EXIT THEN
    _EXT4-LR-INO @ _EXT4-LR-WRITER @ _EXT4-LR-CTX @ _EXT4-DRAIN-ORPHAN ;

\ A drain that fails settles the writer as a failed namespace transaction
\ does, keeps the diagnostic in V.LAST-IOR and turns the volume read-only
\ until mount recovery finishes the orphan.
: _EXT4-LR-FAIL  ( ior -- ior )
    _EXT4-LR-WRITER @ _XC-WRITER ! _EXT4-LR-V @ _XC-V !
    0 SWAP _XC-FAIL-RETAIN NIP
    0 _XC-WRITER !
    VFS-F-RO VFS-F-DIRTY OR
    _EXT4-LR-V @ V.FLAGS DUP @ ROT OR SWAP ! ;

: _EXT4-LR-SCRUB  ( -- )
    0 _EXT4-LR-D ! 0 _EXT4-LR-V ! 0 _EXT4-LR-CTX ! 0 _EXT4-LR-VN !
    0 _EXT4-LR-INO ! 0 _EXT4-LR-GEN ! 0 _EXT4-LR-COOKIE !
    0 _EXT4-LR-WRITER ! 0 _EXT4-LR-RECORD ! 0 _EXT4-LR-IOR ! ;

: _EXT4-STAGED-RELEASE  ( cookie dentry vfs -- ior )
    _EXT4-LR-V ! _EXT4-LR-D ! _EXT4-LR-COOKIE !
    0 _EXT4-LR-WRITER !
    _EXT4-LR-D @ 0= _EXT4-LR-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-LR-V @ V.BINDING @ EXT4-STAGED-WRITE-BINDING <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-LR-D @ _EXT4-LR-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-LR-D @ D.VNODE @ DUP _EXT4-LR-VN ! 0= IF VFS-E-STALE EXIT THEN
    _EXT4-LR-VN @ VN.TYPE @ DUP VFS-T-FILE <> SWAP VFS-T-DIR <> AND IF
        0 EXIT
    THEN
    _EXT4-LR-VN @ VN.BID @ DUP _EXT4-LR-INO !
    DUP 0= SWAP _EXT4-LR-D @ IN.BID @ <> OR
    _EXT4-LR-VN @ VN.GEN @ DUP _EXT4-LR-GEN ! 0xFFFFFFFF U> OR IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-LR-GEN @ 32 LSHIFT _EXT4-LR-INO @ OR _EXT4-LR-COOKIE @ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-LR-VN @ VN.NLINK @ IF 0 EXIT THEN
    _EXT4-LR-D @ D.FLAGS @ VFS-DF-UNLINKED AND 0= IF VFS-E-STALE EXIT THEN
    _EXT4-LR-VN @ VN.OPEN-REFS @ DUP 1 U> IF DROP 0 EXIT THEN
    1 <> IF VFS-E-STALE EXIT THEN
    _EXT4-LR-BODY
    DUP IF _EXT4-LR-FAIL _EXT4-LR-SCRUB EXIT THEN
    DROP 0 _EXT4-LR-V @ V.LAST-IOR ! _EXT4-LR-SCRUB 0 ;

: _EXT4-STAGED-SYNCFS  ( vfs -- ior )
    DUP _EXT4-LIVE-SYNC-PREPARE ?DUP IF NIP EXIT THEN
    _EXT4-SY-CTX @ _EXT4-C.O.ACTIVE + @ IF
        DROP VFS-E-BUSY EXIT
    THEN
    _EXT4-SYNCFS ;

' _EXT4-STAGED-RELEASE EXT4-STAGED-WRITE-OPS VFS-OP-RELEASE CELLS + !
' _EXT4-STAGED-SYNCFS EXT4-STAGED-WRITE-OPS VFS-OP-SYNCFS CELLS + !

\ =====================================================================
\  Atomic linked-regular-file scalar metadata
\ =====================================================================
\
\ SETATTR commits one checksummed inode-table after-image and no data or
\ revoke payload.  It is intentionally a raw scalar interface: credential
\ policy, authorization, and automatic set-id or ctime changes belong above
\ this binding.  MODE must retain the complete regular-file type field and is
\ refused while a POSIX access ACL exists because updating that ACL's mask is
\ outside this slice.  Other authenticated inline and external xattrs remain
\ immutable.  The public VFS publishes selected fields into the shared vnode
\ only after this callback reports committed success.

VARIABLE _XS-D
VARIABLE _XS-V
VARIABLE _XS-CTX
VARIABLE _XS-VN
VARIABLE _XS-MASK
VARIABLE _XS-MODE
VARIABLE _XS-UID
VARIABLE _XS-GID
VARIABLE _XS-ATIME
VARIABLE _XS-ATIME-NS
VARIABLE _XS-MTIME
VARIABLE _XS-MTIME-NS
VARIABLE _XS-CTIME
VARIABLE _XS-CTIME-NS
VARIABLE _XS-RDEV
VARIABLE _XS-INO
VARIABLE _XS-GEN
VARIABLE _XS-GROUP
VARIABLE _XS-INDEX
VARIABLE _XS-HOME
VARIABLE _XS-OFF
VARIABLE _XS-WRITER
VARIABLE _XS-TX
VARIABLE _XS-IOR
VARIABLE _XS-ACTIVE
VARIABLE _XS-IMAGE
VARIABLE _XS-RECORD
VARIABLE _XS-SAVED-LOW
VARIABLE _XS-SAVED-EXTRA
VARIABLE _XS-OWNER-MAP-LIMIT
VARIABLE _XS-OWNER-IOR
CREATE _XS-ATTR-SNAPSHOT VFS-SETATTR-REQ-SIZE ALLOT
CREATE _XS-INODE-SNAPSHOT _EXT4-MAX-INODE ALLOT

: _XS-SCRUB  ( -- )
    _XS-ATTR-SNAPSHOT VFS-SETATTR-REQ-SIZE 0 FILL
    _XS-INODE-SNAPSHOT _EXT4-MAX-INODE 0 FILL
    0 _XS-D ! 0 _XS-V ! 0 _XS-CTX ! 0 _XS-VN !
    0 _XS-MASK ! 0 _XS-MODE ! 0 _XS-UID ! 0 _XS-GID !
    0 _XS-ATIME ! 0 _XS-ATIME-NS !
    0 _XS-MTIME ! 0 _XS-MTIME-NS !
    0 _XS-CTIME ! 0 _XS-CTIME-NS ! 0 _XS-RDEV !
    0 _XS-INO ! 0 _XS-GEN ! 0 _XS-GROUP ! 0 _XS-INDEX !
    0 _XS-HOME ! 0 _XS-OFF ! 0 _XS-WRITER ! 0 _XS-TX !
    0 _XS-IOR ! 0 _XS-ACTIVE ! 0 _XS-IMAGE ! 0 _XS-RECORD !
    0 _XS-SAVED-LOW ! 0 _XS-SAVED-EXTRA !
    0 _XS-OWNER-MAP-LIMIT ! 0 _XS-OWNER-IOR ! ;

: _XS-VALIDATE-TIME  ( seconds nsec -- ior )
    DUP 0< OVER 1000000000 U< 0= OR IF
        2DROP VFS-E-INVALID EXIT
    THEN
    DROP
    DUP -2147483648 < OVER 15032385535 > OR IF
        DROP VFS-E-OVERFLOW EXIT
    THEN
    DROP 0 ;

: _XS-VALIDATE-REQUEST  ( -- ior )
    _XS-ATTR-SNAPSHOT VA.MASK @ DUP _XS-MASK !
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    VFS-SA-ALL INVERT AND IF VFS-E-INVALID EXIT THEN
    _XS-ATTR-SNAPSHOT VA.MODE @ _XS-MODE !
    _XS-ATTR-SNAPSHOT VA.UID @ _XS-UID !
    _XS-ATTR-SNAPSHOT VA.GID @ _XS-GID !
    _XS-ATTR-SNAPSHOT VA.ATIME @ _XS-ATIME !
    _XS-ATTR-SNAPSHOT VA.ATIME-NS @ _XS-ATIME-NS !
    _XS-ATTR-SNAPSHOT VA.MTIME @ _XS-MTIME !
    _XS-ATTR-SNAPSHOT VA.MTIME-NS @ _XS-MTIME-NS !
    _XS-ATTR-SNAPSHOT VA.CTIME @ _XS-CTIME !
    _XS-ATTR-SNAPSHOT VA.CTIME-NS @ _XS-CTIME-NS !
    _XS-ATTR-SNAPSHOT VA.RDEV @ _XS-RDEV !
    _XS-MASK @ VFS-SA-RDEV AND IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XS-MASK @ VFS-SA-MODE AND IF
        _XS-MODE @ 0xFFFF U> IF VFS-E-OVERFLOW EXIT THEN
        _XS-MODE @ 0xF000 AND 0x8000 <> IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
    THEN
    _XS-MASK @ VFS-SA-UID AND IF
        _XS-UID @ 0xFFFFFFFF U> IF VFS-E-OVERFLOW EXIT THEN
    THEN
    _XS-MASK @ VFS-SA-GID AND IF
        _XS-GID @ 0xFFFFFFFF U> IF VFS-E-OVERFLOW EXIT THEN
    THEN
    _XS-MASK @ VFS-SA-ATIME AND IF
        _XS-ATIME @ _XS-ATIME-NS @ _XS-VALIDATE-TIME ?DUP IF EXIT THEN
    THEN
    _XS-MASK @ VFS-SA-MTIME AND IF
        _XS-MTIME @ _XS-MTIME-NS @ _XS-VALIDATE-TIME ?DUP IF EXIT THEN
    THEN
    _XS-MASK @ VFS-SA-CTIME AND IF
        _XS-CTIME @ _XS-CTIME-NS @ _XS-VALIDATE-TIME ?DUP IF EXIT THEN
    THEN
    0 ;

: _XS-ENTRY  ( -- ior )
    _XS-D @ 0= _XS-V @ 0= OR IF VFS-E-INVALID EXIT THEN
    _XS-V @ V.BINDING @ EXT4-STAGED-WRITE-BINDING <> IF
        VFS-E-INVALID EXIT
    THEN
    _XS-V @ _EXT4-MOW-V !
    0 _EXT4-MOW-ENTRY ?DUP IF EXIT THEN
    _EXT4-MOW-CTX @ _XS-CTX !
    _EXT4-MOW-ACTIVE @ _XS-ACTIVE !
    _XS-CTX @ _EXT4-STAGED-WRITE-FS-QUALIFY ?DUP IF EXIT THEN
    _XS-D @ _XS-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XS-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XS-D @ D.VNODE @ DUP _XS-VN ! 0= IF VFS-E-STALE EXIT THEN
    _XS-VN @ VN.TYPE @ VFS-T-FILE <> IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XS-VN @ VN.BID @ DUP _XS-INO ! 0= IF VFS-E-STALE EXIT THEN
    _XS-INO @ _XS-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-STALE EXIT THEN
    _XS-VN @ VN.GEN @ DUP _XS-GEN ! 0xFFFFFFFF U> IF
        VFS-E-STALE EXIT
    THEN
    _XS-VN @ VN.NLINK @ 0= IF VFS-E-STALE EXIT THEN
    _XS-CTX @ _EXT4-C.J.WRITER-STORE-KIND + @
    _EXT4-JWR-STORE-DEDICATED <> IF VFS-E-NOSPC EXIT THEN
    _XS-CTX @ _EXT4-C.J.WRITER-ARENA + @ 0=
    _XS-CTX @ _EXT4-C.J.WRITER + @ 0= OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _XS-REQUIRE-DENTRY  ( -- ior )
    _XS-D @ _XS-V @ _VFS-DENTRY-OWNED? 0= IF VFS-E-STALE EXIT THEN
    _XS-D @ D.FLAGS @ VFS-DF-UNLINKED AND IF VFS-E-STALE EXIT THEN
    _XS-D @ D.VNODE @ _XS-VN @ <> IF VFS-E-STALE EXIT THEN
    _XS-VN @ VN.TYPE @ VFS-T-FILE <>
    _XS-VN @ VN.BID @ _XS-INO @ <> OR
    _XS-VN @ VN.GEN @ _XS-GEN @ <> OR
    _XS-VN @ VN.NLINK @ 0= OR IF VFS-E-STALE EXIT THEN
    0 ;

: _XS-CACHE-MATCH?  ( -- flag )
    _XS-CTX @ _EXT4-C.R.GEN + @ _XS-VN @ VN.GEN @ =
    _XS-CTX @ _EXT4-C.R.SIZE + @ _XS-VN @ VN.SIZE-LO @ = AND
    _XS-VN @ VN.SIZE-HI @ 0= AND
    _XS-CTX @ _EXT4-C.R.MODE + @ _XS-VN @ VN.MODE @ = AND
    _XS-CTX @ _EXT4-C.R.UID + @ _XS-VN @ VN.UID @ = AND
    _XS-CTX @ _EXT4-C.R.GID + @ _XS-VN @ VN.GID @ = AND
    _XS-CTX @ _EXT4-C.R.NLINK + @ _XS-VN @ VN.NLINK @ = AND
    _XS-CTX @ _EXT4-C.R.BLOCKS + @ _XS-VN @ VN.BLOCKS @ = AND
    _XS-CTX @ _EXT4-C.R.ATIME + @ _XS-VN @ VN.ATIME @ = AND
    _XS-CTX @ _EXT4-C.R.ATIME-NS + @ _XS-VN @ VN.ATIME-NS @ = AND
    _XS-CTX @ _EXT4-C.R.MTIME + @ _XS-VN @ VN.MTIME @ = AND
    _XS-CTX @ _EXT4-C.R.MTIME-NS + @ _XS-VN @ VN.MTIME-NS @ = AND
    _XS-CTX @ _EXT4-C.R.CTIME + @ _XS-VN @ VN.CTIME @ = AND
    _XS-CTX @ _EXT4-C.R.CTIME-NS + @ _XS-VN @ VN.CTIME-NS @ = AND
    _XS-CTX @ _EXT4-C.R.RDEV + @ 0= AND
    _XS-VN @ VN.RDEV @ 0= AND ;

: _XS-SCAN-XATTRS  ( -- ior )
    _XS-MASK @ VFS-SA-MODE AND IF
        _EXT4-XOP-GET _EXT4-XA-OP !
        S" system.posix_acl_access"
        _EXT4-XA-REQ-U ! _EXT4-XA-REQ-A !
        0 _EXT4-XA-OUT ! 0 _EXT4-XA-CAP !
        0 _EXT4-XA-FOUND ! 0 _EXT4-XA-FOUND-SIZE ! 0 _EXT4-XA-IOR !
        _XS-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF EXIT THEN
        _EXT4-XA-IOR @ ?DUP IF EXIT THEN
        _EXT4-XA-FOUND @ IF
            EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
        THEN
    ELSE
        _EXT4-XOP-LIST _EXT4-XA-OP !
        0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
        _XS-CTX @ _EXT4-XA-SCAN-BOTH ?DUP IF EXIT THEN
    THEN
    0 ;

: _XS-STAGE-CURRENT-TARGET  ( -- ior )
    _XS-CTX @ _EXT4-STAGE-CURRENT-INODE
    _XS-IOR ! DUP VFS-T-FILE <> IF
        DROP _XS-IOR @ ?DUP IF EXIT THEN
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN DROP
    _XS-IOR @ ?DUP IF EXIT THEN
    _XS-REQUIRE-DENTRY ?DUP IF EXIT THEN
    _XS-CACHE-MATCH? 0= IF VFS-E-CONFLICT EXIT THEN
    _XS-CTX @ _EXT4-C.R.NLINK + @ 0= IF VFS-E-STALE EXIT THEN
    _XS-SCAN-XATTRS ;

: _XS-REQUIRE-TARGET  ( -- ior )
    _XS-INO @ _XS-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XS-GROUP @ <>
    _EXT4-IR-INDEX @ _XS-INDEX @ <> OR
    _EXT4-IR-BLOCK @ _XS-HOME @ <> OR
    _EXT4-IR-OFF @ _XS-OFF @ <> OR IF VFS-E-STALE EXIT THEN
    _XS-CTX @ _EXT4-C.INODE + _XS-INODE-SNAPSHOT
    _XS-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _XS-STAGE-CURRENT-TARGET ;

: _XS-AUTH-TARGET  ( -- ior )
    _XS-INO @
    _XS-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _XS-INO @ 8 =
    _XS-INO @ _XS-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-WRITE-POLICY _EXT4-UNSUPPORTED EXIT
    THEN
    _XS-INO @ _XS-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _XS-GROUP !
    _EXT4-IR-INDEX @ _XS-INDEX !
    _EXT4-IR-BLOCK @ _XS-HOME !
    _EXT4-IR-OFF @ _XS-OFF !
    _XS-STAGE-CURRENT-TARGET ?DUP IF EXIT THEN
    _XS-HOME @ _XS-GROUP @ _XS-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XS-CTX @ _EXT4-C.INODE + _XS-INODE-SNAPSHOT
    _XS-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _XS-REQUIRE-TARGET ;

: _XS-REQUIRE-FRESH-EXACT  ( -- ior )
    _XS-WRITER @ _EXT4-JWR.META-CREDIT + @ 1 <>
    _XS-WRITER @ _EXT4-JWR.DATA-CREDIT + @ 0<> OR
    _XS-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ 0<> OR IF
        VFS-E-INVALID EXIT
    THEN
    _XS-WRITER @ _EXT4-JWR.META-USED + @
    _XS-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _XS-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _XS-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _XS-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _XS-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _XS-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    _XS-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _XS-CTX @ _EXT4-C.O.ACTIVE + @
    _XS-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _XS-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _XS-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

: _XS-APPLY-ATIME  ( inode -- ior )
    DUP _XS-RECORD !
    DUP _EXT4-I.CTIME + L@ _XS-SAVED-LOW !
    _EXT4-I.CTIME-EXTRA + L@ _XS-SAVED-EXTRA !
    _XS-ATIME @ _XS-ATIME-NS @ _XS-RECORD @ _XS-CTX @
    _EXT4-SET-INODE-CTIME _XS-IOR !
    _XS-IOR @ 0= IF
        _XS-RECORD @ _EXT4-I.CTIME + L@
        _XS-RECORD @ _EXT4-I.ATIME + L!
        _XS-RECORD @ _EXT4-I.CTIME-EXTRA + L@
        _XS-RECORD @ _EXT4-I.ATIME-EXTRA + L!
    THEN
    _XS-SAVED-LOW @ _XS-RECORD @ _EXT4-I.CTIME + L!
    _XS-SAVED-EXTRA @ _XS-RECORD @ _EXT4-I.CTIME-EXTRA + L!
    _XS-IOR @ ;

: _XS-APPLY-MTIME  ( inode -- ior )
    DUP _XS-RECORD !
    DUP _EXT4-I.CTIME + L@ _XS-SAVED-LOW !
    _EXT4-I.CTIME-EXTRA + L@ _XS-SAVED-EXTRA !
    _XS-MTIME @ _XS-MTIME-NS @ _XS-RECORD @ _XS-CTX @
    _EXT4-SET-INODE-MTIME-CTIME _XS-IOR !
    _XS-SAVED-LOW @ _XS-RECORD @ _EXT4-I.CTIME + L!
    _XS-SAVED-EXTRA @ _XS-RECORD @ _EXT4-I.CTIME-EXTRA + L!
    _XS-IOR @ ;

: _XS-APPLY-REQUEST  ( inode -- ior )
    _XS-RECORD !
    _XS-MASK @ VFS-SA-MODE AND IF
        _XS-MODE @ _XS-RECORD @ _EXT4-I.MODE + W!
    THEN
    _XS-MASK @ VFS-SA-UID AND IF
        _XS-UID @ 0xFFFF AND _XS-RECORD @ _EXT4-I.UID-LO + W!
        _XS-UID @ 16 RSHIFT 0xFFFF AND
        _XS-RECORD @ _EXT4-I.UID-HI + W!
    THEN
    _XS-MASK @ VFS-SA-GID AND IF
        _XS-GID @ 0xFFFF AND _XS-RECORD @ _EXT4-I.GID-LO + W!
        _XS-GID @ 16 RSHIFT 0xFFFF AND
        _XS-RECORD @ _EXT4-I.GID-HI + W!
    THEN
    _XS-MASK @ VFS-SA-ATIME AND IF
        _XS-RECORD @ _XS-APPLY-ATIME ?DUP IF EXIT THEN
    THEN
    _XS-MASK @ VFS-SA-MTIME AND IF
        _XS-RECORD @ _XS-APPLY-MTIME ?DUP IF EXIT THEN
    THEN
    _XS-MASK @ VFS-SA-CTIME AND IF
        _XS-CTIME @ _XS-CTIME-NS @ _XS-RECORD @ _XS-CTX @
        _EXT4-SET-INODE-CTIME ?DUP IF EXIT THEN
    THEN
    0 ;

: _XS-MAP-CHECK  ( -- ior )
    _XS-CTX @ _XS-WRITER @ _EXT4-NMC-BEGIN ?DUP IF EXIT THEN
    _XS-INO @ _XS-HOME @ _XS-OFF @ _EXT4-NMC-RETAINED _EXT4-NMC-OLD
    _EXT4-NMC-BITMAPS
    _XS-INO @ _XS-HOME @ _XS-OFF @ _EXT4-NMC-RETAINED _EXT4-NMC-NEW
    _EXT4-NMC-END ;

: _EXT4-JTX-STAGE-SETATTR  ( transaction -- ior )
    DUP _XS-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _XS-WRITER @ _EXT4-JWR.CTX + @ DUP _XS-CTX @ <> IF
        DROP VFS-E-INVALID EXIT
    THEN DROP
    _XS-REQUIRE-FRESH-EXACT ?DUP IF EXIT THEN
    _XS-REQUIRE-TARGET ?DUP IF EXIT THEN
    _XS-HOME @ _XS-GROUP @ _XS-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _XS-HOME @ _XS-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _XS-CTX @ _EXT4-C.BLOCK + _XS-OFF @ +
    _XS-INODE-SNAPSHOT _XS-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XS-CTX @ _EXT4-C.BLOCK + _XS-HOME @ _XS-WRITER @
    _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _XS-IMAGE !
    _XS-OFF @ + DUP _XS-RECORD !
    _XS-INODE-SNAPSHOT _XS-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _XS-RECORD @ _XS-APPLY-REQUEST ?DUP IF EXIT THEN
    _XS-RECORD @ _XS-INO @ _XS-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _XS-IMAGE @ _XS-HOME @ _XS-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    _XS-WRITER @ _EXT4-JWR.META-USED + @ 1 <>
    _XS-WRITER @ _EXT4-JWR.META-ACTIVE + @ 1 <> OR
    _XS-WRITER @ _EXT4-JWR.DATA-USED + @ 0<> OR
    _XS-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ 0<> OR
    _XS-WRITER @ _EXT4-JWR.REVOKE-USED + @ 0<> OR
    _XS-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0<> OR
    _XS-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _XS-MAP-CHECK ;

: _XS-FAIL  ( ior -- ior )
    _XS-IOR !
    _XS-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF
                _XS-WRITER @ _EXT4-JWR-LATCH-FAULT _XS-IOR !
            THEN
        ELSE
            DUP _EXT4-JWR.STATE + @ _EXT4-JWR-COMMITTED = IF
                DROP _EXT4-JWP-CHECKPOINT-PREFLIGHT
                _XS-WRITER @ _EXT4-JWR.PHASE + !
                _XS-IOR @ _XS-WRITER @ _EXT4-JWR-LATCH-FAULT
                _XS-IOR !
            ELSE
                DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
                    _EXT4-JWR.FAULT + @ ?DUP IF _XS-IOR ! THEN
                ELSE DROP THEN
            THEN
        THEN
    THEN
    _XS-V @ ?DUP IF _XS-IOR @ SWAP V.LAST-IOR ! THEN
    _XS-IOR @ _XS-SCRUB ;

: _XS-POSTCOMMIT-FAIL  ( ior -- ior )
    _XS-FAIL DROP
    \ Journal commit is authoritative.  Return success so the public VFS,
    \ rather than this driver, publishes the selected shared-vnode fields.
    0 ;

: _XS-REQUIRE-IDLE  ( -- ior )
    _XS-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _XS-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <>
    _XS-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

: _XS-RUN  ( -- ior )
    _XS-ENTRY ?DUP IF _XS-FAIL EXIT THEN
    _XS-AUTH-TARGET ?DUP IF _XS-FAIL EXIT THEN
    1 0 0 _XS-CTX @ _EXT4-JTX-PREFLIGHT-CAPACITY
    ?DUP IF _XS-FAIL EXIT THEN
    1 0 0 _XS-CTX @ _EXT4-JWR-ENSURE
    DUP IF NIP _XS-FAIL EXIT THEN DROP _XS-WRITER !
    _XS-REQUIRE-IDLE ?DUP IF _XS-FAIL EXIT THEN
    _XS-ACTIVE @ 0= IF
        1 0 0 _XS-WRITER @ _EXT4-JTX-BEGIN
        DUP IF NIP _XS-FAIL EXIT THEN DROP _XS-TX !
        _XS-TX @ _EXT4-JTX-STAGE-SETATTR ?DUP IF _XS-FAIL EXIT THEN
        _XS-TX @ _EXT4-JTX-ABORT ?DUP IF _XS-FAIL EXIT THEN
        _XS-WRITER @ _EXT4-JWR-ACTIVATE ?DUP IF _XS-FAIL EXIT THEN
    THEN
    1 0 0 _XS-WRITER @ _EXT4-JTX-BEGIN
    DUP IF NIP _XS-FAIL EXIT THEN DROP _XS-TX !
    _XS-TX @ _EXT4-JTX-STAGE-SETATTR ?DUP IF _XS-FAIL EXIT THEN
    _XS-TX @ _EXT4-JTX-EMIT ?DUP IF _XS-FAIL EXIT THEN
    _XS-TX @ _EXT4-JTX-CHECKPOINT
    ?DUP IF _XS-POSTCOMMIT-FAIL EXIT THEN
    _XS-REQUIRE-IDLE ?DUP IF _XS-POSTCOMMIT-FAIL EXIT THEN
    0 _XS-V @ V.LAST-IOR !
    _XS-SCRUB
    0 ;

: _EXT4-SETATTR  ( attr dentry vfs -- ior )
    2 PICK VFS-SETATTR-REQ-SIZE _VFS-BUFFER? 0= IF
        2DROP DROP _XS-SCRUB VFS-E-INVALID EXIT
    THEN
    2 PICK VFS-SETATTR-REQ-SIZE
    _XS-ATTR-SNAPSHOT VFS-SETATTR-REQ-SIZE MSPAN-OVERLAP? IF
        2DROP DROP _XS-SCRUB VFS-E-INVALID EXIT
    THEN
    2 PICK VFS-SETATTR-REQ-SIZE
    _XS-INODE-SNAPSHOT _EXT4-MAX-INODE MSPAN-OVERLAP? IF
        2DROP DROP _XS-SCRUB VFS-E-INVALID EXIT
    THEN
    2 PICK _XS-ATTR-SNAPSHOT VFS-SETATTR-REQ-SIZE MOVE
    _XS-V ! _XS-D ! DROP
    0 _XS-CTX ! 0 _XS-VN ! 0 _XS-WRITER ! 0 _XS-TX !
    0 _XS-IMAGE ! 0 _XS-RECORD !
    _XS-VALIDATE-REQUEST ?DUP IF _XS-FAIL EXIT THEN
    _XS-RUN ;

' _EXT4-SETATTR EXT4-STAGED-WRITE-OPS VFS-OP-SETATTR CELLS + !
